\begin{lemma}[Sum of Silver Stepsizes]\label{lem:sum-steps}
	$\sum_{t=0}^{n-1} \alpha_t = \rho^k - 1$ for any $k \in \N$. 
\end{lemma}

\begin{proof}
	The base case $k=1$ is trivial. The inductive step follows from the recursion~\eqref{eq:steps-recursive}.
\end{proof}

\begin{theorem}[Recursive gluing]\label{thm:cert}
	Let $n = 2^k-1$. Suppose $\{\sig_{ij}\}_{i,j \in \{0,\dots,n,*\}} $ satisfies $*$-sparsity and certifies the $n$-step rate, i.e.,
	\begin{align}
		\sum_{i \neq j \in \{0, \dots, n,*\}} \sig_{ij} Q_{ij} 
		=
		\|x_0 - x^*\|^2 - \|x_n - c_k g_n - x^*\|^2  + \frac{f^* - f_n}{r_k}\ .
		\label{eq:cert:n}
	\end{align}
	Then there exists $\{\lam_{ij}\}_{i, j \in \{0,\dots,2n+1,*\}}$ that satisfies $*$-sparsity and certifies the $2n+1$-step rate, i.e.,
	\begin{align}
		\sum_{i \neq j \in \{0, \dots, 2n+1,*\}} \lam_{ij} Q_{ij} 
		=
		\|x_0 - x^*\|^2 - \|x_{2n+1} - c_{k+1} g_{2n+1} - x^*\|^2 + \frac{f^* - f_{2n+1}}{r_{k+1}}\ .
		\label{eq:cert:2n+1}
	\end{align}
	Moreover, this certificate is explicitly given by
	\begin{align}
		\lam_{ij} = \underbrace{\Theta_{ij}}_{\text{gluing}}
		+
		\underbrace{\Xi_{ij}}_{\text{rank-one correction}}
		+
		\underbrace{\Delta_{ij}}_{\text{sparse correction}}
		\label{eq:lambda}
	\end{align}
	The ``gluing component'' $\Theta$ is defined as 
	\begin{align}
		\Theta_{ij} := \underbrace{\sig_{i,j} \cdot \mathds{1}_{i,j \in \{0,\dots,n,*\}}}_{\text{recurrence for first $n$ steps}}
		\;\;+\;\;
		\underbrace{ (1 + 2\rho)\; \sig_{i-n-1,j-n-1} \cdot \mathds{1}_{i,j \in \{n+1,\dots,2n+1,*\}}}_{\text{recurrence for last $n$ steps}}\,.
		\label{eq:Theta}
	\end{align}
	The ``rank-one correction'' $\Xi$ is zero except the entries $\{\Xi_{ij}\}_{i \in \{n,2n+1,*\},\; j \in \{n+1, \dots, 2n\}}$ which are
	\begin{align}
		\begin{bmatrix}
			\Xi_{n,n+1} & \Xi_{n,n+2} & \cdots & \Xi_{n,2n} \\
			\Xi_{2n+1,n+1} & \Xi_{2n+1,n+2} & \cdots & \Xi_{2n+1,2n} \\
			\Xi_{*,n+1} & \Xi_{*,n+2} & \cdots & \Xi_{*,2n}
		\end{bmatrix}
		:=
		\rho \begin{bmatrix}
			1 \\
			1 \\
			-2
		\end{bmatrix} \begin{bmatrix}
			\alpha_{n+1} & \alpha_{n+2} & \cdots & \alpha_{2n}
		\end{bmatrix}
		\label{eq:Xi}
	\end{align}
	The ``sparse correction'' $\Delta$ is zero except the entries $\{\Delta_{ij}\}_{i \neq j \in \{n,2n+1,*\}}$ which are
	\begin{align}
		\begin{bmatrix}
			\Delta_{n,n}
			&
			\Delta_{n,2n+1}
			&
			\Delta_{n,*} 
			\\
			\Delta_{2n+1,n}
			&
			\Delta_{2n+1,2n+1} 
			&
			\Delta_{2n+1,*} 
			\\
			\Delta_{*,n}
			&
			\Delta_{*,2n+1} 
			&
			\Delta_{*,*}
		\end{bmatrix}
		:=
		\begin{bmatrix}
			0 
			&
			\rho
			&
			1 - \rho^k
			\\
			\rho^k
			&
			0 
			&
			2\rho - \sqrt{2} \rho^{k+1}
			\\
			1 + \rho^{k-1} - \frac{1}{2r_k}
			&
			\frac{1}{2r_{k+1}} - \frac{1+2\rho}{2r_k}
			&
			0
		\end{bmatrix}
		\label{eq:Del}
	\end{align}
\end{theorem}

\begin{proof}[Proof of Theorem~\ref{thm:main}]
	It suffices to prove~\eqref{eq:cert}; we prove this by induction. The base case $n=1$ is Example~\ref{ex:n=1}. The inductive step is Theorem~\ref{thm:cert}. 
\end{proof}

\begin{lemma}[Multipliers involving $x^*$]\label{lem:opt} 
	$\sig_{n*} = \rho^k - 1$, $\sig_{*n} = \frac{1}{2r_k}$, and $\sig_{*t} = \alpha_t$ for $t \in \{0,\dots,n-1\}$. 
\end{lemma}

\begin{proof}
	Expand both sides of the identity~\eqref{eq:cert:n} using the $*$-sparsity assumption, the definition of the co-coercivities, and the definition of GD, i.e., $x_t = x_0 - \sum_{s=0}^{t-1} \alpha_s g_s$. Matching coefficients for the $\langle x_0, g_t \rangle$ terms yields the claimed formulas for $\sig_{*t}$. Matching coefficients for the $f^*$ term gives the identity $\sig_{n*} = \sum_{j=0}^n \sig_{*j}-  \tfrac{1}{2r_k}$. This equals $\rho^k - 1$ by Lemma~\ref{lem:sum-steps}. 
\end{proof}

\begin{lemma}[Succinct linear forms]\label{lem:succinct-linear}
	Let $u := [f_n, f_{2n+1}, f^*]^T$, and let $e, s, \ell \in \R^3$ be the vectors defined in Appendix~\ref{app:succinct-linear}. 
	\begin{itemize}
		\item \underline{Gluing error.} $\frac{f^* - f_{2n+1}}{r_{k+1}} - \sum_{ij} \Theta_{ij} F_{ij} = \langle e, u \rangle$
		\item \underline{Sparse correction.} $\sum_{ij} \Delta_{ij} F_{ij} = \langle s, u \rangle$
		\item \underline{Rank-one correction.} $\sum_{ij} \Xi_{ij} F_{ij} = \langle \ell, u \rangle$
	\end{itemize}
\end{lemma}

\begin{proof}
	Expand the definition of co-coercivities, simplify the rank-one correction using Lemma~\ref{lem:sum-steps}, and simplify the sparse correction using the Pell recurrence $\rho^{k+1} = 2\rho^k + \rho^{k-1}$.
\end{proof}

\begin{lemma}[Succinct quadratic forms]\label{lem:succinct} Let $v := [x_n,g_n,x_{2n+1},g_{2n+1}]^T$, and let $E$, $S$, $L$ be the $4 \times 4$ matrices defined in Appendix~\ref{app:succinct}.
	\begin{itemize}
		\item \underline{Gluing error.} 
		$\|x_0\|^2 - \|x_{2n+1} - c_{k+1} g_{2n+1}\|^2
		- \sum_{ij} \Theta_{ij} P_{ij} = \langle E, vv^T \rangle$
		\item \underline{Sparse correction.} $\sum_{ij} \Delta_{ij} P_{ij} = \langle S, vv^T \rangle$
		\item \underline{Rank-one correction.} $\sum_{ij} \Xi_{ij} P_{ij} = \langle L, vv^T \rangle$
	\end{itemize}
\end{lemma}

\begin{proof}
	Deferred to Appendix~\ref{app:succinct} for brevity.
\end{proof}

\subsection{Proof of recursive gluing (Theorem~\ref{thm:cert})}\label{ssec:gluing:pf}

\paragraph*{Non-negativity.} We verify $\lam_{ij} \geq 0$ for all $i \neq j \in \{0, \dots, 2n+1,*\}$. For nearly all entries, this is obvious since $\lam_{ij}$ is constructed by adding and multiplying non-negative numbers. For the remaining entries where either $\Xi$ or $\Delta$ is negative, compute the corresponding entry of $\lam$ by summing the corrections and using Lemma~\ref{lem:opt}. This gives $\lam_{n*} = 0$, $\lam_{2n+1,*} = \rho^{k+1} - 1$, $\lam_{*,n} = \rho^{k-1} + 1$, $\lam_{*,2n+1} = \tfrac{1}{2r_{k+1}}$, and $\lam_{*,t} = \alpha_t$ for all $t \in \{n+1,\dots,2n\}$. All these entries are clearly non-negative.

\paragraph*{Rate certificate.} The identity~\eqref{eq:cert:2n+1} has two components: a linear form in the function values and a quadratic form in the iterates and gradients. For the linear form, it suffices to verify $e-s-\ell = 0$ by Lemma~\ref{lem:succinct-linear}, where $e,s,\ell \in \R^3$ are the vectors defined in Appendix~\ref{app:succinct-linear}. This is obvious by inspection. For the quadratic form, it suffices to verify $E - S - L = 0$, where $E,S,L \in \R^{4 \times 4}$ are the matrices in Lemma~\ref{lem:succinct} defined in Appendix~\ref{app:succinct}. By plugging in the explicit values for $r_k$ and $\Delta$, this is straightforward to check by hand. For brevity, we provide a simple Mathematica script that verifies these identities at the URL~\citep{MathematicaURL}.





	 \appendix



\begin{proof}[Proof of Lemma~\ref{lem:succinct}]
	\underline{Gluing component.} 
	Recall that $h_{2n+1} = [h_n, \alpha_n, h_n]$ by the recursive construction~\eqref{eq:steps-recursive} of the Silver Stepsize Schedule. Thus, since $\sig$ certifies the $n$-step rate, we have
	\begin{align*}
		\sum_{i \neq j \in \{0, \dots, n,*\}} \sig_{ij} P_{ij} 
		&=
		\|x_0\|^2 - \|x_n - c_k g_n\|^2
		\\ 
		\sum_{i \neq j \in \{n+1, \dots, 2n,*\}} \sig_{ij} P_{ij} 
		&=
		\|x_{n+1}\|^2 - \|x_{2n+1} - c_k g_{2n+1}\|^2
	\end{align*}
	By definition, $\sum_{ij} \Theta_{ij} P_{ij}$ is the former plus $(1 + 2\rho)$ times the latter. 
	Thus the gluing error $\|x_0\|^2 - \|x_{2n+1} - c_{k+1} g_{2n+1}\|^2 - \sum_{ij} \Theta_{ij} P_{ij}$ is equal to
	\begin{align*}
		(1+2\rho) \|x_{2n+1} - c_k g_{2n+1}\|^2 - \|x_{2n+1} - c_{k+1} g_{2n+1}\|^2 + \|x_n - c_k g_n\|^2 - (1 + 2\rho) \|x_{n+1}\|^2
	\end{align*}
	The key point is that after 
	expanding $x_{n+1} = x_n - \alpha_n g_n$, this is a quadratic form in only the $4$ variables $x_n, g_n, x_{2n+1},g_{2n+1}$. Collecting terms, substituting $c_k = \tfrac{1}{2r_k}$, and using the definition of the Silver Stepsize $\alpha_n = 1 + \rho^{k-1}$ yields $\langle E, vv^T \rangle$, as desired.

	\par \underline{Sparse component.} Expand the definition of the co-coercivity and collect terms. Note also that this equals the matrix $S$ in Part~I~\citep{alt23hedging1}, in the limit that the strong convexity tends to $0$.

	\par \underline{Low-rank component.}  Expanding the co-coercivities, using the identity $x_{2n+1} - x_{n+1}= - \sum_{t=n+1}^{2n} \alpha_t g_t$ by definition of GD, and using the identity $\sum_{t=n+1}^{2n} \alpha_t = \sum_{t=0}^{n-1} \alpha_t = \rho^k - 1$ from Lemma~\ref{lem:sum-steps}, 
	\begin{align*}
		\sum_{t=n+1}^{2n} \Big( \Xi_{n,t} P_{n,t} - \Xi_{*,t} P_{*,t} \Big)
		=
		\rho \sum_{t=n+1}^{2n} \alpha_t \Big(
		2 \langle g_t, g_n - x_n \rangle - \|g_n\|^2
		\Big)
		=
		2\rho \langle x_{2n+1} - x_{n+1}, x_n - g_n \rangle - \rho(\rho^k - 1 ) \|g_n\|^2 \,.
	\end{align*}
	An identical calculation yields
	\begin{align*}
		\sum_{t=n+1}^{2n} \Big( \Xi_{2n+1,t} P_{2n+1,t} - \Xi_{*,t} P_{*,t} \Big)
		&=
		2\rho \langle x_{2n+1} - x_{n+1}, x_{2n+1} - g_{2n+1} \rangle - \rho(\rho^k - 1 ) \|g_{2n+1}\|^2 \,.
	\end{align*}
	Now sum these two displays, use the definition of GD to expand $x_{n+1} = x_n - \alpha_n g_n$, and use the definition of the Silver Stepsize $\alpha_n = 1 + \rho^{k-1}$. This gives $\langle L, vv^T \rangle$, as desired.
\end{proof}

