			\Delta_{2n+1,n}
			&
			\Delta_{2n+1,2n+1} 
			&
			\Delta_{2n+1,*} 
			\\
			\Delta_{*,n}
			&
			\Delta_{*,2n+1} 
			&
			\Delta_{*,*}
		\end{bmatrix}
		:=
