\begin{theorem}[Near-linear time]
\label{thm:lintime}Let $\T=(\{J_{1},\ldots,J_{\ell}\},T)$ be a
tree decomposition for the sparsity graph of $C,A_{1},\ldots,A_{m}\in\S^{n}$.
In the corresponding instance of (\ref{eq:CTC}), let each constraint
be written
\begin{equation}
\sum_{j=1}^{\ell}A_{i,j}\bullet X_{j}=A_{i,j}\bullet X_{j}+A_{i,k}\bullet X_{k}=b_{i}\qquad(j,k)\in E(T).\label{eq:structA}
\end{equation}
Under Assumptions~\ref{ass:lin} \&~\ref{ass:slater}, there exists
an algorithm that computes an iterate $(x,y,s)\in\K\times\R^{p}\times\K_{*}$
satisfying
\begin{align}
\left\Vert \begin{bmatrix}\A\\
\N
\end{bmatrix}x-\begin{bmatrix}b\\
0
\end{bmatrix}\right\Vert  & \le\epsilon, & \left\Vert \begin{bmatrix}\A\\
\N
\end{bmatrix}^{T}y-s+c\right\Vert  & \le\epsilon, & \frac{x^{T}s}{\sum_{j=1}^{\ell}|J_{j}|} & \le\epsilon\label{eq:eps_accurate}
\end{align}
in $O(\omega^{6.5}n^{1.5}\log(1/\epsilon))$ time and $O(\omega^{4}n)$
space, where $\omega=\max_{j}|J_{j}|=1+\wid(\T)$.
\end{theorem}

