We say that $x^*\in \mathbb{R}^n$ is a stable point of a locally Lipschitz function $f:\mathbb{R}^n\rightarrow\mathbb{R}$ if for all $\epsilon>0$, there exist $\delta>0$ and $\bar{\alpha}>0$ such that for all $\alpha \in (0,\bar{\alpha}]$, the subgradient method with constant step size $\alpha$ initialized in $B(x^*,\delta)$ has all its iterates in $B(x^*,\epsilon)$.
\end{definition}

\begin{lemma}
\label{lemma:euler_method}
