\paragraph{Proof of Lemma \ref{lem3}}
Using the definition of the expectation from \eqref{def:exp}, we have,
\allowdisplaybreaks{
\begin{align*}
 \E_{\mathbb{S}} \left[\big | (a_{i^*}^Tx-b_{i^*})^+\big |^2\right] & \overset{\eqref{def:exp}}{=} \frac{1}{\binom{m}{\beta}} \sum\limits_{j = 0}^{m-\beta} \binom{\beta-1+j}{\beta-1}  | (Ax-b)^{+}_{\underline{\mathbf{i_j}}} |^2 \\
    & \overset{\text{Lemma} \ \ref{lem:skmseq}}{\geq} \frac{1}{\binom{m}{\beta}} \sum\limits_{j = 0}^{m-\beta}  \frac{\sum\limits_{l = 0}^{m-\beta} \binom{\beta-1+l}{\beta-1}}{m-\beta +1} | (Ax-b)^{+}_{\underline{\mathbf{i_j}}} |^2 \\
    & \geq \frac{1}{m-\beta+1} \sum\limits_{j = 0}^{m-\beta}  \big |(Ax - b)^+_{\underline{\mathbf{i_j}}} \big |^2  \\
    & \geq \frac{1}{m-\beta+1} \min\{\frac{m-\beta+1}{m-s}, 1\} \ \|(Ax - b)^+\|^2 \\
    &  \overset{\text{Lemma} \ \ref{lem0}}{\geq} \ \frac{1}{m L^2}  \ d(x,P)^2. 
\end{align*}}
Here, $s$ is the number of zero entries in the residual $(Ax - b)^+$, which also corresponds to the number of satisfied constraints for $x$. Since $A \mathcal{P} (x) \leq b$, we have the following:
\begin{align*}
    \E_{\mathbb{S}} \left[\big | (a_{i^*}^Tx-b_{i^*})^+\big |^2\right]   & \overset{\eqref{def:exp}}{=}  \frac{1}{\binom{m}{\beta}} \sum\limits_{j = 0}^{m-\beta} \binom{\beta-1+j}{\beta-1} | (Ax-b)^{+}_{\underline{\mathbf{i_j}}}|^2 \\
    & \leq  \frac{1}{\binom{m}{\beta}} \sum\limits_{j = 0}^{m-\beta} \binom{\beta-1+j}{\beta-1} \ \big | (Ax-A\mathcal{P} (x))_{\underline{\mathbf{i_j}}}   \big|^2 \\
    & =  \frac{1}{\binom{m}{\beta}} (x-\mathcal{P} (x))^T\sum\limits_{j = 0}^{m-\beta} \binom{\beta-1+j}{\beta-1} \ (A^TA)_{\underline{\mathbf{i_j}}} (x-\mathcal{P} (x) ) \\
    & =  (x-\mathcal{P} (x) )^T \E_{\mathbb{S}} \left[a_{i^*}a_{i^*}^T\right] (x-\mathcal{P} (x) ) \\
    & \overset{\text{Lemma} \ \ref{lem1} \ \& \ \ref{lem2} }{\leq} \  \min \left\{1, \frac{\beta}{m} \lambda_{\max}\right\} \big \| x- \mathcal{P} (x) \big \|^2 \\
    & = \  \min \left\{1, \frac{\beta}{m} \lambda_{\max}\right\} d(x,P)^2.
\end{align*}
Combining the above identities and using the expression for $f(x)$ from \eqref{def:function} we get,
\begin{align*}
    \frac{\mu_1}{ 2} \ d(x,P)^2 \ \leq \ f(x) \ \leq \  \frac{\mu_2}{2} \ d(x,P)^2,
\end{align*}
which proves the Lemma. 

\paragraph{Proof of Lemma \ref{lem:grad}}

From the definition of $f(x)$, it can be easily checked that $f(x)$ is a convex function. Now, by the convexity property of $f(x)$, for any $x, y \in \R^n$, we have the following:
\begin{align}
\label{eq:grad}
    \langle x-y, \nabla f(y) \rangle \leq f(x) - f(y).
\end{align}
Therefore, we have
\begin{align*}
\big \langle  x-y, \E_{\mathbb{S}}  \left[(a_{i^*}^Ty-b_{i^*})^{+} a_{i^*}\right] \big \rangle & =  \langle x-y, \nabla f(y) \rangle  \leq  \ f(x) - f(y) \\
&  \overset{\text{Lemma} \  \ref{lem3} }{\leq}  \    \frac{\mu_2}{2} \ d(x,P)^2 -  \frac{\mu_1}{2} \ d(y,P)^2.
\end{align*}
This completes the proof.


