\end{cor}

proof.raw_tex:
\begin{lem}
For a set $\setName := \left\{ W_1, W_2,\ldots, W_{|\setName|} \right\}$ of $d \times k$ matrices, let $\outerName$ denote the following convex cone:
\begin{align*}
\outerName := \left\{  X \in  \mathbb{S}^d : W_i^T X W_i \in \mathbb{S}^k_{+} \;\;\;i = 1, \ldots, |\setName| \right\}.
\end{align*}
The dual cone $\approxName$ satisfies
\begin{align} \label{def:coneProdInner}
 \approxName = \left\{ \sum^{|\setName|}_{i=1}  W_i X_i W_i^T : X_i \in \mathbb{S}_{+}^k  \right\},
\end{align}
and the following inclusions hold:
\[
\approxName \subseteq \mathbb{S}^d_{+} \subseteq \outerName.
\]
\begin{proof}
The inclusions are obvious from the definitions of $\approxName$ and $\outerName$ (as is the fact that  $\outerName$ is a convex cone).  It remains to show correctness of  \eqref{def:coneProdInner}. To show this,
let $\mathcal{T}$ denote the set on the right-hand side of \eqref{def:coneProdInner}.  It is easy to check that  $\mathcal{T}^*= \outerName$, which implies $\mathcal{T}^{**} = \approxName$.
Since $\mathcal{T}$ is a convex cone (as is easily checked), $\mathcal{T}^{**}$ equals the closure of $\mathcal{T}$. The result therefore follows by showing $\mathcal{T}$ is closed. To see this, note that $\mathcal{T}$ equals the Minkowski sum of closed cones $W_i \mathbb{S}^k_{+} W_i^T$.
For  matrices $Z_i \in W_i \mathbb{S}^k_{+} W_i^T$, we have that $\sum^{|\setName|}_{i=1} Z_i=0$
only if $Z_i= 0$ for each $i$.  This shows that $\sum^{|\setName|}_{i =1}Z_i = 0$ only if $Z_i$ is in the lineality space of $W_i \mathbb{S}^k_{+} W_i^T$.
 Direct application of the closedness criteria Corollary 9.1.3 of Rockafellar \cite{rockafellar1997convex} shows $\mathcal{T}$ is closed.
\end{proof}

\end{lem}

\begin{lem} \label{lem:rankX_i} 
Let $\perpName$ be a subspace of $\mathbb{S}^d$. If $X^\star:=\sum^{|\setName|}_{i=1} W_i X^\star_i W^T_i$  maximizes   $\sum^{|\setName|}_{i=1} \rank X_i$ over $\perpName \cap \approxName$, then    $X^\star$  maximizes $\rank X$ over $\perpName \cap \approxName$.
\begin{proof}

We will  argue the kernel of $X^\star$ is contained in the kernel of any  $X \in \perpName \cap \approxName$, which immediately implies $\rank X^\star \ge \rank X$. 

To begin, we first argue for any $X = \sum^{|\setName|}_{i=1} W_i X_i W^T_i \in  \perpName \cap \approxName$ that $\nullspace X^\star_i \subseteq \nullspace X_i$ for all $i \in \{1,\ldots,|\setName|\}$. To see this, first  note  that for any $X  \in  \perpName \cap \approxName$
the matrix
\[
 X^\star + X =  \sum^{|\setName|}_{i=1} W_i ( X^\star_i + X_i )W^T_i 
\]
is also in  $\perpName \cap \approxName$ and  satisfies $\rank (X^\star_i + X_i) \ge \rank X^\star_i$.  Now suppose for some $d \in \{1,\ldots,|\setName|\}$ that  $\nullspace X^\star_d \not\subseteq \nullspace X_d$. This implies that  $\nullspace (X^\star_d + X_d) =  \nullspace X^\star_d \cap \nullspace X_d  \subset \nullspace X^\star_d$ which in turn implies $\rank (X^\star_d + X_d ) > \rank X^\star_d$.
But this contradicts our assumption that  $X^\star$ maximizes $\sum_i \rank X_i$.  Hence, $\nullspace X^\star_i \subseteq \nullspace X_i$ for all $i \in \{1,\ldots,|\setName|\}$.

Now suppose an  $X \in \perpName \cap \approxName$ exists for which  $X^\star w = 0$ but $Xw \ne 0$ for some $w$.  Since $X w = 0$ if and only if $X_i W_i^T w = 0$ for all $i$, we must have for some $d$ that $W_d^Tw$ is in the kernel of $X^\star_d$ but not in the kernel of $X_d$. But we have already established that $\nullspace X^\star_d \subseteq \nullspace X_d$.  Hence, $w$ cannot exist. We therefore have that $\nullspace X^\star \subseteq \nullspace X$ for any $X\in \perpName \cap \approxName$, which completes the proof. 
\end{proof}
\end{lem}

\begin{lem}  \label{lem:sumOfConesMaxRank}
Let $\perpName$ be a subspace of $\mathbb{S}^d$.  A matrix $X$ maximizing $\sum^{|\setName|}_{i=1} \rank X_i$  over $\perpName \cap \approxName$  is given by any optimal solution $(X,X_i,T_i)$  to the following SDP:
\begin{align} \label{sdp:sumOfConesMaxRank}
\begin{array}{lll}
 \mbox{\rm maximize}  &  \sum^{|\setName|}_{i=1} \trace{T_i} \  \\
 \mbox{\rm subject to } & X \in \perpName,\\
&X = \sum^{|\setName|}_{i=1} W_i X_i W^T_i   & \mbox{ \rm  i.e. } X \in \approxName \\
& X_i \succeq T_i  & \forall i\in\{1, \ldots, |\setName|\}\\
&  I \succeq  T_i \succeq 0 &  \forall i\in\{ 1, \ldots, |\setName|\}.
\end{array} 
\end{align}


\begin{proof}
Let $r_{\max}$ equal the maximum of  $\sum^{|\setName|}_{i=1} \rank X_i$ over the  set of feasible $X_i$.  We will
show at optimality $\sum^{|\setName|}_{i=1} \rank X_i = r_{\max}$. 

To begin, the constraint $I \succeq T_i \succeq 0$ implies the eigenvalues of $T_i$ are  less than one. Hence,  $\rank T_i  \ge \trace T_i $.  
Since  $X_i \succeq T_i$ , we also have $\rank{X_i} \ge \rank{T_i}$.  Thus,  any feasible $(X_i,T_i)$ pair satisfies
\begin{align} \label{ineq:maxrank}
r_{\max} \ge \sum^{|\setName|}_{i=1} \rank{X_i}  \ge   \sum^{|\setName|}_{i=1} \rank{T_i}  \ge  \sum^{|\setName|}_{i=1} \trace T_i.
\end{align}

Now note for any feasible $(X,X_i)$ we can pick $\alpha > 0$  and construct a feasible point $(\alpha X, \alpha X_i, \hat{T}_i)$  that satisfies $\sum^{|\setName|}_{i=1} \trace{\hat{T_i}} =  \sum^{|\setName|}_{i=1}\rank{X_i}$; if $X_i$ has  eigen-decomposition $\sum_j \lambda_j u_j u_j^T$ for $\lambda_j > 0$, simply take  $\hat{T_i} = \sum_j u_j u_j^T$ and $\alpha$ equal to
\[
\max \bigcup_i \left\{ \frac{1}{\lambda} : \lambda \mbox{ is a  positive eigenvalue of $X_i$ } \right\}.
\]  
Hence, some feasible point $(\hat{X},\hat{X_i},\hat{T_i})$ satisfies  $\sum^{|\setName|}_{i=1} \trace{\hat{T_i}} = r_{\max}$. Therefore, the optimal $(X,X_i,T_i)$ satisfies 
\[
\sum^{|\setName|}_{i=1} \trace T_i  \ge  r_{\max}.
\]
Combining this inequality with \eqref{ineq:maxrank} yields that at optimality
\[
\sum^{|\setName|}_{i=1} \trace T_i   = \sum^{|\setName|}_{i=1}\rank{X_i}  = r_{\max},
\]
which completes the proof.
\end{proof}
\end{lem}

