s.t. &\quad W_{A} \succeq 0,\quad W_{B} \succeq 0,\quad\mathrm{Tr}[W_A] = \mathrm{Tr}[W_B] = 1\\
&\quad\Lambda_{A\to C_A}\left(W_{A}\right)=X_{C_A},\quad\Gamma_{B\to C_B}\left(W_{B}\right)=Y_{C_B}, 
\end{align}
