\begin{align}
\rho_{A|z}:= \frac{\mathrm{Tr}_{Z}\Big[\rho_{AZ} \left(1_{A} \otimes \ket{z}\bra{z}\right)\Big]}{\mathrm{Tr}\Big[\rho_{AZ} \left(1_{A} \otimes \ket{z}\bra{z}\right)\Big]}.
\end{align}
We simply write $\exc{z_{1}^{m}}{\cdot}$ for the expectation over the choices of $z_1^m$ and the distribution will be clear from the context.


To prove the de Finetti theorem, we will crucially make use of so-called informationally complete measurements for which the loss in distinguishability, or {\it distortion}, can be bounded.

\begin{lemma}{\cite[Lemma 14]{brandao13b}}\label{lem:product-ic-meas}
There exist a product measurement $\mathcal{M}_A\otimes\mathcal{M}_B$ with finitely many outcomes such that for any Hermitian and traceless matrix $\xi_{AB}$ on $A\otimes B$, we have 
\begin{align}
\|(\mathcal{M}_{A} \otimes \mathcal{M}_{B})(\xi_{AB})\|_1 \geq \frac{1}{18\sqrt{d_A d_B}}\| \xi_{AB}\|_{1}.
\end{align}
\end{lemma}

This \cite[Lemma 14]{brandao13b} follows from the methods in \cite{lancien13}. More generally, we define the {\it minimal distortion} for the bipartite system $A \otimes B$ as
\begin{align}\label{eq:def-f1}
f(A, B):=\inf_{\cM_{A}, \cM_{B}}\max_{\substack{\xi_{AB}^{\dagger} = \xi_{AB}\\ \xi_A = 0, \xi_B = 0}} \frac{\| \xi_{AB} \|_1}{\| (\cM_{A} \otimes \cM_B)(\xi_{AB})\|_1},
\end{align}
where the infimum is over all product measurements on $AB$. In this notation, Lemma~\ref{lem:product-ic-meas} shows that
\begin{align}
f(A, B) \leq 18 \sqrt{d_A d_B}.
\end{align}
Note that in the definition of $f(A,B)$ we restricted the maximization to matrices satisfying $\xi_{A} = 0$ and $\xi_{B} = 0$ because this is sufficient for us.

A drawback of Lemma~\ref{lem:product-ic-meas} is that the distortion depends on the dimension $d_A$. More generally, we define the {\it minimal distortion with side information} for a system $B$ as
\begin{align}\label{eq:def-f2}
f(B|\cdot):=\inf_{\cM_B} \sup_{\substack{\xi_{AB}^\dagger=\xi_{AB}\\ \xi_{A} = 0, \xi_B = 0}} \frac{\| \xi_{AB} \|_1}{\| (\cI_{A} \otimes \cM_B)(\xi_{AB})\|_1},
\end{align}
where the infimum is over all measurements on $B$ and the supremum is over all finite-dimensional systems $A$. In Lemma~\ref{lem:ic-meas-side-info} we give an elementary proof that
\begin{align}
f(B|\cdot) \leq d_B^2 (d_B+1)
\end{align}
using state two-designs and properties of weighted non-commutative $L_p$-spaces. In fact, after completion of our work we realised that methods from operator space theory even give the stronger bound
\begin{align}
f(B|\cdot) \leq \sqrt{18d_B^3},
\end{align}
which is discussed in \cite[Equation 66]{brandao13c}. We leave it as an open question to determine the exact dimensional dependence of the minimal distortion with side information.


We note that the existence of such two-designs is known for any dimension, see e.g., \cite[Corollary 5.3]{scott08} for unitary two-designs and applying these unitaries to any fixed state leads to a state two-design.

