\begin{lemma}\cite{brandao13b}\label{lem:conditioning-breaks-correlations}
Let $\rho_{A Z_1^n}$ be a classical-quantum state with the $Z_1^n$-systems classical and $\mathcal{U}^\pi_{Z_1^n}(\rho_{A Z_1^n})=\rho_{A Z_1^n}$ for all $\pi\in\mathfrak{S}_n$. Then, there exists $0\leq m < n$ such that
\begin{align}
\exc{z_{1}^{m}}{D(\rho_{AZ_{m+1}|z_1^m} \| \rho_{A|z_1^m} \otimes \rho_{Z_{m+1}|z_1^m})} &\leq \frac{\log d_A}{n}
\end{align}
as well as
\begin{align}
\exc{z_{1}^{m}}{\| \rho_{AZ_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{Z_{m+1}|z_1^m} \|_1^2} &\leq \frac{(2 \ln 2) \log d_A}{n},
\end{align}
where $\ln(\cdot)$ denotes the natural logarithm.
\end{lemma}

\begin{proof}
For the quantum mutual information we have $I\left(A:Z_1^n\right)_{\rho}:=D(\rho_{AZ_1^n}\|\rho_A\otimes \rho_{Z_1^n}) \leq \log d_A$ as well as (see, e.g., \cite[Chapter 11]{nielsen00})
\begin{align}
I\left(A:Z_1^n\right)_{\rho}=\sum_{m=0}^{n-1} I(A : Z_{m+1} | Z_1^m)_{\rho}
\end{align}
for the quantum conditional mutual information $I(A : Z_{m+1} | Z_1^m)_\rho:=I(A:Z_1^{m+1})_\rho-I(A:Z_1^m)_\rho$. As a result, there exists an $m \in \{0, \cdots, n-1\}$ such that $I(A : Z_{m+1} | Z_1^m)_{\rho} \leq \frac{\log d_A}{n}$, which implies
\begin{align}
\exc{z_1^m}{I(A:Z_{m+1})_{\rho_{AZ_{m+1}|z_1^m}}} \leq \frac{\log d_A}{n},
\end{align}
where we used $I(A : Z_{m+1} | Z_1^m)_{\rho}=\exc{z_1^m}{I(A:Z_{m+1})_{\rho_{AZ_{m+1}|z_1^m}}}$, which holds since the conditioning systems are classical. The second statement then follows directly from Pinsker's inequality $D(\rho\|\sigma)\geq\frac{1}{2\ln 2}\left\|\rho-\sigma\right\|_1^2$ \cite[Theorem 5.38]{watrous-book}.
\end{proof}

\begin{theorem}\label{thm:main-deFinetti}
Let $\rho_{AB_1^n}$ be a quantum state, $\Lambda_{A\to C_A},\Gamma_{B\to C_B}$ linear maps, and $X_{C_A},Y_{C_B}$ matrices such that
\begin{align}
\mathcal{U}_{B_1^n}^\pi(\rho_{AB_1^n})&=\rho_{AB_1^n}\;\forall\pi\in\mathfrak{S}_n\qquad\text{symmetric with respect to $A$}\\
\Lambda_{A\to C_A}(\rho_{AB_1^n})&=X_{C_A}\otimes\rho_{B_1^n}\qquad\quad\;\;\text{linear constraint on $A$}\\
\Gamma_{B_n\to C_B}(\rho_{B_1^n})&=\rho_{B_1^{n-1}}\otimes Y_{C_B}\qquad\quad\text{linear constraint on $B$}.
\end{align}
Then, we have that
\begin{align}
\left\|\rho_{AB}-\sum_{i\in I}p_i\sigma^i_{A}\otimes\omega^i_B\right\|_1\leq&\;\min\big\{ f(A,B) , f(B|\cdot) \big\}\sqrt{ \frac{(2 \ln 2) \log \left(d_A\right)}{n}}
\end{align}
with $\{p_i\}_{i\in I}$ a probability distribution, $\rho_{AB}=\tr_{B_2^n}\left[\rho_{AB_1^n}\right]$, and quantum states $\sigma^i_A,\omega_B^i$ such that for $i\in I$:
\begin{align}
\Lambda_{A\to C_A}\left(\sigma^i_A\right)=X_{C_A}\quad\text{and}\quad\Gamma_{B\to C_B}\left(\omega^i_B\right)=Y_{C_B}.
\end{align}
As stated in Section~\ref{sec:proof-tools}, we can, e.g., take $f(A,B)\leq18\sqrt{d_A d_B}$ or $f(B|\cdot)\leq\sqrt{18d_B^3}$.
\end{theorem}

\begin{proof}
Let $\cM_{B}$ be a measurement of the $B$ system and call the outcome system $Z$. Consider the state $\rho_{AZ_1^n}$ obtained by measuring all the $B$ systems with $\cM_{B}$. This distribution is symmetric with respect to $A$ and so we can apply Lemma~\ref{lem:conditioning-breaks-correlations}. We find that there exists an $m \in \{0, \cdots, n-1\}$ such that
\begin{align}
\exc{z_1^m}{\| \rho_{AZ_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{Z_{m+1}|z_1^m} \|_1^2} \leq \frac{(2 \ln 2) \log d_{A}}{n}.
\end{align}
Note that we have for any $z_1^m$, $\rho_{AZ_{m+1}|z_1^m} = (\cI_{A} \otimes \cM_{B})(\rho_{AB_{m+1}|z_1^m})$ and correspondingly $\rho_{Z_{m+1}|z_1^m} = \cM_{B}(\rho_{B_{m+1}|z_1^m})$. Now, we choose the measurement $\cM_{B}$ to be as in Lemma~\ref{lem:ic-meas-side-info} and achieving $f(B|\cdot)$ in \eqref{eq:def-f2}, we get that $\| \xi_{AB} \|_1^2 \leq f(B|\cdot)^2 \| (\cI_{A} \otimes \cM_{B})(\xi_{AB}) \|_1^2$, where $\xi_{AB} = \rho_{AB_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{B_{m+1}|z_1^m}$. As a result, we have
\begin{align}
\exc{z_1^m}{\| \rho_{AB_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{B_{m+1}|z_1^m} \|_1^2} \leq f(B|\cdot)^2\frac{(2 \ln 2) \log d_{A}}{n}.
\end{align}
But note we can also choose measurements $\cM_{A}$ and $\cM_{B}$ achieving $f(A,B)$ in \eqref{eq:def-f1}. In this case,
\begin{align} 
\| \rho_{AB_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{B_{m+1}|z_1^m} \|_1^2 &\leq f(A,B)^2\| (\cM_A \otimes \cM_{B})(\rho_{AB_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{B_{m+1}|z_1^m}) \|_1^2 \\
&\leq f(A,B)^2 \| (\cI_A \otimes \cM_{B})(\rho_{AB_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{B_{m+1}|z_1^m}) \|_1^2 \\
&= f(A,B)^2 \| \rho_{AZ_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{Z_{m+1}|z_1^m} \|_1^2 ,
\end{align}
where we used the fact that the trace norm cannot increase when applying the quantum channel $\cM_{A}$ \cite[Theorem 3.39]{watrous-book}. As a result, we get
\begin{align}
\exc{z_1^m}{\| \rho_{AB_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{B_{m+1}|z_1^m} \|_1^2} \leq f(A,B)^2 \frac{(2 \ln 2) \log d_{A}}{n}.
\end{align}
Now, using the convexity of the square function, we get
\begin{align}
\exc{z_{1}^m}{\| \rho_{AB_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{B_{m+1}|z_1^m} \|_1}&\leq \sqrt{\exc{z_{1}^m}{\| \rho_{AB_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{B_{m+1}|z_1^m} \|^2_1}} \\
&\leq  \min\big\{f(A, B), f(B|\cdot)\big\}\sqrt{\frac{(2 \ln 2) \log d_{A}}{n}}.
\end{align}
Then, using the convexity of the norm and the fact that $\exc{z_1^m}{\rho_{AB_{m+1}|z_1^m}} = \rho_{AB_{m+1}}$, we obtain
\begin{align}
\left\| \rho_{AB_{m+1}} - \exc{z_1^m}{\rho_{A|z_1^m} \otimes \rho_{B_{m+1}|z_1^m}} \right\|_1 &\leq \min\big\{f(A,B), f(B|\cdot)\big\}\sqrt{\frac{(2 \ln 2) \log d_{A}}{n}}.
\end{align}
The state $\exc{z_1^m}{\rho_{A|z_1^m} \otimes \rho_{B_{m+1}|z_1^m}}$ corresponds to our candidate mixture of product states. It now remains to show that all the states in the mixture satisfy the linear constraints. Indeed we have for any $z_1^m$, writing $M_{z}$ for matrices of the measurement $\cM_{B}$,
\begin{align}
\Lambda_{A \to C_{A}}(\rho_{A|z_1^m})
&= \frac{\tr_{B_1^m}\Big[(1_{A}\otimes M_{z_1} \otimes \cdots \otimes M_{z_m}) \Lambda_{A \to C_{A}}(\rho_{A B_1^m})\Big]}{\tr\Big[(1_{A}\otimes M_{z_1} \otimes \cdots \otimes M_{z_m})\rho_{A B_1^m}\Big]} \\
&= \frac{\tr_{B_1^m}\Big[(1_{A}\otimes M_{z_1} \otimes \cdots \otimes M_{z_m}) (X_{C_A} \otimes \rho_{B_1^m}) \Big]}{\tr\Big[(1_{A}\otimes M_{z_1} \otimes \cdots \otimes M_{z_m})\rho_{A B_1^m}\Big]} \\
&= X_{C_A},
\end{align}
and similarly
\begin{align}
\Gamma_{B \to C_{B}}(\rho_{B_{m+1}|z_1^m})
&= \frac{\tr_{B_1^m}\Big[(M_{z_1} \otimes \cdots \otimes M_{z_m} \otimes 1_{C_{B}} ) \Gamma_{B_{m+1} \to C_{B}}(\rho_{B_1^{m+1}})\Big]}{\tr\Big[(M_{z_1} \otimes \cdots \otimes M_{z_m} \otimes 1_{B_{m+1}} )\rho_{B_1^{m+1}}\Big]} \\
&= \frac{\tr_{B_1^m}\Big[(M_{z_1} \otimes \cdots \otimes M_{z_m} \otimes 1_{B_{m+1}} ) (\rho_{B_1 \cdots B_{m}} \otimes Y_{C_B})\Big]}{\tr\Big[(M_{z_1} \otimes \cdots \otimes M_{z_m} \otimes 1_{B_{m+1}} )\rho_{B_1^{m+1}}\Big]} \\
&= Y_{C_B}.
\end{align}
\end{proof}

\begin{proof}
We have by construction $0 \leq \mathrm{SDP}_n - Q $ and the remaining inequality arises from
\begin{align}
\mathrm{Tr}\left[G_{AB} W_{AB_1}\right]&=\mathrm{Tr}\left[G_{AB} (W_{A} \otimes W_{B})\right]+\mathrm{Tr}\left[G_{AB}\left(W_{AB_1} - W_{A} \otimes W_{B}\right)\right] \\
& \leq \mathrm{Tr}\left[G_{AB} (W_{A} \otimes W_{B})\right]+\| G_{AB} \|_\infty \cdot \|W_{AB_1} - W_{A} \otimes W_{B} \|_1 \\
&\leq\mathrm{Tr}\left[G_{AB} (W_{A} \otimes W_{B})\right]+\frac{\mathrm{poly}(d)}{\sqrt{n}},
\end{align}
where we used H\"older's inequality and the de Finetti argument as in Theorem \ref{thm:main-deFinetti}.
\end{proof}

\begin{lemma}\label{lem:ic-meas-side-info}
Consider a state two-design on $B$, i.e., a set of rank-one projectors $\{P_z\}_{z \in \{1, \dots, t\}}$ such that $\frac{1}{t} \sum_{z=1}^t P_z \otimes P_z = \frac{2 P^{\mathrm{sym}}}{d_B (d_B+1)}$, where $P^{\mathrm{sym}}$ denotes the projector onto the symmetric subspace of $B \otimes B$. Let $\mathcal{M}_B$ be the measurement defined as
\begin{align}
\mathcal{M}_B(X) = \sum_{z} \frac{d_B}{t} \cdot\mathrm{Tr}\big[P_z X\big] |z\rangle\langle z|,
\end{align}
and $\xi_{AB}$ be a Hermitian matrix on $A\otimes B$. Then, we have that
\begin{align}
\| (\mathcal{I}_{A} \otimes \mathcal{M}_B)(\xi_{AB}) \|_1\geq \frac{1}{d_B^2 (d_B+1)} \| \xi_{AB} \|_{1}.
\end{align}
\end{lemma}

\begin{proof}
For any full rank quantum state $\sigma_{A}$, we have by a H\"older type inequality for $\sigma$-weighted Schatten norms that (see, e.g., \cite{OLKIEWICZ1999246} or \cite{beigi13})
\begin{align}
\| (\mathcal{I}_{A} \otimes \mathcal{M}_B)(\xi_{AB}) \|_1 \geq  \frac{\left\| \sigma_{A}^{-1/4} (\mathcal{I}_{A} \otimes \mathcal{M})(\xi_{AB}) \sigma_{A}^{-1/4} \right\|^2_{2}}{\left\| \sigma_{A}^{-1/2} (\mathcal{I}_{A} \otimes \mathcal{M}_B)(\xi_{AB}) \sigma_{A}^{-1/2} \right\|_{\infty}}.
\end{align}
For example, the above inequality can be obtained using \cite[Corollary 3]{beigi13} with the operator $\sigma_{A}^{-1/2} (\mathcal{I}_{A} \otimes \mathcal{M}_B)(\xi_{AB}) \sigma_{A}^{-1/2}$, weight $\sigma$, and $p_\theta = 2$, $\theta = 1/2$, $p_0 = 1$, $p_1 = \infty$. We note that this particular H\"older type inequality for $\sigma$-weighted norms is elementary and follows easily from the usual H\"older inequality, but one way of potentially improving the dimension dependence in Lemma~\ref{lem:ic-meas-side-info} might be to use another H\"older inequality, in particular the $(1,4)$ inequality.

Henceforth, we abbreviate $d\equiv d_B$. To further bound the numerator, letting $\tilde{\xi}_{AB}:=\sigma_{A}^{-1/4} \xi_{AB} \sigma_{A}^{-1/4}$ we get
\begin{align}
\| (\mathcal{I}_{A} \otimes \mathcal{M}_B)(\tilde{\xi}_{AB}) \|^2_{2}
&= \left\| \sum_{z} \frac{d}{t} |z\rangle \langle z| \otimes  \mathrm{Tr}_{B}\left[(1_{A} \otimes P_z) \tilde{\xi}_{AB}\right] \right\|_2^2 \\
&= \sum_{z}  \frac{d^2}{t^2} \mathrm{Tr}\left[\mathrm{Tr}_{B}\left[(1_{A} \otimes P_z) \tilde{\xi}_{AB}\right] \otimes \mathrm{Tr}_{\bar{B}}\left[(1_{\bar{A}} \otimes P_z) \tilde{\xi}_{\bar{A}\bar{B}}\right]^{\dagger} F_{A\bar{A}} \right] \\
&= \sum_{z} \frac{d^2}{t^2} \mathrm{Tr}\left[\left(\left((1_{A} \otimes P_z) \tilde{\xi}_{AB}\right) \otimes \left((1_{\bar{A}} \otimes P_z) \tilde{\xi}_{\bar{A}\bar{B}}\right)^{\dagger}\right)\left(F_{A\bar{A}} \otimes1_{B\bar{B}}\right)\right] \\
&= \frac{d^2}{t^2} \mathrm{Tr}\left[\left(\tilde{\xi}_{AB} \otimes \tilde{\xi}_{\bar{A}\bar{B}}^{\dagger}\right)\left(\sum_{z} (1_{A\bar{A}} \otimes P_z \otimes P_{z})\right)\left(F_{A\bar{A}} \otimes1_{B \bar{B}}\right)\right] \\
&= \frac{1}{t} \frac{d^2}{d(d+1)} \mathrm{Tr}\left[\left(\tilde{\xi}_{AB} \otimes \tilde{\xi}_{\bar{A}\bar{B}}^{\dagger}\right) (1_{A\bar{A}} \otimes (1_{B\bar{B}} + F_{B\bar{B}}))\left(F_{A\bar{A}} \otimes1_{B \bar{B}}\right)\right] \\
&= \frac{1}{t} \frac{d^2}{d(d+1)} \Big(\underbrace{\mathrm{Tr}\left[\tilde{\xi}_{A} \tilde{\xi}_{A}^{\dagger}\right]}_{\geq 0} + \underbrace{\mathrm{Tr}\left[\tilde{\xi}_{AB} \tilde{\xi}_{AB}^{\dagger}\right]}_{=\left\|\tilde{\xi}_{AB}\right\|_2^2} \Big) \\
&\geq \frac{1}{t}\frac{d^2}{d^2 (d+1)} \| \xi_{AB} \|^2_{1} ,
\end{align}
where $F$ denotes the swap operator (as defined in Section \ref{sec:notation}) and in the last step used the H\"older inequality (see, e.g., \cite{bhatia97})
\begin{align}
\left\|\xi_{AB}\right\|_1=\left\|\sigma^{1/4}\sigma^{-1/4}\xi_{AB}\sigma^{-1/4}\sigma^{1/4}\right\|_1\leq\left\|\sigma^{1/4}\otimes1_B\right\|_4\left\|\sigma_A^{-1/4}\xi_{AB}\sigma_A^{-1/4}\right\|_2\left\|\sigma^{1/4}\otimes1_B\right\|_4\leq\sqrt{d}\left\|\tilde{\xi}_{AB}\right\|_2.
\end{align}
For further bounding the denominator we write
\begin{align}
\left\| \sigma_{A}^{-1/2} (\mathcal{I}_{A} \otimes \mathcal{M}_B)(\xi_{AB}) \sigma_{A}^{-1/2} \right\|_\infty
&= \max_{z} \frac{d}{t} \left\| \mathrm{Tr}_{B}\left[(1_{A} \otimes P_z) \sigma_{A}^{-1/2} \xi_{AB} \sigma_{A}^{-1/2}\right]\right\|_\infty \\
&\leq \frac{d}{t} \max_{\ket{\phi}_{A}, \ket{\psi}_{B}} \bra{\phi}_{A} \otimes \bra{\psi}_{B} \sigma_{A}^{-1/2} \xi_{AB} \sigma_{A}^{-1/2} \ket{\phi}_{A} \otimes \ket{\psi}_{B} \\
&\leq \frac{d}{t} \left\| \sigma_{A}^{-1/2} \xi_{AB} \sigma_{A}^{-1/2} \right\|_\infty,
\end{align}
where we used the fact that $P_z$ is a rank 1 projector. Now, observe that for any $\xi_{AB}$, there exists a $\sigma_A$ of unit trace such that
\begin{align}
\frac{\sqrt{\xi_{AB} \xi_{AB}^{\dagger}}}{\| \xi_{AB} \|_{1}} \preceq d\cdot\sigma_{A} \otimes1_{B}.
\end{align}
This just follows from, e.g., \cite[Lemma B.6]{bertachristandl11}, where it is shown that we can in fact choose\footnote{By a continuity argument $\sigma_A$ can be assumed to have full rank.}
\begin{align}
\sigma_{A} = \| \xi_{AB} \|_{1}^{-1}\cdot\mathrm{Tr}_{B}\left[\sqrt{\xi_{AB} \xi_{AB}^{\dagger}}\right].
\end{align}
As a result, we have
\begin{align}
\sqrt{\xi_{AB} \xi_{AB}^{\dagger}} \preceq d\| \xi_{AB} \|_{1}\cdot\sigma_{A} \otimes1_{B}.
\end{align}
As $\xi_{AB}$ is Hermitian, we can decompose it into the positive and negative part $\xi_{AB} = P - Q$ with $P$ and $Q$ positive semidefinite and $PQ = 0$, then $\sqrt{\xi_{AB} \xi_{AB}^{\dagger}} = P + Q$ and so $-\sqrt{\xi_{AB} \xi_{AB}^{\dagger}} \preceq \xi_{AB} \preceq \sqrt{\xi_{AB} \xi_{AB}^{\dagger}}$. Thus, we get
\begin{align}
- d_{B} \| \xi_{AB} \|_1\cdot\sigma_{A} \otimes1_{B} \preceq \xi_{AB} \preceq d_{B} \| \xi_{AB} \|_1 \cdot\sigma_{A} \otimes1_{B},
\end{align}
and we find $\| \sigma_{A}^{-1/2} \xi_{AB} \sigma_{A}^{-1/2} \|_{\infty} \leq d\| \xi_{AB} \|_1$. This concludes the proof.
\end{proof}

