\begin{align}
\exc{z_1^m}{\| \rho_{AZ_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{Z_{m+1}|z_1^m} \|_1^2} \leq \frac{(2 \ln 2) \log d_{A}}{n}.
\end{align}

\begin{proof}
