&\leq \|B^{\top}(z_{n+1}-z_n)\| +(\nu\ell_\psi +2c)\|y_{n+1}-y_{n})\|.
\end{align}

Since $\partial_L ^z \mathcal{F}(w_n) =\mathbf{Ax}_{n+1} + By_{n+1} -b =\frac{1}{\rho}(z_{n+1} -z_n)$ and
$\partial_L ^t \mathcal{F}(w_n) =-2c(y_{n+1}-y_{n})$, it holds that
\begin{align}\label{eq:dzdt}
\dist(0,\partial_L ^{z} \mathcal{F}(w_n)) =\frac{1}{\rho}\|z_{n+1}-z_n\| \text{~~and~~}
\dist(0,\partial_L ^{t} \mathcal{F}(w_n)) =2c\|y_{n+1}-y_n\|.    
\end{align}

Combining \eqref{eq:dxi}, \eqref{eq:dy}, and \eqref{eq:dzdt}, noting that $\limsup_{n\to +\infty} \mu_n =\overline{\mu} <+\infty$, and using \eqref{eq:BTZy} and \eqref{eq:zy} in the proof of Theorem~\ref{t:cvg}, we derive that there exists $n_0\in \mathbb{N}^*$ and $C_2 \in \mathbb{R}_{++}$ such that, for all $n\geq n_0$, 

\begin{align*}
\dist(0, \partial_L \mathcal{F}(w_n)) 
\leq C_2 \left(\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\| +\|y_{n+1}-y_n\| +\|y_{n}-y_{n-1}\|\right) 
\leq C_2(\Delta_{n-1} +\Delta_{n-2}).
\end{align*}

\ref{t:full_cvg}: We see that all the conditions in the \emph{abstract convergence} framework \cite[Theorem~5.1]{BDL22} are satisfied with $I =\{1,2\}$, $\lambda_1=\lambda_2=1/2$, $\alpha_n \equiv C_1$, $\beta_n \equiv 1/(2C_2)$, and $\varepsilon_n \equiv 0 $. By \cite[Theorem~5.1(i)]{BDL22}, 
\begin{align*}
\sum_{n=0}^{+\infty} (\|\mathbf{x}_{n+2}-\mathbf{x}_{n+1}\|+\|y_{n+2}-y_{n+1}\|) =\sum_{n=0}^{+\infty} \Delta_n < +\infty,
\end{align*}

which implies that $\sum_{n=0}^{+\infty} \|\mathbf{x}_{n+1}-\mathbf{x}_{n}\| <+\infty$ and $\sum_{n=0}^{+\infty} \|y_{n+1}-y_{n}\| < +\infty$. Together with \eqref{eq:zy}, we derive that $\sum_{n=0}^{+\infty} \|z_{n+1}-z_n\|<+\infty$, and hence 
\begin{align*}
\sum_{n=0}^{+\infty} \|(\mathbf{x}_{n+1},y_{n+1},z_{n+1})-(\mathbf{x}_{n},y_{n},z_{n})\| < +\infty,
\end{align*}
which yields the convergence of $(\mathbf{x}_{n},y_{n},z_{n})_{n\in\mathbb{N}}$ to $(\mathbf{x}^{*},y^{*},z^{*})$. In view of Theorem~\ref{t:cvg}\ref{t:cvg_seq}, $(\mathbf{x}^{*},y^{*},z^{*})$ is a stationary point of $\mathcal{L}_\rho$.

\ref{t:full_rate_linear}: According to \cite[Theorem~5.1(iv)]{BDL22}, there exist $\gamma_0\in \mathbb{R}_{++}$ and $\zeta\in \left(0,1\right)$ such that, for all $n\in \mathbb{N}^*$, 
\begin{align*}
\|(\mathbf{x}_{n},y_{n})-(\mathbf{x}^{*},y^{*})\|\leq\gamma_0 \zeta^{\frac{n}{2}} \text{~~and~~}
|\mathcal{F}(\mathbf{x}_{n},y_{n},z_{n},y_{n-1})-\mathcal{F}(\mathbf{x}^{*},y^{*},z^{*},y^*)| \leq \gamma_0\zeta^n.
\end{align*}

We derive that, for all $n\in \mathbb{N}^*$, $\|\mathbf{x}_n-\mathbf{x}^{*}\|\leq \gamma_0\zeta^{\frac{n}{2}}$ and $\|y_n-y^{*}\|\leq \gamma_0\zeta^{\frac{n}{2}}$, which yields 
\begin{align*}
\|y_n-y_{n-1}\| \leq \|y_n-y^{*}\|+\|y_{n-1}-y^{*}\| \leq (1+\zeta^{-\frac{1}{2}})\gamma_0\zeta^{\frac{n}{2}}.    
\end{align*}
By passing to the limit in \eqref{eq:B'z}, $B^\top z^{*}=-\nabla H(y^{*})$. Following the same steps as in \eqref{eq:BTZy} and \eqref{eq:zy}, we obtain that, for all $n\in \mathbb{N}^*$,
\begin{align*}
\|z_n-z^{*}\| &\leq \frac{\ell_H}{\sqrt{\lambda}}\|y_n-y^{*}\| + \frac{\nu \ell_{\psi}}{\sqrt{\lambda}}\|y_{n}-y_{n-1}\|\leq \gamma_1\zeta^{\frac{n}{2}}, \text{~~where~} \gamma_1 :=\frac{\ell_H\gamma_0+(1+\zeta^{-\frac{1}{2}})\nu\ell_{\psi}\gamma_0}{\sqrt{\lambda}}.
\end{align*}

Consequently,
\begin{align*}
&\|(\mathbf{x}_{n},y_{n},z_{n})-(\mathbf{x}^{*},y^{*},z^{*})\| \leq \|\mathbf{x}_{n}-\mathbf{x}^{*}\| + \|y_{n}-y^{*}\| + \|z_{n}-z^{*}\|\leq (2\gamma_0 +\gamma_1)\zeta^{\frac{n}{2}}, \\
&\|\mathbf{Ax}_n+By_n-b\| =\frac{1}{\rho}\|z_n-z_{n-1}\| \leq \frac{1}{\rho}(\|z_n-z^{*}\| +\|z_{n-1}-z^{*}\|) \leq \frac{(1+\zeta^{-\frac{1}{2}})\gamma_1}{\rho} \zeta^{\frac{n}{2}}, \\
\text{and~} &\|z_n\| \leq \|z_n-z^{*}\| + \|z^{*}\| \leq \gamma_1 \zeta^{\frac{n}{2}} + \|z^{*}\|.
\end{align*}

We now deduce from the definition of $\mathcal{F}$ that
\begin{align*}
|\mathcal{L}_{\rho}(\mathbf{x}_{n},y_{n},z_{n})- \mathcal{L}_{\rho}(\mathbf{x}^{*},y^{*},z^{*})|&= \left|\mathcal{F}(\mathbf{x}_{n},y_{n},z_{n},y_{n-1})-\mathcal{F}(\mathbf{x}^{*},y^{*},z^{*},y^*) - c\|y_n-y_{n-1}\|^2\right|\\
&\leq |\mathcal{F}(\mathbf{x}_{n},y_{n},z_{n},y_{n-1})-\mathcal{F}(\mathbf{x}^{*},y^{*},z^{*},y^*)| + c\|y_n-y_{n-1}\|^2\\
&\leq \gamma_2\zeta^n, \text{~~where~} \gamma_2 :=\gamma_0 + c(1+\zeta^{-\frac{1}{2}})^2\gamma_0^2
\end{align*}

and from the definition of $\mathcal{L}_\rho$ that 
\begin{align*}
|F(\mathbf{x}_n,y_n)-F(\mathbf{x}^{*},y^{*})| &= |\mathcal{L}_{\rho}(\mathbf{x}_n,y_n,z_n)-\mathcal{L}_{\rho}(\mathbf{x}^{*},y^{*},z^{*})-\langle z_n, \mathbf{Ax}_n + By_n-b\rangle - \frac{\rho}{2}\|\mathbf{Ax}_n + By_n-b\|^2| \\
&\leq |\mathcal{L}_{\rho}(\mathbf{x}_n,y_n,z_n)-\mathcal{L}_{\rho}(\mathbf{x}^{*},y^{*},z^{*})| + \|z_n\|\|\mathbf{Ax}_n + By_n-b\| + \frac{\rho}{2}\|\mathbf{Ax}_n + By_n-b\|^2  \\ 
&\leq \gamma_2\zeta^n + \left(\gamma_1 \zeta^{\frac{n}{2}} + \|z^{*}\|\right)\frac{(1+\zeta^{-\frac{1}{2}})\gamma_1}{\rho} \zeta^{\frac{n}{2}}+ \frac{(1+\zeta^{-\frac{1}{2}})^2\gamma_1^2}{2\rho}\zeta^n \\
&\leq \left(\gamma_2 +\frac{(3+\zeta^{-\frac{1}{2}})(1+\zeta^{-\frac{1}{2}})\gamma_1^2}{2\rho} +\frac{\|z^{*}\|(1+\zeta^{-\frac{1}{2}})\gamma_1}{\rho}\right)\zeta^{\frac{n}{2}},
\end{align*}
where the last inequality follows from the fact that $\zeta^n \leq \zeta^{\frac{n}{2}}$ since $\zeta \in (0,1)$. By letting 
\begin{align*}
\overline{\gamma} =\max \left\{ 2\gamma_0+\gamma_1, \frac{(1+\zeta^{-\frac{1}{2}})\gamma_1}{\rho}, \gamma_2 +\frac{(3+\zeta^{-\frac{1}{2}})(1+\zeta^{-\frac{1}{2}})\gamma_1^2}{2\rho} +\frac{\|z^{*}\|(1+\zeta^{-\frac{1}{2}})\gamma_1}{\rho} \right\} 
\end{align*}
and increasing it if necessary, we arrive at the conclusion.

\ref{t:full_rate_sublinear}: Following the arguments in \cite[Theorem~5.1(iv)]{BDL22} and \cite[Theorem~2(iii)]{Attouch2007}, we find $\gamma_0 \in \mathbb{R}_{++}$ such that, for all $n\in \mathbb{N}^*$, 
\begin{align*}
\|(\mathbf{x}_{n},y_{n})-(\mathbf{x}^{*},y^{*})\|\leq \gamma_0 n^{-\frac{1-\kappa}{2\kappa-1}} \text{~~and~~}
|\mathcal{F}(\mathbf{x}_{n},y_{n},z_{n},y_{n-1})-\mathcal{F}(\mathbf{x}^{*},y^{*},z^{*},y^*)| \leq \gamma_0 n^{-\frac{2-2\kappa}{2\kappa-1}}.
\end{align*}

Similar to \ref{t:full_rate_linear}, for all $n\geq 2$, since $n-1\geq \frac{1}{2}n$ and $\frac{1-\kappa}{2\kappa-1} >0$, we derive that 
\begin{align*}
&\|(\mathbf{x}_{n},y_{n},z_{n})-(\mathbf{x}^{*},y^{*},z^{*})\| \leq (2\gamma_0+\gamma_1) n^{-\frac{1-\kappa}{2\kappa-1}},\\
&\|\mathbf{Ax}_n+By_n-b\|\leq \frac{(1 +2^{\frac{1-\kappa}{2\kappa-1}})\gamma_1}{\rho} n^{-\frac{1-\kappa}{2\kappa-1}},\\
&|\mathcal{L}_{\rho}(\mathbf{x}_{n},y_{n},z_{n})- \mathcal{L}_{\rho}(\mathbf{x}^{*},y^{*},z^{*})|\leq \gamma_2 n^{-\frac{2-2\kappa}{2\kappa-1}},
\end{align*}

and that
\begin{align*}
|F(\mathbf{x}_n,y_n)-F(\mathbf{x}^{*},y^{*})| &\leq \gamma_2 n^{-\frac{2-2\kappa}{2\kappa-1}}+ \left(\gamma_1 n^{-\frac{1-\kappa}{2\kappa-1}} + \|z^{*}\|\right)\frac{(1 +2^{\frac{1-\kappa}{2\kappa-1}})\gamma_1}{\rho} n^{-\frac{1-\kappa}{2\kappa-1}} + \frac{(1 +2^{\frac{1-\kappa}{2\kappa-1}})^2\gamma_1^2}{2\rho} n^{-\frac{2-2\kappa}{2\kappa-1}}\\
&\leq \left(\gamma_2 +\frac{(3 +2^{\frac{1-\kappa}{2\kappa-1}})(1 +2^{\frac{1-\kappa}{2\kappa-1}})\gamma_1^2}{2\rho} +\frac{\|z^{*}\|(1 +2^{\frac{1-\kappa}{2\kappa-1}})\gamma_1}{\rho} \right)n^{-\frac{1-\kappa}{2\kappa-1}},
\end{align*}
where $\gamma_1 :=\frac{\ell_H\gamma_0 +(1 +2^{\frac{1-\kappa}{2\kappa-1}})\nu\ell_{\psi}\gamma_0}{\sqrt{\lambda}}$, $\gamma_2 :=\gamma_0 +c(1 +2^{\frac{1-\kappa}{2\kappa-1}})^2\gamma_0^2$, and the last inequality follows from the fact that $n^{-\frac{2-2\kappa}{2\kappa-1}}<n^{-\frac{1-\kappa}{2\kappa-1}}$ for $\kappa\in(\frac{1}{2},1)$. By setting $\overline{\gamma}$ in the same way as in \ref{t:full_rate_linear}, we obtain the conclusion.

We consider the linearly constrained composite optimization problem
\begin{align}\label{eq:prob}
\min_{x_i \in \mathbb{R}^{d_i}, y\in \mathbb{R}^q} ~F(\mathbf{x},y) :=\sum_{i=1}^m f_i(x_i)+H(y)+P(\mathbf{x})-G(\mathbf{x}) \quad\text{s.t.~~}  \sum_{i=1}^{m}A_ix_i + By=b,
\end{align}
where $\mathbf{x}=(x_1,\dots,x_m)$; for each $i\in \{1,\dots,m\}$, $f_i: \mathbb{R}^{d_i} \to (-\infty,+\infty]$ is a proper lower semicontinuous function; $H:\mathbb{R}^q \to \mathbb{R}$ is a differentiable (possibly
nonconvex) function whose gradient is Lipschitz continuous; $P:\mathbb{R}^{d_1}\times \dots \times \mathbb{R}^{d_m} \to \mathbb{R}$ is another differentiable (possibly nonconvex) function whose gradient is Lipschitz continuous; $G:\mathbb{R}^{d_1}\times \dots \times \mathbb{R}^{d_m} \to \mathbb{R}$ is a continuous (possibly nonsmooth) weakly convex function, $A_i \in \mathbb{R}^{p\times d_i}$, $B\in \mathbb{R}^{p\times q}$, and $b \in \mathbb{R}^p$. Problem \eqref{eq:prob} covers two important models in the literature. Firstly, when $G \equiv 0$, problem \eqref{eq:prob} reduces to the form

Let $x\in \mathbb{R}^d$ with $|f(x)| <+\infty$. The \emph{regular} (or \emph{Fr\'echet}) \emph{subdifferential} of $f$ at $x$ is defined by
\begin{equation*}
\widehat{\partial} f(x) :=\left\{x^*\in \mathbb{R}^d:\; \liminf_{y\to x}\frac{f(y)-f(x)-\langle x^*,y-x\rangle}{\|y-x\|}\geq 0\right\}
\end{equation*}
and the \emph{limiting} (or \emph{Mordukhovich}) \emph{subdifferential} of $f$ at $x$ is defined by
\begin{equation*}
\partial_L f(x) :=\left\{x^*\in \mathbb{R}^d:\; \exists x_n\stackrel{f}{\to}x,\; x_n^*\to x^* \text{~~with~~} x_n^*\in \widehat{\partial} f(x_n)\right\},
\end{equation*}
where the notation $y\stackrel{f}{\to}x$ means $y\to x$ with $f(y)\to f(x)$. In the case where $\lvert f(x) \rvert =+\infty$, both regular subdifferential and limiting subdifferential of $f$ at $x$ are defined to be the empty set. The \emph{domain} of $\partial_L f$ is given by $\dom \partial_L f :=\{x\in \mathbb{R}^d: \partial_L f(x) \neq \varnothing\}$. 
We now collect some important properties of the limiting subdifferential.

We recall the concept of the well-known Bregman distance in a real Hilbert space $\mathcal{H}$, which was introduced in \cite{Bregman}. Given a differentiable convex function $\phi: \mathcal{H} \to \mathbb{R}$, the \emph{Bregman distance} associated with $\phi$ is defined as 
\begin{align*}
\forall u, v\in \mathcal{H},\quad D_{\phi}(u,v)=\phi(u)-\phi(v)-\langle \nabla\phi (v),u-v\rangle,
\end{align*}
When $\phi(x)=\|x\|^2$, then $D_{\phi}(u,v)=\|u-v\|^2$. When $\phi(x)=x^\top M x$, where $M$ is a positive semidefinite matrix, then $D_{\phi}(u,v) = \|u-v\|^2_M :=(u-v)^\top M (u-v)$. When $\mathcal{H}=\mathbb{R}^{p\times d}$ and $\phi(X)=\|X\|_F^2$, then $D_{\phi}(U,V) =\|U-V\|_F^2$ \cite{Dhillon2008}. Some useful properties of the Bregman distance are listed in the following proposition.

\begin{assumption}[Standing assumptions]
\label{a:standing}
~
\begin{enumerate}
\item 
$\nabla H$ is $\ell_H$-Lipschitz continuous, $\nabla P$ is $\ell_P$-Lipschitz continuous, and $G$ is $\beta$-weakly convex.

\item\label{a:standing_rank} 
 $\lambda :=\lambda_{\min}(B^\top B) >0$ (equivalently, $B$ has full column rank).
\end{enumerate}
\end{assumption}

Recall that the augmented Lagrangian of problem \eqref{eq:prob} is given by
\begin{align*}
\mathcal{L}_\rho(\mathbf{x},y,z)=\sum_{i=1}^m f_i(x_i)+H(y)+P(\mathbf{x})-G(\mathbf{x}) +  \langle z, \mathbf{Ax}+By-b \rangle +\frac{\rho}{2}\|\mathbf{Ax}+By-b\|^2,
\end{align*}

where $z\in \mathbb{R}^p$ and $\rho\in \mathbb{R}_{++}$. Now, we present our splitting algorithm with guaranteed global convergence to a stationary point $(\overline{\mathbf{x}},\overline{y},\overline{z})$ of $\mathcal{L}_\rho$, i.e., $0 \in \partial_L \mathcal{L}_\rho(\overline{\mathbf{x}},\overline{y},\overline{z})$, or equivalently,
\begin{equation}\label{eq:optimality_conditions}
\begin{aligned}
&0 \in \partial_L\left(\sum_{i=1}^{m}f_i -G\right)(\overline{\mathbf{x}}) +\nabla P(\overline{\mathbf{x}}) +\mathbf{A}^\top \overline{z},\\
&0 =\nabla H(\overline{y}) +B^\top \overline{z}, \\
&0 =\mathbf{A\overline{x}} +B\overline{y} -b.
\end{aligned}
\end{equation}

\begin{tcolorbox}[
	left=0pt,right=0pt,top=0pt,bottom=0pt,
	colback=blue!10!white, colframe=blue!50!white,
  	boxrule=0.2pt,
  	breakable]
\begin{algorithm}[Bregman proximal linearized ADMM (BPL-ADMM)]
\label{algo:BPLA}
\step{}\label{step:A2_1}
Set $n=0$. Choose $\mathbf{x}_0 =(x_{1,0}, \dots, x_{m,0}) \in \mathbb{R}^{d_1}\times \dots \times \mathbb{R}^{d_m}$, $y_0 \in \mathbb{R}^q$, and $z_0 \in \mathbb{R}^p$. Let $\phi_i: \mathbb{R}^{d_i} \to \mathbb{R}$, $i \in \{1,\dots,m\}$, be differentiable $\alpha$-strongly convex functions with $\alpha \in (0, +\infty)$, and let $\psi: \mathbb{R}^q \to \mathbb{R}$ be a differentiable convex function with $\ell_{\psi}$-Lipschitz continuous gradient. Let 
\begin{align*}
\mu \in \left(\frac{\ell_P+\beta}{\alpha}, +\infty\right),\;\; \nu \in \left[0, +\infty\right), \text{~~and~~} \rho \in \left(\frac{\ell_H +\sqrt{\ell_H^2 +8(\ell_H +2\nu\ell_{\psi})^2}}{2\lambda}, +\infty\right).    
\end{align*}

\step{}\label{step:A2_2}
Calculate $\nabla P(\mathbf{x}_n)=(\nabla_1 P(\mathbf{x}_n),\dots,\nabla_m P(\mathbf{x}_n))$ and $g_{n}=(g_{1,n},\dots,g_{m,n}) \in \partial_L G(\mathbf{x}_{n})$. Let $\mu_n \in [\mu, +\infty)$ and $\nu_n \in [0, \nu]$. For each $i \in \{1,\dots,m\}$, define $\mathbf{u}_{i,n+1}: \mathbb{R}^{d_i}\to \mathbb{R}^{d_1}\times \dots \times \mathbb{R}^{d_m}$ by $\mathbf{u}_{i,n+1}(x_i) =(x_{1,n+1}, \dots, x_{i-1,n+1}, x_i, x_{i+1,n}, \dots, x_{m,n})$, and find
\begin{align*}
x_{i,n+1} &\in  \argmin_{x_i \in \mathbb{R}^{d_i}} \left(f_i(x_i) +\langle \nabla_i P(\mathbf{x}_n) -g_{i,n}, x_i \rangle + \langle z_n, A_ix_i\rangle+\frac{\rho}{2}\|\mathbf{A}\mathbf{u}_{i,n+1}(x_i)+By_n-b\|^2 +\mu_n D_{\phi_i}(x_i,x_{i,n})\right),\\
y_{n+1} &\in  \argmin_{y \in \mathbb{R}^q} \left(H(y) + \langle z_n, By\rangle+\frac{\rho}{2}\|\mathbf{Ax}_{n+1} + By-b \|^2 +\nu_n D_{\psi}(y,y_n) \right),\\
z_{n+1} &=z_n+\rho(\mathbf{Ax}_{n+1}+By_{n+1}-b),
\end{align*}
where $\mathbf{x}_{n+1} =(x_{1,n+1}, \dots, x_{m,n+1})$.
\step{}
If a termination criterion is not met, set $n =n+1$ and go to Step~\ref{step:A2_2}.
\end{algorithm}
\end{tcolorbox}

We now establish the convergence of the full sequence generated by Algorithm~\ref{algo:BPLA}. Recall that a proper lower semicontinuous function $\mathcal{F}\colon \mathcal{H}\to \left(-\infty, +\infty\right]$ satisfies the \emph{Kurdyka--Łojasiewicz (KL) property} \cite{Kurdyka1998,Loja63} at $\overline{x} \in \dom \partial_L \mathcal{F}$ if there are $\eta \in (0, +\infty]$, a neighborhood $V$ of $\overline{x}$, and a continuous concave function $\varphi: \left[0, \eta\right) \to \mathbb{R}_+$ such that $\varphi$ is continuously differentiable with $\varphi' > 0$ on $(0, \eta)$, $\varphi(0) = 0$, and, for all $x \in V$ with $
\mathcal{F}(\overline{x}) < \mathcal{F}(x) < \mathcal{F}(\overline{x}) + \eta$, 
\begin{equation*}
\varphi'(\mathcal{F}(x) -\mathcal{F}(\overline{x})) \dist(0, \partial_L \mathcal{F}(x)) \geq 1.   
\end{equation*}
We say that $\mathcal{F}$ is a \emph{KL function} if it satisfies the KL property at any point in $\dom \partial_L \mathcal{F}$. If $\mathcal{F}$ satisfies the KL property at $\overline{x} \in \dom \partial_L \mathcal{F}$, in which the corresponding function $\varphi$ can be chosen as $\varphi(t) = c t ^{1 - \lambda}$ for some $c \in \mathbb{R}_{++}$ and $\lambda \in [0, 1)$, then $\mathcal{F}$ is said to satisfy the \emph{KL property at $\overline{x}$ with exponent $\lambda$}. The function $\mathcal{F}$ is called a \emph{KL function with exponent $\lambda$} if it is a KL function and has the same exponent $\lambda$ at any $x \in \dom \partial_L \mathcal{F}$. Now we will present the proof of the full sequential convergence in the following theorem.

Define
\begin{align*}
\mathcal{F}(\mathbf{x},y,z,t):=\mathcal{L}_\rho(\mathbf{x},y,z) +c\|y-t\|^2, \text{~~where~} c=\frac{(\ell_H+2\nu\ell_{\psi})\nu\ell_{\psi}}{\lambda\rho}.
\end{align*}

\begin{theorem}[Full sequential convergence]
\label{t:full}
Suppose that Assumption~\ref{a:standing} holds, that $\sum_{i=1}^m f_i(x_i)+P(\mathbf{x})-G(\mathbf{x})$ is coercive, that $H$ is bounded below, that $G$ is differentiable with $\ell_G$-Lipschitz continuous gradient, and that, for all $i\in \{1, \dots, m\}$, $\nabla{\phi_i}$ is $\ell_{\phi}$-Lipschitz continuous. Let $(\mathbf{x}_{n},y_{n},z_{n})_{n\in\mathbb{N}}$ be the sequence generated by Algorithm~\ref{algo:BPLA} with $z_0\in \Ima(B)$ and $\limsup_{n\to +\infty} \mu_n =\overline{\mu} <+\infty$.
Define
\begin{align*}
\mathcal{F}(\mathbf{x},y,z,t):=\mathcal{L}_\rho(\mathbf{x},y,z) +c\|y-t\|^2, \text{~~where~} c=\frac{(\ell_H+2\nu\ell_{\psi})\nu\ell_{\psi}}{\lambda\rho}.
\end{align*}
\begin{enumerate}
\item\label{t:full_cvg} 
Suppose that $\mathcal{F}$ is a KL function. Then the sequence $(\mathbf{x}_{n},y_{n},z_{n})_{n\in\mathbb{N}}$ converges to a stationary point $(\mathbf{x}^{*},y^{*},z^{*})$ of $\mathcal{L}_\rho$ and \begin{align*}
\sum_{n=0}^{+\infty} \|(\mathbf{x}_{n+1},y_{n+1},z_{n+1})-(\mathbf{x}_{n},y_{n},z_{n})\| < +\infty.
\end{align*}
\item\label{t:full_rate} 
Suppose that $\mathcal{F}$ is a KL function with exponent $\kappa\in [0,1)$. Then the following hold:
\begin{enumerate}
\item\label{t:full_rate_finite}
If $\kappa =0$, then $(\mathbf{x}_{n},y_{n},z_{n})_{n\in\mathbb{N}}$ converges to $(\mathbf{x}^{*},y^{*},z^{*})$ in a finite number of steps. 
\item\label{t:full_rate_linear}
If $\kappa\in (0,\frac{1}{2}]$, then there exist $\overline{\gamma}\in \mathbb{R}_{++}$ and $\zeta\in \left(0,1\right)$ such that, for all $n\in \mathbb{N}$, 
\begin{align*}
&\|(\mathbf{x}_{n},y_{n},z_{n})-(\mathbf{x}^{*},y^{*},z^{*})\| \leq \overline{\gamma}\zeta^{\frac{n}{2}}, \\
&\|\mathbf{Ax}_n+By_n-b\| \leq \overline{\gamma} \zeta^{\frac{n}{2}}, \\
&\lvert \mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}) -\mathcal{L}_\rho(\mathbf{x}^{*},y^{*},z^{*}) \rvert \leq \overline{\gamma}\zeta^n, \\
\text{and~} &|F(\mathbf{x}_n,y_n)-F(\mathbf{x}^{*},y^{*})| \leq \overline{\gamma} \zeta^{\frac{n}{2}}.
\end{align*}
\item\label{t:full_rate_sublinear}
If $\kappa\in (\frac{1}{2},1)$, then there exists $\overline{\gamma}\in \mathbb{R}_{++}$ such that, for all $n\in \mathbb{N}$,
\begin{align*}
&\|(\mathbf{x}_{n},y_{n},z_{n})-(\mathbf{x}^{*},y^{*},z^{*})\| \leq \overline{\gamma} n^{-\frac{1-\kappa}{2\kappa-1}}, \\
&\|\mathbf{Ax}_n+By_n-b\| \leq \overline{\gamma} n^{-\frac{1-\kappa}{2\kappa-1}}, \\
&\lvert \mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}) -\mathcal{L}_\rho(\mathbf{x}^{*},y^{*},z^{*})\rvert \leq \overline{\gamma} n^{-\frac{2-2\kappa}{2\kappa-1}}, \\
\text{and~} &|F(\mathbf{x}_n,y_n)-F(\mathbf{x}^{*},y^{*})| \leq \overline{\gamma} n^{-\frac{1-\kappa}{2\kappa-1}}.
\end{align*}
\end{enumerate}
\end{enumerate}
\end{theorem}

\begin{lemma}[Calculus rules]
\label{l:cal}
Let $f, g\colon \mathbb{R}^d \to (-\infty, +\infty]$ be proper lower semicontinuous functions, and let $x \in \mathbb{R}^d$. 
\begin{enumerate}
\item\label{l:cal_sum} 
(Sum rule) Suppose that $f$ is finite at $x$ and $g$ is locally Lipschitz around $\overline{x}$. Then $\partial_L (f + g)(\overline{x}) \subseteq \partial_L f(\overline{x})+\partial_L g(\overline{x})$. Moreover, if $g$ is strictly differentiable at $\overline{x}$, then $\partial_L(f + g)(\overline{x}) = \partial_Lf(\overline{x}) + \nabla g(\overline{x})$.

\item\label{l:cal_sep} 
(Separable sum rule) If $f(\mathbf{x})=\sum_{i=1}^{m}f_i(x_i)$ with $\mathbf{x}=(x_1,\dots,x_m)$, then $\partial_L f(\mathbf{x}) = \partial_L f_1(x_1) \times \dots \times \partial_L f_m(x_m)$. 
\end{enumerate}
\end{lemma}

\begin{proof}
\ref{l:cal_sum} follows from \cite[Proposition~1.107(ii) and Theorem~3.36]{Mordukhovich2006}, while \ref{l:cal_sep} follows from \cite[Proposition~10.5]{Rockafellar1998}.
\end{proof}

\begin{lemma}[Upper semicontinuity of subdifferential]
\label{l:upsemicont}
Let $f\colon \mathbb{R}^d \to [-\infty, +\infty]$ be Lipschitz continuous around $x \in \mathbb{R}^d$ with $|f(x)| <+\infty$, and consider sequences $(x_n)_{n\in \mathbb{N}}$ and $(x_n^*)_{n\in \mathbb{N}}$ in $\mathbb{R}^d$ such that $x_n \to x$ and, for all ${n\in \mathbb{N}}$, $x_n^* \in \partial_L f(x_n)$. 
Then $(x_n^*)_{n\in \mathbb{N}}$ is bounded and its cluster points are contained in $\partial_L f(x)$.
\end{lemma}

\begin{proof}
This follows from \cite[Lemma 2.2]{Tan2023}.
\end{proof}

\begin{proposition}
\label{p:Bregman}
Let $\phi: \mathcal{H} \to \mathbb{R}$ be a differentiable convex function and $D_{\phi}$ is the Bregman distance associated with $\phi$. Then the following hold:
\begin{enumerate}
\item\label{p:Bregman_1} 
For all $u, v \in \mathcal{H}$, $D_{\phi}(u, v)\geq 0$, and $D_{\phi}(u, v)=0$ if and only if $u = v$.

\item\label{p:Bregman_4} 
If $\nabla \phi$ is $\ell_{\phi}$-Lipschitz continuous, then, for all $u, v \in \mathcal{H}$, $D_{\phi}(u,v)\leq \frac{\ell_{\phi}}{2}\|u-v\|^2$. 
\end{enumerate}
\end{proposition}

\begin{proof}
\ref{p:Bregman_1} is given in \cite[Section 1]{Bregman}. \ref{p:Bregman_2}, \ref{p:Bregman_3}, and \ref{p:Bregman_4} can be easily verified by using the definitions. 
\end{proof}

\begin{lemma}
\label{l:diff}
Let $h\colon \mathbb{R}^d\to \mathbb{R}$ be a differentiable function with $\ell$-Lipschitz continuous gradient. Then the following hold:
\begin{enumerate}
\item\label{l:diff_descent}
For all $x, y\in \mathbb{R}^d$, $|h(y) -h(x) -\langle \nabla h(x), y -x\rangle|\leq \frac{\ell}{2}\|y -x\|^2$.

\item\label{l:diff_bounded}
If $h$ is bounded below and $\ell >0$, then
\begin{align*}
\inf_{x\in \mathbb{R}^d} \left(h(x) -\frac{1}{2\ell}\|\nabla h(x)\|^2\right) >-\infty.    
\end{align*}
\end{enumerate}  
\end{lemma}

\begin{proof}
\ref{l:diff_descent}: This follows from \cite[Lemma~1.2.3]{Nesterov2018}.

\ref{l:diff_bounded}: Let $x\in \mathbb{R}^d$. Following the argument of \cite[Equation~(1.2.19)]{Nesterov2018}, we apply \ref{l:diff_descent} with $y =x -\frac{1}{\ell}\nabla h(x)$ to obtain that
\begin{align*}
h\left(x -\frac{1}{\ell}\nabla h(x)\right) &\leq h(x) +\langle \nabla h(x), y -x\rangle +\frac{\ell}{2}\|y -x\|^2 \\
&= h(x) -\frac{1}{\ell}\|\nabla h(x)\|^2 +\frac{1}{2\ell}\|\nabla h(x)\|^2 \\
&= h(x) -\frac{1}{2\ell}\|\nabla h(x)\|^2,
\end{align*}
which together with the boundedness of $h$ implies the conclusion.
\end{proof}

\begin{lemma}
\label{l:norm}
Let $L$ be a symmetric matrix in $\mathbb{R}^{d\times d}$ and let $M$ be a matrix in $\mathbb{R}^{p\times d}$. Then the following hold:
\begin{enumerate}
\item\label{l:norm_Mx}
For all $x\in \mathbb{R}^d$, $\sqrt{\lambda_{\min}(M^\top M)}\|x\| \leq \|Mx\|$.

\item\label{l:norm_M'x}
For all $x\in \mathbb{R}^d$, $\gamma(x^\top Lx) \leq \|Lx\|^2$, where $\gamma =\min\{|\lambda|: \lambda \text{~is a nonzero eigenvalue of~} L\}$. Consequently, for all $z\in \Ima(M)$, $\sqrt{\lambda_*(M^\top M)}\|z\| \leq \|M^\top z\|$, where $\lambda_*(M^\top M)$ is the smallest strictly positive eigenvalue of $M^\top M$. 
\end{enumerate}
\end{lemma}

\begin{proof}
\ref{l:norm_Mx}: This follows from the fact that $\|Mx\|^2 =x^\top (M^\top M)x$.

\ref{l:norm_M'x}: 
The first assertion follows from \cite[Lemma~4.5]{BDL23} and its proof. Now, let $z\in \Ima(M)$. Then there exists $x\in \mathbb{R}^d$ such that $z =Mx$. Since $M^\top M$ is a symmetric matrix in $\mathbb{R}^{d\times d}$ with all eigenvalues being nonnegative, we have from the first assertion that
\begin{align*}
\lambda_*(M^\top M)\|z\|^2 =\lambda_*(M^\top M)(x^\top M^\top Mx) \leq \|M^\top Mx\|^2 =\|M^\top z\|^2,    
\end{align*}
which completes the proof.
\end{proof}

\begin{theorem}[Subsequential convergence]
\label{t:cvg}
Suppose that Assumption~\ref{a:standing} holds. Let $(\mathbf{x}_n,y_n,z_n)_{n\in \mathbb{N}}$ be the sequence generated by Algorithm~\ref{algo:BPLA} and, for each $n\in \mathbb{N}^*$, define
\begin{align*}
L_n =\mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}) +c\|y_n-y_{n-1}\|^2, \text{~where~} c=\frac{(\ell_H+2\nu\ell_{\psi})\nu\ell_{\psi}}{\lambda\rho}.     
\end{align*}
Then the following hold:
\begin{enumerate}
\item\label{t:cvg_decrease}
For all $n\in \mathbb{N}^*$,
\begin{align}\label{eq:decrease}
L_{n+1} +\delta_{\mathbf{x}}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2 +\delta_y\|y_{n+1}-y_n\|^2 \leq L_n,
\end{align}
where $\delta_{\mathbf{x}} =\frac{\mu\alpha -\ell_P -\beta}{2} > 0$ and $\delta_y =\frac{\lambda\rho}{2} -\frac{(\ell_H+2\nu\ell_{\psi})^2}{\lambda\rho} -\frac{\ell_H}{2} >0$.

\item\label{t:cvg_seq}
Suppose that $z_0\in \Ima(B)$, that $\sum_{i=1}^m f_i(x_i)+P(\mathbf{x})-G(\mathbf{x})$ is coercive, and that $H$ is bounded below. 
Then the sequence $(\mathbf{x}_n,{y}_n,{z}_n)_{n\in \mathbb{N}}$ is bounded and $\mathbf{x}_{n+1}-\mathbf{x}_n\to 0$, $y_{n+1}-y_n\to 0$, $z_{n+1}-z_n\to 0$, and $\mathbf{Ax}_n +By_n \to b$ as $n\to +\infty$. Furthermore, for every cluster point $(\overline{\mathbf{x}},\overline{y},\overline{z})$ of $(\mathbf{x}_n,{y}_n,{z}_n)_{n\in \mathbb{N}}$, it holds that
\begin{align*}
\mathbf{A}\overline{\mathbf{x}} +b\overline{y} =b \text{~~and~~} \lim_{n \to +\infty} F(\mathbf{x}_{n },y_{n}) =\lim_{n \to +\infty}\mathcal{L}_\rho(\mathbf{x}_{n },y_{n},z_{n}) =\mathcal{L}_\rho(\overline{\mathbf{x}},\overline{y},\overline{z}) =F(\overline{\mathbf{x}},\overline{y}),    
\end{align*}
and that if $G$ is strictly differentiable and, for each $i \in \{1,\dots,m\}$, $\nabla \phi_i$ is $\ell_{\phi}$-Lipschitz continuous, then $(\overline{\mathbf{x}},\overline{y},\overline{z})$ is a stationary point of $\mathcal{L}_\rho$.
\end{enumerate}
\end{theorem}

\begin{proof}
\ref{t:cvg_decrease}: Let $n\in \mathbb{N}$. The update of $z_{n+1}$ yields
\begin{align}\label{eq:z-update}
z_{n+1} -z_n =\rho(\mathbf{Ax}_{n+1}+By_{n+1}-b).   
\end{align}
By the optimality condition for the update of $y_{n+1}$ in Step~\ref{step:A2_2} of Algorithm~\ref{algo:BPLA}, 
\begin{align*}
0 &= \nabla H(y_{n+1}) + B^\top z_n +\rho B^\top(\mathbf{Ax}_{n+1} +By_{n+1} -b) +\nu_n(\nabla \psi(y_{n+1}) - \nabla \psi(y_n)),
\end{align*}
which combined with \eqref{eq:z-update} yields
\begin{align}\label{eq:B'z}
B^\top z_{n+1} =-\nabla H(y_{n+1}) -\nu_n(\nabla \psi(y_{n+1}) -\nabla \psi(y_n)).  
\end{align}
From the definition of the augmented Lagrangian, we have that
\begin{align}\label{eq:zz}
\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_{n+1}) -\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_{n}) &= \langle z_{n+1}-z_n, \mathbf{Ax}_{n+1}+By_{n+1}-b \rangle \notag\\
&= \frac{1}{\rho}\|z_{n+1}-z_n\|^2 
\end{align}
and that
\begin{align*}
\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_n) -\mathcal{L}_\rho(\mathbf{x}_{n+1},y_n,z_n) &= H(y_{n+1}) - H(y_n) + \langle z_n, B(y_{n+1}-y_n) \rangle \\
&\qquad + \frac{\rho}{2}(\|\mathbf{Ax}_{n+1}+By_{n+1}-b\|^2 - \|\mathbf{Ax}_{n+1}+By_{n}-b\|^2).  
\end{align*}
Writing $\mathbf{Ax}_{n+1}+By_{n}-b =(\mathbf{Ax}_{n+1}+By_{n+1}-b) -(By_{n+1}- By_n)$, we obtain that
\begin{align*}
&\|\mathbf{Ax}_{n+1}+By_{n+1}-b\|^2 - \|\mathbf{Ax}_{n+1}+By_{n}-b\|^2 \\
&= -\|B(y_{n+1}-y_n)\|^2 +2\langle  \mathbf{Ax}_{n+1}+By_{n+1}-b, B(y_{n+1}-y_n)\rangle \\
&= -\|B(y_{n+1}-y_n)\|^2 +\frac{2}{\rho}\langle  z_{n+1}-z_{n}, B(y_{n+1}-y_n)\rangle,
\end{align*}
and so
\begin{align*}
\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_n) -\mathcal{L}_\rho(\mathbf{x}_{n+1},y_n,z_n) = H(y_{n+1}) - H(y_n) +\langle z_{n+1}, B(y_{n+1}-y_n) \rangle -\frac{\rho}{2}\|B(y_{n+1}-y_n)\|^2.
\end{align*}
In view of \eqref{eq:B'z},
\begin{align*}
\langle z_{n+1}, B(y_{n+1}-y_n) \rangle &=\langle B^\top z_{n+1}, y_{n+1}-y_n \rangle \\
&=-\langle \nabla H(y_{n+1}), y_{n+1}-y_n \rangle -\nu_n\langle \nabla \psi(y_{n+1})- \nabla \psi(y_n), y_{n+1}-y_n \rangle \\
&\leq -H(y_{n+1}) +H(y_n) +\frac{\ell_H}{2}\|y_{n+1}-y_n\|^2,
\end{align*}
where the last inequality is from the $\ell_H$-Lipschitz continuity of $\nabla H$ and Lemma~\ref{l:diff}\ref{l:diff_descent}, and from the monotonicity of $\nabla \psi$. 
We therefore obtain that
\begin{align}\label{eq:yy}
\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_n) -\mathcal{L}_\rho(\mathbf{x}_{n+1},y_n,z_n) \leq \frac{\ell_H}{2}\|y_{n+1}-y_n\|^2 -\frac{\rho}{2}\|B(y_{n+1}-y_n)\|^2.    
\end{align}
Next, by the update of $x_{i,n+1}$ in Step~\ref{step:A2_2} of Algorithm~\ref{algo:BPLA}, for all $i \in \{1,\dots,m\}$ and all $x_i \in \mathbb{R}^{d_i}$,
\begin{align}\label{eq:update_step_x}
&f_i(x_{i,n+1}) +\langle \nabla_i P(\mathbf{x}_n) -g_{i,n}, x_{i,n+1} \rangle +\langle z_n, A_{i}x_{i,n+1} \rangle +\frac{\rho}{2}\|\mathbf{A}\mathbf{u}_{i,n+1}(x_{i,n+1}) +By_n -b\|^2 +\mu_n D_{\phi_i}(x_{i,n+1},x_{i,n}) \notag \\
&\leq  f_i(x_i) +\langle \nabla_i P(\mathbf{x}_n) -g_{i,n}, x_i \rangle +\langle z_n, A_{i}x_i\rangle +\frac{\rho}{2}\|\mathbf{A}\mathbf{u}_{i,n+1}(x_i) +By_n -b\|^2 +\mu_n D_{\phi_i}(x_i,x_{i,n}).
\end{align}
Letting $x_i =x_{i,n}$, using Proposition~\ref{p:Bregman}\ref{p:Bregman_1}\&\ref{p:Bregman_3}, and summing up over $i \in \{1,\dots,m\}$, we derive that
\begin{align}\label{eq:from x-update}
&\sum_{i=1}^m f_i(x_{i,n+1}) +\langle \nabla P(\mathbf{x}_n) -g_n, \mathbf{x}_{n+1} \rangle +\langle z_n, \mathbf{Ax}_{n+1} \rangle +\frac{\rho}{2}\|\mathbf{A}\mathbf{x}_{n+1} +By_n -b\|^2 +\frac{\mu\alpha}{2}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2 \notag\\
&\leq \sum_{i=1}^m f_i(x_{i,n}) +\langle \nabla P(\mathbf{x}_n) -g_n, \mathbf{x}_{n} \rangle +\langle z_n, \mathbf{Ax}_{n} \rangle +\frac{\rho}{2}\|\mathbf{A}\mathbf{x}_n +By_n -b\|^2.
\end{align}
On the other hand,
\begin{align}\label{eq:xx}
&\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n},z_n) -\mathcal{L}_\rho(\mathbf{x}_{n},y_n,z_n) \notag\\
&= \sum_{i=1}^m f_i(x_{i,n+1}) -\sum_{i=1}^m f_i(x_{i,n}) +P(\mathbf{x}_{n+1}) -P(\mathbf{x}_{n}) -G(\mathbf{x}_{n+1}) +G(\mathbf{x}_{n}) \notag\\ 
&\quad +\langle z_n, \mathbf{Ax}_{n+1}-\mathbf{Ax}_{n}\rangle +\frac{\rho}{2}\|\mathbf{Ax}_{n+1}+By_{n}-b\|^2 -\frac{\rho}{2}\|\mathbf{Ax}_{n}+By_{n}-b\|^2 \notag\\
&\leq \sum_{i=1}^m f_i(x_{i,n+1}) -\sum_{i=1}^m f_i(x_{i,n}) +\langle \nabla P(\mathbf{x}_n), \mathbf{x}_{n+1}-\mathbf{x}_n \rangle + \frac{\ell_P}{2}\|\mathbf{x}_{n+1}-\mathbf{x}_n\|^2 - \langle g_n, \mathbf{x}_{n+1} -\mathbf{x}_{n} \rangle + \frac{\beta}{2}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2 \notag\\
&\quad +\langle z_n, \mathbf{Ax}_{n+1}-\mathbf{Ax}_{n}\rangle  + \frac{\rho}{2}\|\mathbf{Ax}_{n+1}+By_{n}-b\|^2 - \frac{\rho}{2}\|\mathbf{Ax}_{n}+By_{n}-b\|^2 \notag\\
&\leq -\frac{\mu\alpha -\ell_P -\beta}{2}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2 =-\delta_{\mathbf{x}}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2,
\end{align}
where the first inequality is obtained by using Lemma~\ref{l:diff}\ref{l:diff_descent} on the $\ell_P$-Lipschitz continuity of $\nabla P$ and \cite[Lemma~4.1]{BDL22} on the $\beta$-weak convexity of $G$, while the last inequality follows from \eqref{eq:from x-update}. Summing up three relations \eqref{eq:zz}, \eqref{eq:yy}, and \eqref{eq:xx} yields
\begin{align}\label{eq:LL}
&\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_{n+1}) - \mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}) \notag\\
&\leq -\delta_{\mathbf{x}}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2 +\frac{\ell_H}{2}\|y_{n+1}-y_n\|^2 -\frac{\rho}{2}\|B(y_{n+1}-y_n)\|^2 +\frac{1}{\rho}\|z_{n+1}-z_n\|^2.
\end{align}

Now, since $\Ima(\mathbf{A}) \cup \{b\} \subseteq \Ima(B)$, it follows from \eqref{eq:z-update} that
\begin{align}\label{eq:zImB}
z_{n+1}-z_n \in \Ima(B)    
\end{align}
which, by Lemma~\ref{l:norm}\ref{l:norm_M'x}, yields 
\begin{align*}
\|z_{n+1} -z_n\| \leq \frac{1}{\sqrt{\lambda}}\|B^\top z_{n+1} -B^\top z_n\|.
\end{align*}
Let $n\in \mathbb{N}^*$. We derive from \eqref{eq:B'z} and the Lipschitz continuity of $\nabla H$ and $\nabla \psi$ that
\begin{align}\label{eq:BTZy}
\|B^\top z_{n+1} -B^\top z_n\| &\leq \|\nabla H(y_{n+1}) -\nabla H(y_n)\| +\nu_n\|\nabla \psi(y_{n+1}) -\nabla \psi(y_n)\| +\nu_{n-1}\|\nabla \psi(y_n) - \nabla \psi(y_{n-1})\| \notag \\ 
&\leq (\ell_H +\nu\ell_{\psi})\|y_{n+1} -y_n\| +\nu\ell_{\psi}\|y_n -y_{n-1}\|,
\end{align}
and thus, 
\begin{align}\label{eq:zy}
\|z_{n+1} -z_n\| \leq \frac{1}{\sqrt{\lambda}}\|B^\top z_{n+1} -B^\top z_n\| \leq \frac{1}{\sqrt{\lambda}}((\ell_H +\nu\ell_{\psi})\|y_{n+1} -y_n\| +\nu\ell_{\psi}\|y_n -y_{n-1}\|).
\end{align}
Applying Cauchy--Schwarz inequality to two vectors $u =(\sqrt{\ell_H+\nu\ell_{\psi}},\sqrt{\nu\ell_{\psi}})$ and $v =(\sqrt{\ell_H+\nu\ell_{\psi}}\|y_{n+1} -y_n\|,\sqrt{\nu\ell_{\psi}}\|y_n -y_{n-1}\|)$, we obtain that
\begin{align*}
\|z_{n+1} -z_n\|^2 \leq \frac{\ell_H +2\nu\ell_{\psi}}{\lambda}((\ell_H +\nu\ell_{\psi})\|y_{n+1} -y_n\|^2 +\nu\ell_{\psi}\|y_n -y_{n-1}\|^2).    
\end{align*}
By combining this with \eqref{eq:LL} and using Lemma~\ref{l:norm}\ref{l:norm_Mx},
\begin{align*}
&\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_{n+1}) - \mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}) \notag\\
&\leq -\delta_{\mathbf{x}}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2 +\left(\frac{(\ell_H+2\nu\ell_{\psi})(\ell_H+\nu\ell_{\psi})}{\lambda\rho} +\frac{\ell_H}{2}\right)\|y_{n+1}-y_n\|^2 \\ 
&\qquad -\frac{\rho}{2}\|B(y_{n+1}-y_n)\|^2 +\frac{(\ell_H+2\nu\ell_{\psi})\nu\ell_{\psi}}{\lambda\rho}\|y_n-y_{n-1}\|^2 \\
&\leq -\delta_{\mathbf{x}}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2 -\left(\frac{\lambda\rho}{2} -\frac{(\ell_H+2\nu\ell_{\psi})(\ell_H+\nu\ell_{\psi})}{\lambda\rho} -\frac{\ell_H}{2}\right)\|y_{n+1}-y_n\|^2 \\
&\qquad +\frac{(\ell_H+2\nu\ell_{\psi})\nu\ell_{\psi}}{\lambda\rho}\|y_n-y_{n-1}\|^2,
\end{align*}
or equivalently,
\begin{align*}
&\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_{n+1}) +\frac{(\ell_H +2\nu\ell_{\psi})\nu\ell_{\psi}}{\lambda\rho}\|y_{n+1}-y_{n}\|^2 + \delta_{\mathbf{x}}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2 +\delta_y\|y_{n+1}-y_n\|^2 \\
&\leq \mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}) +\frac{(\ell_H +2\nu\ell_{\psi})\nu\ell_{\psi}}{\lambda\rho}\|y_n-y_{n-1}\|^2,
\end{align*}
which proves \eqref{eq:decrease}. Here, we note that $\delta_{\mathbf{x}} =\frac{\mu\alpha -\ell_P -\beta}{2} > 0$ since $\mu > \frac{\ell_P+\beta}{\alpha}$ and that $\delta_y =\frac{\lambda\rho}{2} -\frac{(\ell_H+2\nu\ell_{\psi})^2}{\lambda\rho} -\frac{\ell_H}{2} >0$ since $\rho > \frac{\ell_H +\sqrt{\ell_H^2 +8(\ell_H +2\nu\ell_{\psi})^2}}{2\lambda}$.

\ref{t:cvg_seq}: Let $n\in \mathbb{N}^*$. As $z_0 \in \Ima(B)$, we have from \eqref{eq:zImB} that $z_n \in \Ima (B)$. Using Lemma~\ref{l:norm}\ref{l:norm_M'x}, \eqref{eq:B'z}, and the Lipschitz continuity of $\psi$ yields
\begin{align*}
\sqrt{\lambda}\|z_n\|\leq \|B^\top z_n\| \leq\|\nabla H(y_n)\|+ \nu_n\|\nabla \psi(y_{n}) -\nabla \psi(y_{n-1})\| 
\leq \|\nabla H(y_n)\|+ \nu \ell_{\psi}\|y_{n}-y_{n-1}\|.
\end{align*}
For $\omega\in \mathbb{R}_{++}$ to be chosen later, invoking Cauchy--Schwarz inequality with two vectors $u =(\sqrt{\omega},\sqrt{\nu\ell_{\psi}})$ and $v =(\frac{1}{\sqrt{\omega}}\|\nabla H(y_n)\|,\sqrt{\nu\ell_{\psi}}\|y_n-y_{n-1}\|)$, we have that
\begin{align}\label{eq:uppper_zn}
\|z_n\|^2 &\leq \frac{\omega +\nu\ell_{\psi}}{\lambda} \left(\frac{1}{\omega}\|\nabla H(y_n)\|^2 +\nu\ell_{\psi}\|y_n-y_{n-1}\|^2\right) \notag \\
&= \frac{1}{\lambda}\left(1 +\frac{\nu\ell_{\psi}}{\omega}\right)\|\nabla H(y_n)\|^2 +\frac{(\omega +\nu\ell_{\psi})\nu\ell_{\psi}}{\lambda}\|y_n-y_{n-1}\|^2.
\end{align}
Combining this with the fact that
\begin{align*}
\langle z_n, \mathbf{Ax}_n+By_n-b \rangle +\frac{\rho}{2}\|\mathbf{Ax}_n+By_n-b\|^2 =\frac{\rho}{2}\left\| \frac{z_n}{\rho} +\mathbf{Ax}_n+By_n-b \right\|^2 -\frac{1}{2\rho}\|z_n\|^2,
\end{align*}
we deduce that
\begin{align*}
L_n &=\mathcal{L}_\rho(\mathbf{x}_n,y_n,z_n) + c\|y_n-y_{n-1}\|^2 \\
&\geq \sum_{i=1}^m f_i(x_{i,n}) +H(y_n) +P(\mathbf{x}_n) -G(\mathbf{x}_n) \\ 
&\quad +\frac{\rho}{2}\left\| \frac{z_n}{\rho} + \mathbf{Ax}_n+By_n-b \right\|^2 -\frac{1}{2\lambda\rho}\left(1 +\frac{\nu\ell_{\psi}}{\omega}\right)\|\nabla H(y_n)\|^2 +\left(c -\frac{(\omega +\nu\ell_{\psi})\nu\ell_{\psi}}{2\lambda\rho}\right)\|y_n-y_{n-1}\|^2 \\
&= \left(\sum_{i=1}^m f_i(x_{i,n}) +P(\mathbf{x}_n) -G(\mathbf{x}_n)\right) +\left(H(y_n) -\frac{1}{2\ell_H}\|\nabla H(y_n)\|^2\right) +\frac{\rho}{2}\left\| \frac{z_n}{\rho} + \mathbf{Ax}_n+By_n-b \right\|^2 \\ 
&\quad +\left(\frac{1}{2\ell_H} -\frac{1}{2\lambda\rho}\left(1 +\frac{\nu\ell_{\psi}}{\omega}\right)\right)\|\nabla H(y_n)\|^2 +\frac{\nu\ell_{\psi}}{2\lambda\rho}(2\ell_H +3\nu\ell_{\psi} -\omega)\|y_n-y_{n-1}\|^2.
\end{align*}
Now, we note that
\begin{align*}
\rho > \frac{\ell_H +\sqrt{\ell_H^2 +8(\ell_H +2\nu\ell_{\psi})^2}}{2\lambda} \geq \frac{\ell_H +\sqrt{\ell_H^2 +8\ell_H^2}}{2\lambda} =\frac{2\ell_H}{\lambda},    
\end{align*}
and so $\frac{1}{2\ell_H} >\frac{1}{\lambda\rho}$. Choosing $\omega =1$ if $\nu\ell_{\psi} =0$, and $\omega =\nu\ell_{\psi}$ if $\nu\ell_{\psi} >0$, it holds that
\begin{align*}
&\theta :=\frac{1}{2\ell_H} -\frac{1}{2\lambda\rho}\left(1 +\frac{\nu\ell_{\psi}}{\omega}\right) \geq \frac{1}{2\ell_H} -\frac{1}{2\lambda\rho}(1 +1) >0 \text{~~and~~} \\
&\frac{\nu\ell_{\psi}}{2\lambda\rho}(2\ell_H +3\nu\ell_{\psi} -\omega) \geq \frac{\nu\ell_{\psi}}{2\lambda\rho}(3\nu\ell_{\psi} -\omega) =\frac{\nu^2\ell_{\psi}^2}{\lambda\rho}. 
\end{align*}
This together with \ref{t:cvg_decrease} yields
\begin{align}\label{eq:L_n_bounded}
L_1 \geq L_n &\geq \left(\sum_{i=1}^m f_i(x_{i,n}) +P(\mathbf{x}_n) -G(\mathbf{x}_n)\right) +\left(H(y_n) -\frac{1}{2\ell_H}\|\nabla H(y_n)\|^2\right) +\frac{\rho}{2}\left\| \frac{z_n}{\rho} + \mathbf{Ax}_n+By_n-b \right\|^2 \notag \\ 
&\quad +\theta\|\nabla H(y_n)\|^2 +\frac{\nu^2\ell_{\psi}^2}{\lambda\rho}\|y_n-y_{n-1}\|^2,
\end{align}
in which the first term on the right hand side is bounded below since $\sum_{i=1}^m f_i(x_i)+P(\mathbf{x})-G(\mathbf{x})$ is coercive, the second term is bounded below due to {the assumption on $H$ and Lemma~\ref{l:diff}\ref{l:diff_bounded}}, while the remaining terms are nonnegative due to their positive coefficients. Therefore, all the terms are bounded. Again, as $\sum_{i=1}^m f_i(x_i)+P(\mathbf{x})-G(\mathbf{x})$ is coercive, the boundedness of the first term implies that $(\mathbf{x}_{n})_{n\in \mathbb{N}}$ is bounded. Since the last two terms are bounded, it follows from \eqref{eq:uppper_zn} that $(z_n)_{n\in \mathbb{N}}$ is bounded. Since $z_{n+1}=z_n+\rho(\mathbf{Ax}_{n+1}+By_{n+1}-b)$ and $B$ has full column rank, we also obtain that $(y_n)_{n\in \mathbb{N}}$ is bounded. Consequently, the sequence $(\mathbf{x}_n,y_n,z_n)_{n\in \mathbb{N}}$ is bounded.

On the other hand, since all the terms on the right hand side of \eqref{eq:L_n_bounded} are bounded below, so is the sequence $(L_n)_{n\in\mathbb{N}}$. Combining with the nonincreasing property of $(L_n)_{n\in\mathbb{N}}$ due to \ref{t:cvg_decrease}, it follows that $(L_n)_{n\in\mathbb{N}}$ is convergent. By rearranging \eqref{eq:decrease} and performing telescoping, we then have that
\begin{align*}
\sum_{n=1}^{+\infty}\delta_y \|y_{n+1}-y_n\|^2 + \delta_{\mathbf{x}}\sum_{n=1}^{+\infty}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2 \leq \sum_{n=1}^{+\infty}(L_n - L_{n+1}) = L_1 - \lim_{n\to+\infty} L_n < +\infty,
\end{align*}
which implies that $\sum_{n=1}^{+\infty}\|\mathbf{x}_{n+1}-\mathbf{x}_n\|^2 < +\infty$, $\sum_{n=1}^{+\infty}\|y_{n+1}-y_n\|^2 <+\infty$, and by \eqref{eq:zy}, $\sum_{n=1}^{+\infty}\|z_{n+1}-z_n\|^2 < +\infty$. As a result, $\mathbf{x}_{n+1}-\mathbf{x}_{n} \to 0$, $y_{n+1}-y_n \to 0$, $z_{n+1}-z_n \to 0$, and $\mathbf{Ax}_n +By_n =(z_n -z_{n-1})/\rho +b \to b$ as $n \to +\infty$. It then follows from the definition of $L_n$ that the sequence $(\mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}))_{n\in\mathbb{N}}$ is also convergent with $\lim_{n\to+\infty} \mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}) =\lim_{n\to+\infty}L_n$.

Let $(\overline{\mathbf{x}},\overline{y},\overline{z})$ be a cluster point of the sequence  $(\mathbf{x}_n,y_n,z_n)_{n\in \mathbb{N}}$. Then there exists a subsequence $(\mathbf{x}_{k_n},y_{k_n},z_{k_n})_{n\in \mathbb{N}}$ that converges to $(\overline{\mathbf{x}},\overline{y},\overline{z})$. In view of \eqref{eq:update_step_x}, letting $n =k_n$ and using Proposition~\ref{p:Bregman}\ref{p:Bregman_3}\&\ref{p:Bregman_4}, we obtain that, for all $i \in \{1,\dots,m\}$ and all $x_i\in \mathbb{R}^{d_i}$,
\begin{align}\label{eq:kn+}
&f_i(x_{i,k_n+1}) +\langle \nabla_i P(\mathbf{x}_{k_n})- g_{i,k_n}, x_{i,k_n+1} -x_i \rangle + \langle z_{k_n}, A_i x_{i,k_n+1} - A_ix_i\rangle +\frac{\rho}{2}\|\mathbf{A}\mathbf{u}_{i,k_n+1}(x_{i,k_n+1}) +By_{k_n} -b \|^2 \notag \\
&\quad  - \frac{\rho}{2}\|\mathbf{A}\mathbf{u}_{i,k_n+1}(x_{i}) +By_{k_n} -b \|^2 +\frac{\mu\alpha}{2}\|x_{i,k_n+1}-x_{i,k_n}\|^2 - \frac{\nu\ell_{\phi}}{2}\|x_{i}-x_{i,k_n}\|^2 \leq f_i(x_{i}).
\end{align}
Since $\nabla P$ is continuous, $\nabla P(\mathbf{x}_{k_n}) \to \nabla P(\overline{\mathbf{x}})$ as $n\to +\infty$. As $G +\frac{\beta}{2}\|\cdot\|^2$ is a continuous convex function, it follows from \cite[Example~9.14]{Rockafellar1998} that $G$ is locally Lipschitz continuous. Since $\mathbf{x}_{k_n} \to \overline{\mathbf{x}}$ as $n\to +\infty$, using Lemma~\ref{l:upsemicont} and passing to a subsequence if necessary, we can and do assume that $g_{k_n}\to \overline{g} \in \partial_L G (\overline{\mathbf{x}})$ as $n\to +\infty$. Now, for each $i \in \{1,\dots,m\}$, letting $x_i =\overline{x}_i$ and $n\to +\infty$ in \eqref{eq:kn+} with noting that $x_{i,k_n+1} \to \overline{x}_i$, $y_{k_n} \to \overline{y}$, and $z_{k_n} \to \overline{z}$, we have that $\limsup_{n \to +\infty} f_i(x_{i,k_n+1}) \leq f_i(\overline{x}_i)$, which together with the lower semicontinuity of $f_i$ yields
\begin{align*}
\lim_{n \to +\infty} f_i(x_{i,k_n+1}) = f_i(\overline{x}_i).
\end{align*}
As $H$, $P$, and $G$ are continuous, it follows that $\lim_{n \to +\infty}\mathcal{L}_\rho(\mathbf{x}_{k_n +1 },y_{k_n+1},z_{k_n +1}) = \mathcal{L}_\rho(\overline{\mathbf{x}},\overline{y},\overline{z})$. Since the sequence $(\mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}))_{n\in\mathbb{N}}$ is convergent, we deduce that
\begin{align*}
\lim_{n \to +\infty}\mathcal{L}_\rho(\mathbf{x}_{n },y_{n},z_{n}) =\mathcal{L}_\rho(\overline{\mathbf{x}},\overline{y},\overline{z}).    
\end{align*}

We next show that $(\overline{\mathbf{x}},\overline{y},\overline{z})$ is a stationary point of $\mathcal{L}_\rho$. In \eqref{eq:z-update} and \eqref{eq:B'z} with $n$ replaced by $k_n-1$, letting $n\to +\infty$ and using the coninuity of $\nabla H$ and the Lipschitz continuity of $\nabla \psi$, we obtain that $0 =\mathbf{A\overline{x}} + B\overline{y} -b$ and $0 =\nabla H(\overline{y}) + B^\top \overline{z}$. In turn, letting $n \to +\infty$ in \eqref{eq:kn+}, we have for all $i \in \{1,\dots,m\}$ and all $x_i\in \mathbb{R}^{d_i}$ that
\begin{align*}
&f_i(\overline{x}_i) +\langle \nabla_i P(\overline{\mathbf{x}})-\overline{g}_i, \overline{x}_i-x_i \rangle + \langle \overline{z}, A_i\overline{x}_i-A_ix_i \rangle\\
&\quad +\frac{\rho}{2}\|A_1\overline{x}_1 +\dots +A_{i-1}\overline{x}_{i-1} +A_i\overline{x}_i +A_{i+1}\overline{x}_{i+1}+\dots+A_m \overline{x}_{m} +B\overline{y} -b \|^2 \\
&\quad -\frac{\rho}{2}\|A_1\overline{x}_1 +\dots +A_{i-1}\overline{x}_{i-1} +A_ix_i +A_{i+1}\overline{x}_{i+1}+\dots+A_m \overline{x}_{m} +B\overline{y} -b \|^2 -\frac{\nu\ell_{ \phi}}{2}\|x_i-\overline{x}_i\|^2 \leq f_i(x_i),
\end{align*}
which can be written as
\begin{align*}
h_i(\overline{x}_i) \leq h_i(x_i),    
\end{align*}
where $h_i(x_i) =f_i(x_i) +\langle \nabla_i P(\overline{\mathbf{x}}) -\overline{g}_i, x_i \rangle + \langle \overline{z}, A_ix_i \rangle +\frac{\rho}{2}\|A_1\overline{x}_1 +\dots +A_{i-1}\overline{x}_{i-1} +A_ix_i +A_{i+1}\overline{x}_{i+1}+\dots+A_m \overline{x}_{m} +B\overline{y} -b \|^2 +\frac{\nu\ell_{\phi}}{2}\|x_i-\overline{x}_i\|^2$. It follows that, for all $i \in \{1,\dots,m\}$,
\begin{align*}
0 &\in \partial_L h_i(\overline{x}_i) =\partial_L (f_i)(\overline{x}_i) +\nabla_i P(\overline{\mathbf{x}})- \overline{g}_i +A_i^\top \overline{z} +\rho A_i^\top (\mathbf{A}\overline{\mathbf{x}}+B\overline{y}-b).
\end{align*}
Since $\mathbf{A}\overline{\mathbf{x}}+B\overline{y}-b =0$, we obtain that
\begin{align*}
0 \in \partial_L (f_1)(\overline{x}_1)\times \cdots \times \partial_L (f_m)(\overline{x}_m) +\nabla P(\overline{\mathbf{x}}) -\overline{g} +\mathbf{A}^\top \overline{z},
\end{align*}
which completes the proof due to Lemma~\ref{l:cal}\ref{l:cal_sum}\&\ref{l:cal_sep} and the strict differentiability of $G$.
\end{proof}

From the definition of the augmented Lagrangian, we have that
\begin{align}\label{eq:zz}
\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_{n+1}) -\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_{n}) &= \langle z_{n+1}-z_n, \mathbf{Ax}_{n+1}+By_{n+1}-b \rangle \notag\\
&= \frac{1}{\rho}\|z_{n+1}-z_n\|^2 
\end{align}

and that
\begin{align*}
\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_n) -\mathcal{L}_\rho(\mathbf{x}_{n+1},y_n,z_n) &= H(y_{n+1}) - H(y_n) + \langle z_n, B(y_{n+1}-y_n) \rangle \\
&\qquad + \frac{\rho}{2}(\|\mathbf{Ax}_{n+1}+By_{n+1}-b\|^2 - \|\mathbf{Ax}_{n+1}+By_{n}-b\|^2).  
\end{align*}
Writing $\mathbf{Ax}_{n+1}+By_{n}-b =(\mathbf{Ax}_{n+1}+By_{n+1}-b) -(By_{n+1}- By_n)$, we obtain that
\begin{align*}
&\|\mathbf{Ax}_{n+1}+By_{n+1}-b\|^2 - \|\mathbf{Ax}_{n+1}+By_{n}-b\|^2 \\
&= -\|B(y_{n+1}-y_n)\|^2 +2\langle  \mathbf{Ax}_{n+1}+By_{n+1}-b, B(y_{n+1}-y_n)\rangle \\
&= -\|B(y_{n+1}-y_n)\|^2 +\frac{2}{\rho}\langle  z_{n+1}-z_{n}, B(y_{n+1}-y_n)\rangle,
\end{align*}
and so
\begin{align*}
\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_n) -\mathcal{L}_\rho(\mathbf{x}_{n+1},y_n,z_n) = H(y_{n+1}) - H(y_n) +\langle z_{n+1}, B(y_{n+1}-y_n) \rangle -\frac{\rho}{2}\|B(y_{n+1}-y_n)\|^2.
\end{align*}
In view of \eqref{eq:B'z},
\begin{align*}
\langle z_{n+1}, B(y_{n+1}-y_n) \rangle &=\langle B^\top z_{n+1}, y_{n+1}-y_n \rangle \\
&=-\langle \nabla H(y_{n+1}), y_{n+1}-y_n \rangle -\nu_n\langle \nabla \psi(y_{n+1})- \nabla \psi(y_n), y_{n+1}-y_n \rangle \\
&\leq -H(y_{n+1}) +H(y_n) +\frac{\ell_H}{2}\|y_{n+1}-y_n\|^2,
\end{align*}
where the last inequality is from the $\ell_H$-Lipschitz continuity of $\nabla H$ and Lemma~\ref{l:diff}\ref{l:diff_descent}, and from the monotonicity of $\nabla \psi$. 
We therefore obtain that
\begin{align}\label{eq:yy}
\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_n) -\mathcal{L}_\rho(\mathbf{x}_{n+1},y_n,z_n) \leq \frac{\ell_H}{2}\|y_{n+1}-y_n\|^2 -\frac{\rho}{2}\|B(y_{n+1}-y_n)\|^2.    
\end{align}

Next, by the update of $x_{i,n+1}$ in Step~\ref{step:A2_2} of Algorithm~\ref{algo:BPLA}, for all $i \in \{1,\dots,m\}$ and all $x_i \in \mathbb{R}^{d_i}$,
\begin{align}\label{eq:update_step_x}
&f_i(x_{i,n+1}) +\langle \nabla_i P(\mathbf{x}_n) -g_{i,n}, x_{i,n+1} \rangle +\langle z_n, A_{i}x_{i,n+1} \rangle +\frac{\rho}{2}\|\mathbf{A}\mathbf{u}_{i,n+1}(x_{i,n+1}) +By_n -b\|^2 +\mu_n D_{\phi_i}(x_{i,n+1},x_{i,n}) \notag \\
&\leq  f_i(x_i) +\langle \nabla_i P(\mathbf{x}_n) -g_{i,n}, x_i \rangle +\langle z_n, A_{i}x_i\rangle +\frac{\rho}{2}\|\mathbf{A}\mathbf{u}_{i,n+1}(x_i) +By_n -b\|^2 +\mu_n D_{\phi_i}(x_i,x_{i,n}).
\end{align}
Letting $x_i =x_{i,n}$, using Proposition~\ref{p:Bregman}\ref{p:Bregman_1}\&\ref{p:Bregman_3}, and summing up over $i \in \{1,\dots,m\}$, we derive that
\begin{align}\label{eq:from x-update}
&\sum_{i=1}^m f_i(x_{i,n+1}) +\langle \nabla P(\mathbf{x}_n) -g_n, \mathbf{x}_{n+1} \rangle +\langle z_n, \mathbf{Ax}_{n+1} \rangle +\frac{\rho}{2}\|\mathbf{A}\mathbf{x}_{n+1} +By_n -b\|^2 +\frac{\mu\alpha}{2}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2 \notag\\
&\leq \sum_{i=1}^m f_i(x_{i,n}) +\langle \nabla P(\mathbf{x}_n) -g_n, \mathbf{x}_{n} \rangle +\langle z_n, \mathbf{Ax}_{n} \rangle +\frac{\rho}{2}\|\mathbf{A}\mathbf{x}_n +By_n -b\|^2.
\end{align}

where the first inequality is obtained by using Lemma~\ref{l:diff}\ref{l:diff_descent} on the $\ell_P$-Lipschitz continuity of $\nabla P$ and \cite[Lemma~4.1]{BDL22} on the $\beta$-weak convexity of $G$, while the last inequality follows from \eqref{eq:from x-update}. Summing up three relations \eqref{eq:zz}, \eqref{eq:yy}, and \eqref{eq:xx} yields
\begin{align}\label{eq:LL}
&\mathcal{L}_\rho(\mathbf{x}_{n+1},y_{n+1},z_{n+1}) - \mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}) \notag\\
&\leq -\delta_{\mathbf{x}}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2 +\frac{\ell_H}{2}\|y_{n+1}-y_n\|^2 -\frac{\rho}{2}\|B(y_{n+1}-y_n)\|^2 +\frac{1}{\rho}\|z_{n+1}-z_n\|^2.
\end{align}

Combining this with the fact that
\begin{align*}
\langle z_n, \mathbf{Ax}_n+By_n-b \rangle +\frac{\rho}{2}\|\mathbf{Ax}_n+By_n-b\|^2 =\frac{\rho}{2}\left\| \frac{z_n}{\rho} +\mathbf{Ax}_n+By_n-b \right\|^2 -\frac{1}{2\rho}\|z_n\|^2,
\end{align*}
we deduce that
\begin{align*}
L_n &=\mathcal{L}_\rho(\mathbf{x}_n,y_n,z_n) + c\|y_n-y_{n-1}\|^2 \\
&\geq \sum_{i=1}^m f_i(x_{i,n}) +H(y_n) +P(\mathbf{x}_n) -G(\mathbf{x}_n) \\ 
&\quad +\frac{\rho}{2}\left\| \frac{z_n}{\rho} + \mathbf{Ax}_n+By_n-b \right\|^2 -\frac{1}{2\lambda\rho}\left(1 +\frac{\nu\ell_{\psi}}{\omega}\right)\|\nabla H(y_n)\|^2 +\left(c -\frac{(\omega +\nu\ell_{\psi})\nu\ell_{\psi}}{2\lambda\rho}\right)\|y_n-y_{n-1}\|^2 \\
&= \left(\sum_{i=1}^m f_i(x_{i,n}) +P(\mathbf{x}_n) -G(\mathbf{x}_n)\right) +\left(H(y_n) -\frac{1}{2\ell_H}\|\nabla H(y_n)\|^2\right) +\frac{\rho}{2}\left\| \frac{z_n}{\rho} + \mathbf{Ax}_n+By_n-b \right\|^2 \\ 
&\quad +\left(\frac{1}{2\ell_H} -\frac{1}{2\lambda\rho}\left(1 +\frac{\nu\ell_{\psi}}{\omega}\right)\right)\|\nabla H(y_n)\|^2 +\frac{\nu\ell_{\psi}}{2\lambda\rho}(2\ell_H +3\nu\ell_{\psi} -\omega)\|y_n-y_{n-1}\|^2.
\end{align*}
Now, we note that
\begin{align*}
\rho > \frac{\ell_H +\sqrt{\ell_H^2 +8(\ell_H +2\nu\ell_{\psi})^2}}{2\lambda} \geq \frac{\ell_H +\sqrt{\ell_H^2 +8\ell_H^2}}{2\lambda} =\frac{2\ell_H}{\lambda},    
\end{align*}
and so $\frac{1}{2\ell_H} >\frac{1}{\lambda\rho}$. Choosing $\omega =1$ if $\nu\ell_{\psi} =0$, and $\omega =\nu\ell_{\psi}$ if $\nu\ell_{\psi} >0$, it holds that
\begin{align*}
&\theta :=\frac{1}{2\ell_H} -\frac{1}{2\lambda\rho}\left(1 +\frac{\nu\ell_{\psi}}{\omega}\right) \geq \frac{1}{2\ell_H} -\frac{1}{2\lambda\rho}(1 +1) >0 \text{~~and~~} \\
&\frac{\nu\ell_{\psi}}{2\lambda\rho}(2\ell_H +3\nu\ell_{\psi} -\omega) \geq \frac{\nu\ell_{\psi}}{2\lambda\rho}(3\nu\ell_{\psi} -\omega) =\frac{\nu^2\ell_{\psi}^2}{\lambda\rho}. 
\end{align*}
This together with \ref{t:cvg_decrease} yields
\begin{align}\label{eq:L_n_bounded}
L_1 \geq L_n &\geq \left(\sum_{i=1}^m f_i(x_{i,n}) +P(\mathbf{x}_n) -G(\mathbf{x}_n)\right) +\left(H(y_n) -\frac{1}{2\ell_H}\|\nabla H(y_n)\|^2\right) +\frac{\rho}{2}\left\| \frac{z_n}{\rho} + \mathbf{Ax}_n+By_n-b \right\|^2 \notag \\ 
&\quad +\theta\|\nabla H(y_n)\|^2 +\frac{\nu^2\ell_{\psi}^2}{\lambda\rho}\|y_n-y_{n-1}\|^2,
\end{align}

On the other hand, since all the terms on the right hand side of \eqref{eq:L_n_bounded} are bounded below, so is the sequence $(L_n)_{n\in\mathbb{N}}$. Combining with the nonincreasing property of $(L_n)_{n\in\mathbb{N}}$ due to \ref{t:cvg_decrease}, it follows that $(L_n)_{n\in\mathbb{N}}$ is convergent. By rearranging \eqref{eq:decrease} and performing telescoping, we then have that
\begin{align*}
\sum_{n=1}^{+\infty}\delta_y \|y_{n+1}-y_n\|^2 + \delta_{\mathbf{x}}\sum_{n=1}^{+\infty}\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\|^2 \leq \sum_{n=1}^{+\infty}(L_n - L_{n+1}) = L_1 - \lim_{n\to+\infty} L_n < +\infty,
\end{align*}
which implies that $\sum_{n=1}^{+\infty}\|\mathbf{x}_{n+1}-\mathbf{x}_n\|^2 < +\infty$, $\sum_{n=1}^{+\infty}\|y_{n+1}-y_n\|^2 <+\infty$, and by \eqref{eq:zy}, $\sum_{n=1}^{+\infty}\|z_{n+1}-z_n\|^2 < +\infty$. As a result, $\mathbf{x}_{n+1}-\mathbf{x}_{n} \to 0$, $y_{n+1}-y_n \to 0$, $z_{n+1}-z_n \to 0$, and $\mathbf{Ax}_n +By_n =(z_n -z_{n-1})/\rho +b \to b$ as $n \to +\infty$. It then follows from the definition of $L_n$ that the sequence $(\mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}))_{n\in\mathbb{N}}$ is also convergent with $\lim_{n\to+\infty} \mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}) =\lim_{n\to+\infty}L_n$.

Let $(\overline{\mathbf{x}},\overline{y},\overline{z})$ be a cluster point of the sequence  $(\mathbf{x}_n,y_n,z_n)_{n\in \mathbb{N}}$. Then there exists a subsequence $(\mathbf{x}_{k_n},y_{k_n},z_{k_n})_{n\in \mathbb{N}}$ that converges to $(\overline{\mathbf{x}},\overline{y},\overline{z})$. In view of \eqref{eq:update_step_x}, letting $n =k_n$ and using Proposition~\ref{p:Bregman}\ref{p:Bregman_3}\&\ref{p:Bregman_4}, we obtain that, for all $i \in \{1,\dots,m\}$ and all $x_i\in \mathbb{R}^{d_i}$,
\begin{align}\label{eq:kn+}
&f_i(x_{i,k_n+1}) +\langle \nabla_i P(\mathbf{x}_{k_n})- g_{i,k_n}, x_{i,k_n+1} -x_i \rangle + \langle z_{k_n}, A_i x_{i,k_n+1} - A_ix_i\rangle +\frac{\rho}{2}\|\mathbf{A}\mathbf{u}_{i,k_n+1}(x_{i,k_n+1}) +By_{k_n} -b \|^2 \notag \\
&\quad  - \frac{\rho}{2}\|\mathbf{A}\mathbf{u}_{i,k_n+1}(x_{i}) +By_{k_n} -b \|^2 +\frac{\mu\alpha}{2}\|x_{i,k_n+1}-x_{i,k_n}\|^2 - \frac{\nu\ell_{\phi}}{2}\|x_{i}-x_{i,k_n}\|^2 \leq f_i(x_{i}).
\end{align}
Since $\nabla P$ is continuous, $\nabla P(\mathbf{x}_{k_n}) \to \nabla P(\overline{\mathbf{x}})$ as $n\to +\infty$. As $G +\frac{\beta}{2}\|\cdot\|^2$ is a continuous convex function, it follows from \cite[Example~9.14]{Rockafellar1998} that $G$ is locally Lipschitz continuous. Since $\mathbf{x}_{k_n} \to \overline{\mathbf{x}}$ as $n\to +\infty$, using Lemma~\ref{l:upsemicont} and passing to a subsequence if necessary, we can and do assume that $g_{k_n}\to \overline{g} \in \partial_L G (\overline{\mathbf{x}})$ as $n\to +\infty$. Now, for each $i \in \{1,\dots,m\}$, letting $x_i =\overline{x}_i$ and $n\to +\infty$ in \eqref{eq:kn+} with noting that $x_{i,k_n+1} \to \overline{x}_i$, $y_{k_n} \to \overline{y}$, and $z_{k_n} \to \overline{z}$, we have that $\limsup_{n \to +\infty} f_i(x_{i,k_n+1}) \leq f_i(\overline{x}_i)$, which together with the lower semicontinuity of $f_i$ yields
\begin{align*}
\lim_{n \to +\infty} f_i(x_{i,k_n+1}) = f_i(\overline{x}_i).
\end{align*}
As $H$, $P$, and $G$ are continuous, it follows that $\lim_{n \to +\infty}\mathcal{L}_\rho(\mathbf{x}_{k_n +1 },y_{k_n+1},z_{k_n +1}) = \mathcal{L}_\rho(\overline{\mathbf{x}},\overline{y},\overline{z})$. Since the sequence $(\mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}))_{n\in\mathbb{N}}$ is convergent, we deduce that
\begin{align*}
\lim_{n \to +\infty}\mathcal{L}_\rho(\mathbf{x}_{n },y_{n},z_{n}) =\mathcal{L}_\rho(\overline{\mathbf{x}},\overline{y},\overline{z}).    
\end{align*}

We next show that $(\overline{\mathbf{x}},\overline{y},\overline{z})$ is a stationary point of $\mathcal{L}_\rho$. In \eqref{eq:z-update} and \eqref{eq:B'z} with $n$ replaced by $k_n-1$, letting $n\to +\infty$ and using the coninuity of $\nabla H$ and the Lipschitz continuity of $\nabla \psi$, we obtain that $0 =\mathbf{A\overline{x}} + B\overline{y} -b$ and $0 =\nabla H(\overline{y}) + B^\top \overline{z}$. In turn, letting $n \to +\infty$ in \eqref{eq:kn+}, we have for all $i \in \{1,\dots,m\}$ and all $x_i\in \mathbb{R}^{d_i}$ that
\begin{align*}
&f_i(\overline{x}_i) +\langle \nabla_i P(\overline{\mathbf{x}})-\overline{g}_i, \overline{x}_i-x_i \rangle + \langle \overline{z}, A_i\overline{x}_i-A_ix_i \rangle\\
&\quad +\frac{\rho}{2}\|A_1\overline{x}_1 +\dots +A_{i-1}\overline{x}_{i-1} +A_i\overline{x}_i +A_{i+1}\overline{x}_{i+1}+\dots+A_m \overline{x}_{m} +B\overline{y} -b \|^2 \\
&\quad -\frac{\rho}{2}\|A_1\overline{x}_1 +\dots +A_{i-1}\overline{x}_{i-1} +A_ix_i +A_{i+1}\overline{x}_{i+1}+\dots+A_m \overline{x}_{m} +B\overline{y} -b \|^2 -\frac{\nu\ell_{ \phi}}{2}\|x_i-\overline{x}_i\|^2 \leq f_i(x_i),
\end{align*}
which can be written as
\begin{align*}
h_i(\overline{x}_i) \leq h_i(x_i),    
\end{align*}
where $h_i(x_i) =f_i(x_i) +\langle \nabla_i P(\overline{\mathbf{x}}) -\overline{g}_i, x_i \rangle + \langle \overline{z}, A_ix_i \rangle +\frac{\rho}{2}\|A_1\overline{x}_1 +\dots +A_{i-1}\overline{x}_{i-1} +A_ix_i +A_{i+1}\overline{x}_{i+1}+\dots+A_m \overline{x}_{m} +B\overline{y} -b \|^2 +\frac{\nu\ell_{\phi}}{2}\|x_i-\overline{x}_i\|^2$. It follows that, for all $i \in \{1,\dots,m\}$,
\begin{align*}
0 &\in \partial_L h_i(\overline{x}_i) =\partial_L (f_i)(\overline{x}_i) +\nabla_i P(\overline{\mathbf{x}})- \overline{g}_i +A_i^\top \overline{z} +\rho A_i^\top (\mathbf{A}\overline{\mathbf{x}}+B\overline{y}-b).
\end{align*}
Since $\mathbf{A}\overline{\mathbf{x}}+B\overline{y}-b =0$, we obtain that
\begin{align*}
0 \in \partial_L (f_1)(\overline{x}_1)\times \cdots \times \partial_L (f_m)(\overline{x}_m) +\nabla P(\overline{\mathbf{x}}) -\overline{g} +\mathbf{A}^\top \overline{z},
\end{align*}
which completes the proof due to Lemma~\ref{l:cal}\ref{l:cal_sum}\&\ref{l:cal_sep} and the strict differentiability of $G$.

Suppose that Assumption~\ref{a:standing} holds. Let $(\mathbf{x}_n,y_n,z_n)_{n\in \mathbb{N}}$ be the sequence generated by Algorithm~\ref{algo:BPLA} and, for each $n\in \mathbb{N}^*$, define
\begin{align*}
L_n =\mathcal{L}_\rho(\mathbf{x}_{n},y_{n},z_{n}) +c\|y_n-y_{n-1}\|^2, \text{~where~} c=\frac{(\ell_H+2\nu\ell_{\psi})\nu\ell_{\psi}}{\lambda\rho}.     
\end{align*}

\ref{t:cvg_decrease}: Let $n\in \mathbb{N}$. The update of $z_{n+1}$ yields
\begin{align}\label{eq:z-update}
z_{n+1} -z_n =\rho(\mathbf{Ax}_{n+1}+By_{n+1}-b).   
\end{align}
By the optimality condition for the update of $y_{n+1}$ in Step~\ref{step:A2_2} of Algorithm~\ref{algo:BPLA}, 
\begin{align*}
0 &= \nabla H(y_{n+1}) + B^\top z_n +\rho B^\top(\mathbf{Ax}_{n+1} +By_{n+1} -b) +\nu_n(\nabla \psi(y_{n+1}) - \nabla \psi(y_n)),
\end{align*}
which combined with \eqref{eq:z-update} yields
\begin{align}\label{eq:B'z}
B^\top z_{n+1} =-\nabla H(y_{n+1}) -\nu_n(\nabla \psi(y_{n+1}) -\nabla \psi(y_n)).  
\end{align}

Now, since $\Ima(\mathbf{A}) \cup \{b\} \subseteq \Ima(B)$, it follows from \eqref{eq:z-update} that
\begin{align}\label{eq:zImB}
z_{n+1}-z_n \in \Ima(B)    
\end{align}
which, by Lemma~\ref{l:norm}\ref{l:norm_M'x}, yields 
\begin{align*}
\|z_{n+1} -z_n\| \leq \frac{1}{\sqrt{\lambda}}\|B^\top z_{n+1} -B^\top z_n\|.
\end{align*}
Let $n\in \mathbb{N}^*$. We derive from \eqref{eq:B'z} and the Lipschitz continuity of $\nabla H$ and $\nabla \psi$ that
\begin{align}\label{eq:BTZy}
\|B^\top z_{n+1} -B^\top z_n\| &\leq \|\nabla H(y_{n+1}) -\nabla H(y_n)\| +\nu_n\|\nabla \psi(y_{n+1}) -\nabla \psi(y_n)\| +\nu_{n-1}\|\nabla \psi(y_n) - \nabla \psi(y_{n-1})\| \notag \\ 
&\leq (\ell_H +\nu\ell_{\psi})\|y_{n+1} -y_n\| +\nu\ell_{\psi}\|y_n -y_{n-1}\|,
\end{align}
and thus, 
\begin{align}\label{eq:zy}
\|z_{n+1} -z_n\| \leq \frac{1}{\sqrt{\lambda}}\|B^\top z_{n+1} -B^\top z_n\| \leq \frac{1}{\sqrt{\lambda}}((\ell_H +\nu\ell_{\psi})\|y_{n+1} -y_n\| +\nu\ell_{\psi}\|y_n -y_{n-1}\|).
\end{align}

\begin{proof}
For each $n\in \mathbb{N}$, set $w_n=(\mathbf{x}_{n+1},y_{n+1},z_{n+1},y_n)$ and $\Delta_n =\|\mathbf{x}_{n+2}-\mathbf{x}_{n+1}\| +\|y_{n+2}-y_{n+1}\|$. Let $n \in \mathbb{N}^*$. According to Theorem~\ref{t:cvg}, we have that
\begin{align}\label{eq:auxilary_decrease}
\mathcal{F}(w_{n+1}) +\delta_{\mathbf{x}}\|\mathbf{x}_{n+2}-\mathbf{x}_{n+1}\|^2 + \delta_y \|y_{n+2}-y_{n+1}\|^2 \leq \mathcal{F}(w_{n}),
\end{align}
that $w_{n+1} - w_n \to 0$ as $n\to +\infty$, that $(w_n)_{n\in\mathbb{N}}$ is bounded, that any of its cluster point $\overline{w}=(\overline{\mathbf{x}},\overline{y},\overline{z},\overline{y})$ is a stationary point of \eqref{eq:prob}, and also that $\mathcal{F}(w_{n}) \to \mathcal{F}(\overline{w}) = \mathcal{L}_{\rho}(\overline{\mathbf{x}},\overline{y},\overline{z})$ as $n\to +\infty$. Notice that
\begin{align*}
\Delta_n^2 \leq \left(\frac{1}{\delta_{\mathbf{x}}} +\frac{1}{\delta_y}\right) \left(\delta_{\mathbf{x}}\|\mathbf{x}_{n+2}-\mathbf{x}_{n+1}\|^2 + \delta_y \|y_{n+2}-y_{n+1}\|^2\right),    
\end{align*}
which together with \eqref{eq:auxilary_decrease} yields
\begin{align*}
\mathcal{F}(w_{n+1}) +C_1\Delta_n^2 \leq \mathcal{F}(w_{n}), \text{~~where~} C_1 =\frac{\delta_{\mathbf{x}}\delta_y}{\delta_{\mathbf{x}}+\delta_y}.
\end{align*}

Next, we have that
\begin{align*}
\partial_L ^\mathbf{x} \mathcal{F}(w_n) = \partial_L \left( \sum_{i=1}^{m} f_i\right)(\mathbf{x}_{n+1}) + \nabla P(\mathbf{x}_{n+1}) - \nabla G(\mathbf{x}_{n+1}) + \mathbf{A}^\top z_{n+1} + \rho \mathbf{A}^\top(\mathbf{Ax}_{n+1} + By_{n+1} -b)    
\end{align*}
and, for all $i \in \{1,\dots,m\}$,
\begin{align*}
\partial_L ^{x_i} \mathcal{F}(w_n) = \partial_L f_i(x_{i,n+1})+\nabla_i P(\mathbf{x}_{n+1}) - \nabla_i G(\mathbf{x}_{n+1}) + A_i^\top z_{n+1} + \rho A_i^\top(\mathbf{Ax}_{n+1} + By_{n+1} -b).    
\end{align*}
By revoking the optimality condition for the update of $x_{i,n+1}$ in Step~\ref{step:A2_2} of Algorithm~\ref{algo:BPLA},
\begin{align*}
0 &\in \partial_L f_i(x_{i,n+1}) +\nabla_i P(\mathbf{x}_{n}) -  \nabla_i G(\mathbf{x}_n) + A_i^\top z_n   +\rho A_i^\top(\mathbf{A}\mathbf{u}_{i,n+1}(x_{i,n+1} ) +By_n -b ) \\
&\quad +\mu_n(\nabla \phi_i (x_{i,n+1})- \nabla \phi_i (x_{i,n})),    
\end{align*}
which combined with the above equality implies that
\begin{align*}
&(\nabla_i P(\mathbf{x}_{n+1}) -\nabla_i P(\mathbf{x}_{n})) -(\nabla_i G(\mathbf{x}_{n+1}) -\nabla_i G(\mathbf{x}_n)) +A_i^\top(z_{n+1}-z_n) -\mu_n(\nabla \phi_i (x_{i,n+1}) -\nabla \phi_i (x_{i,n})) \\
&\quad +\rho A_i^\top (A_{i+1}x_{i+1,n+1} +\dots +A_mx_{m,n+1} -A_{i+1}x_{i+1,n} -\dots -A_mx_{m,n} +By_{n+1} -By_n) \in \partial_L ^{x_i} \mathcal{F}(w_n).
\end{align*}
Therefore,
\begin{align}\label{eq:dxi}
\dist(0,\partial_L ^{x_i} \mathcal{F}(w_n)) 
&\leq \|\nabla_i P(\mathbf{x}_{n+1}) -\nabla_i P(\mathbf{x}_{n})\| +\|\nabla_i G(\mathbf{x}_{n+1}) -\nabla_i G(\mathbf{x}_n)\| \notag \\
&\quad +\|A_i^\top(z_{n+1}-z_n)\| +\mu_n\|\nabla \phi_i (x_{i,n+1}) -\nabla \phi_i (x_{i,n})\| \notag \\
&\quad +\rho \|A_i^\top (A_{i+1}x_{i+1,n+1} +\dots +A_mx_{m,n+1} -A_{i+1}x_{i+1,n} -\dots -A_mx_{m,n} +By_{n+1} -By_n\| \notag \\ 
&\leq \ell_P\|\mathbf{x}_{n+1} - \mathbf{x}_{n}\| +\ell_G\|\mathbf{x}_{n} - \mathbf{x}_{n+1}\| +\|A_i^\top\|\|z_{n+1}-z_n\| +\mu_n \ell_{\phi}\|x_{i,n+1}-x_{i,n}\| \notag \\
&\quad +\rho\sum_{j=i+1}^{m} \|A_i^\top\| \|A_j\| \|x_{j,n+1}-x_{j,n}\| +\rho\|A_i^\top\| \|B\| \|y_{n+1}-y_n\| \notag \\
&\leq  \left(\ell_P +\ell_G +\mu_n\ell_{\phi} +\rho\sum_{j=i+1}^{m} \|A_i^\top\| \|A_j\|\right)\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\| +\|A_i^\top\|\|z_{n+1}-z_n\| \notag \\
&\quad +\rho\|A_i^\top\| \|B\| \|y_{n+1}-y_n\|.
\end{align}

We now see that
\begin{align*}
\partial_L ^y \mathcal{F}(w_n) =\nabla H(y_{n+1}) + B^\top z_{n+1} +\rho B^\top(\mathbf{Ax}_{n+1} + By_{n+1} -b) +2c(y_{n+1}-y_{n})    
\end{align*}
and from the optimality condition for the update of $y_{n+1}$ in Algorithm~\ref{algo:BPLA} that 
\begin{align*}
0 &= \nabla H(y_{n+1}) + B^\top z_n +\rho B^\top(\mathbf{Ax}_{n+1} +By_{n+1} -b) +\nu_n(\nabla \psi(y_{n+1}) - \nabla \psi(y_n)).
\end{align*}
This leads to
\begin{align*}
\partial_L ^y \mathcal{F}(w_n) &=B^{\top}(z_{n+1}-z_n) -\nu_n(\nabla \psi(y_{n+1}) -\nabla \psi(y_n)) + 2c(y_{n+1}-y_{n}),   
\end{align*}
and so
\begin{align}\label{eq:dy}
\dist(0,\partial_L ^{y} \mathcal{F}(w_n)) 
&\leq \|B^{\top}(z_{n+1}-z_n)\| +\nu_n\|\nabla \psi(y_{n+1}) -\nabla \psi(y_n)\| + 2c\|y_{n+1}-y_{n})\| \notag \\
&\leq \|B^{\top}(z_{n+1}-z_n)\| +(\nu\ell_\psi +2c)\|y_{n+1}-y_{n})\|.
\end{align}

Since $\partial_L ^z \mathcal{F}(w_n) =\mathbf{Ax}_{n+1} + By_{n+1} -b =\frac{1}{\rho}(z_{n+1} -z_n)$ and
$\partial_L ^t \mathcal{F}(w_n) =-2c(y_{n+1}-y_{n})$, it holds that
\begin{align}\label{eq:dzdt}
\dist(0,\partial_L ^{z} \mathcal{F}(w_n)) =\frac{1}{\rho}\|z_{n+1}-z_n\| \text{~~and~~}
\dist(0,\partial_L ^{t} \mathcal{F}(w_n)) =2c\|y_{n+1}-y_n\|.    
\end{align}
Combining \eqref{eq:dxi}, \eqref{eq:dy}, and \eqref{eq:dzdt}, noting that $\limsup_{n\to +\infty} \mu_n =\overline{\mu} <+\infty$, and using \eqref{eq:BTZy} and \eqref{eq:zy} in the proof of Theorem~\ref{t:cvg}, we derive that there exists $n_0\in \mathbb{N}^*$ and $C_2 \in \mathbb{R}_{++}$ such that, for all $n\geq n_0$, 

\begin{align*}
\dist(0, \partial_L \mathcal{F}(w_n)) 
\leq C_2 \left(\|\mathbf{x}_{n+1}-\mathbf{x}_{n}\| +\|y_{n+1}-y_n\| +\|y_{n}-y_{n-1}\|\right) 
\leq C_2(\Delta_{n-1} +\Delta_{n-2}).
\end{align*}

\ref{t:full_cvg}: We see that all the conditions in the \emph{abstract convergence} framework \cite[Theorem~5.1]{BDL22} are satisfied with $I =\{1,2\}$, $\lambda_1=\lambda_2=1/2$, $\alpha_n \equiv C_1$, $\beta_n \equiv 1/(2C_2)$, and $\varepsilon_n \equiv 0 $. By \cite[Theorem~5.1(i)]{BDL22}, 
\begin{align*}
\sum_{n=0}^{+\infty} (\|\mathbf{x}_{n+2}-\mathbf{x}_{n+1}\|+\|y_{n+2}-y_{n+1}\|) =\sum_{n=0}^{+\infty} \Delta_n < +\infty,
\end{align*}
which implies that $\sum_{n=0}^{+\infty} \|\mathbf{x}_{n+1}-\mathbf{x}_{n}\| <+\infty$ and $\sum_{n=0}^{+\infty} \|y_{n+1}-y_{n}\| < +\infty$. Together with \eqref{eq:zy}, we derive that $\sum_{n=0}^{+\infty} \|z_{n+1}-z_n\|<+\infty$, and hence 
\begin{align*}
\sum_{n=0}^{+\infty} \|(\mathbf{x}_{n+1},y_{n+1},z_{n+1})-(\mathbf{x}_{n},y_{n},z_{n})\| < +\infty,
\end{align*}
which yields the convergence of $(\mathbf{x}_{n},y_{n},z_{n})_{n\in\mathbb{N}}$ to $(\mathbf{x}^{*},y^{*},z^{*})$. In view of Theorem~\ref{t:cvg}\ref{t:cvg_seq}, $(\mathbf{x}^{*},y^{*},z^{*})$ is a stationary point of $\mathcal{L}_\rho$.

\ref{t:full_rate_finite}: This follows from the arguments in the proof of \cite[Theorem~5.1]{BDL22} and \cite[Theorem~2(i)]{Attouch2007}. 

\ref{t:full_rate_linear}: According to \cite[Theorem~5.1(iv)]{BDL22}, there exist $\gamma_0\in \mathbb{R}_{++}$ and $\zeta\in \left(0,1\right)$ such that, for all $n\in \mathbb{N}^*$, 
\begin{align*}
\|(\mathbf{x}_{n},y_{n})-(\mathbf{x}^{*},y^{*})\|\leq\gamma_0 \zeta^{\frac{n}{2}} \text{~~and~~}
|\mathcal{F}(\mathbf{x}_{n},y_{n},z_{n},y_{n-1})-\mathcal{F}(\mathbf{x}^{*},y^{*},z^{*},y^*)| \leq \gamma_0\zeta^n.
\end{align*}
We derive that, for all $n\in \mathbb{N}^*$, $\|\mathbf{x}_n-\mathbf{x}^{*}\|\leq \gamma_0\zeta^{\frac{n}{2}}$ and $\|y_n-y^{*}\|\leq \gamma_0\zeta^{\frac{n}{2}}$, which yields 
\begin{align*}
\|y_n-y_{n-1}\| \leq \|y_n-y^{*}\|+\|y_{n-1}-y^{*}\| \leq (1+\zeta^{-\frac{1}{2}})\gamma_0\zeta^{\frac{n}{2}}.    
\end{align*}
By passing to the limit in \eqref{eq:B'z}, $B^\top z^{*}=-\nabla H(y^{*})$. Following the same steps as in \eqref{eq:BTZy} and \eqref{eq:zy}, we obtain that, for all $n\in \mathbb{N}^*$,
\begin{align*}
\|z_n-z^{*}\| &\leq \frac{\ell_H}{\sqrt{\lambda}}\|y_n-y^{*}\| + \frac{\nu \ell_{\psi}}{\sqrt{\lambda}}\|y_{n}-y_{n-1}\|\leq \gamma_1\zeta^{\frac{n}{2}}, \text{~~where~} \gamma_1 :=\frac{\ell_H\gamma_0+(1+\zeta^{-\frac{1}{2}})\nu\ell_{\psi}\gamma_0}{\sqrt{\lambda}}.
\end{align*}
Consequently,
\begin{align*}
&\|(\mathbf{x}_{n},y_{n},z_{n})-(\mathbf{x}^{*},y^{*},z^{*})\| \leq \|\mathbf{x}_{n}-\mathbf{x}^{*}\| + \|y_{n}-y^{*}\| + \|z_{n}-z^{*}\|\leq (2\gamma_0 +\gamma_1)\zeta^{\frac{n}{2}}, \\
&\|\mathbf{Ax}_n+By_n-b\| =\frac{1}{\rho}\|z_n-z_{n-1}\| \leq \frac{1}{\rho}(\|z_n-z^{*}\| +\|z_{n-1}-z^{*}\|) \leq \frac{(1+\zeta^{-\frac{1}{2}})\gamma_1}{\rho} \zeta^{\frac{n}{2}}, \\
\text{and~} &\|z_n\| \leq \|z_n-z^{*}\| + \|z^{*}\| \leq \gamma_1 \zeta^{\frac{n}{2}} + \|z^{*}\|.
\end{align*}

We now deduce from the definition of $\mathcal{F}$ that
\begin{align*}
|\mathcal{L}_{\rho}(\mathbf{x}_{n},y_{n},z_{n})- \mathcal{L}_{\rho}(\mathbf{x}^{*},y^{*},z^{*})|&= \left|\mathcal{F}(\mathbf{x}_{n},y_{n},z_{n},y_{n-1})-\mathcal{F}(\mathbf{x}^{*},y^{*},z^{*},y^*) - c\|y_n-y_{n-1}\|^2\right|\\
&\leq |\mathcal{F}(\mathbf{x}_{n},y_{n},z_{n},y_{n-1})-\mathcal{F}(\mathbf{x}^{*},y^{*},z^{*},y^*)| + c\|y_n-y_{n-1}\|^2\\
&\leq \gamma_2\zeta^n, \text{~~where~} \gamma_2 :=\gamma_0 + c(1+\zeta^{-\frac{1}{2}})^2\gamma_0^2
\end{align*}
and from the definition of $\mathcal{L}_\rho$ that 
\begin{align*}
|F(\mathbf{x}_n,y_n)-F(\mathbf{x}^{*},y^{*})| &= |\mathcal{L}_{\rho}(\mathbf{x}_n,y_n,z_n)-\mathcal{L}_{\rho}(\mathbf{x}^{*},y^{*},z^{*})-\langle z_n, \mathbf{Ax}_n + By_n-b\rangle - \frac{\rho}{2}\|\mathbf{Ax}_n + By_n-b\|^2| \\
&\leq |\mathcal{L}_{\rho}(\mathbf{x}_n,y_n,z_n)-\mathcal{L}_{\rho}(\mathbf{x}^{*},y^{*},z^{*})| + \|z_n\|\|\mathbf{Ax}_n + By_n-b\| + \frac{\rho}{2}\|\mathbf{Ax}_n + By_n-b\|^2  \\ 
&\leq \gamma_2\zeta^n + \left(\gamma_1 \zeta^{\frac{n}{2}} + \|z^{*}\|\right)\frac{(1+\zeta^{-\frac{1}{2}})\gamma_1}{\rho} \zeta^{\frac{n}{2}}+ \frac{(1+\zeta^{-\frac{1}{2}})^2\gamma_1^2}{2\rho}\zeta^n \\
&\leq \left(\gamma_2 +\frac{(3+\zeta^{-\frac{1}{2}})(1+\zeta^{-\frac{1}{2}})\gamma_1^2}{2\rho} +\frac{\|z^{*}\|(1+\zeta^{-\frac{1}{2}})\gamma_1}{\rho}\right)\zeta^{\frac{n}{2}},
\end{align*}
where the last inequality follows from the fact that $\zeta^n \leq \zeta^{\frac{n}{2}}$ since $\zeta \in (0,1)$. By letting 
\begin{align*}
\overline{\gamma} =\max \left\{ 2\gamma_0+\gamma_1, \frac{(1+\zeta^{-\frac{1}{2}})\gamma_1}{\rho}, \gamma_2 +\frac{(3+\zeta^{-\frac{1}{2}})(1+\zeta^{-\frac{1}{2}})\gamma_1^2}{2\rho} +\frac{\|z^{*}\|(1+\zeta^{-\frac{1}{2}})\gamma_1}{\rho} \right\} 
\end{align*}
and increasing it if necessary, we arrive at the conclusion.

\ref{t:full_rate_sublinear}: Following the arguments in \cite[Theorem~5.1(iv)]{BDL22} and \cite[Theorem~2(iii)]{Attouch2007}, we find $\gamma_0 \in \mathbb{R}_{++}$ such that, for all $n\in \mathbb{N}^*$, 
\begin{align*}
\|(\mathbf{x}_{n},y_{n})-(\mathbf{x}^{*},y^{*})\|\leq \gamma_0 n^{-\frac{1-\kappa}{2\kappa-1}} \text{~~and~~}
|\mathcal{F}(\mathbf{x}_{n},y_{n},z_{n},y_{n-1})-\mathcal{F}(\mathbf{x}^{*},y^{*},z^{*},y^*)| \leq \gamma_0 n^{-\frac{2-2\kappa}{2\kappa-1}}.
\end{align*}
Similar to \ref{t:full_rate_linear}, for all $n\geq 2$, since $n-1\geq \frac{1}{2}n$ and $\frac{1-\kappa}{2\kappa-1} >0$, we derive that 
\begin{align*}
&\|(\mathbf{x}_{n},y_{n},z_{n})-(\mathbf{x}^{*},y^{*},z^{*})\| \leq (2\gamma_0+\gamma_1) n^{-\frac{1-\kappa}{2\kappa-1}},\\
&\|\mathbf{Ax}_n+By_n-b\|\leq \frac{(1 +2^{\frac{1-\kappa}{2\kappa-1}})\gamma_1}{\rho} n^{-\frac{1-\kappa}{2\kappa-1}},\\
&|\mathcal{L}_{\rho}(\mathbf{x}_{n},y_{n},z_{n})- \mathcal{L}_{\rho}(\mathbf{x}^{*},y^{*},z^{*})|\leq \gamma_2 n^{-\frac{2-2\kappa}{2\kappa-1}},
\end{align*}
and that
\begin{align*}
|F(\mathbf{x}_n,y_n)-F(\mathbf{x}^{*},y^{*})| &\leq \gamma_2 n^{-\frac{2-2\kappa}{2\kappa-1}}+ \left(\gamma_1 n^{-\frac{1-\kappa}{2\kappa-1}} + \|z^{*}\|\right)\frac{(1 +2^{\frac{1-\kappa}{2\kappa-1}})\gamma_1}{\rho} n^{-\frac{1-\kappa}{2\kappa-1}} + \frac{(1 +2^{\frac{1-\kappa}{2\kappa-1}})^2\gamma_1^2}{2\rho} n^{-\frac{2-2\kappa}{2\kappa-1}}\\
&\leq \left(\gamma_2 +\frac{(3 +2^{\frac{1-\kappa}{2\kappa-1}})(1 +2^{\frac{1-\kappa}{2\kappa-1}})\gamma_1^2}{2\rho} +\frac{\|z^{*}\|(1 +2^{\frac{1-\kappa}{2\kappa-1}})\gamma_1}{\rho} \right)n^{-\frac{1-\kappa}{2\kappa-1}},
\end{align*}
where $\gamma_1 :=\frac{\ell_H\gamma_0 +(1 +2^{\frac{1-\kappa}{2\kappa-1}})\nu\ell_{\psi}\gamma_0}{\sqrt{\lambda}}$, $\gamma_2 :=\gamma_0 +c(1 +2^{\frac{1-\kappa}{2\kappa-1}})^2\gamma_0^2$, and the last inequality follows from the fact that $n^{-\frac{2-2\kappa}{2\kappa-1}}<n^{-\frac{1-\kappa}{2\kappa-1}}$ for $\kappa\in(\frac{1}{2},1)$. By setting $\overline{\gamma}$ in the same way as in \ref{t:full_rate_linear}, we obtain the conclusion.
\end{proof}

