\begin{equation*}
x\in \bigcap_{i\in\varphi(x)}\Fix T_i =\bigcap_{i\in\varphi(x)} \left[\varphi^{-1}(i)\cap\Fix T_i\right].
\end{equation*}
\item\label{it:fixed points_StrFixSing} The strong fixed point set is the intersection of the fixed point set and the single-valued set, that is,
\begin{equation*}
\StrFix T =\Fix T\cap \Sing T.
\end{equation*}
\item\label{it:fixed points_Sing} If in addition $\{T_i\}_{i\in I}$ is a collection of continuous operators, then $T$ is ocs. Consequently,
\begin{equation*}
\Sing T =\left\{x\in X:\Limsup_{x'\to x}T(x')\text{ is singleton}\right\}.
\end{equation*}
\end{enumerate}
\end{proposition}

\begin{proof}
\ref{it:fixed points_X}: Let $i\in I$ and consider a sequence $(x_n)_{n\in\mathbb{N}}\subseteq\varphi^{-1}(i)$ such that $x_n\to\overline{x}$. The definition of the inverse implies that $i\in\varphi(x_n)$ for all $n\in\mathbb{N}$ and, since $\varphi$ is osc, it holds that $i\in \varphi(\overline{x})$, which shows that $\varphi^{-1}(i)$ is closed and proves the first claim. The fact that \eqref{eq:X is a union} follows from the assumption that $\varphi(x)\neq \varnothing$ for all $x\in X$.

\ref{it:fixed points_Fix}: $x\in\Fix T\iff\exists i\in \varphi(x)$ such that $x\in\Fix T_i\iff\exists i\in I$ such that $x\in\varphi^{-1}(i)\cap\Fix T_i.$ 

\ref{it:fixed points_StrFix}: $x\in\StrFix T\iff x\in\Fix T_i$ for all $i\in\varphi(x)\iff x\in\varphi^{-1}(i)\cap\Fix T_i$ for all $i\in\varphi(x)$.

\ref{it:fixed points_StrFixSing}: Immediate from the respective definitions.

\ref{it:fixed points_Sing}: Fix $x\in X$. We first show that $T$ is osc. To this end, take $x_n\to x$ and $y_n\to y$ with $y_n\in T(x_n)$. Then the definition of $T$ ensures the existence of sequence $i_n\in \varphi(x_n)$ such that $y_n =T_{i_n}(x_n)\in T(x_n)$. Using the pigeonhole princple, we pass to a subsequence so that $y_{k_n} =T_i(x_{k_n})$ for fixed $i\in I$. The osc of $\varphi$ implies that $i\in\varphi(x)$ and continuity of $T_i$ gives
\begin{equation*}
y =\lim_{n\to\infty}y_{k_n} =\lim_{n\to\infty}T_i(x_{k_n}) =T_i(x)\in T(x),
\end{equation*}
which proves osc. The claimed formula for the singleton set follows since $x\in\Sing T\iff T(x)$ is singleton, and osc implies that $T(x) =\Limsup_{x'\to x}T(x')$. 
\end{proof}

\begin{theorem}[Krasnosel'ski\u{\i}--Mann iterations with admissible control]
\label{thm:KM iterations with admissible control}
Let $I$ be a finite index set and let $\{T_i\}_{i\in I}$ be a collection of nonexpansive operators on $X$ with a common fixed point. Define a sequence $(x_n)_{n\in\mathbb{N}}$ with starting point $x_0\in X$ according to
\begin{equation*}
\forall n\in\mathbb{N},\quad x_{n+1} :=(1-\lambda_n)x_n+\lambda_n T_{i_n}(x_n),
\end{equation*}
where $(i_n)_{n\in\mathbb{N}}$ is admissible in $I$, and $(\lambda_n)_{n\in\mathbb{N}}$ is in $(0, 1]$ with $\liminf_{n\to\infty}\lambda_n(1-\lambda_n)> 0$.
Then $(x_n)_{n\in\mathbb{N}}$ converges to a point $\overline{x}\in\cap_{i\in I} \Fix T_i$.
\end{theorem}

\begin{proof}
Since $\liminf_{n\to\infty}\lambda_n(1-\lambda_n)> 0$, there exists $n_0\in \mathbb{N}$ such that $\inf_{n\geq n_0}\lambda_n(1-\lambda_n)> 0$. By relabeling if necessary, we may assume without loss of generality that $\varepsilon :=\inf_{n\in\mathbb{N}}\lambda_n(1-\lambda_n)> 0$. 
Let $x\in \cap_{i\in I} \Fix T_i$ be arbitrary. Then, for all $n\in\mathbb{N}$, nonexpansiveness of $T_{i_n}$ yields
\begin{subequations} 
\begin{align*}
\|x_{n+1}-x\|^2& =\|(1-\lambda_n)(x_n-x)+\lambda_n(T_{i_n}(x_n)-x)\|^2 \\
& =(1-\lambda_n)\|x_n-x\|^2+\lambda_n\|T_{i_n}(x_n)-x\|^2-\lambda_n(1-\lambda_n)\|x_n-T_{i_n}(x_n)\|^2 \\
&\leq \|x_n-x\|^2-\varepsilon\|x_n-T_{i_n}(x_n)\|^2.
\end{align*}
\end{subequations}
It follows that $(\|x_n-x\|^2)_{n\in\mathbb{N}}$ is monotone nonincreasing, and hence convergent. Consequently, the sequence $(x_n)_{n\in\mathbb{N}}$ is bounded and 
\begin{equation}\label{eq:pre-asymp}
x_n-T_{i_n}(x_n)\to 0 \quad\text{as~} n\to\infty.
\end{equation}
Now, let $\overline{x}\in X$ be a cluster point of $(x_n)_{n\in\mathbb{N}}$. Then $(x_n)_{n\in\mathbb{N}}$ contains a convergent subsequence, say $(x_{k_n})_{n\in\mathbb{N}}$, with limit $\overline{x}$. 
We claim that $\overline{x}$ is an element of $\cap_{i\in I} \Fix T_i$. To this end suppose, by way of a contradiction, that $\overline{x}\not\in\cap_{i\in I} \Fix T_i$.
By passing to a further subsequence if necessary, we deduce that the sequence $(t_n)_{n\in\mathbb{N}}$ defined by
\begin{equation*}
t_n :=\min\{p\in\{k_n,\dots,k_{n+1}-1\}:\overline{x}\not\in\Fix T_{i_p}\}, 
\end{equation*}
is well defined.
Since $I$ is finite, by passing to yet another subsequence if necessary, we may assume that $i_{t_n} =\ell$ for all $n\in\mathbb{N}$ for some fixed index $\ell\in I$. 
Together with \eqref{eq:pre-asymp}, we deduce that
\begin{equation*}
x_{t_n}\to \overline{x} \text{~~~and~~~} (\Id-T_\ell)(x_{t_n})\to 0 \quad\text{as~} n\to\infty,
\end{equation*}
which, due to nonexpansiveness of $T_\ell$, implies that $\overline{x}\in\Fix T_\ell$. 
Thus a contradiction is obtained, and conclude that $\overline{x}\in\cap_{i\in I} \Fix T_i$. We then have that $(\|x_n-\overline{x}\|)_{n\in\mathbb{N}}$ is monotone nonincreasing and $\|x_{k_n}-\overline{x}\|\to 0$, and thus the conclusion follows.
\end{proof}

\begin{proposition}[Radius of attraction at strong fixed points]\label{prop:radius}
Let $T\colon X\setto X$ be a union nonexpansive operator with $x^*\in\StrFix T$. Then $r :=r(x^*;T)\in (0,+\infty]$ and
\begin{equation}\label{eq:attraction nonexpansive}
\forall x\in \inte\mathbb{B}(x^*;r),\,\forall y\in T(x),\quad 
\|y-x^*\|\leq \|x-x^*\|.
\end{equation}
Furthermore, for any $\lambda\in (0, 1]$, we have
\begin{equation}\label{eq:attraction averaged}
\forall x\in \inte\mathbb{B}(x^*;r),\,\forall y\in (1-\lambda)x+\lambda T(x),\quad 
\|y-x^*\|^2+\frac{1-\lambda}{\lambda}\|x-y\|^2\leq \|x-x^*\|^2.
\end{equation}
\end{proposition}

\begin{proof}
Since $\varphi$ is osc and its range, $I$, is a finite set, Proposition~\ref{prop:prop2.1 Tam17} implies that $r :=r(x^*;T)\in(0,+\infty]$. Since $x^*\in\StrFix T$, Proposition~\ref{prop:fixed points}\ref{it:fixed points_StrFix} implies that $x^*\in\cap_{i\in\varphi(x*)}\Fix T_i$ and, since each $T_i$ is nonexpansive, we have
\begin{equation}
\label{eq:nonexpansive}
\forall i\in\varphi(x^*),\, \forall x\in X,\quad \|T_i(x)-x^*\|^2\leq \|x-x^*\|^2.
\end{equation}
In particular, for any $x\in \inte\mathbb{B}(x^*;r)$ and $y\in T(x)$, there exists an $i\in \varphi(x)\subseteq \varphi(x^*)$ such that $y =T_i(x)$. Consequently, \eqref{eq:attraction nonexpansive} follows from \eqref{eq:nonexpansive}.

Furthermore, for any $\lambda\in (0, 1]$, the operator $S_i :=(1-\lambda)\Id+\lambda T_i$ is $\lambda$-averaged nonexpansive by Proposition~\ref{prop:averaged} and we therefore have that
\begin{equation}
\label{eq:averaged}
\forall i\in\varphi(x^*),\, \forall x\in X,\quad \|S_i(x)-x^*\|^2+\frac{1-\lambda}{\lambda}\|x-S_i(x)\|^2\leq \|x-x^*\|^2.
\end{equation}
In particular, if $x\in\inte\mathbb{B}(x^*;r)$ and $y\in (1-\lambda)x+\lambda T(x)$, then there exists $i\in \varphi(x)\subseteq \varphi(x^*)$ such that $y =S_i(x)$. As before, \eqref{eq:attraction averaged} follows from \eqref{eq:averaged}.
\end{proof}

\begin{theorem}[Local convergence of union nonexpansive iterations]\label{thm:union}
Let $T\colon X\setto X$ be a union nonexpansive operator with $x^*\in\StrFix T$ and let $(\lambda_n)_{n\in\mathbb{N}}$ be a sequence in $(0, 1]$ with $\liminf_{n\to\infty}\lambda_n(1-\lambda_n)> 0$. Denote $r :=r(x^*;T)\in(0,+\infty]$ and consider a sequence $(x_n)_{n\in\mathbb{N}}$ with $x_0\in \inte\mathbb{B}(x^*;r)$ satisfying
\begin{equation*}
\forall n\in\mathbb{N},\quad x_{n+1}\in (1-\lambda_n)x_n+\lambda_n T(x_n).
\end{equation*} 
Then $(x_n)_{n\in\mathbb{N}}$ converges to a point $\overline{x}\in\Fix T\cap \mathbb{B}(x^*;r)$. 
\end{theorem}

\begin{proof}
We first observe from Proposition~\ref{prop:radius} that, for all $n\in\mathbb{N}$, $x_n\in \inte\mathbb{B}(x^*;r)$ and 
\begin{equation*}
\forall n\in\mathbb{N},\quad \|x_{n+1}-x^*\|^2+\frac{1-\lambda_n}{\lambda_n}\|x_n-x_{n+1}\|^2\leq \|x_n-x^*\|^2
\end{equation*}
with convention that $\frac{1-\lambda_n}{\lambda_n} =0$ if $\lambda_n =0$.
By the definition of $T$, there is a sequence of indices $(i_n)_{n\in\mathbb{N}}\subseteq I$ such that
\begin{equation*}
\forall n\in\mathbb{N},\quad x_{n+1} =(1-\lambda_n)x_n+\lambda_n T_{i_n}(x_n)\quad\text{and}\quad i_n\in \varphi(x_n)\subseteq\varphi(x^*),
\end{equation*}
where the last inclusion is a consequence of Proposition~\ref{prop:prop2.1 Tam17} and the fact that $(x_n)_{n\in\mathbb{N}}\subseteq\inte\mathbb{B}(x^*;r)$.

Let $I^*$ denote the set of admissible indices in the sequence $(i_n)_{n\in\mathbb{N}}$. Then $I^*\subseteq \varphi(x^*)$ which,  together with Proposition~\ref{prop:fixed points}\ref{it:fixed points_StrFix} applied to $x^*\in \StrFix T$, yields
\begin{equation*}
x^*\in \bigcap_{i\in\varphi(x*)}\Fix T_i\subseteq \bigcap_{i\in I^*}\Fix T_i.
\end{equation*}
That is, $\{T_i\}_{i\in I^*}$ is a collection of nonexpansive operators with a common fixed point. By applying Theorem~\ref{thm:KM iterations with admissible control}, $x_n\to\overline{x}\in\cap_{i\in I^*}\Fix T_i$. Since, for all $n\in\mathbb{N}$, $x_n\in \mathbb{B}(x^*;r)$, it also holds that $\overline{x}\in \mathbb{B}(x^*;r)$. Finally, for any $i\in I^*$, there exists a subsequence $i_{k_n}\to i$. Since $x_{k_n}\to\overline{x}$ and $\varphi$ is osc with $i_{k_n}\in\varphi(x_{n_k})$, we deduce that $i\in\varphi(\overline{x})$. By Proposition~\ref{prop:fixed points}\ref{it:fixed points_Fix},  it follows that $\overline{x}\in\Fix T$ as was claimed.
\end{proof}

\begin{proof}
It follows from Proposition~\ref{prop:averaged} that $R :=(1-1/\alpha)\Id+(1/\alpha)T$ is union nonexpansive. Under the fixed representation of $T$ in \eqref{eq:a particular uan op}, we have $r(x^*;R) =r(x^*;T)$. Moreover, $\StrFix R =\StrFix T$, $\Fix R =\Fix T$, and, for all $n\in\mathbb{N}$, $x_{n+1} =(1-\alpha\lambda_n)x_n+\alpha\lambda_n R(x)$. The result now follows from Theorem~\ref{thm:union} applied to $R$ and $(\alpha\lambda_n)_{n\in\mathbb{N}}$. 
\end{proof}

