\begin{proposition}[Radius of attraction at strong fixed points]\label{prop:radius}
Let $T\colon X\setto X$ be a union nonexpansive operator with $x^*\in\StrFix T$. Then $r :=r(x^*;T)\in (0,+\infty]$ and
\begin{equation}\label{eq:attraction nonexpansive}
\forall x\in \inte\mathbb{B}(x^*;r),\,\forall y\in T(x),\quad 
\|y-x^*\|\leq \|x-x^*\|.
\end{equation}

Furthermore, for any $\lambda\in (0, 1]$, we have
\begin{equation}\label{eq:attraction averaged}
\forall x\in \inte\mathbb{B}(x^*;r),\,\forall y\in (1-\lambda)x+\lambda T(x),\quad 
\|y-x^*\|^2+\frac{1-\lambda}{\lambda}\|x-y\|^2\leq \|x-x^*\|^2.
\end{equation}
\end{proposition}

