\begin{equation*}
\forall n\in\mathbb{N},\quad x_{n+1}\in (1-\lambda_n)x_n+\lambda_n T(x_n).
\end{equation*} 
Then $(x_n)_{n\in\mathbb{N}}$ converges to a point $\overline{x}\in\Fix T\cap \mathbb{B}(x^*;r)$. 
\end{theorem}

\begin{proof}
We first observe from Proposition~\ref{prop:radius} that, for all $n\in\mathbb{N}$, $x_n\in \inte\mathbb{B}(x^*;r)$ and 
\begin{equation*}
\forall n\in\mathbb{N},\quad \|x_{n+1}-x^*\|^2+\frac{1-\lambda_n}{\lambda_n}\|x_n-x_{n+1}\|^2\leq \|x_n-x^*\|^2
\end{equation*}
with convention that $\frac{1-\lambda_n}{\lambda_n} =0$ if $\lambda_n =0$.
By the definition of $T$, there is a sequence of indices $(i_n)_{n\in\mathbb{N}}\subseteq I$ such that
\begin{equation*}
\forall n\in\mathbb{N},\quad x_{n+1} =(1-\lambda_n)x_n+\lambda_n T_{i_n}(x_n)\quad\text{and}\quad i_n\in \varphi(x_n)\subseteq\varphi(x^*),
\end{equation*}
where the last inclusion is a consequence of Proposition~\ref{prop:prop2.1 Tam17} and the fact that $(x_n)_{n\in\mathbb{N}}\subseteq\inte\mathbb{B}(x^*;r)$.

Let $I^*$ denote the set of admissible indices in the sequence $(i_n)_{n\in\mathbb{N}}$. Then $I^*\subseteq \varphi(x^*)$ which,  together with Proposition~\ref{prop:fixed points}\ref{it:fixed points_StrFix} applied to $x^*\in \StrFix T$, yields
\begin{equation*}
x^*\in \bigcap_{i\in\varphi(x*)}\Fix T_i\subseteq \bigcap_{i\in I^*}\Fix T_i.
\end{equation*}
That is, $\{T_i\}_{i\in I^*}$ is a collection of nonexpansive operators with a common fixed point. By applying Theorem~\ref{thm:KM iterations with admissible control}, $x_n\to\overline{x}\in\cap_{i\in I^*}\Fix T_i$. Since, for all $n\in\mathbb{N}$, $x_n\in \mathbb{B}(x^*;r)$, it also holds that $\overline{x}\in \mathbb{B}(x^*;r)$. Finally, for any $i\in I^*$, there exists a subsequence $i_{k_n}\to i$. Since $x_{k_n}\to\overline{x}$ and $\varphi$ is osc with $i_{k_n}\in\varphi(x_{n_k})$, we deduce that $i\in\varphi(\overline{x})$. By Proposition~\ref{prop:fixed points}\ref{it:fixed points_Fix},  it follows that $\overline{x}\in\Fix T$ as was claimed.
\end{proof}

