This section reviews useful results from convex analysis~\cite{Beck,Combettes,Nesterov,Nesterov2,Boyd,Bubeck}, and introduces key definitions that will be used throughout the paper. The paper considers functions on a Hilbert space $\Hi$ with corresponding norm $\|\cdot\|$. We assume all functions, $f_t: \Hi \rightarrow \R$,  are  proper, lower semicontinuous, convex, and strongly smooth; $t\in\N\cup\{0\}$ denotes the time index~\cite{SPMag,popkov2005gradient,SimonettoGlobalsip2014,mokhtari2016online}. The discretized time-varying optimization problem of interest is the sequence of convex problems (one for each $t$): 
\begin{align}
\label{eq:time-varying-opt}
   \min_{x\in\Hi} f_t(x) \,, \hspace{.5cm} t \in\N\cup\{0\}
\end{align}

\begin{align*}
    \sigma_t :=\|x_{t+1}\opt-x_t\opt\| , \hspace{.5cm} t\in \N\cup\{0\}.
\end{align*}

The specific sequence constructed by $\OLNM(T)$ is defined in Algorithm~\ref{algo:OLNM}.
\begin{algorithm}[h]
\begin{algorithmic}[1]
\Require $x_0$
\State $y_0\gets x_0$, $z_0\gets x_0$, $a_0\gets 1$
\For{$t=1,2,\ldots$} %\Comment{We have the answer if r is 0}
          \State $z_{t+1} =y_t-\frac{1}{L}\nabla f_{T\lfloor t/T \rfloor}(y_t)$
 \If{     $T \not| ~ t+1$ }
 \State $a_{t+1} = \frac{1+\sqrt{1+4a_t^2}}{2}$
 \State $y_{t+1} = z_{t+1} +\frac{a_t-1}{a_{t+1}}(z_{t+1}-z_t)$
 \State $x_{t+1} = x_t$ \Comment{so $x_{t+1} = x_t = x_{T\lfloor t/T\rfloor}$}
 \ElsIf{$T\mid t+1$}
 \State $a_{t+1} = 1$
 \State $y_{t+1} = z_{t+1}$
 \State $x_{t+1} = z_{t+1}$
 \EndIf
\EndFor
\end{algorithmic}
\caption{$\OLNM(T)$}
\label{algo:OLNM}
\end{algorithm}

\Require $x_0$
\State $y_0\gets x_0$, $z_0\gets x_0$, $a_0\gets 1$
\For{$t=1,2,\ldots$} %\Comment{We have the answer if r is 0}

\begin{theorem} \label{thm:onlineNesterov}
If $(f_t)\in \SS(\kappa^{-1},L,\sigma)$, then, given $x_0$, $\OLNM(T)$ where $T=c\sqrt{\kappa}$ for $c>2$ such that $c\sqrt{\kappa}\in\N$, constructs a sequence $(x_t)$ such that
\begin{align} \label{eq:OLNM}
    \limsup_{t\to\infty}\|x_t-x_t\opt\|\leq \frac{2c(c-1)}{c-2}\sqrt{\kappa}\sigma.
\end{align}
\end{theorem}

\begin{proof}
First, via standard batch optimization bounds, we have
\begin{align*}
    \|x_{kT}-x_{(k-1)T}\opt\|\leq \frac{2\sqrt{\kappa}}{T}\|x_{(k-1)T}-x_{(k-1)T}\opt\|.
\end{align*}
Thus,
\begin{align*}
    \|x_{kT}-x_{kT}\opt\|&\leq\frac{2\sqrt{\kappa}}{T}\|x_{(k-1)T}-x_{(k-1)T}\opt\|+T\sigma\\
    &\leq \left(\frac{2\sqrt{\kappa}}{T}\right)^k\|x_0-x_0\opt\|+\frac{T\sigma}{1-\frac{2\sqrt{\kappa}}{T}}\\
    &= \left(\frac{2\sqrt{\kappa}}{T}\right)^k\|x_0-x_0\opt\|+\frac{T^2\sigma}{T-2\sqrt{\kappa}}
\end{align*}
and so
\begin{align*}
    \|x_t-x_t\opt\| &= \|x_{T\lfloor t/T \rfloor}-x_t\opt\|\\
    &\leq \|x_{T\lfloor t/T \rfloor}-x_{T\lfloor t/T \rfloor}\opt\|+\|x_t\opt-x_{T\lfloor t/T \rfloor}\opt\|\\
    &\leq \left(\frac{2\sqrt{\kappa}}{T}\right)^{\lfloor t/T \rfloor}\|x_0-x_0\opt\|+\frac{T^2\sigma}{T-2\sqrt{\kappa}}+T\sigma.
\end{align*}
Then, taking the limit supremum, we get
\begin{align*}
    \limsup_{t\to\infty}\|x_t-x_t\opt\| &\leq \frac{T^2\sigma}{T-2\sqrt{\kappa}}+T\sigma\\
    &= \frac{2T\sigma\left(T-\sqrt{\kappa}\right)}{T-2\sqrt{\kappa}}\\
    &= \frac{2c(c-1)}{c-2}\sqrt{\kappa}\sigma.
\end{align*}
\end{proof}

