  \label{e-ls-conv-3}
\end{align}
The equality~\eqref{e-ls-conv-2} at $k=i-2$ is
\begin{align*}
\inprod{z-z^{(i-1)}}{Ax^{(i-1)}-b}
  &= \frac{1}{\sigma_{i-2}} \inprod{z-z^{(i-1)}}{z^{(i-1)}-z^{(i-2)}} \\
&= \frac{\theta_{i-1}}{\sigma_{i-1}}
  \inprod{z-z^{(i-1)}}{z^{(i-1)}-z^{(i-2)}} \\
&= \frac{1}{\sigma_{i-1}} \inprod{z-z^{(i-1)}}{\bar z^{(i)}-z^{(i-1)}}.
\end{align*}
We evaluate this at $z=z^{(i)}$ and add it to the equality
at $z=z^{(i-2)}$ multiplied by $\theta_{i-1}$:
\begin{align}
\inprod{z^{(i)}-\bar z^{(i)}}{Ax^{(i-1)}-b}
  &= \frac{1}{\sigma_{i-1}}
  \inprod{z^{(i)}-\bar z^{(i)}}{\bar z^{(i)} - z^{(i-1)}} \nonumber \\
&= \frac{1}{2\sigma_{i-1}} \left(\|z^{(i)}-z^{(i-1)}\|^2
  -\|z^{(i)}-\bar z^{(i)}\|^2-\|\bar z^{(i)}-z^{(i-1)}\|^2 \right).
  \label{e-ls-conv-4}
\end{align}
Now we combine~\eqref{e-ls-conv-1} for $k=i-1$,
with~\eqref{e-ls-conv-3} and~\eqref{e-ls-conv-4}. For $i \geq 1$,
\BEAS
\lefteqn{\cL(x^{(i)},z) - \cL(x, \bar z^{(i)})} \nonumber \\
&=& f(x^{(i)})+h(x^{(i)})+\inprod{z}{Ax^{(i)}-b}
  -f(x)-h(x)-\inprod{\bar z^{(i)}}{Ax-b} \nonumber \\
&\leq & \frac{1}{\tau_{i-1}}
  \Big(d_\primal(x,x^{(i-1)})-d_\primal(x,x^{(i)})
  - d_\primal(x^{(i)},x^{(i-1)})\Big)
  + \inprod{A^T\bar z^{(i)}}{x-x^{(i)}} + \inprod{z}{Ax^{(i)}-b} \nonumber\\
& &\mbox{} - \inprod{\bar z^{(i)}}{Ax-b} + h(x^{(i)}) - h(x^{(i-1)})
  -\inprod{\nabla h(x^{(i-1)})}{x^{(i)}-x^{(i-1)}} \nonumber \\
&=& \frac{1}{\tau_{i-1}}
  \Big(d_\primal(x,x^{(i-1)}) - d_\primal(x,x^{(i)}) 
  - d_\primal(x^{(i)},x^{(i-1)})\Big)
  + \inprod{z-\bar z^{(i)}}{Ax^{(i)}-b} \nonumber \\
& &\mbox{} +h(x^{(i)})-h(x^{(i-1)})
  -\inprod{\nabla h(x^{(i-1)})}{x^{(i)}-x^{(i-1)}} \nonumber \\
&=& \frac{1}{\tau_{i-1}}
  \Big(d_\primal(x,x^{(i-1)}) - d_\primal(x,x^{(i)})
  - d_\primal(x^{(i)},x^{(i-1)})\Big) \nonumber \\
& & \mbox{} +\inprod{z^{(i)}-\bar z^{(i)}}{A(x^{(i)}-x^{(i-1)})}
  + \inprod{z-z^{(i)}}{Ax^{(i)}-b}
  + \inprod{z^{(i)}-\bar z^{(i)}}{Ax^{(i-1)}-b} \nonumber \\
& &\mbox{} +h(x^{(i)})-h(x^{(i-1)})
  -\inprod{\nabla h(x^{(i-1)})}{x^{(i)}-x^{(i-1)}} \nonumber \\
&=& \frac{1}{\tau_{i-1}}
  \Big(d_\primal(x,x^{(i-1)}) - d_\primal(x,x^{(i)})
  - d_\primal(x^{(i)},x^{(i-1)}))\Big) \nonumber \\
& &\mbox{} +\frac{1}{2\sigma_{i-1}}
  \Big(\|z-z^{(i-1)}\|^2-\|z-z^{(i)}\|^2-\|\bar z^{(i)}-z^{(i-1)}\|^2
  -\|\bar z^{(i)}-z^{(i)}\|^2\Big) \nonumber \\
& &\mbox{}+\inprod{A^T(z^{(i)}-\bar z^{(i)})}{x^{(i)}-x^{(i-1)}}
  +h(x^{(i)})-h(x^{(i-1)})
  -\inprod{\nabla h(x^{(i-1)})}{x^{(i)}-x^{(i-1)})} \\
&\leq & \frac{1}{\tau_{i-1}} 
  \left(d_\primal(x,x^{(i-1)}) - d_\primal(x,x^{(i)}) -
  (1-\delta^2) d_\primal(x^{(i)},x^{(i-1)})\right) \nonumber \\
& &\mbox{} + \frac{1}{2\sigma_{i-1}} \left(
  \|z-z^{(i-1)}\|^2 - \|z-z^{(i)}\|^2 - 
  \|\bar z^{(i)} - z^{(i-1)}\|^2 \right),
\EEAS
which is the desired result~\eqref{e-ls-conv-i}.
The first inequality follows from~\eqref{e-ls-conv-1}.
In the second last step we substitute~\eqref{e-ls-conv-3}
and~\eqref{e-ls-conv-4}.
The last step uses the line search exit condition~\eqref{e-ls-cond}
at $k=i-1$.
\end{proof}

We show that
\begin{align}
\cL(x^{(k)}_\avg,z) - \cL(x,\bar z^{(k)}_\avg)
  &\leq \frac{1}{\sum_{i=1}^k \tau_{i-1}}
  \big(d_\primal(x,x^{(0)}) + \frac{1}{2\beta} \|z-z^{(0)}\|^2\big)
  \label{e-ls-conv} \\ 
&\leq \frac{1}{k \tau_\mathrm{min}}
  \big(d_\primal(x,x^{(0)}) + \frac{1}{2\beta} \|z-z^{(0)}\|^2\big)
  \label{e-ls-conv-1/k}
\end{align}
for all $x \in \dom f \cap \dom \phi_\primal$ and all $z$.
This holds for any choice of $\delta \in (0,1]$ in~\eqref{e-ls-cond}.

units.raw_tex:
For a twice-differentiable function $f$, we say
that it has \textit{H\"older continuous Hessian} of degree
$\nu \in [0, 1]$ on a convex set $C \subseteq \dom f$, if for some
constant $\mathcal{H}$, it
holds:
\begin{equation} \label{HolderHessianDefinition}
\ba{rcl}
\| \nabla^2 f(x) - \nabla^2 f(y) \| & \leq &
\mathcal{H} \|x - y\|^{\nu}, \qquad x, y \in C.
\ea
\end{equation}
Two simple consequences of~\eqref{HolderHessianDefinition}
are as follows:
\beq \label{HolderHessianGradBound}
\ba{rcl}
\| \nabla f(y) - \nabla f(x) - \nabla^2 f(x)(y - x) \|_{*} 
& \leq &
 \frac{\H \|x - y\|^{1 + \nu}}{1 + \nu},
\ea
\eeq
\beq \label{HolderHessianFuncBound}
\ba{rcl}
| f(y) - Q(x; y) |  & \leq & 
\frac{\H \|x - y\|^{2 + \nu}}{(1 + \nu)(2 + \nu)},
\ea
\eeq
where $Q(x; y)$ is the quadratic model of $f$ at the point
$x$:
$$
\ba{rcl}
Q(x; y) & \; \defeq \; & f(x) + \langle \nabla f(x), y - x \rangle +
\frac{1}{2} \langle \nabla^2 f(x) (y - x), y - x \rangle.
\ea
$$

In order to characterize the level of smoothness of
function $f$ on the set $C := \dom F$, let us define
the system of H\"older constants (see
\cite{grapiglia2017regularized}):
\begin{equation} \label{HfnuDefinition}
\ba{rcl}
\Hfnu & \; \defeq &\; \sup\limits_{\substack{x, y \in \dom F \\ x \not= y}}
\frac{\| \nabla^2 f(x) - \nabla^2 f(y) \|}{\|x - y\|^{\nu}},
\qquad \nu \in [0, 1].
\ea
\end{equation}
We allow $\Hfnu$ to be equal to $+\infty$ for some $\nu$.

Let us start from the case when we know that for a specific
$\nu \in [0, 1]$ function $f$ has H\"older continuous Hessian:
$\H_f(\nu) < +\infty$. Then, from~\eqref{HolderHessianFuncBound}, we
have the global upper bound for the objective function:
\begin{displaymath}
\ba{rcl}
F(y) & \; \leq \; & M_{\nu, H}(x; y) \;\defeq \; Q(x; y)
+ \frac{H \|x - y\|^{2 + \nu}}{(1 + \nu)(2 + \nu)} + h(y),
\qquad x, y \in \dom F,
\ea
\end{displaymath}
where $H > 0$ is large enough: $H \geq \Hfnu$. Thus, it is
natural to employ the minimum of a regularized quadratic
model:
\begin{displaymath}
\ba{c}
T_{\nu, H}(x) \; \defeq \;
\argmin\limits_{y \in \dom F} M_{\nu, H}(x; y), \qquad M_{\nu, H}^{*}(x)
\; \defeq \; \min\limits_{y \in \dom F} M_{\nu, H}(x; y),
\ea
\end{displaymath}

\vspace*{5pt}
\noindent
\hspace*{5pt}
\lfbox{
	\hspace*{4pt}
	\centering
	\begin{minipage}[b]{0.85\linewidth} \label{MainAlgorithm}
		\begin{algorithm}[H] 
		  	\caption{\small \textbf{Adaptive Cubic
					Regularization of Newton Method}}
			\vspace*{6pt}
			\noindent\makebox[\linewidth]{\rule{1.097\linewidth}{0.4pt}}
			\begin{algorithmic}[1]
				%\vspace{5pt}
				\Require Choose $x_0 \in \dom F$, $H_0 > 0$.
				\vspace*{2pt}
				\Ensure $k \geq 0$. \vspace*{2pt}
				\State Find the minimal integer $i_k \geq 0 \;$
				such that $F(T_{H_k 2^{i_k}}(x_k)) \leq M^{*}_{H_k
					2^{i_k}} (x_k)$. %\vspace*{1pt}
				\State Perform the Cubic Step: $x_{k + 1}  = T_{H_k
					2^{i_k}}(x_k)$. \vspace*{1pt}
				\State Set $H_{k + 1} := 2^{i_k - 1} H_k $.
				\vspace*{5pt}
			\end{algorithmic}
		\end{algorithm}
	\end{minipage}
	\hspace*{4pt}
}
\vspace*{1pt}

