By the composite representation~\eqref{MainProblem},
we have for every $x \in \dom F$ and for
all $F'(x) \in \partial F(x)$:
\begin{equation} \label{UniformlyConvexLowerBound}
\ba{rcl}
F(y) & \geq  & F(x) + \langle
F'(x), y - x \rangle + \frac{\sigma}{p}\|x - y\|^p, \qquad
y \in \dom F.
\ea
\end{equation}

Two simple consequences of~\eqref{HolderHessianDefinition}
are as follows:
\beq \label{HolderHessianGradBound}
\ba{rcl}
\| \nabla f(y) - \nabla f(x) - \nabla^2 f(x)(y - x) \|_{*} 
& \leq &
 \frac{\H \|x - y\|^{1 + \nu}}{1 + \nu},
\ea
\eeq

\beq \label{HolderHessianFuncBound}
\ba{rcl}
| f(y) - Q(x; y) |  & \leq & 
\frac{\H \|x - y\|^{2 + \nu}}{(1 + \nu)(2 + \nu)},
\ea
\eeq

In order to characterize the level of smoothness of
function $f$ on the set $C := \dom F$, let us define
the system of H\"older constants (see
\cite{grapiglia2017regularized}):
\begin{equation} \label{HfnuDefinition}
\ba{rcl}
\Hfnu & \; \defeq &\; \sup\limits_{\substack{x, y \in \dom F \\ x \not= y}}
\frac{\| \nabla^2 f(x) - \nabla^2 f(y) \|}{\|x - y\|^{\nu}},
\qquad \nu \in [0, 1].
\ea
\end{equation}
We allow $\Hfnu$ to be equal to $+\infty$ for some $\nu$.

natural to employ the minimum of a regularized quadratic
model:
\begin{displaymath}
\ba{c}
T_{\nu, H}(x) \; \defeq \;
\argmin\limits_{y \in \dom F} M_{\nu, H}(x; y), \qquad M_{\nu, H}^{*}(x)
\; \defeq \; \min\limits_{y \in \dom F} M_{\nu, H}(x; y),
\ea
\end{displaymath}

\vspace*{5pt}
\noindent
\hspace*{5pt}
\lfbox{
	\hspace*{4pt}
	\centering
	\begin{minipage}[b]{0.85\linewidth} \label{MainAlgorithm}
		\begin{algorithm}[H] 
		  	\caption{\small \textbf{Adaptive Cubic
					Regularization of Newton Method}}
			\vspace*{6pt}
			\noindent\makebox[\linewidth]{\rule{1.097\linewidth}{0.4pt}}
			\begin{algorithmic}[1]
				%\vspace{5pt}
				\Require Choose $x_0 \in \dom F$, $H_0 > 0$.
				\vspace*{2pt}
				\Ensure $k \geq 0$. \vspace*{2pt}
				\State Find the minimal integer $i_k \geq 0 \;$
				such that $F(T_{H_k 2^{i_k}}(x_k)) \leq M^{*}_{H_k
					2^{i_k}} (x_k)$. %\vspace*{1pt}
				\State Perform the Cubic Step: $x_{k + 1}  = T_{H_k
					2^{i_k}}(x_k)$. \vspace*{1pt}
				\State Set $H_{k + 1} := 2^{i_k - 1} H_k $.
				\vspace*{5pt}
			\end{algorithmic}
		\end{algorithm}
	\end{minipage}
	\hspace*{4pt}
}
\vspace*{1pt}

In other words, the vector
$$
\ba{rcl}
h'(T_H(x)) & \defeq & -\nabla f(x) - \nabla^2 f(x)(T_H(x) -
x) - \frac{H r_H(x)}{2}B(T_H(x) - x)
\ea
$$
belongs to the subdifferential of $h$:
\begin{equation} \label{CubicStepSubdiff}
\ba{rcl}
h'(T_H(x)) &\; \in \; & \partial h(T_H(x)).
\ea
\end{equation}

\beq \label{CubicGradNewPoint}
\ba{cl}
& \|  F'(T_H(x)) \|_{*} \\[5pt]
& \leq \;
  \| \nabla f(T_H(x)) - \nabla f(x) - \nabla^2 f(x)
(T_H(x) - x)\|_{*} + \tfrac{H r^2_H(x)}{2} \\[5pt]
& \stackrel{\eqref{HolderHessianGradBound}}{\leq}
\tfrac{\Hfnu
	r^{1 + \nu}_H(x)}{1 + \nu}  +  \tfrac{H r^2_H(x)}{2} 
\; = \; 
r^{1 + \nu}_H(x) \cdot \Bigl(  \tfrac{\Hfnu}{1 + \nu} + 
\tfrac{Hr_H^{1 - \nu}(x)}{2} \Bigr). 
\ea
\eeq

\begin{lemma} \label{UniformlyConvexConsequence}
	Let $f$ be uniformly convex of degree $p \geq 2$ with
	constant $\sigma > 0$ on set $\dom F$. Then, for every $x
	\in \dom F$ and for all $F'(x) \in \partial F(x)$ we have
	\begin{equation} \label{UniformlyConvexGradientBound}
	\ba{rcl}
	F(x) - F^{*} & \; \leq \; & \frac{p - 1}{p} \left( \frac{1}{\sigma}
	\right)^{\frac{1}{p - 1}} \|F'(x)\|_{*}^{\frac{p}{p - 1}}.
	\ea
	\end{equation}
\end{lemma}

\begin{proof}
	\noindent
	In view of~\eqref{UniformlyConvexLowerBound}, 
	bound \eqref{UniformlyConvexGradientBound}
	follows as in the proof of Lemma~3 
	in~\cite{nesterov2008accelerating}.
\qed
\end{proof}

\begin{lemma} \label{LemmaStepHolder}
	Let $0 < \Hfnu < +\infty$ and $\sigmafnu > 0$ for some
	$\nu \in [0,1]$. Then, for arbitrary $x \in \dom F$ and $H
	> 0$ we have:
	\beq \label{OneStepProgressHolder}
	\ba{cl}
	& F(x) - M_H^{*}(x)  \\[5pt] 
	& \quad \geq \; \min\Bigl[ \left( F(x) -
	F^{*} \right) \cdot \frac{(1 + \nu)}{(2 + \nu)} \cdot
	\min\bigl\{\bigl( \frac{(1 + \nu) \gammafnu}{2(2 + \nu)}  \bigr)^{\frac{1}{1 + \nu}}, 
	\; 1\bigr\} ,   \\[5pt]
	& \; \qquad \qquad \left( F(T_H(x)) - F^{*} \right)^{\frac{3(1 + \nu)}{2(2 + \nu)}}
	\cdot \bigl ( \frac{2 + \nu}{1 + \nu}  \bigr)^{\frac{3(1 + \nu)}{2(2
			+ \nu)}} \cdot \frac{(\sigmafnu)^{\frac{3}{2(2 + \nu)}}}{ 3 \sqrt{H}
	}  \;  \Bigr]. 
	\ea
	\eeq
\end{lemma}

2) $H r_H^{1 - \nu}(x) > \frac{2 \Hfnu}{1 + \nu}.$
By~\eqref{CubicGradNewPoint}, we have the bound:
\begin{equation} \label{NextPointGradBound2}
\ba{rcl}
\| F'(T_H(x)) \|_{*} & \; < \; & Hr_H^2(x).
\ea
\end{equation}

		Using the fact that $\nabla^2 f(x) \succeq 0$, we get the second argument of the
		minimum:
	$$
