\begin{lemma}\label{lem01}
Let $f$ be a strictly convex function. If $f(Ax-b)+\|x\|_1$ is constant on a convex set $S$, then both $Ax-b$ and $\|x\|_1$ are  constant on $S$.
\end{lemma}

\begin{IEEEproof}
It suffices to prove the case where $S$ has more one point. Let $x_1$ and $x_2$ be any two  different points in $S$. Consider the line segment $L$ connecting $x_1$ and $x_2$. Since  $X$ is convex, we have $L\subset X$ and that   $f(Ax-b)+\|x\|_1$ is constant on $L$.  On one hand, $\|x\|_1$ is piece-wise linear over $L$; on the other hand, the strict convexity of $f$ makes it impossible for $f(Ax-b)$ to be piece-wise linear over $L$ unless $Ax_1-b=Ax_2-b$. Hence, we have $Ax_1-b=Ax_2-b$ and thus $f(Ax_1-b)=f(Ax_2-b)$, from which it follows  $\|x_1\|_1= \|x_2\|_1$. Since $x_1$ and $x_2$ are arbitrary two points in $S$, the lemma is proved.
\end{IEEEproof}

\begin{lemma}\label{lem02}
Under Assumptions \ref{assmp2} and \ref{assmp3}, the following statements for problems \eqref{eq:qpa}--\eqref{eq:qpc} hold
\begin{itemize}
\item[1)]  $X_\lambda, Y_\sigma$ and $Z_\tau$ are convex;
\item[2)]  In problem \eqref{eq:qpa}, $Ax-b$ and $\|x\|_1$ are constant for all $x\in X_\lambda$;
\item[3)]  Part 2) holds for problem \eqref{eq:qpb} and $Y_\sigma$;
\item[4)]  Part 2) holds for problem \eqref{eq:qpc} and $Z_\tau$.
\end{itemize}
\end{lemma}

