\begin{itemize}
\item[\bfseries A1] 
$\nabla^2 f$ exists and is continuous on $U$;
\item[\bfseries A2] 
$D_f$ is \emph{jointly convex}, i.e., convex on $X\times X$;
\item[\bfseries A3] 
$(\forall x\in U)$ $D_f(x,\cdot)$ is strictly convex on $U$;
\item[\bfseries A4] 
$(\forall x\in U)$ $D_f(x,\cdot)$ is coercive, i.e., 
$D_f(x, y) \to +\infty$ as $\|y\| \to +\infty$.
\end{itemize}
