the \emph{left proximity operator} associated with $\theta$ is
\begin{equation} \label{e:dbprox}
\bprox{\theta} \colon U \to U \colon
y\mapsto
\underset{x\in X}{\operatorname{argmin}}\;\: \big(\theta(x) +D_f(x,y)\big).
\end{equation}
If \eqref{e:fcoeR} holds for $\gamma =1$, then 
the \emph{right proximity operator} associated with $\theta$ is
\begin{equation} \label{e:dfprox}
\fprox{\theta}\colon U \to  U \colon
x \mapsto
\underset{y\in X}{\operatorname{argmin}}\;\: \big(\theta(y) +D_f(x,y)\big).
\end{equation}
\end{definition}


Given a closed convex subset $C$ of $X$ with $C\cap U \neq\varnothing$, we have that $\iota_C \in \Gamma_0(X)$, $\dom\iota_C =C$, 
and hence $U\cap \dom\iota_C =U\cap C \neq\varnothing$ and also $\inf \iota_C(U) =0 >-\infty$, 
which together with \cref{f:coeR} imply that \eqref{e:bcoeR} and \eqref{e:fcoeR} hold for all $\gamma \in \RPP$. 
This leads to the following definition. 

\begin{definition}[Bregman projectors]
\label{d:BregProj}
Let $C$ be a closed convex subset of $X$ such that 
$U\cap C\neq\varnothing$. 
Then $\bproj{C} :=\bprox{\iota_C}$ is the \emph{left Bregman projector} onto $C$
and $\fproj{C} :=\fprox{\iota_C}$ is the \emph{right Bregman projector} onto $C$.
\end{definition}


\begin{remark}
\label{r:prox}
Let $\theta\in\Gamma_0(X)$ be such that 
$U\cap \dom\theta\neq\varnothing$ and let $\gamma \in \RPP$.
\cref{p:12.22i} implies that 
$\benv{\gamma\theta} =\gamma\benv[\gamma]{\theta}$ 
and $\fenv{\gamma\theta} =\gamma\fenv[\gamma]{\theta}$. 
