where $P_\sigma$ is the square matrix indexed by $[n]^r\times [n]^r$, with entries 
$(P_\sigma)_{\ui, \uj}=1$ if $\uj=\ui^\sigma$ and 0 otherwise, for $\ui,\uj\in [n]^r$.

Consider a  matrix $M$ indexed by the set $[n]^r\times [n]^r$, so that $M$ represents an endomorphism from $(\K^n)^{\ot r}$ to $(\K^n)^{\ot r}$. Then, any permutation $\sigma\in \MFS_r$  induces naturally a permutation of  the columns (and rows) of $M$. 

\begin{definition}[Doubly symmetric matrix]\label{defdoublesymmetric}
A matrix $M\in \K^{[n]^r\times [n]^r}$  is called  {\em $r$-column symmetric} (resp., {\em $r$-row symmetric}) if $M\Pi_r =M$ (resp., $\Pi_rM=M$). If $M$ is complex Hermitian or real symmetric, then $M$ is $r$-column symmetric if and only if it is $r$-row symmetric, or equivalently if $\Pi_rM\Pi_r=M$, in which case  $M$ is called {\em $ r $-doubly symmetric} (or just {\em doubly symmetric} if $r$ is clear from the context).
\end{definition}


Hermitian doubly symmetric matrices are also known as {\em Bose symmetric} matrices in the quantum information literature. \MoL{The following stronger symmetry property is sometimes needed (it is considered, e.g.,   in \cite{Doherty_Wehner_2013}).}

\begin{definition}[Maximally symmetric matrix]\label{defmaximallysymmetric}
A  matrix $M\in \K^{[n]^r\times [n]^r}$ can be   viewed as  a $2r$-tensor $\vvec(M)\in (\K^n)^{\ot 2r}$, with entries  $\vvec(M)_{\ui\uj} = M_{\ui,\uj}$ for $\ui,\uj\in [n]^r$.
Then, $M$ is said to be {\em maximally symmetric} when $\vvec(M)$ is a symmetric $2r$-tensor.
\end{definition}

\tcolred{Note that a Hermitian matrix that is maximally symmetric is in fact real-valued (see also Lemma \ref{lem:ppt-sym-is-real-rank-2} below).} Let $\PiMS$ denote the projection from the space $\K^{[n]^r\times [n]^r}$ onto $\MaxSym_r(\K^n)$, the  space of maximally symmetric matrices. Concretely, the projection $\PiMS(M)$ is obtained by first constructing the symmetric $2r$-tensor $\Pi_{2r}(\vvec(M))$ and then reshaping it as a square matrix indexed by $[n]^r$ (by splitting the $2r$ indices into two classes of size $r$, which can be done   arbitrarily  as the tensor is $2r$-symmetric).

A polynomial $f\in R$ is a {\em sum of squares} (abbreviated as sos) if $ f = p_1^2  + \ldots + p_N^2 $ for some $ N\in \N $ and $ p_1,\ldots,p_N\in R$. Then, all $p_i$ lie in $R_d$ (resp., $R_{\le d}$) if $f\in R_{2d}$ (resp., $f\in R_{\le 2d}$). The following characterization is well-known \tcolblue{(see \cite{Choi-Lam-Reznick-1995,Powers-Wormann-1998})}.

\begin{lemma}\label{lem:sos-equiv-gram-matrix}
A polynomial $f$ is a sum of squares if and only if it admits a positive semidefinite representing matrix (then, often called a {\em Gram matrix} of $f$).
\end{lemma}

\begin{definition} \label{defGramtensor}
	Let $f\in R_{2d}$. A symmetric matrix $G$ indexed by $[n]^d$ is called a {\em tensor-indexed representing matrix} of  $ f $ if the following polynomial identity holds:
	\begin{align*}
		f = (x^{\otimes d})^{T}G x^{\otimes d} = \langle G, (x x^{T})^{\otimes d} \rangle. 
	\end{align*}
\end{definition}

	Then, any polynomial  $f\in R_{2d}$ admits  a (unique) tensor-indexed representing matrix  that is maximally symmetric, denoted by $\MaxSym(f)$. Namely, we have $\MaxSym(f)=\PiMS(G)$, where $G$ is any tensor-indexed representing matrix of $f$.
Moreover,
in analogy with \Cref{lem:sos-equiv-gram-matrix}, a polynomial $ f $ is a sum of squares if and only if it has a tensor-indexed positive semidefinite representing matrix.

\MoL{\johnstonlovitz{} \cite{Johnston_Lovitz_Vijayaraghavan_2023} proposed recently a hierarchy of spectral bounds $\spec_r(p)$ for the minimum value $p_{\min}$ of a homogeneous polynomial $p$ over the unit sphere,\footnote{ Their hierarchy  applies more generally to optimization of  a multivariate tensor over a spherical Segre-Veronese variety. We only focus here on their hierarchy for polynomials on the sphere.} 
see Section \ref{secJLV-intro} below for their definition and relationship to the  moment-sos bounds.  Throughout, let $p\in R_{2d}$, $s=x_1^2+\cdots +x_n^2$, and let 
\begin{align}\label{eqQpM}
	Q(p) = \maxsym(p), \quad  M = \maxsym(s^d) 
\end{align}
denote  the maximally symmetric  matrices representing the polynomials $ p $ and $s^d$, respectively (as in Definition \ref{defGramtensor}). They show the following convergence rate.
}

We introduce the spectral hierarchy of \johnstonlovitz{} \cite{Johnston_Lovitz_Vijayaraghavan_2023}. 
Let $p\in R_{2d}$ and recall the matrices $Q(p)$   and $M$ from (\ref{eqQpM}). For an integer $ r\ge d $, define the matrices 
\begin{align}\label{eqQrpM}
	Q_r(p) = \Pi_{r}(Q(p) \otimes I_n^{\otimes (r-d)})\Pi_{r}, \\
	M_r= \Pi_{r}(M \otimes I_n^{\otimes (r-d)})\Pi_{r}. 
\end{align}
So,  $ Q_r(p) $ and $M_r$ are   $ r $-doubly symmetric matrices    representing  $ s^{r-d}p $ and $s^r$, respectively. That is, $\langle Q_r(p), x^{\ot r}(x^{\ot r})^T\rangle = s^{r-d}p$ and $
\langle M_r, x^{\ot r}(x^{\ot r})^T\rangle= s^r$ hold.
Then, the  spectral bound  $\spec_r(p)$ at the $ r $-th level is defined as the smallest generalized eigenvalue of the matrix $ Q_r(p) $ with respect to $ M_r $. We gather some equivalent formulations for $\spec_r(p)$. 

\begin{definition}
	The spectral bound $\spec_r(p)$  is defined by any of the following equivalent programs:
	\begin{align}
		\spec_r(p)& =\max_{\nu\in\R} \{ \nu: Q_r(p)-\nu M_r\succeq 0\},\label{eqnu1} \\
		& = \min_{v\in S^r(\R^n) } \{v^T Q_r(p)v: v^T M_rv=1\}, \label{eqnu2}\\
		& = \min_{X } \{\langle Q_r(p), X\rangle: X \  r\text{-doubly symmetric},\ X\succeq 0,\ \langle M_r,X\rangle =1\}.\label{eqnu3}
	\end{align}
\end{definition}

We start by picking a  quartic form  in four variables that is nonnegative but not a sum of squares.
A concrete example is given by the \emph{Choi-Lam form} $ p_{CL} $, 
\begin{align}\label{eqpCL}
	p_{CL}(x) = x_1^2x_2^2+x_1^2x_3^2+ x_2^2x_3^2 + x_4^4 -4 x_1x_2x_3x_4.
\end{align}

The Choi-Lam form $ p_{CL}$ is famously known to be a nonnegative polynomial, which is not a sum of squares (see \cite{Choi_Lam_1977}). Hence, {\em no} matrix representation of $ p_{CL} $ is positive semidefinite.
This property is stronger than necessary. As it will turn out, our strategy for proving the lower bound $\Omega(1/r^2)$ for  the spectral hierarchy works with any nonnegative quartic form whose  maximally symmetric representation is not positive semidefinite. 

We use one small trick, which is to choose an unnatural representation of   $ p_{CL} $. While $ p_{CL} $ is intrinsically a polynomial in four variables $x=(x_1,x_2,x_3,x_4)$, one can artificially view it as a polynomial $p$ in five variables $ \underline{x} := (x_1,x_2,x_3,x_4,u) $, where $u$ is an additional variable, by setting $p(\underline x)=p_{CL}(x)$.
If, as a 4-variate polynomial,  $ p_{CL} $ is represented by a matrix $ Q^{(4)} \in \R^{[4]^2\times [4]^2} $, then, as a 5-variate polynomial in   $ \underline{x} = (x,u) $, it is represented by the matrix 
\begin{align}\label{eqmatQ}
	\begin{pmatrix}
		Q^{(4)} & 0\\
		0^{T} & 0
	\end{pmatrix} \in  \R^{[5]^2\times [5]^2}.
\end{align}
Note that the same holds   for the maximally symmetric representations of $p_{CL}$  in four variables and of $p $ as a polynomial in five variables: 
\begin{align}\label{eqmatMQ}
	\maxsym(p)  = \begin{pmatrix}
		\maxsym(p_{CL}) & 0\\
		0^{T} & 0
	\end{pmatrix}.
\end{align}
The reason is again that $ p $ is only supported on monomials, which do not depend on the fifth variable $ u $.

statement.raw_tex:
\begin{theorem}\label{thm:lower-bound-spectral}
	Let $\spec_r(p)$ denote the spectral bound of order $r$ for the Choi-Lam form $p \in \R[x_1,x_2,x_3,x_4,u]$. Then, we have	$p_{\min}=0$ and $\spec_r(p)=\Omega(1/r^2)$.
\end{theorem}

