\begin{definition}
    \label{def:absolute_continuity} 
    \cite[Definition 1 p. 12]{aubin1984differential}
    Given two real numbers $a<b$, a function $x:[a,b]\rightarrow\mathbb{R}^n$ is \textit{absolutely continuous} if for all $\epsilon>0$, there exists $\delta>0$ such that, for any finite collection of disjoint subintervals $[a_1,b_1],\hdots,[a_m,b_m]$ of $[a,b]$ such that $\sum_{i=1}^m b_i-a_i \leqslant \delta$, we have $\sum_{i=1}^m \|x(b_i) - x(a_i)\| \leqslant \epsilon$.
\end{definition}

By virtue of \cite[Theorem 20.8]{nielsen1997introduction}, $x:[a,b]\rightarrow\mathbb{R}^n$ is absolutely continuous if and only if it is differentiable almost everywhere on $(a,b)$, its derivative $x'$ is Lebesgue integrable, and $x(t) - x(a) = \int_a^t x'(\tau)d\tau$ for all $t\in [a,b]$. Given a non-compact interval $I$ of $\mathbb{R}$, $x:I\rightarrow \mathbb{R}^n$ is absolutely continuous if it is absolutely continuous on all compact subintervals of $I$.

An absolutely continuous function $x:[0,\infty)\rightarrow\mathbb{R}^n$ is called a \textit{subgradient trajectory} of $f:\mathbb{R}^n\rightarrow\mathbb{R}$ starting at $x_0\in\mathbb{R}^n$ if it satisfies the following differential inclusion with initial condition: 
\begin{equation}\label{eq:ivp-subgrad}
    x'(t) \in -\partial f(x(t)),\quad \text{for almost every $t\geqslant 0$},\quad x(0)=x_0,
\end{equation}
where ``almost every'' means all elements except for those in a set of zero measure.

\begin{definition}\label{def:bdd-subgrad}
A locally Lipschitz lower bounded function $f:\mathbb{R}^n\rightarrow\mathbb{R}$ has \textit{bounded subgradient trajectories} if for any $x_0\in\mathbb{R}^n$, there exists a subgradient trajectory $x$ of $f$ starting at $x_0$ and a constant $r>0$, such that $\|x(t)\|\leqslant r$ for all $t\geqslant 0$. 
\end{definition}

\begin{definition}\label{def:chain-rule}
Let $f:\mathbb{R}^n\rightarrow\mathbb{R}$ be locally Lipschitz. We say $f$ \textit{admits a chain rule} if for any absolutely continuous function $x:[0,\infty)\rightarrow \mathbb{R}^n$, we have
\begin{equation*}
	(f\circ x)'(t) = \langle v, x'(t)\rangle, \quad \forall\, v\in\partial f(x(t)),
\end{equation*}
for almost every $t\in [0,\infty)$. 
\end{definition}

Thus, for any locally Lipschitz function that admits a chain rule, by \cite[Lemma 5.2]{davis2020stochastic}, the function value is always decreasing in time along the subgradient trajectory. A detailed discussion on what class of functions admits a chain rule can be found in \cite{bolte2020conservative}. Note that general Lipschitz functions are far from admitting a chain rule since they generically have a maximal Clarke subdifferential \cite{daniilidis2020pathological,borwein2000lipschitz,daniilidis2019linear}.

\begin{assumption}\label{assm:funcClass}
Let $f:\mathbb{R}^n\rightarrow\mathbb{R}$ be a function such that it  
\begin{enumerate}[label={(\alph*)}]
    \item is bounded below, namely, $\inf_{\mathbb{R}^n}f > -\infty$;
    \item is locally Lipschitz continuous on $\mathbb{R}^n$; see \Cref{def:locally-lipschitz}; 
    \item admits a chain rule; see \Cref{def:chain-rule}; 
    \item has finitely many critical values; see \Cref{subsec:clarke}; 
    \item has bounded subgradient trajectories; see \Cref{def:bdd-subgrad}. 
\end{enumerate}
\end{assumption}

