\hfill solve the level-1 coarse problem
}
\STATE{(v)\,~~~ $z^{k+1}_0 = y^{k+1}_0  + \alpha P\big(  x^{k+1}_1 - y^{k+1}_1 \big)$
\hfill coarse correction \vspace{0.25mm}
}
\STATE{(vi)~~\, $x^{k+1}_0 = \prox_{\frac{1}{L_0}g_0} \Big (z^{k+1}_0 - \frac{1}{L_0} \nabla f(z^{k+1}_0) \Big)$
\hfill level-0 proximal gradient step~~
}
%
\ENDFOR
\end{algorithmic}
\end{algorithm}

Here are remarks for the steps in Algorithm~\ref{aglo:2levelMG_exact}.
\begin{itemize}
    \item (i): we perform one or more proximal gradient iterations on the fine variable with a constant stepsize $1/L_0$, where $L_0$ is the Lipschitz constant of $\nabla f_0$.
    \item (iii): we pick a value within the set to define $\tau$;
    as we are now using adaptive $R$, we use $+$ instead of $\oplus$ in the expression of $\tau$.
    \item (v): $\alpha > 0$ is a stepsize; for its selection see \cref{sec:mgprox:subsec:alpha}.
    \item The restriction for variable $y_0^{k+1}$ and the restriction for the subdifferential $ \underline{\partial  F_0(y^{k+1}_0)}$ can be slightly different.
    On $y_0^{k+1}$ the restriction is the full restriction, on $ \underline{\partial  F_0(y^{k+1}_0)}$ is the adaptive one. 
    The explanation is as follows.   
    For the particular cases of $g_0$ such as $\ell_1$, $\max\{ \cdot, 0\}$ (element-wise maximum) and $\iota_{[0,\infty)}$ (indicator of nonnegative orthant), when we zero out column $i$ of $R$, the corresponding entry of $y_0^{k+1}$ is already $0$.    
    Note that this conclusion does not hold in general for other nonsmooth functions or when the non-differentiability occur at another point (say at $x=1$). 
    Generally in those cases we will need to specify which restriction matrix (the full $R$ or the adaptive $R$) to be used to define $P$.
        However, to simplify the presentation we always assume the non-differentiability occurs at $x=0$,
         by performing a translation to shift the non-differentiability to occur at $x=0$.
%        In fact, this is what exact we do in the experiment.
\end{itemize}


Before we prove the theorem we emphasize that \eqref{iq:descent_dir} applies for any subgradient in the set $\underline{\partial F_0(y^{k+1}_0)} $.
Furthermore,
\[
\eqref{iq:descent_dir} 
%
\iff
%
\big\langle 
P^\top \underline{\partial F_0(y^{k+1}_0)} , x^{k+1}_1 - y^{k+1}_1 
\big\rangle
< 0
%
\overset{P^\top = cR}{\iff}
%
c \big\langle 
R \underline{\partial F_0(y^{k+1}_0)} , x^{k+1}_1 - y^{k+1}_1 
\big\rangle
< 0
.
\]
As $c>0$, showing \eqref{iq:descent_dir} is equivalent to showing
\begin{equation}
\big\langle R \underline{\partial F_0(y^{k+1}_0)},  ~ x^{k+1}_1 - y^{k+1}_1 \big\rangle < 0,
\label{pf:descent_to_prove}
\end{equation}
where $R \underline{\partial F_0(y^{k+1}_0)} $ is a singleton vector for all subgradients in $\underline{\partial F_0(y^{k+1}_0)}$ due to the adaptive $R$.


\subsubsection{Existence of coarse correction stepsize \texorpdfstring{$\alpha_k$}{}}
\label{sec:mgprox:subsec:alpha}
Based on Theorem~\ref{thm:coarse_dir_descent}, we now show that there exists a stepsize $\alpha_k > 0$ such that 
\begin{equation}
F_0(z^{k+1}_0) 
~\coloneqq~
F_0\big(
y^{k+1}_0 + \alpha_k P(x^{k+1}_1 - y^{k+1}_1) 
\big)
~<~
F_0(y^{k+1}_0).
\label{iq:coarse_descent_on_F}
\end{equation}


To prove the lemma, we make use 
of a fact of the subdifferentials of finite convex functions \cite[Def.1.1.4, p.165]{hiriart2004fundamentals}: $\partial g(x)$ is a nonempty compact convex set $\cS \subset \IRn$ whose support function $\displaystyle \sup_{s}\{ \langle s, x\rangle \,|\, s \in \cS  \}$ 
is the directional derivative of $g$ at $x$.
By this, the subdifferential
 $\underline{\partial F_0(y_0^{k+1})}$ is a compact convex set whose support function is the directional derivative of $F_0$ at $y_0^{k+1}$.
We emphasize that here 
%$F_0 : \IR^{n_0} \rightarrow  \overline{\IR}$ at $y_0^{k+1}$ is 
$F_0(y_0^{k+1})$ is 
finite, 
% i.e., $F_0 : \IR^{n_0} \rightarrow  \overline{\IR}$ will never reach $+\infty$ at $y_0^{k+1}$ since $y_0^{k+1}$ is obtained by the proximal gradient step (in other words, $y_0^{k+1}$ is a ``feasible point'' if $g_0$ is an indicator function of a constraint set),
so we can make use of the result on directional derivative in \cite[Def. 1.1.4, p.165]{hiriart2004fundamentals}, which only applies for finite convex functions, associated with the subdifferential.


\begin{lemma}
(Sufficient descent property of proximal gradient \cite[Lemma 10.4]{beck2017first})
\label{lemma:suff_descent_proxgrad} 
Let $L_0$ be the Lipschitz constant of $\nabla f_0$.
For step (i) in Algorithm~\ref{aglo:2levelMG_exact},  we have
\begin{equation}
F_0( y^{k+1}_0)
\leq 
F_0( x^k_0) - \| G_0(x_0^k) \|_2^2 / (2L_0),
~~
G_0( x_0^k) 
=
L_0 \big[
x_0^k - \prox_{ \frac{1}{L} g_0 }\big( x_0^k - \nabla f_0(x_0^k)/L_0
\big)
\big].
\label{eqn:suffdescentPGD}
\end{equation}
\end{lemma}
$G_0( x_0^k)$ is called the proximal gradient map of $F_0$ at $x_0^k$.
The inequality also holds for step (vi).


\begin{algorithm}
\caption{Naive line search}\label{aglo:naivelinesearch}
\begin{algorithmic}
\STATE{Set $\alpha > 0$ and select a tolerance $\epsilon > 0$  (e.g. $10^{-15}$)}
\WHILE{true}
\STATE{\textbf{If} $F_0\big( y^{k+1}_0 + \alpha P (x^{k+1}_1 - y^{k+1}_1) \big) \leq F_0( y^{k+1}_0 )$ \textbf{ then }
return $z_0^{k+1}=y^{k+1}_0 + \alpha P(x^{k+1}_1 - y^{k+1}_1)$.}
\\
\STATE{\textbf{else if} $\alpha > \epsilon $ \textbf{then} $\alpha = \alpha/2 $.}
\\
\STATE{~~~~~~~\textbf{else} return $z_0^{k+1}=y^{k+1}_0$.}
\ENDWHILE
\end{algorithmic}
\end{algorithm}


\subsubsection{Linear convergence rate}
All the functions and variables here are at level 0 so we omit the subscripts.
Now we show that $\big\{F( x^k) \big\}_{k \in \IN}$ converges to $F^*$ with a linear rate using the \emph{Proximal Polyak-{\L}ojasiewicz inequality} \cite[Section 4]{karimi2016linear}. 
The function $F$ in Problem \eqref{prob:minfg} is called ProxPL, if there exists $\mu > 0$, called the ProxPL constant, such that 
\begin{equation}
\cD_g(x,L)
~\geq~
2 \mu \big( F(x) - F^* \big)  \qquad  \forall x,
\tag{ProxPL}
\label{def:ProxPL}
\end{equation}
\begin{equation}
\cD_g(x,\alpha) 
\coloneqq
-2\alpha \min_z \,
\Big\{
{\textstyle\frac{\alpha}{2}} \| z - x \|_2^2 
+ \big\langle z - x, \nabla f(x) \big\rangle
+ g(z) - g(x)
\Big\}
.
\label{def:dg}
\end{equation}
Intuitively, $\cD_g$ is defined based on the proximal gradient operator:
\[
\prox_{\frac{1}{L}g} \Big( x - \frac{\nabla f(x)}{L} \Big)
=
\underset{z}{\argmin} \, \frac{L}{2} \| z -  x \|_2^2
+ \big\langle z - x, \nabla f(x) \big\rangle
+ g(z) - g(x).
\]
It has been shown in \cite{karimi2016linear} that if $f$ in \eqref{prob:minfg} is $\mu$-strongly convex, then $F$ is $\mu$-ProxPL.
Now we prove the linear convergence rate of Algorithm~\ref{aglo:2levelMG_exact}.
Note that a standard result such as \cite[Theorem 10.29]{beck2017first} on convergence of proximal gradient for strongly convex functions is not directly applicable because, as mentioned above, we interleave proximal gradient steps with coarse correction steps.

units.raw_tex:
We study the combination of two iterative algorithms: proximal gradient descent and multigrid, to solve the following class of optimization problems
\begin{equation}\label{prob:minfg}
\argmin_x ~ F_0(x) \coloneqq f_0(x) + g_0(x).
\end{equation}
\textbf{(Assumption)} We assume $f_0 : \IRn \rightarrow \IR$ is 
% lower semi-continuous, % NO need because smoothness implies LSC
$L_0$-smooth and $\mu_0$-strongly convex,
and  
%$g_0 : \IRn \rightarrow \overline{\IR} \coloneqq \IR \cup \{+\infty\}$ 
$g_0 : \IRn \rightarrow \IR$ 
is proper, possibly nonsmooth, convex, 
%lower semi-continuous, 
and separable.
Regarding the non-smoothness (nondifferentiability) of $g_0$, we further assume a single point of non-differentiability for $g_0$.
We recall that a function $\zeta(x) : \IRn \rightarrow \IR$ is separable if $\zeta(x) = \sum_i \zeta_i(x_i)$, and  is $\mu$-strongly convex (and thus coercive) with $\mu>0$ if $\zeta(x) - \frac{\mu}{2}\| x \|_2^2$ is convex;
and lastly is $L$-smooth if  $\zeta$ is $C^{1,1}_L$ and $\nabla \zeta$ is $L$-Lipschitz; i.e., for all $x,y$ in $\IRn$, $\nabla \zeta(x)$ exists and
\begin{equation}
\zeta(y) \leq \zeta(x) + \big\langle \nabla \zeta(x), y-x \big\rangle + \frac{L}{2}\|y-x\|_2^2.
\label{def:Lsmooth}
\end{equation}

The proximal gradient method solves problems of the form \eqref{prob:minfg} as follows.
Starting from an initial guess $x^1$, the method updates the variable by a gradient descent step (with a stepsize $\alpha > 0$) followed by a proximal step associated with $g_0$:
\begin{subequations}\label{eq:5}
\begin{align}
x^{k+1} &\,= \prox_{\alpha g_0} 
\Big( 
x^k - \alpha \nabla f_0(x^k)
\Big), 
%~~ \alpha > 0
\label{updt:proxgrad}
\\
\prox_{\alpha g_0}(x) 
& \coloneqq 
\underset{u}{\argmin} ~ \Big\{\, \alpha g_0(u) + \frac{1}{2} \| u - x \|_2^2 \,\Big\}
= \underset{u}{\argmin} ~ \Big\{\, g_0(u) + \frac{1}{2\alpha} \| u - x \|_2^2 \,\Big\}.
\label{def:prox_opertor}
\end{align}
\end{subequations}

\subsection{Adaptive restriction and the \texorpdfstring{$\tau$}{} vector}\label{sec:mgprox:subsec:adaptiveR}
Since subdifferentials are set-valued, we define $\tau$ in \MGProx as an element of a set.
At a level $\ell$, we define a set $\underline{\tau_{\ell \rightarrow \ell+1}} ~\coloneqq~
\underline{\partial F_{\ell+1}(x_{\ell+1})} \oplus (- R) \underline{\partial F_\ell (x_\ell)} $, where $\ell \rightarrow \ell+1$ specifies that $\tau$ connects level $\ell$ to level $\ell+1$, and the matrix $R$ here is an adaptive restriction operator that we will define soon.
In \MGProx we choose an element of $\underline{\tau_{\ell \rightarrow \ell+1}}$ as the tau vector.
That is, at level $\ell=0$,
\begin{subequations}
\begin{align}
\tau_{0 \rightarrow 1}
~\, \in \,~ 
\underline{\tau_{0 \rightarrow 1}}
& 
~\coloneqq~
\underline{\partial F_1(x_1)} \oplus (- R) \underline{\partial F_0(x_0)}
\label{def:tau_mgprox1}
\\
&\overset{\eqref{ass:F_sum_rule}}{=} \nabla f_1(x_1) - R \nabla f_0(x_0) + \underline{\partial g_1(x_1)}
\oplus 
(- R) \underline{\partial g_0(x_0)}.
\label{def:tau_mgprox2}
\end{align}
\end{subequations}
Note that $\underline{\tau_{0 \rightarrow 1}}$ is a function of two points at two different levels.
In \eqref{def:tau_mgprox1} $\underline{\tau_{0 \rightarrow 1}}$ is the Minkowski sum of two subdifferentials $\partial F_1(x_1) $ and $-R\partial F_0(x_0)$ which are generally set-valued.
To obtain a tractable coarse-grid optimization problem (corresponding to line (iv) in Algorithm~\ref{algo:mgopt}) we need to avoid complications coming from the Minkowski sum, and we do this by modifying the standard restriction (and prolongation) 
by zeroing out columns in $\overline{R}$ to form $R$ such that the second subdifferential $R \partial g_0(x_0)$ in \eqref{def:tau_mgprox2}
is a singleton vector.
Similarly, we  zero out the corresponding rows in $\overline{P}$ to form $P$ for the coarse correction step, such that non-differentiable fine points are not corrected by the coarse grid.
This zeroing out process is adapted to the current point $x_0$, so we call this $R$ an adaptive restriction operator. 
In other words, the purpose of the adaptive restriction is to reduce a generally set-valued subdifferential $R\partial g_0(x_0)$ to a singleton.
We denote the adaptive operator $R$ corresponding to a point $x$ as $R(x)$ and thereby the adaptive restriction of $x$ is denoted as $R(x)x$.
Sometimes we just write $Rx$ if the meaning is clear from the context.
Based on the above discussion, we now formally define adaptive restriction,
and we give an example in \cref{sec:exp}.


\begin{definition}[Adaptive restriction operator for separable $g$]\label{eg:adaptiveR_L1}
For a possibly nonsmooth function $g : \IRn \rightarrow \IR$ that is separable, i.e., with $x = [x_1,x_2,\dots,x_n]$, $g(x) = \sum g_i(x_i)$ where $g_i$ is a function only of component $x_i$, 
given a full restriction operator $\overline{R}$ and a vector $x$, the adaptive restriction operator $R$ with respect to a function $g$ at $x$ is defined by zeroing out the columns of $\overline{R}$ corresponding to the elements in $\partial g$ that are set-valued.
\label{def:adaptiveR}
\end{definition}

\subsection{A 2-level \texorpdfstring{\MGProx}{}algorithm}\label{sec:mgprox:subsec:2lv}
Similar to the 2-level \MGOPT method for solving Problem \eqref{prob:mgopt}, we propose a 2-level \MGProx method (Algorithm \ref{aglo:2levelMG_exact}) that solves Problem \eqref{prob:minfg} by utilizing a coarse problem defined as 
\begin{equation}\label{prob:minfg_coarse}
\argmin_{\xi \in \IR^{n_1}}\,
\bigg\{\,
F^{\tau}_1 (\xi) 
~\coloneqq~  F_1(\xi) - \langle \tau_{0 \rightarrow 1}^{k+1}, \xi \rangle
~=~ f_1 (\xi) + g_1(\xi) - \langle \tau_{0 \rightarrow 1}^{k+1}, \xi \rangle
\,\bigg\}.
\end{equation}


\begin{algorithm}
\caption{2-level \MGProx for an approximate solution of \eqref{prob:minfg}}
\label{aglo:2levelMG_exact}
\begin{algorithmic}
\STATE{Initialize $x^1_0$, $R$ and $P$}
\FOR{$k = 1,2,\dots$}
%
\STATE{(i)~~~~ $y^{k+1}_0 = \prox_{\frac{1}{L_0}g_0} \Big (x^k_0 - \frac{1}{L_0} \nabla f(x^k_0) \Big)$
\hfill level-0 proximal gradient step \vspace{0.25mm}
}
\STATE{(ii)~~~ $y^{k+1}_1  = R(y^{k+1}_0) y^{k+1}_0 $   
\hfill construct the level-1 coarse variable \vspace{0.25mm}
}
\STATE{(iii)~~ $\tau_{0 \rightarrow 1}^{k+1} \hspace{-1mm} \in\,
\underline{\partial F_1(y^{k+1}_1 )}  - R(y^{k+1}_0) \, \underline{\partial  F_0(y^{k+1}_0)}$
\hfill construct the tau vector \vspace{0.25mm}
}
\STATE{(iv)~~ $
x^{k+1}_1
= \underset{\xi}{\argmin} \, \Big\{ F_1^{\tau}(\xi) \coloneqq F_1(\xi) - \langle \tau_{0 \rightarrow 1}^{k+1}, \xi \rangle \Big\}
$
\hfill solve the level-1 coarse problem
}
\STATE{(v)\,~~~ $z^{k+1}_0 = y^{k+1}_0  + \alpha P\big(  x^{k+1}_1 - y^{k+1}_1 \big)$
\hfill coarse correction \vspace{0.25mm}
}
\STATE{(vi)~~\, $x^{k+1}_0 = \prox_{\frac{1}{L_0}g_0} \Big (z^{k+1}_0 - \frac{1}{L_0} \nabla f(z^{k+1}_0) \Big)$
\hfill level-0 proximal gradient step~~
}
%
\ENDFOR
\end{algorithmic}
\end{algorithm}

Here are remarks for the steps in Algorithm~\ref{aglo:2levelMG_exact}.
\begin{itemize}
    \item (i): we perform one or more proximal gradient iterations on the fine variable with a constant stepsize $1/L_0$, where $L_0$ is the Lipschitz constant of $\nabla f_0$.
    \item (iii): we pick a value within the set to define $\tau$;
    as we are now using adaptive $R$, we use $+$ instead of $\oplus$ in the expression of $\tau$.
    \item (v): $\alpha > 0$ is a stepsize; for its selection see \cref{sec:mgprox:subsec:alpha}.
    \item The restriction for variable $y_0^{k+1}$ and the restriction for the subdifferential $ \underline{\partial  F_0(y^{k+1}_0)}$ can be slightly different.
    On $y_0^{k+1}$ the restriction is the full restriction, on $ \underline{\partial  F_0(y^{k+1}_0)}$ is the adaptive one. 
    The explanation is as follows.   
    For the particular cases of $g_0$ such as $\ell_1$, $\max\{ \cdot, 0\}$ (element-wise maximum) and $\iota_{[0,\infty)}$ (indicator of nonnegative orthant), when we zero out column $i$ of $R$, the corresponding entry of $y_0^{k+1}$ is already $0$.    
    Note that this conclusion does not hold in general for other nonsmooth functions or when the non-differentiability occur at another point (say at $x=1$). 
    Generally in those cases we will need to specify which restriction matrix (the full $R$ or the adaptive $R$) to be used to define $P$.
        However, to simplify the presentation we always assume the non-differentiability occurs at $x=0$,
         by performing a translation to shift the non-differentiability to occur at $x=0$.
%        In fact, this is what exact we do in the experiment.
\end{itemize}

\subsubsection{Existence of coarse correction stepsize \texorpdfstring{$\alpha_k$}{}}
\label{sec:mgprox:subsec:alpha}
Based on Theorem~\ref{thm:coarse_dir_descent}, we now show that there exists a stepsize $\alpha_k > 0$ such that 
\begin{equation}
F_0(z^{k+1}_0) 
~\coloneqq~
F_0\big(
y^{k+1}_0 + \alpha_k P(x^{k+1}_1 - y^{k+1}_1) 
\big)
~<~
F_0(y^{k+1}_0).
\label{iq:coarse_descent_on_F}
\end{equation}

\begin{algorithm}
\caption{Naive line search}\label{aglo:naivelinesearch}
\begin{algorithmic}
\STATE{Set $\alpha > 0$ and select a tolerance $\epsilon > 0$  (e.g. $10^{-15}$)}
\WHILE{true}
\STATE{\textbf{If} $F_0\big( y^{k+1}_0 + \alpha P (x^{k+1}_1 - y^{k+1}_1) \big) \leq F_0( y^{k+1}_0 )$ \textbf{ then }
return $z_0^{k+1}=y^{k+1}_0 + \alpha P(x^{k+1}_1 - y^{k+1}_1)$.}
\\
\STATE{\textbf{else if} $\alpha > \epsilon $ \textbf{then} $\alpha = \alpha/2 $.}
\\
\STATE{~~~~~~~\textbf{else} return $z_0^{k+1}=y^{k+1}_0$.}
\ENDWHILE
\end{algorithmic}
\end{algorithm}

\begin{theorem}[Angle condition of coarse correction]\label{thm:coarse_dir_descent}
If $P(x^{k+1}_1 - y^{k+1}_1) \neq 0$, then
\begin{equation}\label{iq:descent_dir}
\big\langle 
\underline{\partial F_0(y^{k+1}_0)} , P(x^{k+1}_1 - y^{k+1}_1) 
\big\rangle 
%\leq 
<
0. 
\end{equation}
%I.e., $P(x^{k+1}_1 - y^{k+1}_1) $ and any subgradient in $\partial F_0(y^{k+1}_0)$ forms a strict obtuse angle.
\end{theorem}

\begin{lemma}[Existence of stepsize]\label{lemma:alphaexists}
There exists $\alpha_k > 0$ such that \eqref{iq:coarse_descent_on_F} is satisfied for $P(x^{k+1}_1 - y^{k+1}_1) \neq 0$.
\end{lemma}

\begin{proof}
We prove the lemma in 3 steps.
\begin{enumerate}

\item (Half-space)
The strict inequality in Theorem~\ref{thm:coarse_dir_descent} means that $\underline{\partial F_0(y_0^{k+1})}$ is strictly inside a half-space with normal vector $p = P(x^{k+1}_1 - y^{k+1}_1)$.  

\item (Strict separation)
Being a compact convex set, $\underline{\partial F_0(y_0^{k+1}0)}$ lying strictly on one side of the hyperplane must be a positive distance (say $\alpha_k > 0$) from that hyperplane.

\item (Support and directional derivative)
Evaluating the support function of $\underline{\partial F_0(y_0^{k+1})}$, i.e., the directional derivative of $F_0$ at $y_0^{k+1}$ in the direction $p$, we have \eqref{iq:coarse_descent_on_F}.
\end{enumerate}
\end{proof}

