We study the combination of two iterative algorithms: proximal gradient descent and multigrid, to solve the following class of optimization problems
\begin{equation}\label{prob:minfg}
\argmin_x ~ F_0(x) \coloneqq f_0(x) + g_0(x).
\end{equation}

and lastly is $L$-smooth if  $\zeta$ is $C^{1,1}_L$ and $\nabla \zeta$ is $L$-Lipschitz; i.e., for all $x,y$ in $\IRn$, $\nabla \zeta(x)$ exists and
\begin{equation}
\zeta(y) \leq \zeta(x) + \big\langle \nabla \zeta(x), y-x \big\rangle + \frac{L}{2}\|y-x\|_2^2.
\label{def:Lsmooth}
\end{equation}

The proximal gradient method solves problems of the form \eqref{prob:minfg} as follows.
Starting from an initial guess $x^1$, the method updates the variable by a gradient descent step (with a stepsize $\alpha > 0$) followed by a proximal step associated with $g_0$:
\begin{subequations}\label{eq:5}
\begin{align}
x^{k+1} &\,= \prox_{\alpha g_0} 
\Big( 
x^k - \alpha \nabla f_0(x^k)
\Big), 
%~~ \alpha > 0
\label{updt:proxgrad}
\\

\prox_{\alpha g_0}(x) 
& \coloneqq 
\underset{u}{\argmin} ~ \Big\{\, \alpha g_0(u) + \frac{1}{2} \| u - x \|_2^2 \,\Big\}
= \underset{u}{\argmin} ~ \Big\{\, g_0(u) + \frac{1}{2\alpha} \| u - x \|_2^2 \,\Big\}.
\label{def:prox_opertor}
\end{align}
\end{subequations}

To sum up, in this work \eqref{fact:subgrad_sum_rule} holds for all levels $\ell$:
\begin{equation}
\partial F_\ell(x_\ell) 
\coloneqq  \partial \Big( f_\ell(x_\ell) + g_\ell(x_\ell) \Big)
= \partial f_\ell(x_\ell) \oplus \partial g_\ell(x_\ell)
= \nabla f_\ell(x_\ell) + \partial g_\ell (x_\ell)
,
\label{ass:F_sum_rule}
\end{equation}
where $+$ is used instead of $\oplus$ in $\nabla f_\ell(x_\ell) + \partial g_\ell (x_\ell)$ because $\nabla f_\ell(x_\ell)$ is a singleton.

\subsection{Convexity and subdifferential of coarse function}
From Definition~\ref{def:restriction}, the coarse function can be written as $F_{\ell+1} \coloneqq F_\ell \circ R$, meaning that we can see the restriction process as the fine function taking composition with the linear map $R$.
Such composition view point gives us a series of useful properties for this work.
First, we have a closed-form expression for the subdifferential of the coarse function in terms of the the subdifferential of the fine function.
I.e., by \cite[Theorem 3.43]{beck2017first}, we have that
\begin{equation}\label{subdiff_coarse_linearmap}
\partial F_{\ell+1}(x) = \partial (F_\ell \circ R)(x) = R^\top \partial F_\ell (Rx). 
\end{equation}

\begin{lemma}[Composition with full-rank matrix preserves  convexity]
\label{lem:strcvx_linearmap}
Given a function $F : \IRn \rightarrow \overline{\IR}$ that is $\mu$-strongly convex and a rank-$n$ matrix $R \in \IR^{m \times n}$, the function $F \circ R$ is $\mu \sigma^2_n$-strongly convex, where $\sigma_n$ is the $n$th singular value of $R$.

\begin{proof}
$F$ is strongly convex so $\partial F$ is strongly monotone \cite{bauschke2011convex}: for all $x,y \in \dom F$, 
\begin{equation}\label{lem:strcvx_linearmap:fineF}
\big\langle x - y, ~ \partial F(x) - \partial F(y ) \big\rangle 
~\geq~
\mu \| x - y\|_2^2.
\end{equation}

\subsection{Adaptive restriction and the \texorpdfstring{$\tau$}{} vector}\label{sec:mgprox:subsec:adaptiveR}
Since subdifferentials are set-valued, we define $\tau$ in \MGProx as an element of a set.
At a level $\ell$, we define a set $\underline{\tau_{\ell \rightarrow \ell+1}} ~\coloneqq~
\underline{\partial F_{\ell+1}(x_{\ell+1})} \oplus (- R) \underline{\partial F_\ell (x_\ell)} $, where $\ell \rightarrow \ell+1$ specifies that $\tau$ connects level $\ell$ to level $\ell+1$, and the matrix $R$ here is an adaptive restriction operator that we will define soon.
In \MGProx we choose an element of $\underline{\tau_{\ell \rightarrow \ell+1}}$ as the tau vector.
That is, at level $\ell=0$,
\begin{subequations}
\begin{align}
\tau_{0 \rightarrow 1}
~\, \in \,~ 
\underline{\tau_{0 \rightarrow 1}}
& 
~\coloneqq~
\underline{\partial F_1(x_1)} \oplus (- R) \underline{\partial F_0(x_0)}
\label{def:tau_mgprox1}
\\

&\overset{\eqref{ass:F_sum_rule}}{=} \nabla f_1(x_1) - R \nabla f_0(x_0) + \underline{\partial g_1(x_1)}
\oplus 
(- R) \underline{\partial g_0(x_0)}.
\label{def:tau_mgprox2}
\end{align}
\end{subequations}
Note that $\underline{\tau_{0 \rightarrow 1}}$ is a function of two points at two different levels.
In \eqref{def:tau_mgprox1} $\underline{\tau_{0 \rightarrow 1}}$ is the Minkowski sum of two subdifferentials $\partial F_1(x_1) $ and $-R\partial F_0(x_0)$ which are generally set-valued.

\begin{definition}[Adaptive restriction operator for separable $g$]\label{eg:adaptiveR_L1}
For a possibly nonsmooth function $g : \IRn \rightarrow \IR$ that is separable, i.e., with $x = [x_1,x_2,\dots,x_n]$, $g(x) = \sum g_i(x_i)$ where $g_i$ is a function only of component $x_i$, 
given a full restriction operator $\overline{R}$ and a vector $x$, the adaptive restriction operator $R$ with respect to a function $g$ at $x$ is defined by zeroing out the columns of $\overline{R}$ corresponding to the elements in $\partial g$ that are set-valued.
\label{def:adaptiveR}
\end{definition}

\subsection{A 2-level \texorpdfstring{\MGProx}{}algorithm}\label{sec:mgprox:subsec:2lv}
Similar to the 2-level \MGOPT method for solving Problem \eqref{prob:mgopt}, we propose a 2-level \MGProx method (Algorithm \ref{aglo:2levelMG_exact}) that solves Problem \eqref{prob:minfg} by utilizing a coarse problem defined as 
\begin{equation}\label{prob:minfg_coarse}
\argmin_{\xi \in \IR^{n_1}}\,
\bigg\{\,
F^{\tau}_1 (\xi) 
~\coloneqq~  F_1(\xi) - \langle \tau_{0 \rightarrow 1}^{k+1}, \xi \rangle
~=~ f_1 (\xi) + g_1(\xi) - \langle \tau_{0 \rightarrow 1}^{k+1}, \xi \rangle
\,\bigg\}.
\end{equation}

\begin{algorithm}
\caption{2-level \MGProx for an approximate solution of \eqref{prob:minfg}}
\label{aglo:2levelMG_exact}
\begin{algorithmic}
\STATE{Initialize $x^1_0$, $R$ and $P$}
\FOR{$k = 1,2,\dots$}
%
\STATE{(i)~~~~ $y^{k+1}_0 = \prox_{\frac{1}{L_0}g_0} \Big (x^k_0 - \frac{1}{L_0} \nabla f(x^k_0) \Big)$
\hfill level-0 proximal gradient step \vspace{0.25mm}
}
\STATE{(ii)~~~ $y^{k+1}_1  = R(y^{k+1}_0) y^{k+1}_0 $   
\hfill construct the level-1 coarse variable \vspace{0.25mm}
}
\STATE{(iii)~~ $\tau_{0 \rightarrow 1}^{k+1} \hspace{-1mm} \in\,
\underline{\partial F_1(y^{k+1}_1 )}  - R(y^{k+1}_0) \, \underline{\partial  F_0(y^{k+1}_0)}$
\hfill construct the tau vector \vspace{0.25mm}
}
\STATE{(iv)~~ $
x^{k+1}_1
= \underset{\xi}{\argmin} \, \Big\{ F_1^{\tau}(\xi) \coloneqq F_1(\xi) - \langle \tau_{0 \rightarrow 1}^{k+1}, \xi \rangle \Big\}
$
\hfill solve the level-1 coarse problem
}
\STATE{(v)\,~~~ $z^{k+1}_0 = y^{k+1}_0  + \alpha P\big(  x^{k+1}_1 - y^{k+1}_1 \big)$
\hfill coarse correction \vspace{0.25mm}
}
\STATE{(vi)~~\, $x^{k+1}_0 = \prox_{\frac{1}{L_0}g_0} \Big (z^{k+1}_0 - \frac{1}{L_0} \nabla f(z^{k+1}_0) \Big)$
\hfill level-0 proximal gradient step~~
}
%
\ENDFOR
\end{algorithmic}
\end{algorithm}

Here are remarks for the steps in Algorithm~\ref{aglo:2levelMG_exact}.
\begin{itemize}
    \item (i): we perform one or more proximal gradient iterations on the fine variable with a constant stepsize $1/L_0$, where $L_0$ is the Lipschitz constant of $\nabla f_0$.
    \item (iii): we pick a value within the set to define $\tau$;
    as we are now using adaptive $R$, we use $+$ instead of $\oplus$ in the expression of $\tau$.
    \item (v): $\alpha > 0$ is a stepsize; for its selection see \cref{sec:mgprox:subsec:alpha}.

\begin{theorem}[Angle condition of coarse correction]\label{thm:coarse_dir_descent}
If $P(x^{k+1}_1 - y^{k+1}_1) \neq 0$, then
\begin{equation}\label{iq:descent_dir}
\big\langle 
\underline{\partial F_0(y^{k+1}_0)} , P(x^{k+1}_1 - y^{k+1}_1) 
\big\rangle 
%\leq 
<
0. 
\end{equation}
%I.e., $P(x^{k+1}_1 - y^{k+1}_1) $ and any subgradient in $\partial F_0(y^{k+1}_0)$ forms a strict obtuse angle.
\end{theorem}

\begin{proof}
By definition 
$\tau_{0 \rightarrow 1}^{k+1} \overset{\eqref{def:tau_mgprox1}}{\in} \underline{\partial F_1(y_1^{k+1})}  - R \underline{\partial F_0(y_0^{k+1})}$ 
and the fact that $R \underline{\partial F_0(y^{k+1}_0)} $ is a singleton, we have
$
R \underline{\partial F_0(y_0^{k+1})} 
\in
\underline{\partial F_1(y_1^{k+1})}  - \tau_{0 \rightarrow 1}^{k+1}
\overset{\eqref{prob:minfg_coarse}}{=} \underline{\partial F_1^\tau(y_1^{k+1})}$,
showing that $R \underline{\partial F_0(y_0^{k+1})} $ is a subgradient of $F_1^{\tau}$ at $y_1^{k+1}$.

\subsubsection{Existence of coarse correction stepsize \texorpdfstring{$\alpha_k$}{}}
\label{sec:mgprox:subsec:alpha}
Based on Theorem~\ref{thm:coarse_dir_descent}, we now show that there exists a stepsize $\alpha_k > 0$ such that 
\begin{equation}
F_0(z^{k+1}_0) 
~\coloneqq~
F_0\big(
y^{k+1}_0 + \alpha_k P(x^{k+1}_1 - y^{k+1}_1) 
\big)
~<~
F_0(y^{k+1}_0).
\label{iq:coarse_descent_on_F}
\end{equation}

\begin{lemma}[Existence of stepsize]\label{lemma:alphaexists}
There exists $\alpha_k > 0$ such that \eqref{iq:coarse_descent_on_F} is satisfied for $P(x^{k+1}_1 - y^{k+1}_1) \neq 0$.
\end{lemma}

\begin{proof}
We prove the lemma in 3 steps.
\begin{enumerate}

\item (Half-space)
The strict inequality in Theorem~\ref{thm:coarse_dir_descent} means that $\underline{\partial F_0(y_0^{k+1})}$ is strictly inside a half-space with normal vector $p = P(x^{k+1}_1 - y^{k+1}_1)$.  

\item (Strict separation)
Being a compact convex set, $\underline{\partial F_0(y_0^{k+1}0)}$ lying strictly on one side of the hyperplane must be a positive distance (say $\alpha_k > 0$) from that hyperplane.

\item (Support and directional derivative)
Evaluating the support function of $\underline{\partial F_0(y_0^{k+1})}$, i.e., the directional derivative of $F_0$ at $y_0^{k+1}$ in the direction $p$, we have \eqref{iq:coarse_descent_on_F}.
\end{enumerate}
\end{proof}

