\FOR{$k = 1,2,\dots$}
%
\STATE{(i)~~~~ $y^{k+1}_0 = \prox_{\frac{1}{L_0}g_0} \Big (x^k_0 - \frac{1}{L_0} \nabla f(x^k_0) \Big)$
