\label{def:ProxPL}
\end{equation}

\begin{equation}
\cD_g(x,\alpha) 
\coloneqq
-2\alpha \min_z \,
\Big\{
{\textstyle\frac{\alpha}{2}} \| z - x \|_2^2 
+ \big\langle z - x, \nabla f(x) \big\rangle
