				x(t) =&
				A\frac{1+\delta_1(t)}{r(t)^{1/4}}\frac{\sqrt{\alpha(t)+\beta\lambda}}{\sqrt{\eps(t)}}
				\exp\left(\int_0^t -\frac{\lambda}{\alpha(s)+\beta\lambda} - \frac{\lambda^2\eps(s)}{(\alpha(s)+\beta\lambda)^{3}}+o(\eps(s))\diff s\right)
