				+B&\frac{1+\delta_2(t)}{r(t)^{1/4}}
				\frac{\sqrt{\eps(t)}}{\sqrt{\alpha(t)+\beta\lambda}}
				\\
				&\exp\left(\int_0^t -\frac{\alpha(s)+\beta\lambda}{\eps(s)}+\frac{\lambda}{\alpha(s)+\beta\lambda}+\frac{\lambda^2\eps(s)}{(\alpha(s)+\beta\lambda)^{3}}+o(\eps(s))\diff s\right),
