\begin{proof}[Proof of Theorem~\ref{thm::MainResLG}]
		Let $x$ be the solution of \eqref{eq::QuadeDINAVD} define $p,r$ as in \eqref{eq::pr}. Let us also define $y(t)\stackrel{\textrm{def}}{=}x(t)\exp\left(\int_0^t \frac{p(s)}{2}\diff s\right)$. According to Lemma~\ref{lem::canonForm}, $r$ is positive and $y$ is solution to \eqref{eq::ODErewritten}. Then, from Lemma~\ref{lem::phiintegrable}, $\int_t^{T} \vert \varphi(s)\vert\diff s<+\infty$, so we can apply Theorem~\ref{thm::olver} to $y$ on $[0,+\infty[$. Therefore, there exists $A,B\in\R$, such that $\forall t\geq 0$,
		$$
		y(t)= A\frac{1+\delta_1(t)}{r(t)^{1/4}}\exp\left(\int_0^t \sqrt{r(s)}\diff s\right) + B\frac{1+\delta_2(t)}{r(t)^{1/4}}\exp\left(\int_0^t -\sqrt{r(s)}\diff s\right),
		$$
		where $A$ and $B$ are determined by the initial conditions, and $\delta_1$, $\delta_2$ are such that \eqref{eq::deltabounds} holds.
		Going back to $x(t) = y(t)\exp\left(\int_0^t -\frac{p(s)}{2}\diff s\right)$, we obtain 	that for all $t\geq 0$,
		\begin{multline}\label{eq::formofx0}
			x(t) = A\frac{1+\delta_1(t)}{r(t)^{1/4}}\exp\left(\int_0^t -\frac{p(s)}{2} +\sqrt{r(s)}\diff s\right) \\ + B\frac{1+\delta_2(t)}{r(t)^{1/4}}\exp\left(\int_0^t -\frac{p(s)}{2} -\sqrt{r(s)}\diff s\right).
		\end{multline}
		It now remains to expand the terms in the two exponentials in \eqref{eq::formofx0} in order to obtain \eqref{eq::formofx}. To this aim, we approximate $\sqrt{r(s)}$, let $s\geq 0$,
		\begin{align}\label{eq::sqrtr}
			\begin{split}
				\sqrt{r(s)}&=\frac{p(s)}{2}\sqrt{1+ \frac{2p'(s)}{p(s)^2} - \frac{4\lambda}{\eps(s)p(s)^2}}
				\\&= \frac{p(s)}{2}\left(1 + \frac{p'(s)}{p(s)^2} - \frac{2\lambda}{\eps(s)p(s)^2} - \frac{1}{8}\left(\frac{2p'(s)}{p(s)^2} - \frac{4\lambda}{\eps(s)p(s)^2}\right)^2 + o(\eps(s)^2) \right)
				\\ & = \frac{p(s)}{2} +\frac{ p'(s)}{2p(s)} - \frac{\lambda}{\eps(s)p(s)} - \frac{1}{16}\left(\frac{2p'(s)}{p(s)^{3/2}} - \frac{4\lambda}{\eps(s)p(s)^{3/2}}\right)^2 + o(\eps(s))
				\\  = \frac{p(s)}{2} &+ \frac{p'(s)\eps(s)}{2(\alpha(s)+\beta\lambda)} - \frac{\lambda}{\alpha(s)+\beta\lambda} - \frac{1}{16}\left(\frac{2p'(s)}{p(s)^{3/2}} - \frac{4\lambda\sqrt{\eps(s)}}{(\alpha(s)+\beta\lambda)^{3/2}}\right)^2 + o(\eps(s))
				\\  = \frac{p(s)}{2} &+ \frac{\alpha'(s)/2-\lambda}{\alpha(s)+\beta\lambda} -\frac{\eps'(s)}{2\eps(s)}  - \frac{1}{16}\left(\frac{2p'(s)}{p(s)^{3/2}} - \frac{4\lambda\sqrt{\eps(s)}}{(\alpha(s)+\beta\lambda)^{3/2}}\right)^2 + o(\eps(s))
			\end{split}
		\end{align}
		To ease the readability, we denote $h(t)=\left(\frac{2p'(s)}{p(s)^{3/2}} - \frac{4\lambda\sqrt{\eps(s)}}{(\alpha(s)+\beta\lambda)^{3/2}}\right)^2$. Focusing on the first exponential term in \eqref{eq::formofx0}, we deduce from \eqref{eq::sqrtr} that for all $t\geq 0$,
		\begin{align*}%\label{eq::Aexpterm}
			\begin{split}
				&\exp\left(\int_0^t -\frac{p(s)}{2} +\sqrt{r(s)}\diff s\right)
				\\&= \exp\left(\int_0^t \frac{\alpha'(s)/2}{\alpha(s)+\beta\lambda} -\frac{\eps'(s)}{2\eps(s)} -\frac{\lambda}{\alpha(s)+\beta\lambda} - \frac{1}{16}h(t) + o(\eps(s))\diff s\right)
				\\&=  \frac{\sqrt{\alpha(t)+\beta\lambda})}{\sqrt{\alpha_0+\beta\lambda}} \frac{\sqrt{\eps_0}}{\sqrt{\eps(t)}} \exp\left(
				\int_0^t \frac{-\lambda}{\alpha(s)+\beta\lambda} -
				\frac{1}{16}h(t) + o(\eps(s))\diff s\right)
				\\&=  \frac{\sqrt{\alpha(t)+\beta\lambda})}{\sqrt{\alpha_0+\beta\lambda}} \frac{\sqrt{\eps_0}}{\sqrt{\eps(t)}} \exp\left(
				\int_0^t \frac{-\lambda}{\alpha(s)+\beta\lambda} -
				\frac{\lambda^2\eps(s)}{(\alpha(s)+\beta\lambda)^{3}} + o(\eps(s))\diff s\right),
			\end{split}
		\end{align*}
		where the last line relies on further computations postponed to Lemma~\ref{lem::remainderterm} in Appendix~\ref{app::integrability}. Performing the exact same type of computations on $\exp\left(\int_0^t -\frac{p(s)}{2} -\sqrt{r(s)}\diff s\right)$, and up to redefining $A$ and $B$ so as to encompass all the constants, we obtain \eqref{eq::formofx} and the result is proved.
