\begin{lemma}\label{lem::remainderterm}
		Under Assumptions~\ref{ass:smooth} and~\ref{ass:subexp}, for all $s\geq 0$, $$\frac{1}{16}\left(\frac{2p'(s)}{p(s)^{3/2}} - \frac{4\lambda\sqrt{\eps(s)}}{(\alpha(s)+\beta\lambda)^{3/2}}\right)^2 = \frac{\lambda^2\eps(s)}{(\alpha(s)+\beta\lambda)^{3}}+o(\eps(s)).$$
	\end{lemma}

\begin{proof}
		We omit the time dependence on $s\geq 0$ for the sake of readability. Using Assumption~\ref{ass:smooth} we can define and expand the following quantity,
		\begin{align*}
			&\frac{1}{16}\left(\frac{2p'}{p^{3/2}} - \frac{4\lambda\sqrt{\eps}}{(\alpha+\beta\lambda)^{3/2}}\right)^2
			=\frac{\lambda^2\eps}{(\alpha+\beta\lambda)^{3}}  - \frac{p'\lambda\sqrt{\eps}}{p^{3/2}(\alpha+\beta\lambda)^{3/2}} + \frac{(p')^2}{4p^{3}}
			\\&= \frac{\lambda^2\eps}{(\alpha+\beta\lambda)^{3}}
				- \frac{\lambda(\alpha'\eps - (\alpha+\beta\lambda)\eps')}{(\alpha+\beta\lambda)^{3}}
