    \frac{\Lmax^{1/2} \Mmax^2 \Delta}{\epsilon^{7/4} M_0^{7/4}}
    + 2 (c_2 + 1) \frac{\Lmax^{1/2} \Mmax^{1/4}}{\epsilon^{1/4} M_0^{1/2}}.
    \label{eq:complexity_bound}
  \end{align}
  If $M_k$ is computed with \cref{eq:update_Mest} in the algorithm and $\beta$ is set as $\beta = 1$, the above bound is improved to
  \begin{align}
    70
    \frac{\Lmax^{1/2} \Mmax^{1/4} \Delta}{\epsilon^{7/4}}
    +
    2 (c_2 + 1) \frac{\Lmax^{1/2}}{M_0^{1/4} \epsilon^{1/4}}.
    \label{eq:complexity_bound_tight}
  \end{align}
\end{theorem}

