	Furthermore, for any \( \bm{w} \) satisfying \( \| \bm{w} \| \leq  1\), it holds that \( \left\langle \bm{\zeta}, \bm{w} \right\rangle \geq -1 \), with the equality holding if and only if \( \bm{w} = \overline{\bm{\zeta}} \).
  \end{lemma}
}

\begin{proposition}[Proper nontrivial exposed faces of \( \gK \)]\label{prop:facial-stru-gK}
		Let \( \bm{z} = (\bbz,\tbz)\in \bd\dgK\backslash\{\bm{0}\} \).
