\end{equation}


The definition of strong SOSC for NLSDP, which demands the supremum of \eqref{eq:defssosc} over $Y\in{\cal M}(\bar{x})$ holds, is originally given by \cite{Sun06} as an analogue for Robinson \cite{Robin80} for the nonlinear programming (NLP). However, the strong SOSC mentioned here is slightly different in only requiring the validity of \eqref{eq:defssosc} at $\overline{Y}$. It is worth to note when ${\cal M}(\bar{x})$ is a singleton, both of them are the same.
\begin{definition}\label{def:sigt}\cite[Definition 3.2]{Sun06}
	Let $\bar{x}$ be a stationary point of NLSDP \eqref{eq:NLSDP} and $\overline{Y}\in{\cal M}(\bar{x})$. We say the strong second order sufficient condition (SOSC) holds at $(\bar{x},\overline{Y})$ if
	\begin{equation}\label{eq:defssosc}
		\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle-\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)>0\quad\forall\; 0\neq G'(\bar{x})d\in{\rm aff}\,{\cal C}_{\mathbb{S}_+^n}(G(\bar{x}),\overline{Y}).
	\end{equation}
	where $\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)=2\langle\overline{Y},(G'(\bar{x}){d})G(\bar{x})^{\dagger}(G'(\bar{x}){d})\rangle$ is the $\sigma$-term and $G(\bar{x})^{\dagger}$ is the generalized inverse matrix of $G(\bar{x})$.
\end{definition}

Suppose $A=G(\bar{x})+\overline{Y}$ possesses the decomposition \eqref{eq:eig-decomp}. From \cite[page 386]{CSun08}, we know the $\sigma$-term takes the explicit form of
\begin{equation}\label{eq:sigtsdp}
	\varUpsilon_{G(\bar{x})}\big(\overline{Y},H\big)=2\sum_{i\in\alpha,j\in\gamma}\frac{\lambda_j(A)}{\lambda_i(A)}(\widetilde{H}_{ij})^2,
\end{equation}
where $\widetilde{H}=P^THP$.


Next, we introduce some essential notation for our main result. The (second order) generalized differentiability  of the augmented Lagrangian function ${\cal L}_{\rho}$ defined by \eqref{eq:deflag} for NLSDP \eqref{eq:NLSDP} has been explicitly established in \cite{SSZhang08}.  In fact, it is well-known that ${\cal L}_{\rho}$ is continuously differentiable with
\begin{equation}\label{eq:algrad}
	({\cal L}_{\rho})_x'(x,Y)=f'(x)+\rho G'(x)^*\Pi_{\mathbb{S}_-^n}(G(x)+\rho^{-1}Y),
\end{equation}
where $\Pi_{\mathbb{S}_-^n}(\cdot)$ is the metric projection over $\mathbb{S}_{-}^n$ and $G'(x)^*$ denotes the adjoint of the corresponding linear mapping. Moreover, since $({\cal L}_{\rho})_x'$ is  Lipschitz continuous, by using Rademacher’s theorem, the B(ouligand)-subdifferential of $({\cal L}_{\rho})_x'$ at $(x,Y)$ is given by
\begin{equation}\label{eq:partb}
	\partial_B\big(({\cal L}_{\rho})'_x\big)(x,Y):=\{\lim_{k\rightarrow\infty}(({\cal L}_{\rho})_{x}')'(x^k,Y^k)\mid (x^k,Y^k)\in{\cal U},\ (x^k,Y^k)\rightarrow(x,Y)\},
\end{equation}
where ${\cal U}$ is the set of Fr\'{e}chet-differentiable points of $({\cal L}_{\rho})_x'$.
It follows from \cite[(18)]{SSZhang08} (using \cite[Lemma 2 and 3]{SSZhang08}) that
\begin{align*}
	&\pi_x\partial_B\big(({\cal L}_{\rho})_x'\big)(x,Y)(\Delta x)\\
	&=L_{xx}''(x,\rho\Pi_{\mathbb{S}_-^n}(G(x)+\rho^{-1}Y))(\Delta x)+\rho G'({x})^*\partial_B\Pi_{\mathbb{S}_-^n}(G({x})+\rho^{-1}Y) G'({x})(\Delta x),
\end{align*}
where $\pi_x\partial_B\big(({\cal L}_{\rho})_x'\big)(x,Y)$ is the projection of $\partial_B\big(({\cal L}_{\rho})_x'\big)(x,Y)$ onto the space $\mathbb{X}$ and  $\partial_B\Pi_{\mathbb{S}_-^n}(G({x})+\rho^{-1}Y)$ is the B-subdifferential of $\Pi_{\mathbb{S}_-^n}(\cdot)$ at $G({x})+\rho^{-1}Y$. Actually, the set $\pi_x\partial_B\big(({\cal L}_{\rho})_x'\big)(x,Y)$ is recently defined as the $x$ part of the Hessian bundle \cite[(3.1)]{Roh22} for the augmented Lagrangian function ${\cal L}_{\rho}$ at $(x,Y)$ (see \cite[(3.6)]{Roh22} for detail).



Let $\bar{x}$ be the stationary point of \eqref{eq:NLSDP}. For each $\overline{Y}\in{\cal M}(\bar{x})$ and $W\in\partial_B\Pi_{\mathbb{S}_-^n}(G(\bar{x})+\rho^{-1}\overline{Y})$, define the following mapping
\begin{equation}\label{eq:algrad2}
	{\cal A}_{\rho}(\overline{Y},W):=L_{xx}''(\bar{x},\overline{Y})+\rho G'(\bar{x})^*WG'(\bar{x}).
\end{equation}
Let $\overline{Z}=G(\bar{x})+\overline{Y}$ possesses decomposition \eqref{eq:eig-decomp} with $\overline{P}\in{\cal O}^{n}(\overline{Z})$. It follows from \cite[Lemma 5]{SSZhang08} that $W\in\partial_B\Pi_{\mathbb{S}_-^n}(\overline{Z})$ if and only if there exists $W_0\in\partial_B\Pi_{\mathbb{S}_-^{\lvert\beta\rvert}}(0)$ such that for all $H\in\mathbb{S}^n$
{\footnotesize
\begin{equation*}
	W(H)=\overline{P}\left[\begin{array}{ccc}
		0 & 0 & \Sigma_{\alpha\gamma}\circ\overline{P}_{\alpha}^TH\overline{P}_{\gamma}\\
		0 & W_0(\overline{P}_{\beta}^TH\overline{P}_{\beta}) & \overline{P}_{\beta}^TH\overline{P}_{\gamma} \\
		\Sigma_{\gamma\alpha}\circ\overline{P}_{\gamma}^TH\overline{P}_{\alpha} & \overline{P}_{\gamma}^TH\overline{P}_{\beta} & \overline{P}_{\gamma}^TH\overline{P}_{\gamma}
	\end{array}\right]\overline{P}^T,
\end{equation*}}
where
\begin{equation*}
\begin{cases}		\Sigma_{ij}=1-\frac{\max\{\lambda_i,0\}+\max\{\lambda_j,0\}}{\lvert\lambda_i\rvert+\lvert\lambda_j\rvert}, & (i,j)\notin\beta\times\beta\\
\Sigma_{ij}	\in[0,1] & (i,j)\in\beta\times\beta
	\end{cases}
\end{equation*}
with $\lambda_i:=\lambda_i(\overline{Z})$ for short. Let ${\cal Q}^n$ denote the set of $n$-dimensional orthogonal matrix.
Also, $W_0\in\partial_B\Pi_{\mathbb{S}_-^{\lvert\beta\rvert}}(0)$ if and only if there exist $Q\in{\cal Q}^{\lvert\beta\rvert}$ and $\Omega\in\mathbb{S}^{\lvert\beta\rvert}$ with entries $\Omega_{ij}\in[0,1]$ such that for all $H\in\mathbb{S}^{\lvert\beta\rvert}$,
$$W_0(H)=Q(\Omega\circ(Q^THQ))Q^T.$$
By \cite[Lemma 9]{SSZhang08}, we have
{\small \begin{align}
	\langle d,{\cal A}_{\rho}(\overline{Y},W)d\rangle=&\langle d,L_{xx}''(\bar{x},\overline{Y})d\rangle+\rho\sum_{i,j\in\gamma}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2+2\rho\sum_{i\in\beta,j\in\gamma}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\label{eq:expcalA}\\
	&+2\rho\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j}{\rho\lambda_i-\lambda_j}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2+\rho\sum_{i,j\in\beta}(\Omega_{\rho})_{ij}({P}^T(G'(\bar{x})d){P})_{ij}^2,\nonumber
\end{align}}
where $\Omega_{\rho}\in\mathbb{S}^{\lvert\beta\rvert}$ with entries $(\Omega_{\rho})_{ij}\in[0,1]$, $P=[\overline{P}_{\alpha}\;\overline{P}_{\beta}Q\;\overline{P}_{\gamma}]$ with $Q\in{\cal Q}^{\lvert\beta\rvert}$.


The definition of (strong) variational sufficient condition is given in \cite{Roh22}  for general composite optimization problem \eqref{eq:genp}.
We can recast \eqref{eq:genp} in the form
\begin{equation}\label{eq:pgpert}
	\min\;\phi(x,u)\;\mbox{subject to}\;u=0,\quad\mbox{where}\;\phi(x,u)=f(x)+\theta(G(x)+u).
\end{equation}
The first order local optimality condition for \eqref{eq:genp}  of $\bar{x}$ is the existence of $\overline{Y}$ such that
$$L_x'(\bar{x},\overline{Y})=0\quad \mbox{with}\quad\overline{Y}\in\partial\, \theta(G(\bar{x})). $$
Define
\begin{equation}\label{eq:phir}
\phi_r:=\phi(x,u)+\frac{r}{2}|u|^2.
\end{equation}
The variational (strong) convexity, which is firstly proposed in \cite{rock247}, refers to the existence of open convex neighborhoods ${\cal W}$ of $(\bar{x},0)$ and ${\cal Z}$ of $(0,\overline{Y})$ such that there exists a proper closed (strongly) convex function $\psi\leq\phi_r2$ on ${\cal W}$ such that
\begin{equation*}
	({\cal W}\times{\cal Z})\cap{\rm gph}\,\partial\psi=({\cal W}\times{\cal Z})\cap{\rm gph}\,\partial\phi_r
\end{equation*}
and for $(x,u;v,y)$ belonging to this common set, $\psi(x,u)=\phi_r(x,u)$.
\begin{definition}\label{def:svasc}\cite{Roh22}
	The (strong) variational sufficient condition for local optimality in \eqref{eq:pgpert} holds with respect to $\bar{x}$ and $\overline{Y}$ satisfying the first order condition if there exists $r>0$ such that $\displaystyle\phi_r(x,u)$ is variationally (strongly) convex with respect to the pair $\big((\bar{x},0),(0,\overline{Y})\big)$ in ${\rm gph}\,\partial\phi_r$.
\end{definition}


To characterize the above property, the tools of the second subderivative and generalized quadratic form are needed.
\begin{definition}\cite[Definition 13.6]{RoWe98}
	Let $\bar{x}$ be a point where the function $f:\mathbb{X}\rightarrow[-\infty,+\infty]$ is finite. $f$ is twice epi-differentiable at $\bar{x}$ for $v$ if the functions
	$$\Delta^2_{t}f(\bar{x}\mid v)(u)=\frac{f(\bar{x}+tu)-f(\bar{x})-t\langle v,u\rangle}{\frac{1}{2}t^2}$$
	epi-converge to $d^2f(\bar{x}\mid v)$ as $t\downarrow0$, where $d^2f(\bar{x}\mid v)$ is the second subderivative of $f$ at $\bar{x}$ for $v$ defined as
	$$d^2f(\bar{x}\mid v)(w)=\liminf_{t\downarrow0,u\rightarrow w}\Delta^2_{t}f(\bar{x}\mid v)(u)$$
\end{definition}
We know from \cite[Theorem 3.6]{mohammadi20} that $\delta_{\mathbb{S}_+^n}$ is twice epi-differentiable at $X$ for $Y$ with $Y\in{\cal N}_{\mathbb{S}_+^n}(X)$.

\begin{definition}\label{def:genguadf} \cite{Roh22}
	A generalized linear mapping ${\cal R}$ from $\mathbb{X}$ to $\mathbb{Y}$, is a set-valued mapping for which ${\rm gph}\,{\cal R}$ is a subspace of $\mathbb{X}\times\mathbb{Y}$. This means that ${\rm dom}{\cal R}$ is a subspace $\mathbb{Z}$ of $\mathbb{X}$, ${\cal R}(0)$ is a subspace $\mathbb{Z}'$ of $\mathbb{Y}$, and there is an ordinary linear mapping ${\cal R}_0:\mathbb{Z}\rightarrow\mathbb{Y}$ such that ${\cal R}(x)={\cal R}_0(x)+\mathbb{Z}'$ for $x\in\mathbb{Z}$.
	We call a function $q: \mathbb{X}\rightarrow(-\infty,+\infty]$ is a generalized quadratic form on $\mathbb{X}$ if $q(0)=0$ and the subgradient mapping $\partial q:\mathbb{X}\rightrightarrows\mathbb{X}$ is generalized linear. A function $g$ on $\mathbb{X}$ will be called generalized twice differentiable at $x$ for a subgradient $y$ if it is twice epi-differentiable at $x$ for $y$ with the second-order subderivative $d^2g(x\mid y)$ being a generalized quadratic form.
\end{definition}


The following definition of the quadratic bundle is taken from \cite{Roh22}, which is essential in characterizing the strong variational sufficiency.
\begin{definition}\label{def:quadratic bundle}
	For general optimization problem \eqref{eq:genp}, suppose $(\bar{x},\overline{Y})$ is a KKT pair. The quadratic bundle of $\theta$ is defined as
	\begin{equation*}
		{\rm quad}\,\theta(G(\bar{x})\mid\overline{Y})=\left\{
		\begin{array}{l}
			\mbox{the collection of generalized quadratic forms}\; q\; \mbox{for which}\\
			\exists(X^k,Y^k)\rightarrow(G(\bar{x}),\overline{Y})\;\mbox{with}\;\theta\;\mbox{generalized twice differentiable}\\
			\mbox{at}\;X^k\;\mbox{for}\;Y^k\;\mbox{and such that the generalized quadratic}\\
			\mbox{forms}\;q_k=\frac{1}{2}d^2\theta(X^k\mid Y^k)\;\mbox{converge epigraphically to}\;q.
		\end{array}
		\right.
	\end{equation*}
\end{definition}
As mentioned in \cite{Roh22}, the variational sufficient condition guarantees the local optimality for \eqref{eq:pgpert}. The following result is taken from \cite[Theorem 5]{Roh22}, which is useful for the subsequent analysis.
\begin{proposition}\label{prop:thm5}
	For general optimization problem \eqref{eq:genp},
	strong variational sufficient condition for local optimality with respect to $(\bar{x},\overline{Y})$ is equivalent to that  every $q\in{\rm quad}\,\theta(G(\bar{x})\mid\overline{Y})$ has
	\begin{equation}\label{svs-equ}
		\frac{1}{2}\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle+q(G'(\bar{x}){d})>0\quad{\rm when}\;d\neq0,
	\end{equation}
	where ${\rm quad}\,\theta(G(\bar{x})\mid\overline{Y})$ is the quadratic bundle of $\theta$.
\end{proposition}

