The definition of (strong) variational sufficient condition (Definition \ref{def:svasc}) is officially given in \cite{Roh22}  for the following general composite optimization problem
\begin{equation}\label{eq:genp}
	\min_{x\in \mathbb{X}}\quad f(x)+\theta(G(x)),
\end{equation}
where $\mathbb{X}$ and $\mathbb{Y}$ are two given Euclidean spaces, $f:\mathbb{X}\to \mathbb{R}$ and $G:\mathbb{X}\to \mathbb{Y}$ are twice continuously differentiable, and $\theta:\mathbb{Y}\to (-\infty,\infty]$ is a closed proper convex function. The strong variational sufficient condition is firstly introduced to deal with the local convexity of primal augmented Lagrangian function and the augmented tilt stability. It has gained more and more attention for its mathematical elegance and wide applications in the convergence analysis of multiplier methods. Several characterizations of this abstract property are also given in \cite{Roh22}. For instance, it is equivalent to the positive definiteness of the Hessian bundle of the augmented Lagrangian function \cite[Theorem 3]{Roh22} or the criterion \cite[Theorem 5]{Roh22} involving quadratic bundle (Definition \ref{def:quadratic bundle}).

\begin{equation}\label{eq:NLSDPc}
	\begin{array}{cl}
		\displaystyle{\min_{x\in \mathbb{X}}} & f(x) \\ [3pt]
		{\rm s.t.} &{G(x)\in \mathbb{S}^n_+},
	\end{array}
\end{equation}
where  $\mathbb{S}^n$ is the linear space of all $n\times n$ real symmetric matrices equipped with the usual Frobenius inner product and its induced norm, $\mathbb{S}_+^n$ ($\mathbb{S}_-^n$) is the closed convex cone of all $n\times n$ positive (negative) semidefinite matrices in $\mathbb{S}^n$. One of our contributions lies in uncovering the equivalence between strong variational sufficient condition and strong SOSC (see Definition \ref{def:sigt} for details) for  NLSDP problems without requiring any other constraint qualifications.

For NLSDP \eqref{eq:NLSDPc}, the Lagrangian function is defined by
\begin{equation}\label{eq:L-function}
	L(x,Y):=f(x) +\langle Y,G(x)\rangle, \quad (x,Y)\in\mathbb{X}\times\mathbb{S}^n.
\end{equation}
For any $Y\in\mathbb{S}^n$, denote the first-order and second-order derivatives of $L(\cdot,Y)$ at $x\in\mathbb{X}$ by $L_x'(x,Y)$ and $L_{xx}''(x,Y)$, respectively. Given $\rho > 0$, the augmented Lagrangian function of \eqref{eq:NLSDPc} takes the following form (cf. \cite[Section 11.K]{RoWe98} and \cite{ShapS04})

\begin{equation}\label{eq:deflag}
	\mathcal{L}_{\rho}(x,Y):=f(x)+\frac{\rho}{2}{\rm dist}^2(G(x)+\frac{Y}{\rho},\mathbb{S}_+^n)-\frac{\|Y\|^2}{2\rho},
\end{equation}
where ${\rm dist}(z,\mathbb{S}_+^n)$ is the distance from point $z$ to $\mathbb{S}_+^n$.

\begin{definition}
	Consider a function $f:\mathbb{X}\rightarrow(-\infty, +\infty]$ and a point $\bar{x}$ with $f(\bar{x})$ finite. The proximal subdifferential of $f$ at $\bar{x}$ is defined as
	$$\partial^{\pi}f(\bar{x}):=\{{d}\mid \exists\; l>0, r>0\;{\rm such\; that}\;f(x)\geq f(\bar{x})+\langle{d},{x}-\bar{x}\rangle-l\|{x}-\bar{x}\|^2\;\forall\,{x}\in{\cal B}_{r}(\bar{x})\},$$
	where ${\cal B}_{r}(\bar{x})$ is the ball centered at $\bar{x}$ with radius $r$.
	The (general/Mordukhovich limiting) subdifferential of $f$ at $\bar{x}$ is $\partial f(\bar{x}):=\limsup\limits_{{x}\stackrel{f}{\rightarrow}\bar{x}}\partial^{\pi}f({x})$, where ${x}\stackrel{f}{\rightarrow}\bar{x}$ signifies ${x}\rightarrow\bar{x}$ with $f({x})\rightarrow f(\bar{x})$.
\end{definition}

Let  $A \in\mathbb{S}^n$ be given. We use $\lambda_{1}(A)\ge \lambda_2(A) \ge \ldots \ge \lambda_{n}(A)$ to denote the eigenvalues of $A$ (all real and counting multiplicity) arranging in  nonincreasing order and use $\lambda(A)$ to denote the vector of the ordered eigenvalues of $A$. Let $\Lambda(A):= {\rm Diag}(\lambda(A))$. Also, we use $v_1(A)> \dots> v_d(A)$ to denote the different eigenvalues and
$\zeta_l:=\{i\mid \lambda_i(A)=v_l(A)\}$.
Consider the eigenvalue decomposition of $A$, i.e., $A={P} \Lambda(A){P}^{T}$, where ${P}\in{\cal O}^{n}(A)$ is a corresponding
orthogonal matrix of the orthonormal eigenvectors.
By considering the index sets of positive, zero, and negative eigenvalues of $A$, we are able to write $A$ in the following form
{\footnotesize
\begin{equation}\label{eq:eig-decomp}
	A= \left[\begin{array}{ccc}
		{P}_{\alpha} & {P}_{\beta} & {P}_{\gamma}
	\end{array}\right] \left[\begin{array}{ccc}
		\Lambda(A)_{\alpha\alpha} & 0 & 0 \\ [3pt]
		0 & 0 & 0\\ [3pt]
		0 & 0 & \Lambda(A)_{\gamma\gamma}
	\end{array}\right]\left[\begin{array}{c}
		{P}_{\alpha}^T \\ [3pt]
		{P}_{\beta}^T \\
		{P}_{\gamma}^T
	\end{array}\right],
\end{equation}}
where $\alpha:=\{i: \lambda_i(A)>0\}$, $\beta:=\{i: \lambda_i(A)=0\}$ and $\gamma:=\{i: \lambda_i(A)<0\}$.

The critical cone of $\mathbb{S}_+^n$ at ${Y}\in{\cal N}_{\mathbb{S}_+^n}({X})$ with $A=X+Y$ is given by (cf. \cite[equations (11) and (12)]{CSun08})
\begin{equation}\label{eq:cricsdp}
	{\cal C}_{\mathbb{S}_+^n}({X},{Y})=\{H\in\mathbb{S}^n\mid P^T_{\beta}HP_{\beta}\in\mathbb{S}^{|\beta|}_+,\;P^T_{\beta}HP_{\gamma}=0,\;P^T_{\gamma}HP_{\gamma}=0\}
\end{equation}

and the affine hull of ${\cal C}_{\mathbb{S}_+^n}({X},{Y})$ is
\begin{equation}\label{eq:affcsdp}
	{\rm aff}\,{\cal C}_{\mathbb{S}_+^n}({X},{Y})=\{H\in\mathbb{S}^n\mid P^T_{\beta}HP_{\gamma}=0,\;P^T_{\gamma}HP_{\gamma}=0\}.
\end{equation}

The  NLSDP \eqref{eq:NLSDPc} can be written in the following form
\begin{eqnarray}
	%\mbox{(SDP)}~~~~
	\min\quad && f(x)+\delta_{\mathbb{S}^n_+}(G(x)), \label{eq:NLSDP}
\end{eqnarray}
where
$\delta_{\mathbb{S}^n_+} : \mathbb{S}^n\rightarrow (-\infty,\infty]$ is the indicator function of positive semidefinite cone $\mathbb{S}^n_+$.

Denote ${S}_{KKT}(a,b)$ the solution set of the KKT optimality condition for problem \eqref{eq:NLSDP}, i.e.,
\begin{equation}\label{eq:KKT-NLSDP-p1}
	{S}_{KKT}(a,b)=\left\{(x,Y)\in \mathbb{X}\times\mathbb{S}^n \Bigg | \left.
	\begin{array}{l}
		L_x'(x,Y)-a=0,\\ [3pt]
		\mathbb{S}_+^n\ni (G(x)-b)\perp Y \in \mathbb{S}_-^n.
	\end{array}
	\right.\right \}.
\end{equation}
For any KKT pair $(\bar{x},\overline{Y})$ that satisfies the KKT condition with $(a,b) = (0,0)$, we call $\bar{x}$ a stationary point.

Suppose $\bar{x}$ is a stationary point. Define ${\cal M}(\bar{x})$ as the set of all multipliers $Y\in\mathbb{S}^n$ satisfying the KKT condition \eqref{eq:KKT-NLSDP-p1}, i.e.,
\begin{equation}\label{eq:defcalm}
	{\cal M}(\bar{x})=\{Y\in\mathbb{S}^n \mid (\bar{x},Y)\in {S}_{KKT}(0,0)\}.
\end{equation}

\begin{definition}\label{def:sigt}\cite[Definition 3.2]{Sun06}
	Let $\bar{x}$ be a stationary point of NLSDP \eqref{eq:NLSDP} and $\overline{Y}\in{\cal M}(\bar{x})$. We say the strong second order sufficient condition (SOSC) holds at $(\bar{x},\overline{Y})$ if
	\begin{equation}\label{eq:defssosc}
		\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle-\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)>0\quad\forall\; 0\neq G'(\bar{x})d\in{\rm aff}\,{\cal C}_{\mathbb{S}_+^n}(G(\bar{x}),\overline{Y}).
	\end{equation}
	where $\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)=2\langle\overline{Y},(G'(\bar{x}){d})G(\bar{x})^{\dagger}(G'(\bar{x}){d})\rangle$ is the $\sigma$-term and $G(\bar{x})^{\dagger}$ is the generalized inverse matrix of $G(\bar{x})$.
\end{definition}

Suppose $A=G(\bar{x})+\overline{Y}$ possesses the decomposition \eqref{eq:eig-decomp}. From \cite[page 386]{CSun08}, we know the $\sigma$-term takes the explicit form of
\begin{equation}\label{eq:sigtsdp}
	\varUpsilon_{G(\bar{x})}\big(\overline{Y},H\big)=2\sum_{i\in\alpha,j\in\gamma}\frac{\lambda_j(A)}{\lambda_i(A)}(\widetilde{H}_{ij})^2,
\end{equation}
where $\widetilde{H}=P^THP$.

Next, we introduce some essential notation for our main result. The (second order) generalized differentiability  of the augmented Lagrangian function ${\cal L}_{\rho}$ defined by \eqref{eq:deflag} for NLSDP \eqref{eq:NLSDP} has been explicitly established in \cite{SSZhang08}.  In fact, it is well-known that ${\cal L}_{\rho}$ is continuously differentiable with
\begin{equation}\label{eq:algrad}
	({\cal L}_{\rho})_x'(x,Y)=f'(x)+\rho G'(x)^*\Pi_{\mathbb{S}_-^n}(G(x)+\rho^{-1}Y),
\end{equation}
where $\Pi_{\mathbb{S}_-^n}(\cdot)$ is the metric projection over $\mathbb{S}_{-}^n$ and $G'(x)^*$ denotes the adjoint of the corresponding linear mapping. Moreover, since $({\cal L}_{\rho})_x'$ is  Lipschitz continuous, by using Rademacher’s theorem, the B(ouligand)-subdifferential of $({\cal L}_{\rho})_x'$ at $(x,Y)$ is given by

where $\Pi_{\mathbb{S}_-^n}(\cdot)$ is the metric projection over $\mathbb{S}_{-}^n$ and $G'(x)^*$ denotes the adjoint of the corresponding linear mapping. Moreover, since $({\cal L}_{\rho})_x'$ is  Lipschitz continuous, by using Rademacher’s theorem, the B(ouligand)-subdifferential of $({\cal L}_{\rho})_x'$ at $(x,Y)$ is given by
\begin{equation}\label{eq:partb}
	\partial_B\big(({\cal L}_{\rho})'_x\big)(x,Y):=\{\lim_{k\rightarrow\infty}(({\cal L}_{\rho})_{x}')'(x^k,Y^k)\mid (x^k,Y^k)\in{\cal U},\ (x^k,Y^k)\rightarrow(x,Y)\},
\end{equation}
where ${\cal U}$ is the set of Fr\'{e}chet-differentiable points of $({\cal L}_{\rho})_x'$.

It follows from \cite[(18)]{SSZhang08} (using \cite[Lemma 2 and 3]{SSZhang08}) that
\begin{align*}
	&\pi_x\partial_B\big(({\cal L}_{\rho})_x'\big)(x,Y)(\Delta x)\\
	&=L_{xx}''(x,\rho\Pi_{\mathbb{S}_-^n}(G(x)+\rho^{-1}Y))(\Delta x)+\rho G'({x})^*\partial_B\Pi_{\mathbb{S}_-^n}(G({x})+\rho^{-1}Y) G'({x})(\Delta x),
\end{align*}
where $\pi_x\partial_B\big(({\cal L}_{\rho})_x'\big)(x,Y)$ is the projection of $\partial_B\big(({\cal L}_{\rho})_x'\big)(x,Y)$ onto the space $\mathbb{X}$ and  $\partial_B\Pi_{\mathbb{S}_-^n}(G({x})+\rho^{-1}Y)$ is the B-subdifferential of $\Pi_{\mathbb{S}_-^n}(\cdot)$ at $G({x})+\rho^{-1}Y$. Actually, the set $\pi_x\partial_B\big(({\cal L}_{\rho})_x'\big)(x,Y)$ is recently defined as the $x$ part of the Hessian bundle \cite[(3.1)]{Roh22} for the augmented Lagrangian function ${\cal L}_{\rho}$ at $(x,Y)$ (see \cite[(3.6)]{Roh22} for detail).

Let $\bar{x}$ be the stationary point of \eqref{eq:NLSDP}. For each $\overline{Y}\in{\cal M}(\bar{x})$ and $W\in\partial_B\Pi_{\mathbb{S}_-^n}(G(\bar{x})+\rho^{-1}\overline{Y})$, define the following mapping
\begin{equation}\label{eq:algrad2}
	{\cal A}_{\rho}(\overline{Y},W):=L_{xx}''(\bar{x},\overline{Y})+\rho G'(\bar{x})^*WG'(\bar{x}).
\end{equation}

Let $\overline{Z}=G(\bar{x})+\overline{Y}$ possesses decomposition \eqref{eq:eig-decomp} with $\overline{P}\in{\cal O}^{n}(\overline{Z})$. It follows from \cite[Lemma 5]{SSZhang08} that $W\in\partial_B\Pi_{\mathbb{S}_-^n}(\overline{Z})$ if and only if there exists $W_0\in\partial_B\Pi_{\mathbb{S}_-^{\lvert\beta\rvert}}(0)$ such that for all $H\in\mathbb{S}^n$
{\footnotesize
\begin{equation*}
	W(H)=\overline{P}\left[\begin{array}{ccc}
		0 & 0 & \Sigma_{\alpha\gamma}\circ\overline{P}_{\alpha}^TH\overline{P}_{\gamma}\\
		0 & W_0(\overline{P}_{\beta}^TH\overline{P}_{\beta}) & \overline{P}_{\beta}^TH\overline{P}_{\gamma} \\
		\Sigma_{\gamma\alpha}\circ\overline{P}_{\gamma}^TH\overline{P}_{\alpha} & \overline{P}_{\gamma}^TH\overline{P}_{\beta} & \overline{P}_{\gamma}^TH\overline{P}_{\gamma}
	\end{array}\right]\overline{P}^T,
\end{equation*}}
where
\begin{equation*}
\begin{cases}		\Sigma_{ij}=1-\frac{\max\{\lambda_i,0\}+\max\{\lambda_j,0\}}{\lvert\lambda_i\rvert+\lvert\lambda_j\rvert}, & (i,j)\notin\beta\times\beta\\
\Sigma_{ij}	\in[0,1] & (i,j)\in\beta\times\beta
	\end{cases}
\end{equation*}
with $\lambda_i:=\lambda_i(\overline{Z})$ for short. Let ${\cal Q}^n$ denote the set of $n$-dimensional orthogonal matrix.

By \cite[Lemma 9]{SSZhang08}, we have
{\small \begin{align}
	\langle d,{\cal A}_{\rho}(\overline{Y},W)d\rangle=&\langle d,L_{xx}''(\bar{x},\overline{Y})d\rangle+\rho\sum_{i,j\in\gamma}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2+2\rho\sum_{i\in\beta,j\in\gamma}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\label{eq:expcalA}\\
	&+2\rho\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j}{\rho\lambda_i-\lambda_j}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2+\rho\sum_{i,j\in\beta}(\Omega_{\rho})_{ij}({P}^T(G'(\bar{x})d){P})_{ij}^2,\nonumber
\end{align}}
where $\Omega_{\rho}\in\mathbb{S}^{\lvert\beta\rvert}$ with entries $(\Omega_{\rho})_{ij}\in[0,1]$, $P=[\overline{P}_{\alpha}\;\overline{P}_{\beta}Q\;\overline{P}_{\gamma}]$ with $Q\in{\cal Q}^{\lvert\beta\rvert}$.

Define
\begin{equation}\label{eq:phir}
\phi_r:=\phi(x,u)+\frac{r}{2}|u|^2.
\end{equation}
The variational (strong) convexity, which is firstly proposed in \cite{rock247}, refers to the existence of open convex neighborhoods ${\cal W}$ of $(\bar{x},0)$ and ${\cal Z}$ of $(0,\overline{Y})$ such that there exists a proper closed (strongly) convex function $\psi\leq\phi_r2$ on ${\cal W}$ such that
\begin{equation*}
	({\cal W}\times{\cal Z})\cap{\rm gph}\,\partial\psi=({\cal W}\times{\cal Z})\cap{\rm gph}\,\partial\phi_r
\end{equation*}
and for $(x,u;v,y)$ belonging to this common set, $\psi(x,u)=\phi_r(x,u)$.

\begin{definition}\label{def:svasc}\cite{Roh22}
	The (strong) variational sufficient condition for local optimality in \eqref{eq:pgpert} holds with respect to $\bar{x}$ and $\overline{Y}$ satisfying the first order condition if there exists $r>0$ such that $\displaystyle\phi_r(x,u)$ is variationally (strongly) convex with respect to the pair $\big((\bar{x},0),(0,\overline{Y})\big)$ in ${\rm gph}\,\partial\phi_r$.
\end{definition}

\begin{definition}\label{def:genguadf} \cite{Roh22}
	A generalized linear mapping ${\cal R}$ from $\mathbb{X}$ to $\mathbb{Y}$, is a set-valued mapping for which ${\rm gph}\,{\cal R}$ is a subspace of $\mathbb{X}\times\mathbb{Y}$. This means that ${\rm dom}{\cal R}$ is a subspace $\mathbb{Z}$ of $\mathbb{X}$, ${\cal R}(0)$ is a subspace $\mathbb{Z}'$ of $\mathbb{Y}$, and there is an ordinary linear mapping ${\cal R}_0:\mathbb{Z}\rightarrow\mathbb{Y}$ such that ${\cal R}(x)={\cal R}_0(x)+\mathbb{Z}'$ for $x\in\mathbb{Z}$.
	We call a function $q: \mathbb{X}\rightarrow(-\infty,+\infty]$ is a generalized quadratic form on $\mathbb{X}$ if $q(0)=0$ and the subgradient mapping $\partial q:\mathbb{X}\rightrightarrows\mathbb{X}$ is generalized linear. A function $g$ on $\mathbb{X}$ will be called generalized twice differentiable at $x$ for a subgradient $y$ if it is twice epi-differentiable at $x$ for $y$ with the second-order subderivative $d^2g(x\mid y)$ being a generalized quadratic form.
\end{definition}

The following definition of the quadratic bundle is taken from \cite{Roh22}, which is essential in characterizing the strong variational sufficiency.
\begin{definition}\label{def:quadratic bundle}
	For general optimization problem \eqref{eq:genp}, suppose $(\bar{x},\overline{Y})$ is a KKT pair. The quadratic bundle of $\theta$ is defined as
	\begin{equation*}
		{\rm quad}\,\theta(G(\bar{x})\mid\overline{Y})=\left\{
		\begin{array}{l}
			\mbox{the collection of generalized quadratic forms}\; q\; \mbox{for which}\\
			\exists(X^k,Y^k)\rightarrow(G(\bar{x}),\overline{Y})\;\mbox{with}\;\theta\;\mbox{generalized twice differentiable}\\
			\mbox{at}\;X^k\;\mbox{for}\;Y^k\;\mbox{and such that the generalized quadratic}\\
			\mbox{forms}\;q_k=\frac{1}{2}d^2\theta(X^k\mid Y^k)\;\mbox{converge epigraphically to}\;q.
		\end{array}
		\right.
	\end{equation*}
\end{definition}

As mentioned in \cite{Roh22}, the variational sufficient condition guarantees the local optimality for \eqref{eq:pgpert}. The following result is taken from \cite[Theorem 5]{Roh22}, which is useful for the subsequent analysis.
\begin{proposition}\label{prop:thm5}
	For general optimization problem \eqref{eq:genp},
	strong variational sufficient condition for local optimality with respect to $(\bar{x},\overline{Y})$ is equivalent to that  every $q\in{\rm quad}\,\theta(G(\bar{x})\mid\overline{Y})$ has
	\begin{equation}\label{svs-equ}
		\frac{1}{2}\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle+q(G'(\bar{x}){d})>0\quad{\rm when}\;d\neq0,
	\end{equation}
	where ${\rm quad}\,\theta(G(\bar{x})\mid\overline{Y})$ is the quadratic bundle of $\theta$.
\end{proposition}

\begin{proposition}\label{prop:onesidessosc}
	Let $\bar{x}\in\mathbb{X}$ be a stationary point to NLSDP \eqref{eq:NLSDP} and $\overline{Y}\in {\cal M}(\bar{x})$, where ${\cal M}(\bar{x})$ is given in \eqref{eq:defcalm}. Let $A=G(\bar{x})+\overline{Y}$, which possesses the decomposition \eqref{eq:eig-decomp}. Then, there exists $q\in {\rm quad}\,\delta_{\mathbb{S}_+^n}(G(\bar{x})\mid\overline{Y})$ such that for all $H\in\mathbb{S}^n$,
	\begin{align}
		q(H)&=-\frac{1}{2}\varUpsilon_{G(\bar{x})}\big(\overline{Y},H\big)+\delta_{{\rm aff}\,{\cal C}_{\mathbb{S}_+^n}(G(\bar{x}),\overline{Y})}(H)\nonumber\\
		&=\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j(A)}{\lambda_i(A)}(\widetilde{H}_{ij})^2+\delta_{{\rm aff}\,{\cal C}_{\mathbb{S}_+^n}(G(\bar{x}),\overline{Y})}(H),\label{eq:qeqsg}
	\end{align}
	where $\widetilde{H}=P^THP$.
\end{proposition}

\begin{theorem}\label{thm:varscequissosc}
	Let $\bar{x}\in\mathbb{X}$ be a stationary point to the NLSDP \eqref{eq:NLSDP} and $\overline{Y}\in {\cal M}(\bar{x})$. Then the following three conditions are equivalent
	\begin{itemize}
		\item[(i)] the strong variational sufficient condition with respect to $(\bar{x},\overline{Y})$ holds;
		\item[(ii)] the strong second order sufficient condition (SOSC) \eqref{eq:defssosc} holds at $(\bar{x},\overline{Y})$;
		\item[(iii)] there exist $\rho_0>0$ and $\underline{\eta}>0$ such that for any $\rho\geq \rho_0$ and any $W\in\partial_B\Pi_{\mathbb{S}_-^n}(G(\bar{x})+\rho^{-1}\overline{Y})$,
		\begin{equation*}\label{eq:psdofpb}
		\langle d, {\cal A}_{\rho}(\overline{Y},W)d\rangle\geq\underline{\eta}\|d\|^2\quad\forall d\in\mathbb{X},
		\end{equation*}
		where ${\cal A}_{\rho}(\overline{Y},W)$ is defined by \eqref{eq:algrad2}.
	\end{itemize}
\end{theorem}

\begin{proof}
	``$(i)\Longrightarrow(ii)$":  This direction can be obtained directly from Proposition \ref{prop:onesidessosc} and Proposition \ref{prop:thm5} as we only need to substitute \eqref{eq:qeqsg} into \eqref{svs-equ}.

	``$(ii)\Longrightarrow(iii)$": This proof sketch is similar to \cite[Proposition 4]{SSZhang08} although they require the validity of nondegeneracy, which is superfluous here.
	It follows from Definition \ref{eq:defssosc} that there exists $\eta_0>0$ such that
	$$\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle-\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)\geq\eta_0\|d\|^2\quad\forall\; G'(\bar{x})d\in{\rm aff}\,{\cal C}_{\mathbb{S}_+^n}(G(\bar{x}),\overline{Y}).$$
	By using \cite[Lemma 7]{SSZhang08}, there exist two positive numbers $\rho_1$ and $\underline{\eta}\in(0,\eta_0/2]$ such that for any $\rho'\geq \rho_1$,
	\begin{align*}
		&\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle-\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)\\
		&+\rho'\|\overline{P}^T_{\gamma}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2+\rho'\|\overline{P}^T_{\beta}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2\geq2\underline{\eta}\|d\|^2\quad \forall d\in\mathbb{X}.
	\end{align*}
	Suppose a sufficient large $\rho_0\geq\rho_1$. For any $\rho\geq\rho_0$ and $d\in{\cal X}$, we have
	{\small \begin{align*}
			&-\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)-2\rho\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j}{\rho\lambda_i-\lambda_j}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\\
			&=2\sum\limits_{i\in\alpha,\,j\in\gamma}\frac{-\lambda_j}{\lambda_i}(\overline{P}^T(G'(\bar{x}){d})\overline{P})_{ij}^2-2\rho\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j}{\rho\lambda_i-\lambda_j}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\\
			&=2\sum\limits_{i\in\alpha,\,j\in\gamma}\frac{\lambda_j^2}{\lambda_i(\rho\lambda_i-\lambda_j)}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\leq\underline{\eta}\|d\|^2,
	\end{align*}}
	where the last inequality can be obtained by sufficiently large $\rho$.
	Combining the above two relations together, we have for any $\rho\geq\rho_0$,  $\rho'\geq\rho_0\geq\rho_1$,
	\begin{align*}
		&\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle+2\rho\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j}{\rho\lambda_i-\lambda_j}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\\
		&+\rho'\|\overline{P}^T_{\gamma}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2+\rho'\|\overline{P}^T_{\beta}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2\geq\underline{\eta}\|d\|^2.
	\end{align*}
	Then it can be checked directly that for all $d\in\mathbb{X}$ and $\rho\geq\rho_0$,  $\langle d,{\cal A}_{\rho}(\overline{Y},W)d\rangle\geq\underline{\eta}\|d\|^2 $.



	``$(iii)\Longrightarrow(i)$": It follows directly from \cite[Theorem 3]{Roh22} as ${\cal A}_{\rho}(\overline{Y},W)$ coincides with \cite[(3.6)]{Roh22}.
\end{proof}

By using \cite[Lemma 7]{SSZhang08}, there exist two positive numbers $\rho_1$ and $\underline{\eta}\in(0,\eta_0/2]$ such that for any $\rho'\geq \rho_1$,
\begin{align*}
	&\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle-\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)\\
	&+\rho'\|\overline{P}^T_{\gamma}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2+\rho'\|\overline{P}^T_{\beta}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2\geq2\underline{\eta}\|d\|^2\quad \forall d\in\mathbb{X}.
\end{align*}

Combining the above two relations together, we have for any $\rho\geq\rho_0$,  $\rho'\geq\rho_0\geq\rho_1$,
\begin{align*}
	&\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle+2\rho\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j}{\rho\lambda_i-\lambda_j}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\\
	&+\rho'\|\overline{P}^T_{\gamma}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2+\rho'\|\overline{P}^T_{\beta}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2\geq\underline{\eta}\|d\|^2.
\end{align*}

The definition of (strong) variational sufficient condition (Definition \ref{def:svasc}) is officially given in \cite{Roh22}  for the following general composite optimization problem
\begin{equation}\label{eq:genp}
	\min_{x\in \mathbb{X}}\quad f(x)+\theta(G(x)),
\end{equation}
where $\mathbb{X}$ and $\mathbb{Y}$ are two given Euclidean spaces, $f:\mathbb{X}\to \mathbb{R}$ and $G:\mathbb{X}\to \mathbb{Y}$ are twice continuously differentiable, and $\theta:\mathbb{Y}\to (-\infty,\infty]$ is a closed proper convex function. The strong variational sufficient condition is firstly introduced to deal with the local convexity of primal augmented Lagrangian function and the augmented tilt stability. It has gained more and more attention for its mathematical elegance and wide applications in the convergence analysis of multiplier methods. Several characterizations of this abstract property are also given in \cite{Roh22}. For instance, it is equivalent to the positive definiteness of the Hessian bundle of the augmented Lagrangian function \cite[Theorem 3]{Roh22} or the criterion \cite[Theorem 5]{Roh22} involving quadratic bundle (Definition \ref{def:quadratic bundle}).

\begin{equation}\label{eq:NLSDPc}
	\begin{array}{cl}
		\displaystyle{\min_{x\in \mathbb{X}}} & f(x) \\ [3pt]
		{\rm s.t.} &{G(x)\in \mathbb{S}^n_+},
	\end{array}
\end{equation}
where  $\mathbb{S}^n$ is the linear space of all $n\times n$ real symmetric matrices equipped with the usual Frobenius inner product and its induced norm, $\mathbb{S}_+^n$ ($\mathbb{S}_-^n$) is the closed convex cone of all $n\times n$ positive (negative) semidefinite matrices in $\mathbb{S}^n$. One of our contributions lies in uncovering the equivalence between strong variational sufficient condition and strong SOSC (see Definition \ref{def:sigt} for details) for  NLSDP problems without requiring any other constraint qualifications.

For NLSDP \eqref{eq:NLSDPc}, the Lagrangian function is defined by
\begin{equation}\label{eq:L-function}
	L(x,Y):=f(x) +\langle Y,G(x)\rangle, \quad (x,Y)\in\mathbb{X}\times\mathbb{S}^n.
\end{equation}
For any $Y\in\mathbb{S}^n$, denote the first-order and second-order derivatives of $L(\cdot,Y)$ at $x\in\mathbb{X}$ by $L_x'(x,Y)$ and $L_{xx}''(x,Y)$, respectively. Given $\rho > 0$, the augmented Lagrangian function of \eqref{eq:NLSDPc} takes the following form (cf. \cite[Section 11.K]{RoWe98} and \cite{ShapS04})

\begin{equation}\label{eq:deflag}
	\mathcal{L}_{\rho}(x,Y):=f(x)+\frac{\rho}{2}{\rm dist}^2(G(x)+\frac{Y}{\rho},\mathbb{S}_+^n)-\frac{\|Y\|^2}{2\rho},
\end{equation}
where ${\rm dist}(z,\mathbb{S}_+^n)$ is the distance from point $z$ to $\mathbb{S}_+^n$.

\begin{definition}
	Consider a function $f:\mathbb{X}\rightarrow(-\infty, +\infty]$ and a point $\bar{x}$ with $f(\bar{x})$ finite. The proximal subdifferential of $f$ at $\bar{x}$ is defined as
	$$\partial^{\pi}f(\bar{x}):=\{{d}\mid \exists\; l>0, r>0\;{\rm such\; that}\;f(x)\geq f(\bar{x})+\langle{d},{x}-\bar{x}\rangle-l\|{x}-\bar{x}\|^2\;\forall\,{x}\in{\cal B}_{r}(\bar{x})\},$$
	where ${\cal B}_{r}(\bar{x})$ is the ball centered at $\bar{x}$ with radius $r$.
	The (general/Mordukhovich limiting) subdifferential of $f$ at $\bar{x}$ is $\partial f(\bar{x}):=\limsup\limits_{{x}\stackrel{f}{\rightarrow}\bar{x}}\partial^{\pi}f({x})$, where ${x}\stackrel{f}{\rightarrow}\bar{x}$ signifies ${x}\rightarrow\bar{x}$ with $f({x})\rightarrow f(\bar{x})$.
\end{definition}

Let  $A \in\mathbb{S}^n$ be given. We use $\lambda_{1}(A)\ge \lambda_2(A) \ge \ldots \ge \lambda_{n}(A)$ to denote the eigenvalues of $A$ (all real and counting multiplicity) arranging in  nonincreasing order and use $\lambda(A)$ to denote the vector of the ordered eigenvalues of $A$. Let $\Lambda(A):= {\rm Diag}(\lambda(A))$. Also, we use $v_1(A)> \dots> v_d(A)$ to denote the different eigenvalues and
$\zeta_l:=\{i\mid \lambda_i(A)=v_l(A)\}$.
Consider the eigenvalue decomposition of $A$, i.e., $A={P} \Lambda(A){P}^{T}$, where ${P}\in{\cal O}^{n}(A)$ is a corresponding
orthogonal matrix of the orthonormal eigenvectors.
By considering the index sets of positive, zero, and negative eigenvalues of $A$, we are able to write $A$ in the following form
{\footnotesize
\begin{equation}\label{eq:eig-decomp}
	A= \left[\begin{array}{ccc}
		{P}_{\alpha} & {P}_{\beta} & {P}_{\gamma}
	\end{array}\right] \left[\begin{array}{ccc}
		\Lambda(A)_{\alpha\alpha} & 0 & 0 \\ [3pt]
		0 & 0 & 0\\ [3pt]
		0 & 0 & \Lambda(A)_{\gamma\gamma}
	\end{array}\right]\left[\begin{array}{c}
		{P}_{\alpha}^T \\ [3pt]
		{P}_{\beta}^T \\
		{P}_{\gamma}^T
	\end{array}\right],
\end{equation}}
where $\alpha:=\{i: \lambda_i(A)>0\}$, $\beta:=\{i: \lambda_i(A)=0\}$ and $\gamma:=\{i: \lambda_i(A)<0\}$.

The critical cone of $\mathbb{S}_+^n$ at ${Y}\in{\cal N}_{\mathbb{S}_+^n}({X})$ with $A=X+Y$ is given by (cf. \cite[equations (11) and (12)]{CSun08})
\begin{equation}\label{eq:cricsdp}
	{\cal C}_{\mathbb{S}_+^n}({X},{Y})=\{H\in\mathbb{S}^n\mid P^T_{\beta}HP_{\beta}\in\mathbb{S}^{|\beta|}_+,\;P^T_{\beta}HP_{\gamma}=0,\;P^T_{\gamma}HP_{\gamma}=0\}
\end{equation}

and the affine hull of ${\cal C}_{\mathbb{S}_+^n}({X},{Y})$ is
\begin{equation}\label{eq:affcsdp}
	{\rm aff}\,{\cal C}_{\mathbb{S}_+^n}({X},{Y})=\{H\in\mathbb{S}^n\mid P^T_{\beta}HP_{\gamma}=0,\;P^T_{\gamma}HP_{\gamma}=0\}.
\end{equation}

The  NLSDP \eqref{eq:NLSDPc} can be written in the following form
\begin{eqnarray}
	%\mbox{(SDP)}~~~~
	\min\quad && f(x)+\delta_{\mathbb{S}^n_+}(G(x)), \label{eq:NLSDP}
\end{eqnarray}
where
$\delta_{\mathbb{S}^n_+} : \mathbb{S}^n\rightarrow (-\infty,\infty]$ is the indicator function of positive semidefinite cone $\mathbb{S}^n_+$.

Denote ${S}_{KKT}(a,b)$ the solution set of the KKT optimality condition for problem \eqref{eq:NLSDP}, i.e.,
\begin{equation}\label{eq:KKT-NLSDP-p1}
	{S}_{KKT}(a,b)=\left\{(x,Y)\in \mathbb{X}\times\mathbb{S}^n \Bigg | \left.
	\begin{array}{l}
		L_x'(x,Y)-a=0,\\ [3pt]
		\mathbb{S}_+^n\ni (G(x)-b)\perp Y \in \mathbb{S}_-^n.
	\end{array}
	\right.\right \}.
\end{equation}
For any KKT pair $(\bar{x},\overline{Y})$ that satisfies the KKT condition with $(a,b) = (0,0)$, we call $\bar{x}$ a stationary point.

Suppose $\bar{x}$ is a stationary point. Define ${\cal M}(\bar{x})$ as the set of all multipliers $Y\in\mathbb{S}^n$ satisfying the KKT condition \eqref{eq:KKT-NLSDP-p1}, i.e.,
\begin{equation}\label{eq:defcalm}
	{\cal M}(\bar{x})=\{Y\in\mathbb{S}^n \mid (\bar{x},Y)\in {S}_{KKT}(0,0)\}.
\end{equation}

\begin{definition}\label{def:sigt}\cite[Definition 3.2]{Sun06}
	Let $\bar{x}$ be a stationary point of NLSDP \eqref{eq:NLSDP} and $\overline{Y}\in{\cal M}(\bar{x})$. We say the strong second order sufficient condition (SOSC) holds at $(\bar{x},\overline{Y})$ if
	\begin{equation}\label{eq:defssosc}
		\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle-\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)>0\quad\forall\; 0\neq G'(\bar{x})d\in{\rm aff}\,{\cal C}_{\mathbb{S}_+^n}(G(\bar{x}),\overline{Y}).
	\end{equation}
	where $\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)=2\langle\overline{Y},(G'(\bar{x}){d})G(\bar{x})^{\dagger}(G'(\bar{x}){d})\rangle$ is the $\sigma$-term and $G(\bar{x})^{\dagger}$ is the generalized inverse matrix of $G(\bar{x})$.
\end{definition}

Suppose $A=G(\bar{x})+\overline{Y}$ possesses the decomposition \eqref{eq:eig-decomp}. From \cite[page 386]{CSun08}, we know the $\sigma$-term takes the explicit form of
\begin{equation}\label{eq:sigtsdp}
	\varUpsilon_{G(\bar{x})}\big(\overline{Y},H\big)=2\sum_{i\in\alpha,j\in\gamma}\frac{\lambda_j(A)}{\lambda_i(A)}(\widetilde{H}_{ij})^2,
\end{equation}
where $\widetilde{H}=P^THP$.

Next, we introduce some essential notation for our main result. The (second order) generalized differentiability  of the augmented Lagrangian function ${\cal L}_{\rho}$ defined by \eqref{eq:deflag} for NLSDP \eqref{eq:NLSDP} has been explicitly established in \cite{SSZhang08}.  In fact, it is well-known that ${\cal L}_{\rho}$ is continuously differentiable with
\begin{equation}\label{eq:algrad}
	({\cal L}_{\rho})_x'(x,Y)=f'(x)+\rho G'(x)^*\Pi_{\mathbb{S}_-^n}(G(x)+\rho^{-1}Y),
\end{equation}
where $\Pi_{\mathbb{S}_-^n}(\cdot)$ is the metric projection over $\mathbb{S}_{-}^n$ and $G'(x)^*$ denotes the adjoint of the corresponding linear mapping. Moreover, since $({\cal L}_{\rho})_x'$ is  Lipschitz continuous, by using Rademacher’s theorem, the B(ouligand)-subdifferential of $({\cal L}_{\rho})_x'$ at $(x,Y)$ is given by

where $\Pi_{\mathbb{S}_-^n}(\cdot)$ is the metric projection over $\mathbb{S}_{-}^n$ and $G'(x)^*$ denotes the adjoint of the corresponding linear mapping. Moreover, since $({\cal L}_{\rho})_x'$ is  Lipschitz continuous, by using Rademacher’s theorem, the B(ouligand)-subdifferential of $({\cal L}_{\rho})_x'$ at $(x,Y)$ is given by
\begin{equation}\label{eq:partb}
	\partial_B\big(({\cal L}_{\rho})'_x\big)(x,Y):=\{\lim_{k\rightarrow\infty}(({\cal L}_{\rho})_{x}')'(x^k,Y^k)\mid (x^k,Y^k)\in{\cal U},\ (x^k,Y^k)\rightarrow(x,Y)\},
\end{equation}
where ${\cal U}$ is the set of Fr\'{e}chet-differentiable points of $({\cal L}_{\rho})_x'$.

It follows from \cite[(18)]{SSZhang08} (using \cite[Lemma 2 and 3]{SSZhang08}) that
\begin{align*}
	&\pi_x\partial_B\big(({\cal L}_{\rho})_x'\big)(x,Y)(\Delta x)\\
	&=L_{xx}''(x,\rho\Pi_{\mathbb{S}_-^n}(G(x)+\rho^{-1}Y))(\Delta x)+\rho G'({x})^*\partial_B\Pi_{\mathbb{S}_-^n}(G({x})+\rho^{-1}Y) G'({x})(\Delta x),
\end{align*}
where $\pi_x\partial_B\big(({\cal L}_{\rho})_x'\big)(x,Y)$ is the projection of $\partial_B\big(({\cal L}_{\rho})_x'\big)(x,Y)$ onto the space $\mathbb{X}$ and  $\partial_B\Pi_{\mathbb{S}_-^n}(G({x})+\rho^{-1}Y)$ is the B-subdifferential of $\Pi_{\mathbb{S}_-^n}(\cdot)$ at $G({x})+\rho^{-1}Y$. Actually, the set $\pi_x\partial_B\big(({\cal L}_{\rho})_x'\big)(x,Y)$ is recently defined as the $x$ part of the Hessian bundle \cite[(3.1)]{Roh22} for the augmented Lagrangian function ${\cal L}_{\rho}$ at $(x,Y)$ (see \cite[(3.6)]{Roh22} for detail).

Let $\bar{x}$ be the stationary point of \eqref{eq:NLSDP}. For each $\overline{Y}\in{\cal M}(\bar{x})$ and $W\in\partial_B\Pi_{\mathbb{S}_-^n}(G(\bar{x})+\rho^{-1}\overline{Y})$, define the following mapping
\begin{equation}\label{eq:algrad2}
	{\cal A}_{\rho}(\overline{Y},W):=L_{xx}''(\bar{x},\overline{Y})+\rho G'(\bar{x})^*WG'(\bar{x}).
\end{equation}

Let $\overline{Z}=G(\bar{x})+\overline{Y}$ possesses decomposition \eqref{eq:eig-decomp} with $\overline{P}\in{\cal O}^{n}(\overline{Z})$. It follows from \cite[Lemma 5]{SSZhang08} that $W\in\partial_B\Pi_{\mathbb{S}_-^n}(\overline{Z})$ if and only if there exists $W_0\in\partial_B\Pi_{\mathbb{S}_-^{\lvert\beta\rvert}}(0)$ such that for all $H\in\mathbb{S}^n$
{\footnotesize
\begin{equation*}
	W(H)=\overline{P}\left[\begin{array}{ccc}
		0 & 0 & \Sigma_{\alpha\gamma}\circ\overline{P}_{\alpha}^TH\overline{P}_{\gamma}\\
		0 & W_0(\overline{P}_{\beta}^TH\overline{P}_{\beta}) & \overline{P}_{\beta}^TH\overline{P}_{\gamma} \\
		\Sigma_{\gamma\alpha}\circ\overline{P}_{\gamma}^TH\overline{P}_{\alpha} & \overline{P}_{\gamma}^TH\overline{P}_{\beta} & \overline{P}_{\gamma}^TH\overline{P}_{\gamma}
	\end{array}\right]\overline{P}^T,
\end{equation*}}
where
\begin{equation*}
\begin{cases}		\Sigma_{ij}=1-\frac{\max\{\lambda_i,0\}+\max\{\lambda_j,0\}}{\lvert\lambda_i\rvert+\lvert\lambda_j\rvert}, & (i,j)\notin\beta\times\beta\\
\Sigma_{ij}	\in[0,1] & (i,j)\in\beta\times\beta
	\end{cases}
\end{equation*}
with $\lambda_i:=\lambda_i(\overline{Z})$ for short. Let ${\cal Q}^n$ denote the set of $n$-dimensional orthogonal matrix.

By \cite[Lemma 9]{SSZhang08}, we have
{\small \begin{align}
	\langle d,{\cal A}_{\rho}(\overline{Y},W)d\rangle=&\langle d,L_{xx}''(\bar{x},\overline{Y})d\rangle+\rho\sum_{i,j\in\gamma}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2+2\rho\sum_{i\in\beta,j\in\gamma}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\label{eq:expcalA}\\
	&+2\rho\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j}{\rho\lambda_i-\lambda_j}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2+\rho\sum_{i,j\in\beta}(\Omega_{\rho})_{ij}({P}^T(G'(\bar{x})d){P})_{ij}^2,\nonumber
\end{align}}
where $\Omega_{\rho}\in\mathbb{S}^{\lvert\beta\rvert}$ with entries $(\Omega_{\rho})_{ij}\in[0,1]$, $P=[\overline{P}_{\alpha}\;\overline{P}_{\beta}Q\;\overline{P}_{\gamma}]$ with $Q\in{\cal Q}^{\lvert\beta\rvert}$.

Define
\begin{equation}\label{eq:phir}
\phi_r:=\phi(x,u)+\frac{r}{2}|u|^2.
\end{equation}
The variational (strong) convexity, which is firstly proposed in \cite{rock247}, refers to the existence of open convex neighborhoods ${\cal W}$ of $(\bar{x},0)$ and ${\cal Z}$ of $(0,\overline{Y})$ such that there exists a proper closed (strongly) convex function $\psi\leq\phi_r2$ on ${\cal W}$ such that
\begin{equation*}
	({\cal W}\times{\cal Z})\cap{\rm gph}\,\partial\psi=({\cal W}\times{\cal Z})\cap{\rm gph}\,\partial\phi_r
\end{equation*}
and for $(x,u;v,y)$ belonging to this common set, $\psi(x,u)=\phi_r(x,u)$.

\begin{definition}\label{def:svasc}\cite{Roh22}
	The (strong) variational sufficient condition for local optimality in \eqref{eq:pgpert} holds with respect to $\bar{x}$ and $\overline{Y}$ satisfying the first order condition if there exists $r>0$ such that $\displaystyle\phi_r(x,u)$ is variationally (strongly) convex with respect to the pair $\big((\bar{x},0),(0,\overline{Y})\big)$ in ${\rm gph}\,\partial\phi_r$.
\end{definition}

\begin{definition}\label{def:genguadf} \cite{Roh22}
	A generalized linear mapping ${\cal R}$ from $\mathbb{X}$ to $\mathbb{Y}$, is a set-valued mapping for which ${\rm gph}\,{\cal R}$ is a subspace of $\mathbb{X}\times\mathbb{Y}$. This means that ${\rm dom}{\cal R}$ is a subspace $\mathbb{Z}$ of $\mathbb{X}$, ${\cal R}(0)$ is a subspace $\mathbb{Z}'$ of $\mathbb{Y}$, and there is an ordinary linear mapping ${\cal R}_0:\mathbb{Z}\rightarrow\mathbb{Y}$ such that ${\cal R}(x)={\cal R}_0(x)+\mathbb{Z}'$ for $x\in\mathbb{Z}$.
	We call a function $q: \mathbb{X}\rightarrow(-\infty,+\infty]$ is a generalized quadratic form on $\mathbb{X}$ if $q(0)=0$ and the subgradient mapping $\partial q:\mathbb{X}\rightrightarrows\mathbb{X}$ is generalized linear. A function $g$ on $\mathbb{X}$ will be called generalized twice differentiable at $x$ for a subgradient $y$ if it is twice epi-differentiable at $x$ for $y$ with the second-order subderivative $d^2g(x\mid y)$ being a generalized quadratic form.
\end{definition}

The following definition of the quadratic bundle is taken from \cite{Roh22}, which is essential in characterizing the strong variational sufficiency.
\begin{definition}\label{def:quadratic bundle}
	For general optimization problem \eqref{eq:genp}, suppose $(\bar{x},\overline{Y})$ is a KKT pair. The quadratic bundle of $\theta$ is defined as
	\begin{equation*}
		{\rm quad}\,\theta(G(\bar{x})\mid\overline{Y})=\left\{
		\begin{array}{l}
			\mbox{the collection of generalized quadratic forms}\; q\; \mbox{for which}\\
			\exists(X^k,Y^k)\rightarrow(G(\bar{x}),\overline{Y})\;\mbox{with}\;\theta\;\mbox{generalized twice differentiable}\\
			\mbox{at}\;X^k\;\mbox{for}\;Y^k\;\mbox{and such that the generalized quadratic}\\
			\mbox{forms}\;q_k=\frac{1}{2}d^2\theta(X^k\mid Y^k)\;\mbox{converge epigraphically to}\;q.
		\end{array}
		\right.
	\end{equation*}
\end{definition}

As mentioned in \cite{Roh22}, the variational sufficient condition guarantees the local optimality for \eqref{eq:pgpert}. The following result is taken from \cite[Theorem 5]{Roh22}, which is useful for the subsequent analysis.
\begin{proposition}\label{prop:thm5}
	For general optimization problem \eqref{eq:genp},
	strong variational sufficient condition for local optimality with respect to $(\bar{x},\overline{Y})$ is equivalent to that  every $q\in{\rm quad}\,\theta(G(\bar{x})\mid\overline{Y})$ has
	\begin{equation}\label{svs-equ}
		\frac{1}{2}\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle+q(G'(\bar{x}){d})>0\quad{\rm when}\;d\neq0,
	\end{equation}
	where ${\rm quad}\,\theta(G(\bar{x})\mid\overline{Y})$ is the quadratic bundle of $\theta$.
\end{proposition}

\begin{proposition}\label{prop:onesidessosc}
	Let $\bar{x}\in\mathbb{X}$ be a stationary point to NLSDP \eqref{eq:NLSDP} and $\overline{Y}\in {\cal M}(\bar{x})$, where ${\cal M}(\bar{x})$ is given in \eqref{eq:defcalm}. Let $A=G(\bar{x})+\overline{Y}$, which possesses the decomposition \eqref{eq:eig-decomp}. Then, there exists $q\in {\rm quad}\,\delta_{\mathbb{S}_+^n}(G(\bar{x})\mid\overline{Y})$ such that for all $H\in\mathbb{S}^n$,
	\begin{align}
		q(H)&=-\frac{1}{2}\varUpsilon_{G(\bar{x})}\big(\overline{Y},H\big)+\delta_{{\rm aff}\,{\cal C}_{\mathbb{S}_+^n}(G(\bar{x}),\overline{Y})}(H)\nonumber\\
		&=\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j(A)}{\lambda_i(A)}(\widetilde{H}_{ij})^2+\delta_{{\rm aff}\,{\cal C}_{\mathbb{S}_+^n}(G(\bar{x}),\overline{Y})}(H),\label{eq:qeqsg}
	\end{align}
	where $\widetilde{H}=P^THP$.
\end{proposition}

\begin{theorem}\label{thm:varscequissosc}
	Let $\bar{x}\in\mathbb{X}$ be a stationary point to the NLSDP \eqref{eq:NLSDP} and $\overline{Y}\in {\cal M}(\bar{x})$. Then the following three conditions are equivalent
	\begin{itemize}
		\item[(i)] the strong variational sufficient condition with respect to $(\bar{x},\overline{Y})$ holds;
		\item[(ii)] the strong second order sufficient condition (SOSC) \eqref{eq:defssosc} holds at $(\bar{x},\overline{Y})$;
		\item[(iii)] there exist $\rho_0>0$ and $\underline{\eta}>0$ such that for any $\rho\geq \rho_0$ and any $W\in\partial_B\Pi_{\mathbb{S}_-^n}(G(\bar{x})+\rho^{-1}\overline{Y})$,
		\begin{equation*}\label{eq:psdofpb}
		\langle d, {\cal A}_{\rho}(\overline{Y},W)d\rangle\geq\underline{\eta}\|d\|^2\quad\forall d\in\mathbb{X},
		\end{equation*}
		where ${\cal A}_{\rho}(\overline{Y},W)$ is defined by \eqref{eq:algrad2}.
	\end{itemize}
\end{theorem}

\begin{proof}
	``$(i)\Longrightarrow(ii)$":  This direction can be obtained directly from Proposition \ref{prop:onesidessosc} and Proposition \ref{prop:thm5} as we only need to substitute \eqref{eq:qeqsg} into \eqref{svs-equ}.

	``$(ii)\Longrightarrow(iii)$": This proof sketch is similar to \cite[Proposition 4]{SSZhang08} although they require the validity of nondegeneracy, which is superfluous here.
	It follows from Definition \ref{eq:defssosc} that there exists $\eta_0>0$ such that
	$$\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle-\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)\geq\eta_0\|d\|^2\quad\forall\; G'(\bar{x})d\in{\rm aff}\,{\cal C}_{\mathbb{S}_+^n}(G(\bar{x}),\overline{Y}).$$
	By using \cite[Lemma 7]{SSZhang08}, there exist two positive numbers $\rho_1$ and $\underline{\eta}\in(0,\eta_0/2]$ such that for any $\rho'\geq \rho_1$,
	\begin{align*}
		&\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle-\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)\\
		&+\rho'\|\overline{P}^T_{\gamma}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2+\rho'\|\overline{P}^T_{\beta}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2\geq2\underline{\eta}\|d\|^2\quad \forall d\in\mathbb{X}.
	\end{align*}
	Suppose a sufficient large $\rho_0\geq\rho_1$. For any $\rho\geq\rho_0$ and $d\in{\cal X}$, we have
	{\small \begin{align*}
			&-\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)-2\rho\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j}{\rho\lambda_i-\lambda_j}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\\
			&=2\sum\limits_{i\in\alpha,\,j\in\gamma}\frac{-\lambda_j}{\lambda_i}(\overline{P}^T(G'(\bar{x}){d})\overline{P})_{ij}^2-2\rho\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j}{\rho\lambda_i-\lambda_j}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\\
			&=2\sum\limits_{i\in\alpha,\,j\in\gamma}\frac{\lambda_j^2}{\lambda_i(\rho\lambda_i-\lambda_j)}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\leq\underline{\eta}\|d\|^2,
	\end{align*}}
	where the last inequality can be obtained by sufficiently large $\rho$.
	Combining the above two relations together, we have for any $\rho\geq\rho_0$,  $\rho'\geq\rho_0\geq\rho_1$,
	\begin{align*}
		&\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle+2\rho\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j}{\rho\lambda_i-\lambda_j}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\\
		&+\rho'\|\overline{P}^T_{\gamma}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2+\rho'\|\overline{P}^T_{\beta}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2\geq\underline{\eta}\|d\|^2.
	\end{align*}
	Then it can be checked directly that for all $d\in\mathbb{X}$ and $\rho\geq\rho_0$,  $\langle d,{\cal A}_{\rho}(\overline{Y},W)d\rangle\geq\underline{\eta}\|d\|^2 $.



	``$(iii)\Longrightarrow(i)$": It follows directly from \cite[Theorem 3]{Roh22} as ${\cal A}_{\rho}(\overline{Y},W)$ coincides with \cite[(3.6)]{Roh22}.
\end{proof}

By using \cite[Lemma 7]{SSZhang08}, there exist two positive numbers $\rho_1$ and $\underline{\eta}\in(0,\eta_0/2]$ such that for any $\rho'\geq \rho_1$,
\begin{align*}
	&\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle-\varUpsilon_{G(\bar{x})}\big(\overline{Y},G'(\bar{x}){d}\big)\\
	&+\rho'\|\overline{P}^T_{\gamma}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2+\rho'\|\overline{P}^T_{\beta}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2\geq2\underline{\eta}\|d\|^2\quad \forall d\in\mathbb{X}.
\end{align*}

Combining the above two relations together, we have for any $\rho\geq\rho_0$,  $\rho'\geq\rho_0\geq\rho_1$,
\begin{align*}
	&\langle L_{xx}''(\bar{x},\overline{Y})d,d\rangle+2\rho\sum_{i\in\alpha,j\in\gamma}\frac{-\lambda_j}{\rho\lambda_i-\lambda_j}(\overline{P}^T(G'(\bar{x})d)\overline{P})_{ij}^2\\
	&+\rho'\|\overline{P}^T_{\gamma}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2+\rho'\|\overline{P}^T_{\beta}(G'(\bar{x})d)\overline{P}_{\gamma}\|^2\geq\underline{\eta}\|d\|^2.
\end{align*}

