Our problem of interest is the following Empirical Risk Minimization (ERM) problem (also called the \textit{finite-sum} problem) with constraints: 
\begin{equation}\label{pro: ERM}
	\text{ERM:} \ \ \ \ \    \text{minimize}_{x \in \calC} \quad F(x):= \tfrac{1}{n} \sum_{i=1}^{n} f_i(x) \ , 
\end{equation}
where $f_i(\cdot): \mathbb{R}^p \to \mathbb{R}$ is the loss function of observation $i$ for $i=1,\dots, n$, and $x$ is comprised of the (model) coefficients/parameters which are to be optimized over the feasibility set $\calC \subset \mathbb{R}^p$. Problem \cref{pro: ERM} is a fundamental problem in statistical and machine learning, as it is the underlying optimization problem on which models are ``trained'' or ``learned'', see  \cite{vapnik1991principles,hastie2009elements}. The number of observations $n$ can be significantly larger than the dimension $p$, and our interest here will be in the regime where $n \gg p$.
We make the following assumptions for $\erm$ problems throughout this paper:

\begin{assumption}\label{assump: ERM}
	The following conditions hold for the $\erm$ problem \cref{pro: ERM}:
	\begin{enumerate}
		\item[(i)] the feasibility set $\mathcal{C}$ is a compact convex set,
		\item[(ii)] for any $g \in \mathbb{R}^p$, the linear minimization problem $\arg\min_{x\in\calC} g^\top x$
		can be easily solved, 
		\item[(iii)] for all $i\in[n]$, the multivariate loss function $f_i(\cdot)$ is twice-differentiable and its gradient $\nabla f_i(\cdot)$ is $L$-Lipschitz continuous on $\calC$, namely, 
		\begin{equation}\label{eq: ERM ass lip 1}
			\| \nabla f_i(u) - \nabla f_i(v) \|_* \le L \|u-v\| ~~\text{ for any $u,v\in \calC$}
		\end{equation}
		where $\|\cdot\|_*$ is the dual norm of the norm on the space of variables, and 
		\item[(iv)] for all $i\in[n]$, the Hessian $\nabla^2 f_i(\cdot)$ is $\hat{L}$-Lipschitz continuous on $\calC$, namely
		\begin{equation}\label{eq: ERM ass lip 2}
			\| \nabla^2 f_i(u) - \nabla^2 f_i(v) \| \le \hat{L} \|u-v\|~~\text{ for any $u,v\in \calC$}
		\end{equation}
		where the norm of the Hessian matrices is the operator norm induced by the norm on the space of variables.
	\end{enumerate}
\end{assumption}

\item[(iii)] for all $i\in[n]$, the multivariate loss function $f_i(\cdot)$ is twice-differentiable and its gradient $\nabla f_i(\cdot)$ is $L$-Lipschitz continuous on $\calC$, namely, 
\begin{equation}\label{eq: ERM ass lip 1}
	\| \nabla f_i(u) - \nabla f_i(v) \|_* \le L \|u-v\| ~~\text{ for any $u,v\in \calC$}
\end{equation}
where $\|\cdot\|_*$ is the dual norm of the norm on the space of variables, and

\item[(iv)] for all $i\in[n]$, the Hessian $\nabla^2 f_i(\cdot)$ is $\hat{L}$-Lipschitz continuous on $\calC$, namely
\begin{equation}\label{eq: ERM ass lip 2}
	\| \nabla^2 f_i(u) - \nabla^2 f_i(v) \| \le \hat{L} \|u-v\|~~\text{ for any $u,v\in \calC$}
\end{equation}
where the norm of the Hessian matrices is the operator norm induced by the norm on the space of variables.

\begin{algorithm}
	\caption{(TUFW) Frank-Wolfe Method with Taylor Point Updating}
	\label{alg: TUFW in general finite sum}
	\begin{algorithmic}[1]
		\STATE \textbf{input}  initial point $x^0$, step-size sequence $\{\gamma_k\}_k$, and (possibly) number of iterations $K$
		\STATE \textbf{initialize Taylor points} $\calB_0 \gets [n]$ and $b_i \leftarrow x^0$ for $i\in [n]$  \; \label{bettina}
		\FOR{$k=0,1,2,\dots,K$,}
		\STATE\label{algline: 3}\textbf{If $k>0$, update Taylor points}: \\ \ \ Use some \textbf{Rule} to construct set $\calB_k \subset [n]$ of indices for Taylor-point updating\\ \ \ Update Taylor points:  for $i\in\calB_k$ update $b_i \gets x^k$ \; \label{fanette}
		\STATE\label{algline: 4}  \textbf{Compute estimates of individual gradients}:\\ $g^k_{i}\gets \nabla f_{i}(b_{i})  +  \nabla^2 f_i (b_{i}) ( x^k -  b_{i} ) $ for $i\in [n]$\; \label{charlie}
		\STATE\label{algline: 5}   \textbf{Compute estimate of full gradient}: $g^k\gets \frac{1}{n}\sum_{i=1}^{n}g_i^k$\; \label{beverly}
		\STATE\label{algline: 6}   \textbf{Solve LMO}: $s^{k}\gets \arg\min_{s\in\calC} \langle g^k,s\rangle$\; \label{alex} 
		\STATE\label{algline: 7}   \textbf{Update feasible solution}: $x^{k+1}\gets x^k + \gamma_k (s^{k} - x^k)$. \label{hotel}
		\ENDFOR
		\RETURN $x^{K+1}$
	\end{algorithmic}
\end{algorithm}

\STATE \textbf{input}  initial point $x^0$, step-size sequence $\{\gamma_k\}_k$, and (possibly) number of iterations $K$
\STATE \textbf{initialize Taylor points} $\calB_0 \gets [n]$ and $b_i \leftarrow x^0$ for $i\in [n]$  \; \label{bettina}
\FOR{$k=0,1,2,\dots,K$,}
\STATE\label{algline: 3}\textbf{If $k>0$, update Taylor points}: \\ \ \ Use some \textbf{Rule} to construct set $\calB_k \subset [n]$ of indices for Taylor-point updating\\ \ \ Update Taylor points:  for $i\in\calB_k$ update $b_i \gets x^k$ \; \label{fanette}

Recall that in order to run \cref{alg: TUFW in general finite sum} we need to specify the step-sizes $\{\gamma_k\}_k$ and the {\bf Rule} to construct the sets $\calB_k$ of indices for Taylor-point updating in \cref{fanette}.  Our first rule is designed 
for $\calB_k$ to be comprised of $\beta_k := n /\sqrt{k}$ independently drawn samples from $[n]$ without replacement, for all $k \ge 1$.   Since $\beta_k$ is not in general an integer, then rather than ensuring $|\calB_k| = \beta_k$, we will instead ensure that $\mathbb{E}|\calB_k| = \beta_k$ by proceeding as follows.  



\begin{definition}\label{rule 1} $\rone$.  Define $\beta_k := n /\sqrt{k}$ and $p_k := \beta_k - \lfloor \beta_k \rfloor$.  Sample $\xi_k$ from the Bernoulli distribution $\mathrm{Ber}(p_k)$ and then uniformly sample $\lfloor \beta_k \rfloor + \xi_k$ samples from $[n]$ without replacement.  Then define $\calB_k$ to be the set of these index samples.\end{definition}

We begin with the following straightforward properties of smooth functions.
\begin{proposition}\label{prop: general basic ineq}
	Under \cref{assump: ERM} for $\erm$,  for any $x$, $y\in\calC$ and $i$, 
	\begin{align}
		| f_i(y) -  f_i(x) - \langle\nabla f_i(x),  y- x\rangle |\le  L\|x-y\|^2 /2 \ , \text{ and } \label{eq: fact: general basic ineq 1} \\

		\| \nabla f_i(y) - \nabla f_i(x) - \langle\nabla^2 f_i(x),  y- x\rangle \|_*\le  \hat{L}\|x-y\|^2 /2 \ . \label{eq: fact: general basic ineq 2}
	\end{align}
\end{proposition}

For any $k \ge 0$ and $i\in [n]$, we will be interested in the most recent iteration (up through $k$) at which Taylor point $b_i$ was updated.  This is defined as:
\begin{equation}\label{def: tau}
	\tau^k_i := \max\{t: t\le k  \text{ and } i \in \calB_t\} \ ,
\end{equation}
which means that in the first $k$ iterations, $\tau^k_i$ is the latest iteration in which the Taylor point $b_i$ was updated. In \cref{alg: TUFW in general finite sum}, the relationship between $\tau^k_i$ and $\tau^{k-1}_i$ is then:

\begin{equation}\label{eq: tauk relationship}
	\tau^{k}_i = \left\{
	\begin{array}{ll}
		k & \text{ if } \  i\in\calB_k \\
		\tau^{k-1}_i & \text{ if } \ i\notin\calB_k \ . 
	\end{array}
	\right.
\end{equation}

\begin{theorem}\label{thm: general convergence rate convex}
		Suppose that $F$ is convex and Assumption \ref{assump: ERM} holds, and  \cref{alg: TUFW in general finite sum} with $\rone$ is applied to the problem \cref{pro: ERM} with step-sizes defined by $\gamma_k:={2}/({k+2})$ for all $k \ge 0$. Then for all $k\ge 1$ we have:
		\begin{equation}\label{eq of thm: general convergence rate convex}
			\mathbb{E}[F(x^{k}) - F(x^\star)] \le  \frac{2L D^2 + 134 \hat{L}D^3}{k+1} \ .
		\end{equation} 
	\end{theorem}

\begin{lemma}\label{lm: general 3rd term upper bound}
		Under \cref{assump: ERM} for the problem $\erm$, for any $u,v \in\calC$,
		\begin{equation}\label{eq: lm: general 3rd term upper bound}
			\left(
			\nabla F(x^k)   - g^k
			\right)^\top (u - v) \le \frac{\hat{L}D^3}{2n}\sum_{i=1}^{n}\Big( \sum_{j = \tau^k_i}^{k-1}  \gamma_j \Big)^2
		\end{equation}
		holds for iteration $k$ of Algorithm \ref{alg: TUFW in general finite sum} for all $k \ge 1$.
	\end{lemma}

\begin{proof}[Proof of \cref{lm: general 3rd term upper bound}]
		First of all, $\left(
		\nabla F(x^k)   - g^k
		\right)^\top (u - v)$ can be rewritten as
		\begin{small}
			\begin{equation}\label{ineq: general etimate gradient 0}
				\frac{1}{n}\sum_{i=1}^{n}\left(\nabla f_{i}\big(x^k \big) -   \nabla f_{i}\big( x^{\tau^{k}_i}\big) -  \nabla^2 f_{i} \big( x^{\tau^{k}_i}\big)\big(x^k  - x^{\tau^{k}_i} \big)    \right)^\top (u - v),
			\end{equation}	
		\end{small}which, since $\|u-v\| \le D$, is smaller than or equal to 
		\begin{small}\begin{equation}\label{ineq: general etimate gradient 1}
			\frac{D}{n}\sum_{i=1}^{n}\left\| \nabla f_{i}\big(x^k \big) -   \nabla f_{i}\big( x^{\tau^{k}_i}\big) -  \nabla^2 f_{i} \big( x^{\tau^{k}_i}\big)\big(x^k  - x^{\tau^{k}_i} \big)    \right\|_* \le    \frac{\hat{L}D}{2n}\sum_{i=1}^{n}\big\|x^k  - x^{\tau^{k}_i}\big\|^2,
		\end{equation}\end{small}where the inequality is due to \cref{eq: fact: general basic ineq 2} in \cref{prop: general basic ineq}.
		Additionally, we have 
		\begin{small}\begin{equation*}
			\|x^k  - x^{\tau^{k}_i}
			\|^2 \le  \bigg( \sum_{j = \tau^k_i}^{k-1} \| x^{j+1} -  x^{j}\| \bigg)^2\le  \bigg( \sum_{j = \tau^k_i}^{k-1}  \gamma_j D \bigg)^2 \  ,
		\end{equation*}\end{small}and substituting this last bound into \cref{ineq: general etimate gradient 1} yields \cref{eq: lm: general 3rd term upper bound}.
	\end{proof}

First of all, $\left(
\nabla F(x^k)   - g^k
\right)^\top (u - v)$ can be rewritten as
\begin{small}
	\begin{equation}\label{ineq: general etimate gradient 0}
		\frac{1}{n}\sum_{i=1}^{n}\left(\nabla f_{i}\big(x^k \big) -   \nabla f_{i}\big( x^{\tau^{k}_i}\big) -  \nabla^2 f_{i} \big( x^{\tau^{k}_i}\big)\big(x^k  - x^{\tau^{k}_i} \big)    \right)^\top (u - v),
	\end{equation}

Additionally, we have 
\begin{small}\begin{equation*}
	\|x^k  - x^{\tau^{k}_i}
	\|^2 \le  \bigg( \sum_{j = \tau^k_i}^{k-1} \| x^{j+1} -  x^{j}\| \bigg)^2\le  \bigg( \sum_{j = \tau^k_i}^{k-1}  \gamma_j D \bigg)^2 \  ,
\end{equation*}\end{small}and substituting this last bound into \cref{ineq: general etimate gradient 1} yields \cref{eq: lm: general 3rd term upper bound}.

\begin{lemma}\label{lm: general convergence rate convex}
		Under \cref{assump: ERM} for problem $\erm$, suppose that $F$ is conevx, and let the step-sizes be given by $\gamma_k=2/(k+2)$ for all $k \ge 0$. Then for all $k \ge 1$ we have
		\begin{equation}\label{eq lm: general convergence rate convex}
			\eps_k  \le  \frac{2L D^2}{k+1}
			+  \frac{2}{k(k+1)}\sum_{t=1}^{k} t \left(
			\nabla F(x^{t-1})   - g^{t-1}
			\right)^\top (s^{t-1} - x^\star) \ .
		\end{equation}
	\end{lemma}

\begin{proof}[Proof of \cref{lm: general convergence rate convex}]
		Utilizing  \cref{prop: general basic ineq} we have
		\begin{small}\begin{equation}\label{eq lm general convergence rate convex 0}
				\begin{aligned}
					F(x^{k+1})\leq ~ & F(x^k)+\gamma_{k}\langle\nabla F(x^k),s^{k}- x^k \rangle+ \gamma_{k}^{2} {L D^2}/{2} \\
					= ~ & F(x^{k})+\gamma_{k}\langle \nabla F(x^{k})-g^k, s^{k}-x^k\rangle +\gamma_{k}\langle{g^k}, s^{k}-x^k\rangle+ \gamma_{k}^{2} {L D^2}/{2} \\
					\leq ~ & F(x^{k})+\gamma_{k}\langle\nabla F(x^{k})-{g^k}, s^{k}-x^k\rangle + \gamma_{k}\langle{g^k}, {x}^{\star}-x^k\rangle+ \gamma_{k}^{2} {L D^2}/{2} \\
					= ~ & F(x^{k})+\gamma_{k}\langle \nabla F(x^{k})-{g^k},s^{k}-{x}^{\star}\rangle +\gamma_{k}\langle \nabla F(x^{k}), {x}^{\star}-x^k\rangle+ \gamma_{k}^{2} {L D^2}/{2}\\
					\le ~& F(x^{k})+\gamma_{k}\langle \nabla F(x^{k})-{g^k},s^{k}-{x}^{\star}\rangle +\gamma_{k}(F(x^\star) - F(x^k))+ \gamma_{k}^{2} {L D^2}/{2} \ , 
				\end{aligned}
		\end{equation}\end{small}where the second inequality uses $s^{k} \in \arg\min_{s\in\calC} (g^k)^\top s$ from \cref{alex} of the algorithm, and the third inequality uses the gradient inequality applied to $F$.  Subtracting $F^\star$ from both sides of the above inequality chain, we arrive at:
		\begin{small}\begin{equation}\label{eq lm general convergence rate convex 1}
				\begin{aligned}
					\eps_{k+1}& \le (1-\gamma_k)\eps_k + \gamma_k \big(
					\nabla F(x^k)   - g^k
					\big)^\top (s^{k} - x^\star) +  {\gamma_k^2 L D^2}/{2} \ .
			\end{aligned}
		\end{equation}\end{small}Multiplying both side by $(k+1)(k+2)$ and telescoping the inequalities yields:
		\begin{small}\begin{equation}
				\begin{aligned}
					(k+1)(k+2)\eps_{k+1}  &\le  2(k+1)L D^2
					+  \sum_{t=0}^{k}2(t+1) (
					\nabla F(x^t)   - g^t
					)^\top (s^{t} - x^\star) \ ,
			\end{aligned}
		\end{equation}\end{small}which yields \cref{eq lm: general convergence rate convex} after rearranging and re-indexing the counter $t$.
	\end{proof}

Utilizing  \cref{prop: general basic ineq} we have
\begin{small}\begin{equation}\label{eq lm general convergence rate convex 0}
		\begin{aligned}
			F(x^{k+1})\leq ~ & F(x^k)+\gamma_{k}\langle\nabla F(x^k),s^{k}- x^k \rangle+ \gamma_{k}^{2} {L D^2}/{2} \\
			= ~ & F(x^{k})+\gamma_{k}\langle \nabla F(x^{k})-g^k, s^{k}-x^k\rangle +\gamma_{k}\langle{g^k}, s^{k}-x^k\rangle+ \gamma_{k}^{2} {L D^2}/{2} \\
			\leq ~ & F(x^{k})+\gamma_{k}\langle\nabla F(x^{k})-{g^k}, s^{k}-x^k\rangle + \gamma_{k}\langle{g^k}, {x}^{\star}-x^k\rangle+ \gamma_{k}^{2} {L D^2}/{2} \\
			= ~ & F(x^{k})+\gamma_{k}\langle \nabla F(x^{k})-{g^k},s^{k}-{x}^{\star}\rangle +\gamma_{k}\langle \nabla F(x^{k}), {x}^{\star}-x^k\rangle+ \gamma_{k}^{2} {L D^2}/{2}\\
			\le ~& F(x^{k})+\gamma_{k}\langle \nabla F(x^{k})-{g^k},s^{k}-{x}^{\star}\rangle +\gamma_{k}(F(x^\star) - F(x^k))+ \gamma_{k}^{2} {L D^2}/{2} \ , 
		\end{aligned}
\end{equation}\end{small}where the second inequality uses $s^{k} \in \arg\min_{s\in\calC} (g^k)^\top s$ from \cref{alex} of the algorithm, and the third inequality uses the gradient inequality applied to $F$.  Subtracting $F^\star$ from both sides of the above inequality chain, we arrive at:

\begin{small}\begin{equation}\label{eq lm general convergence rate convex 1}
		\begin{aligned}
			\eps_{k+1}& \le (1-\gamma_k)\eps_k + \gamma_k \big(
			\nabla F(x^k)   - g^k
			\big)^\top (s^{k} - x^\star) +  {\gamma_k^2 L D^2}/{2} \ .
	\end{aligned}
\end{equation}\end{small}Multiplying both side by $(k+1)(k+2)$ and telescoping the inequalities yields:

\begin{small}\begin{equation}
		\begin{aligned}
			(k+1)(k+2)\eps_{k+1}  &\le  2(k+1)L D^2
			+  \sum_{t=0}^{k}2(t+1) (
			\nabla F(x^t)   - g^t
			)^\top (s^{t} - x^\star) \ ,
	\end{aligned}
\end{equation}\end{small}which yields \cref{eq lm: general convergence rate convex} after rearranging and re-indexing the counter $t$.

\begin{lemma}\label{lm: convex EZ} Let the series $\{d_{ij}\}_{i\in[n],j\in\mathbb{N}}$ be given, and suppose that there exist $M_{1}$ and $M_{\infty}$ for which $\sup_{j} \sum_{i=1}^n d_{ij} \le M_{1}$ and  $\sup_{i,j} d_{ij}\le M_{\infty}$.  
		Let $\tau_i^k$ be defined in \cref{def: tau}, in which $\calB_t$ is constructed using $\rone$ in \cref{rule 1}. Let $\gamma_k$ be ${2}/(k+2)$ for all $k \ge 0$.  Then it holds that
		\begin{equation}\label{eq: lm: convex EZ}
			\mathbb{E}\bigg[\sum_{i=1}^{n}\Big( \sum_{j = \tau^k_i}^{k-1}  \gamma_j d_{ij} \Big)\bigg] \le
			\frac{6 M_1}{\sqrt{k+2}} \ \ \text{ and }   \ \
			\mathbb{E} \bigg[\sum_{i=1}^{n}\Big( \sum_{j = \tau^k_i}^{k-1}  \gamma_j d_{ij} \Big)^2 \bigg]\le  \frac{134M_1M_\infty}{k+2} \ .
		\end{equation}
	\end{lemma}

