\begin{theorem}
\label{pr_avg_conv}
Let $h_t \geqslant 0$, and $a_t \geqslant 0$, $P_t \succcurlyeq 0$ be continuously differentiable with respect to time. Let  $f \in \mathcal{F}_{0, \infty}$ be a twice continuously differentiable function and $(X_t, \bar{X}_t) \in \mathbf{R}^d \times \mathbf{R}^d$ be a trajectory generated by the SDE under Polyak-Ruppert averaging~\eqref{ODE_mean1}. Let $\mathcal{V}$ be a quadratic function~\eqref{lyap_avg}, such that there exist $\lambda^{(1)}_t, ..., \lambda^{(6)}_t \geqslant 0$ verifying:
\begin{equation*}
    \begin{aligned}
&\begin{pmatrix} \dot{p}^{(11)}_t + \frac{2p^{(12)}_t}{t} & \dot{p}^{(12)}_t + \frac{p^{(22)}_t - p^{(12)}_t}{t}& \frac{\lambda^{(6)}_t + \lambda^{(4)}_t - 2h_tp^{(11)}_t}{2} & \frac{a^{(2)}_t}{2t} - \frac{\lambda^{(5)}_t}{2}\\ 

\dot{p}^{(12)}_t + \frac{p^{(22)}_t - p^{(12)}_t}{t} & \dot{p}^{(22)}_t - \frac{2p^{(22)}_t}{t} & -\frac{\lambda^{(6)}_t - 2h_tp^{(12)}_t}{2} & -\frac{a^{(2)}_t}{2t} + \frac{\lambda^{(5)}_t + \lambda^{(3)}_t}{2}\\ 

 \frac{\lambda^{(6)}_t + \lambda^{(4)}_t - 2h_tp^{(11)}_t}{2} & -\frac{\lambda^{(6)}_t - 2h_tp^{(12)}_t}{2} & -a^{(1)}_t & 0 \\ 

\frac{a^{(2)}_t}{2t} - \frac{\lambda^{(5)}_t}{2} & -\frac{a^{(2)}_t}{2t} + \frac{\lambda^{(5)}_t + \lambda^{(3)}_t}{2} & 0 &  0\end{pmatrix} \preccurlyeq 0, \\ 
&\dot{a}^{(1)}_t + \lambda^{(1)}_t + \lambda^{(5)}_t = \lambda^{(4)}_t + \lambda^{(6)}_t, \\ 
&\dot{a}^{(2)}_t + \lambda^{(2)}_t + \lambda^{(6)}_t = \lambda^{(3)}_t + \lambda^{(5)}_t + \dot{a}^{(1)}_t. 
\end{aligned}
\end{equation*}
Then, the following inequality is satisfied:
\smallbreak 
$\displaystyle\frac{d}{dt}\mathbf{E}\mathcal{V}(X_t, \bar{X}_t, t)\leqslant \frac{1}{2}\mathbf{E}{\rm Tr}\left((a^{(1)}_t\nabla_{xx} f(X_t) + 2p^{(11)}_t I_d)\Sigma(X_t)\right)h_t^2\gamma$.
\end{theorem}

