\begin{proof}
The proof follows the method from Section~\ref{sec:methodo} (see Appendix~\ref{sec:A11}).
\end{proof}

\begin{proof}

We rewrite the SDE into 
\begin{equation*}
\begin{aligned}
    \begin{pmatrix} dX_t \\ d\bar{X}_t\end{pmatrix} =& \left(\begin{pmatrix} 0 & 0 \\ \frac{1}{t} & -\frac{1}{t} \end{pmatrix}\otimes I_d\right)\begin{pmatrix} X_t \\ \bar{X}_t\end{pmatrix}dt +\left(\begin{pmatrix}- h_t & 0 \\ 0  & 0  \end{pmatrix}\otimes I_d\right)\begin{pmatrix} \nabla f(X_t) \\ \nabla f(\bar{X}_t) \end{pmatrix}dt \\
    &+\left(\begin{pmatrix}h_t (\gamma\Sigma(X_t))^{1/2} \\ 0\end{pmatrix}\otimes I_d\right)dB_t
\end{aligned}
\end{equation*}
 and denote $Y_t = \begin{pmatrix} X_t \\ \bar{X}_t \end{pmatrix}$. 
 \smallbreak
 We consider the quadratic function~\eqref{lyap_avg} $\mathcal{V}_{a^{(1)}_t, a^{(2)}_t, P_t}(X_t, \bar{X}_t ,t) = \mathcal{V}(Y_t,t)$. Applying Ito's formula, its derivative with respect to time is $\frac{d}{dt} \mathcal{V}(Y_t,t) = \frac{\partial}{\partial t}\mathcal{V}(Y_t,t) + \frac{\partial}{\partial y}\mathcal{V}\frac{dY_t}{dt} + \frac{1}{2}\gamma h^2_t {\rm Tr}[\frac{\partial^2}{\partial Y_t^2}\mathcal{V}(Y_t,t)^\top \begin{pmatrix}\Sigma(X_t) \\ 0\end{pmatrix}]$. By taking the expectation of Ito's formula, we have $\frac{d}{dt} \mathbf{E}\mathcal{V}(Y_t,t) = \mathbf{E}[\frac{\partial}{\partial t}\mathcal{V}(Y_t,t) + \frac{\partial}{\partial y}\mathcal{V}\frac{dY_t}{dt}] +\frac{1}{2}\gamma h^2_t \mathbf{E}{\rm Tr}(\frac{\partial^2}{\partial Y_t^2}\mathcal{V}(Y_t,t)^\top \begin{pmatrix}\Sigma(X_t) \\ 0\end{pmatrix})$.
 \smallbreak
 The variance term $\frac{1}{2}\gamma h^2_t \mathbf{E}{\rm Tr}(\frac{\partial^2}{\partial Y_t^2}\mathcal{V}(Y_t,t)^\top \begin{pmatrix}\Sigma(X_t) \\ 0\end{pmatrix})$ depends on the second derivative of $f$ in the space variable $(X_t)$, and on the covariance $\Sigma_t$. We do not take this term into account in the performance estimation frawework.
 \smallbreak
 We formulate the problem of verifying a quadratic function as verifying the inequality $\frac{d}{dt}\mathbf{E}\mathcal{V}(X_t, \bar{X}_t,t) \leqslant \frac{1}{2}\gamma h^2_t \mathbf{E}{\rm Tr}(\frac{\partial^2}{\partial X_t^2}\mathcal{V}(X_t, \bar{X}_t, t)^\top \Sigma(X_t))$ (that is $\mathbf{E}[\frac{\partial}{\partial t}\mathcal{V}(Y_t,t) + \frac{\partial}{\partial y}\mathcal{V}\frac{dY_t}{dt}] \leqslant 0$) holds for any twice continuously differentiable function $f \in \mathcal{F}_{0, \infty}$, and any trajectory $(X_t, \bar{X}_t)$ generated by the SDE under Polyak-Ruppert averaging~\eqref{ODE_mean1}. 
 \smallbreak
 This problem is equivalent with verifying that $\frac{d}{dt}\mathcal{V}(\tilde{Y}_t,t) \leqslant 0$ holds for any function twice continuously differentiable $f \in \mathcal{F}_{0, \infty}$ and any trajectory $\tilde{Y}_t = \begin{pmatrix} \tilde{X}_t & \tilde{\bar{X}}_t\end{pmatrix}^\top $ generated by deterministic gradient flow from the SDE~\eqref{ODE_mean1} with $\gamma = 0$. 
\smallbreak
We follow the methodology developed in Section~\ref{sec:deterministic} for ODEs. We formulate the verification of such a Lyapunov function as the maximization problem
\begin{equation*}
    \begin{aligned}
      0\geqslant \max_{X_t \in \mathbf{R}^d,  d\in \mathbf{N}, \ f\in \mathcal{F}_{0, \infty}} \ & \ \frac{d}{dt}  \mathcal{V}_{a^{(1)}_t, a^{(2)}_t, P_t}(X_t, \bar{X}_t, t)\\
      \text{subject to }
    \ \dot{X}_t &= -h_t\nabla f(\bar{X}_t), \
        \dot{\bar{X}}_t = \frac{X_t - \bar{X}_t}{t}dt.
\end{aligned}
\end{equation*}
This maximization problem can be formulated as the following SDP program

\begin{equation*}
    \begin{aligned}
    & \min_{\lambda_t^{(i)} \geqslant 0, \ i \in \{1, ..., 6 \}} \ 0 \, \\
&\begin{pmatrix} \dot{p}^{(11)}_t + \frac{2p^{(12)}_t}{t} & \dot{p}^{(12)}_t + \frac{p^{(22)}_t - p^{(12)}_t}{t}& \frac{\lambda^{(6)}_t + \lambda^{(4)}_t - 2h_tp^{(11)}_t}{2} & \frac{a^{(2)}_t}{2t} - \frac{\lambda^{(5)}_t}{2}\\ 

\dot{p}^{(12)}_t + \frac{p^{(22)}_t - p^{(12)}_t}{t} & \dot{p}^{(22)}_t - \frac{2p^{(22)}_t}{t} & -\frac{\lambda^{(6)}_t - 2h_tp^{(12)}_t}{2} & -\frac{a^{(2)}_t}{2t} + \frac{\lambda^{(5)}_t + \lambda^{(3)}_t}{2}\\ 

 \frac{\lambda^{(6)}_t + \lambda^{(4)}_t - 2h_tp^{(11)}_t}{2} & -\frac{\lambda^{(6)}_t - 2h_tp^{(12)}_t}{2} & -a^{(1)}_t & 0 \\ 

\frac{a^{(2)}_t}{2t} - \frac{\lambda^{(5)}_t}{2} & -\frac{a^{(2)}_t}{2t} + \frac{\lambda^{(5)}_t + \lambda^{(3)}_t}{2} & 0 &  0\end{pmatrix} \preccurlyeq 0, \\ 
&\dot{a}^{(1)}_t + \lambda^{(1)}_t + \lambda^{(5)}_t = \lambda^{(4)}_t + \lambda^{(6)}_t, \\ 
&\dot{a}^{(2)}_t + \lambda^{(2)}_t + \lambda^{(6)}_t = \lambda^{(3)}_t + \lambda^{(5)}_t + \dot{a}^{(1)}_t. 
\end{aligned}
\end{equation*}
Note that the Gram matrix $G$ and function value vector $F$ to be introduced are different from the setting explored in Section~\ref{sec:deterministic}, more precisely $G = Q^\top Q \succcurlyeq 0, \ Q = [X_t - x_\star, \bar{X}_t - x_\star, g_t, \bar{g}_t]$ and $F = (f(X_t), f(\bar{X}_t), f_\star)$.

The final inequality follows from Ito's formula.
\end{proof}

