Convex optimization is an important tool in the numerical analyst toolbox. It serves, among others, for framing modeling problems in data science and signal processing. We consider optimization problems of the form:
\begin{equation}
    \min_{x \in \mathbf{R}^d} f(x),
    \label{eq:optim}
\end{equation}

\subsection{Assumptions}
\label{sec:assumptions}
Throughout this work, functions to be minimized are convex (see Problem~\eqref{eq:optim}). Under this assumption, stationary points are global minimizers. We restrict ourselves to continuous-time versions of gradient descent, accelerated gradient descent and stochastic gradient descent.
\smallbreak

Let us recall a few basic definitions and properties characterizing the classes of functions under consideration within the next sections. A function $f : \mathbf{R}^d \rightarrow \mathbf{R}$ is convex if for all $x,y \in \mathbf{R}^d$, and for all $\lambda \in [0,1]$, $f(\lambda x + (1-\lambda)y) \leqslant \lambda f(x) + (1-\lambda)f(y)$. Such functions (i.e. with full domain, $\text{dom}(f) = \mathbf{R}^d$) are convex closed proper (CCP) (i.e., their epigraphs are non-empty closed convex sets). For simplicity, we assume in addition differentiability of $f$.  Such a differentiable function $f$ is convex if and only if for all $x,y \in \mathbf{R}^d$, $f(y) \geqslant f(x) + \langle \nabla f(x), y-x \rangle$. A differentiable function $f$ is $L$-smooth if its gradient is $L$-Lipschitz, that is if for any $x,y  \ \in \mathbf{R}^d$:
\begin{equation*}
        \|\nabla f(x) - \nabla f(y)\| \leqslant L \|x-y\|.
\end{equation*}

Smoothness is a common assumption for analyzing optimization methods, that limits the growth rate of the function. A convex differentiable function $f$ is $\mu$-strongly convex if for any $x, y \in \mathbf{R}^d$ it satisfies:
\begin{equation*}
         \|\nabla f(x) - \nabla f(y)\| \geqslant \mu \|x-y\|.
\end{equation*}

Let $f$ be $\mu$-strongly convex (i.e., $f\in\mathcal{F}_{\mu,\infty}$) with $\mu>0$, and $x_\star$ be its unique minimizer such that $f(x_\star) = f_\star$. In this context, it is possible to prove linear convergence of the gradient flow to its stationary point. Scieur et~al.~proved in~\cite[Proposition 1.1]{scieur2017integration} the following convergence bound in function values for the gradient flow:
\begin{equation}
\label{reflyapmu}
f(X_t) - f_\star \leqslant e^{- 2 \mu t}(f(x_0) - f_\star).
\end{equation}

\bigbreak
Given the specific gradient flows studied in this work, it is reasonable to search for Lyapunov functions made of linear combinations of function values, and a quadratic form in the trajectory $X_t$. We simply refer to them as quadratic Lyapunov functions:
\begin{equation}
\label{lyapunov}
    \mathcal{V}_{a,c}(X_t) = a \cdot (f(X_t) - f_\star) + c \cdot \|X_t - x_\star\|^2,
\end{equation}
where $a, c \geqslant 0$ are constants that do not depend on $t$, such that the function $ \mathcal{V}_{a,c}$ is nonnegative and nonincreasing along the flow. Quadratic Lyapunov functions are common for proving convergence of gradient flows and cover for instance the Lyapunov function used to prove convergence of the gradient flow under strong convexity~\eqref{reflyapmu}. Given a Lyapunov function $\mathcal{V}_{a,c}$, the idea is to find the largest nonnegative value $\tau_\star$ such that the condition

\begin{equation}
\label{wc_mu}
    \frac{d}{dt}\mathcal{V}_{a,c}(X_t) \leqslant -\tau_\star \mathcal{V}_{a,c}(X_t),
\end{equation}
holds for any dimension $d \in \mathbf{N}$, any function $f \in \mathcal{F}_{\mu, \infty}$ and any trajectory $X_t$ generated by the gradient flow. After integration, \eqref{wc_mu} allows to obtain a convergence guarantee of the form $\mathcal{V}_{a,c}(X_t) \leqslant e^{-\tau_\star t} \mathcal{V}_{a,c}(X_0)$. Given a certain Lyapunov function $\mathcal{V}_{a,c}$ and a time $t$, we get that the largest acceptable $\tau_\star$ is a solution to:

\begin{equation}
\label{eq:str_pep}
    \begin{aligned}
      -\tau_\star = \max_{X_t \in \mathbf{R}^d, d \in \mathbf{N}, f\in \mathcal{F}_{\mu, \infty}} \ & \  \frac{d}{dt}\mathcal{V}_{a,c}(X_t), \\
      \text{subject to }
    \mathcal{V}_{a,c}(X_t) &= 1, \\
    \dot{X_t} &= - \nabla f (X_t).
\end{aligned}
\end{equation}
This minimization problem is invariant with respect to $t$.

\begin{equation}
\label{eq:interpolation_step}
    \begin{aligned}
      -\tau_\star = \max_{X_t \in \mathbf{R}^d, d \in \mathbf{N}} \ & \ \frac{d}{dt}\mathcal{V}_{a, c}(X_t), \\
      \text{subject to } &\mathcal{V}_{a,c}(X_t) = 1, \\
    &\dot{X}_t = - g_t, \\
    & f_i - f_j -\langle g_j, X_i-X_j\rangle \geqslant \frac{\mu}{2}\|X_i-X_j\|^2, \ \forall i,j=t, \star.
\end{aligned}
\end{equation}

\begin{equation}
\label{SDP}
    \begin{aligned}
      -\tau_\star = \max_{G\succcurlyeq 0, F \in \mathbf{R}^2} & b_0^\top F + {\rm Tr}(A_0G), \\
      \text{subject to }
    & b_1^\top F + {\rm Tr}(A_1G) \geqslant 0, \\
    & b_2^\top F + {\rm Tr}(A_2G) \geqslant 0, \\
    & b_3^\top F + {\rm Tr}(A_3G) = 1. \\
\end{aligned}
\end{equation}
where $A_0 = \begin{pmatrix} 0 & -c \\ -c & -a \end{pmatrix}$, $A_1 = \begin{pmatrix}-\mu/2 & 1/2 \\ 1/2 & 0 \end{pmatrix}$, $A_2= \begin{pmatrix}-\mu/2 & 0 \\ 0 & 0\end{pmatrix}$, $A_3 = \begin{pmatrix}c & 0 \\ 0 & 0 \end{pmatrix}$, $b_0 = [0, 0]^\top$, $b_1 = [-1,\ 1]^\top $, $b_2=[1, \ -1]^\top $ and $b_3 = a[1, \ -1]^\top $. Consider the corresponding Lagrangian, for $F \in \mathbf{R}^2$, $G \succcurlyeq 0$, $\tau \in \mathbf{R}$ and $\lambda_1, \lambda_2 \geqslant 0$:

where $A_0 = \begin{pmatrix} 0 & -c \\ -c & -a \end{pmatrix}$, $A_1 = \begin{pmatrix}-\mu/2 & 1/2 \\ 1/2 & 0 \end{pmatrix}$, $A_2= \begin{pmatrix}-\mu/2 & 0 \\ 0 & 0\end{pmatrix}$, $A_3 = \begin{pmatrix}c & 0 \\ 0 & 0 \end{pmatrix}$, $b_0 = [0, 0]^\top$, $b_1 = [-1,\ 1]^\top $, $b_2=[1, \ -1]^\top $ and $b_3 = a[1, \ -1]^\top $. Consider the corresponding Lagrangian, for $F \in \mathbf{R}^2$, $G \succcurlyeq 0$, $\tau \in \mathbf{R}$ and $\lambda_1, \lambda_2 \geqslant 0$: 
\begin{equation*}
    \begin{aligned}
    \mathcal{L}(F, G, \tau, \lambda_1, \lambda_2) =& b_0^\top F + {\rm Tr}(A_0G) + \tau \cdot (b_3^\top F + {\rm Tr}(A_3G) - 1) \\ 
    & + \lambda_1 \cdot(b_1^\top F + {\rm Tr}(A_1G)) + \lambda_2 \cdot(b_2^\top F + {\rm Tr}(A_2G)).
    \end{aligned}
\end{equation*}

The saddle point of the Lagrangian is given by:
\begin{equation*}
    \begin{aligned}
    \tau_\star &= \min_{\tau, \lambda_1 \geqslant 0, \lambda_2 \geqslant 0} \max_{F, G \succcurlyeq 0} \mathcal{L}(F, G, \tau, \lambda_1, \lambda_2).
\end{aligned}
\end{equation*}

The Lagrangian dual of the SDP~\eqref{SDP} is obtained by maximizing over $F \in \mathbf{R}^2$, $G \succcurlyeq 0$:
\begin{equation*}
    \begin{aligned}
    -\tau_\star =  \min_{\tau, \lambda_1, \lambda_2} & \ -\tau, \\
      \text{subject to } & S = A_0 + \lambda_1 A_1 + \lambda_2 A_2 + \tau A_3 \preccurlyeq 0 \\ 
    &  b_0 +  \lambda_1 b_1 +\lambda_2 b_2  + \tau b_3 = 0, \\
    &  \tau\in \mathbf{R}, \ \lambda_1, \lambda_2 \geqslant 0.
\end{aligned}
\end{equation*}

The corresponding SDE is given by:
\begin{equation}
\label{eq:sme}
    dX_t = -\nabla f(X_t)dt + (\gamma \Sigma(X_t))^{1/2}dB_t,
\end{equation}

Compared to gradient descent, SGD does not converge to a stationary point under constant step sizes~\cite{bach2011, taylor2021stochastic}. Convergence to a stationary point requires diminishing step sizes such as $\gamma_k = \frac{1}{\sqrt{k}}$. Li~et~al.~\cite[Section 4.1]{li2017stochastic} (and later Orvieto~and~Lucchi~\cite[Section 2.1]{orvieto2020continuoustime}) proposed to include this varying learning rate in the dynamics:
\begin{equation*}
    x_{k+1} = x_k - \gamma h_k \nabla f(x_k),
\end{equation*}
where $\gamma$ is the maximum allowed learning rate and $h_k \in [0, 1]$ is the time-varying part. For $h_t \geqslant 0$ a continuous function playing the role of step sizes $h_k$, the SDE is:

where $\gamma$ is the maximum allowed learning rate and $h_k \in [0, 1]$ is the time-varying part. For $h_t \geqslant 0$ a continuous function playing the role of step sizes $h_k$, the SDE is:
\begin{equation}
\label{sme_general}
    dX_t = - h_t \nabla f(X_t)dt + h_t(\gamma \Sigma(X_t))^{1/2}dB_t.
\end{equation}

\smallbreak
In SDE theory, a differential with respect to time of a function of a solution to a stochastic process is given by Ito's Lemma~\cite[Theorem 4.2]{sarkka_solin_2019}.
\begin{lemma}[Ito's Lemma]
Let $g$ be a twice continuously differentiable function, and $X_t$ be a stochastic process solution to the SDE~\eqref{eq:sme}, then
\begin{equation*}
    dg(X_t,t) = \frac{\partial}{\partial t}g(X_t, t)dt + \frac{\partial}{\partial x}g(X_t, t) dX_t + \frac{1}{2}\gamma {\rm Tr}(\frac{\partial^2}{\partial x^2}g(X_t, t)\Sigma(X_t))dt.
\end{equation*}
\end{lemma}

\begin{equation}
\label{ODE_mean1}
    \begin{aligned}
        dX_t &= -h_t\nabla f(X_t)dt + h_t(\gamma \Sigma(X_t))^{1/2} dB_t, \\
        d\bar{X}_t &= \frac{X_t - \bar{X}_t}{t}dt,
        \end{aligned}
    \end{equation}

\begin{equation}
\label{lyap_avg}
    \mathcal{V}_{a^{(1)}_t, a^{(2)}_t, P_t}(X_t, \bar{X}_t, t) = \begin{pmatrix}a^{(1)}_t \\ a^{(2)}_t \end{pmatrix}^\top \!\!\!\begin{pmatrix} f(X_t) - f_\star \\ f(\bar{X_t}) - f_\star \end{pmatrix} + \begin{pmatrix} X_t - X_\star\\ \bar{X_t} - X_\star\end{pmatrix}^\top \!\!\! \left(P_t\otimes I_d\right) \! \begin{pmatrix} X_t - X_\star\\ \bar{X_t} - X_\star\end{pmatrix},
\end{equation}

\begin{equation*}
    \begin{aligned}
      \max_{f \in \mathcal{F}_{0, \infty}, d \in \mathbf{N}, X_t \in \mathbf{R}^d} \ & \ \frac{d}{dt}\mathbf{E}\mathcal{V}_{a^{(1)}_t, a^{(2)}_t, P_t}(X_t, \bar{X}_t, t), \\
       \text{subject to} \ & dX_t = -h_t\nabla f(X_t)dt + h_t(\gamma \Sigma(X_t))^{1/2} dB_t, \\
        & d\bar{X}_t = \frac{X_t - \bar{X}_t}{t}dt.
    \end{aligned}
\end{equation*}

\begin{theorem}
\label{pr_avg_conv}
Let $h_t \geqslant 0$, and $a_t \geqslant 0$, $P_t \succcurlyeq 0$ be continuously differentiable with respect to time. Let  $f \in \mathcal{F}_{0, \infty}$ be a twice continuously differentiable function and $(X_t, \bar{X}_t) \in \mathbf{R}^d \times \mathbf{R}^d$ be a trajectory generated by the SDE under Polyak-Ruppert averaging~\eqref{ODE_mean1}. Let $\mathcal{V}$ be a quadratic function~\eqref{lyap_avg}, such that there exist $\lambda^{(1)}_t, ..., \lambda^{(6)}_t \geqslant 0$ verifying:
\begin{equation*}
    \begin{aligned}
&\begin{pmatrix} \dot{p}^{(11)}_t + \frac{2p^{(12)}_t}{t} & \dot{p}^{(12)}_t + \frac{p^{(22)}_t - p^{(12)}_t}{t}& \frac{\lambda^{(6)}_t + \lambda^{(4)}_t - 2h_tp^{(11)}_t}{2} & \frac{a^{(2)}_t}{2t} - \frac{\lambda^{(5)}_t}{2}\\ 

\dot{p}^{(12)}_t + \frac{p^{(22)}_t - p^{(12)}_t}{t} & \dot{p}^{(22)}_t - \frac{2p^{(22)}_t}{t} & -\frac{\lambda^{(6)}_t - 2h_tp^{(12)}_t}{2} & -\frac{a^{(2)}_t}{2t} + \frac{\lambda^{(5)}_t + \lambda^{(3)}_t}{2}\\ 

 \frac{\lambda^{(6)}_t + \lambda^{(4)}_t - 2h_tp^{(11)}_t}{2} & -\frac{\lambda^{(6)}_t - 2h_tp^{(12)}_t}{2} & -a^{(1)}_t & 0 \\ 

\frac{a^{(2)}_t}{2t} - \frac{\lambda^{(5)}_t}{2} & -\frac{a^{(2)}_t}{2t} + \frac{\lambda^{(5)}_t + \lambda^{(3)}_t}{2} & 0 &  0\end{pmatrix} \preccurlyeq 0, \\ 
&\dot{a}^{(1)}_t + \lambda^{(1)}_t + \lambda^{(5)}_t = \lambda^{(4)}_t + \lambda^{(6)}_t, \\ 
&\dot{a}^{(2)}_t + \lambda^{(2)}_t + \lambda^{(6)}_t = \lambda^{(3)}_t + \lambda^{(5)}_t + \dot{a}^{(1)}_t. 
\end{aligned}
\end{equation*}
Then, the following inequality is satisfied:
\smallbreak 
$\displaystyle\frac{d}{dt}\mathbf{E}\mathcal{V}(X_t, \bar{X}_t, t)\leqslant \frac{1}{2}\mathbf{E}{\rm Tr}\left((a^{(1)}_t\nabla_{xx} f(X_t) + 2p^{(11)}_t I_d)\Sigma(X_t)\right)h_t^2\gamma$.
\end{theorem}

\begin{proof}
The proof follows the method from Section~\ref{sec:methodo} (see Appendix~\ref{sec:A11}).
\end{proof}

\begin{proof}

We rewrite the SDE into 
\begin{equation*}
\begin{aligned}
    \begin{pmatrix} dX_t \\ d\bar{X}_t\end{pmatrix} =& \left(\begin{pmatrix} 0 & 0 \\ \frac{1}{t} & -\frac{1}{t} \end{pmatrix}\otimes I_d\right)\begin{pmatrix} X_t \\ \bar{X}_t\end{pmatrix}dt +\left(\begin{pmatrix}- h_t & 0 \\ 0  & 0  \end{pmatrix}\otimes I_d\right)\begin{pmatrix} \nabla f(X_t) \\ \nabla f(\bar{X}_t) \end{pmatrix}dt \\
    &+\left(\begin{pmatrix}h_t (\gamma\Sigma(X_t))^{1/2} \\ 0\end{pmatrix}\otimes I_d\right)dB_t
\end{aligned}
\end{equation*}
 and denote $Y_t = \begin{pmatrix} X_t \\ \bar{X}_t \end{pmatrix}$. 
 \smallbreak
