\frac{a^{(2)}_t}{2t} - \frac{\lambda^{(5)}_t}{2} & -\frac{a^{(2)}_t}{2t} + \frac{\lambda^{(5)}_t + \lambda^{(3)}_t}{2} & 0 &  0\end{pmatrix} \preccurlyeq 0, \\ 
&\dot{a}^{(1)}_t + \lambda^{(1)}_t + \lambda^{(5)}_t = \lambda^{(4)}_t + \lambda^{(6)}_t, \\ 
&\dot{a}^{(2)}_t + \lambda^{(2)}_t + \lambda^{(6)}_t = \lambda^{(3)}_t + \lambda^{(5)}_t + \dot{a}^{(1)}_t. 
\end{aligned}
\end{equation*}
Note that the Gram matrix $G$ and function value vector $F$ to be introduced are different from the setting explored in Section~\ref{sec:deterministic}, more precisely $G = Q^\top Q \succcurlyeq 0, \ Q = [X_t - x_\star, \bar{X}_t - x_\star, g_t, \bar{g}_t]$ and $F = (f(X_t), f(\bar{X}_t), f_\star)$.

The final inequality follows from Ito's formula.
