			\innprod{\nabla h^\gamma(s)-\nabla h^\gamma(s')}{s-s'}
		{}\leq{}
			\tfrac{L_{h}}{1+\gamma L_{h}}
			\|s-s'\|^2.
		\]
		The claimed smoothness and hypoconvexity follow from the characterization of \eqref{eq:innprod}.
		\qedhere
	\end{proofitemize}
\end{appendixproof}

