				{}+{}
				\innprod{\nabla\sDRS(u^+)}{v-u^+}
				{}+{}
				\nsDRS(v)
				{}+{}
				\tfrac{1}{2\gamma}
				\|u^+-v\|^2
			\\
			{}={} &
