\begin{theorem}[\fy{Rate analysis for Algorithm \ref{algorithm:IR-S-BFGS}}]\label{thm:rate}
\fy{Consider Algorithm \ref{algorithm:IR-S-BFGS}. The following statements hold:}
\begin{itemize}
\item [(a)] Suppose Assumptions \ref{assum:main} and \ref{assum:convex2} hold. Then, there exists \fy{$K\geq2m-1$} such that 
\[\EXP{f(x_{k })}-f^*\leq \left(\frac{\theta\g_0}{\left(\mu_0\sqrt[3]{2}\right)^{1-2\alpha}}\right)\frac{1}{k^{\frac{1}{3}-\e}}, \quad \hbox{for all } k > K,\] 
where $\theta$ is given by \eqref{def:theta}, and $\lambda_{\min}$, $\lambda$, and $\alpha$ are given by \eqref{equ:valuesForAssumH_k}. 
\item [(b)] \fy{Let the scheme be at the $k$th iteration where $k\geq 2m-1$. Then, by the end of the LBFGS \fys{two-loop} recursion, i.e., line $\#$26 in Algorithm \ref{algorithm:IR-S-BFGS}, we have 
\begin{align}\label{eqn:r_Lemma}
  r=H_k\left(\nabla F(x_k,\xi_k)+\mu_k(x_k-x_0)\right),
\end{align}
where $H_{k}$ is defined by \eqref{eqn:H-k}.}
\end{itemize}
\end{theorem}

\begin{proof}
\noindent (a) First, we show that the conditions of Proposition~\ref{prop:mean} are satisfied. Assumption \ref{assum:convex} holds as a consequence of Assumption \ref{assum:convex2}. From Lemma \ref{LBFGS-matrix}(c), Assumption \ref{assump:Hk} holds for any \fy{$k \geq 2m-1$} as well. To show that Assumption \ref{assum:sequences-ms-convergence} holds, we apply Lemma \ref{lemma:mean-sequences}. We have 
\[\frac{a}{b}=\frac{\frac{2}{3}-\e+\frac{2\delta(n+m)}{3}}{1/3}=2-3\e+2\delta(n+m)>1+2\delta\left(m+n\right),\]
where we used $\e<\frac{1}{3}$. Moreover, since $\delta < \frac{1.5\e}{n+m}$, we have $a+b=1-\e +\frac{2\delta(n+m)}{3}<1$. Also, from the values of $a$ and $b$ we have $2b\left(1+\delta\left(m+n\right)\right)=a+\e>a.$
Thus, the conditions of Lemma \ref{lemma:mean-sequences} hold. This implies that there exists $K_0>0$ such that for any $k\geq K_0$,  the sequences $\g_k$ and $\mu_k$ satisfy Assumption \ref{assum:sequences-ms-convergence} with any arbitrary $0<\beta<1$ and for $\rho=\g_0^{-1}\left(\mu_02^b\right)^{2+2\delta(m+n)}$, and with $\lambda_{\min}$, $\lambda$ and $\alpha$ given by \eqref{equ:valuesForAssumH_k}. Let us define $K:=\max\{K_0,2m-1\}$. Since all conditions in Proposition~\ref{prop:mean} are met, \an{from \eqref{ineq:bound}, \eqref{equ:seq}, and by substituting values of $a$, $b$, and $\alpha$, for any $k \geq K$ we obtain}
\begin{align*}\EXP{f(x_{k+1})}-f^*&\leq \theta\g_{k-1}\mu_{k-1}^{2\alpha-1}= \frac{\theta\g_0(k+\kappa-1)^{(1-2\alpha)/3}}{\left(\mu_0\sqrt[3]{2}\right)^{1-2\alpha}k^{2/3-\e-\frac{2}{3}\alpha}}\\ &\leq  \frac{\theta\g_0(k+1)^{(1-2\alpha)/3}}{\left(\mu_0\sqrt[3]{2}\right)^{1-2\alpha}(k+1)^{2/3-\e-\frac{2}{3}\alpha}}=\left(\frac{\theta\g_0}{\left(\mu_0\sqrt[3]{2}\right)^{1-2\alpha}}\right)\frac{1}{(k+1)^{\frac{1}{3}-\e}}.\end{align*}
Through a change of variable from $k+1$ to $k$, we conclude the result. \\

\fy{\noindent (b)  To show \eqref{eqn:r_Lemma}, it suffices to show that
 \begin{align*}
  r=\begin{cases}
    H_{k,m}\left(\nabla F(x_k,\xi_k)+\mu_k(x_k-x_0)\right),  &    \text{if } k \text{ is odd}, \\
    H_{k-1,m}\left(\nabla F(x_k,\xi_k)+\mu_k(x_k-x_0)\right),  &   \text{otherwise},
  \end{cases}
\end{align*}
where $H_{k,m}$ is defined by the recursion \eqref{eqn:H-k-m} for an odd $k$. First, consider the case that $k\geq 2m-1$ is an odd number. As such, at the $k$th iteration, from line $\#$7, we have $i:=\lceil k/2 \rceil$. For clarity of the presentation, throughout \vus{this} proof, we use $K$ (instead of $i$), i.e., $K\triangleq \lceil k/2 \rceil$ \vus{and} $q_{K-t+1}$ \vus{is used to} denote the value of the vector $q \in \mathbb{R}^n$ after being updated at iteration $t$ in line $\#$21. Similarly, we use $r_{t-K+m}$ to denote the value of the vector $r \in \mathbb{R}^n$ after being updated at iteration $t$ in line $\#$25. Also, we use the following definitions:
\begin{align*}
& q_0\triangleq \nabla F(x_k,\xi_k)+\mu_k(x_k-x_0), \quad r_0\triangleq H_{k,0}q_{m},\cr 
&\rho_j\triangleq \frac{1}{y_j^Ts_j}, \hbox{ and }V_j\triangleq \mathbf{I}-\rho_{j}y_js_j^T, \quad \hbox{for all } j=K-(m-1),\ldots, K.
\end{align*}
Consider relation \eqref{eqn:H-k-m}. By applying this recursive relation repeatedly, we obtain
\begin{align}\label{equ:H_kClosedForm}
H_{k,m} &=\left(\prod_{j=1}^{m}V_{K-(m-j)}\right)^TH_{k,0}\left(\prod_{j=1}^{m}V_{K-(m-j)}\right)\\
&+ \rho_{K-m+1}\left(\prod_{j=2}^{m}V_{K-(m-j)}\right)^Ts_{K-m+1}s^T_{K-m+1}\left(\prod_{j=2}^{m}V_{K-(m-j)}\right) \notag\\
& + \rho_{K-m+2}\left(\prod_{j=3}^{m}V_{K-(m-j)}\right)^Ts_{K-m+2}s^T_{K-m+2}\left(\prod_{j=3}^{m}V_{K-(m-j)}\right)\notag\\
& + \ldots\notag\\
& +\rho_{K-1}V^T_{K}s_{K-1}s_{K-1}^TV_{K}\notag\\
&+\rho_{K}s_{K}s_{K}^T.\notag
\end{align}
Next, we derive a formula for $q_t$. From lines $\#$20-21 in the algorithm, we have
\begin{align*}
q_{K-t+1}&=q_{K-t} -\alpha_{K-t+1}y_t =q_{K-t} - \rho_t\left(s_t^Tq_{K-t}\right)y_t = q_{K-t} - \rho_t\left(y_ts_t^T\right)q_{K-t} \\
&= \left( \mathbf{I}-\rho_{t}y_ts_t^T\right)q_{K-t}=V_tq_{K-t}, \quad \hbox{for all } t= K, K-1, \ldots, K-m+1.
\end{align*}
From the preceding relation, we obtain
\begin{align}\label{equ:q_ell}
q_{\ell}=\left(\prod_{j=m-\ell+1}^{m}V_{K-(m-j)}\right)q_0, \quad \hbox{for all } \ell= 1,2, \ldots, m.
\end{align}
From the update rule for $\alpha_{i-t+1}$ in line $\#$20, using the definition of $\rho_t$, and applying the previous relation, we have $\alpha_1=\rho_{K}s_K^Tq_0$ and 
\begin{align}\label{equ:alpha_ell}
\alpha_{\ell}=\rho_{K-\ell+1}s_{K-\ell+1}^T\left(\prod_{j=m-\ell+2}^{m}V_{K-(m-j)}\right)q_0, \quad \hbox{for all } \ell= 2,3, \ldots, m.
\end{align}
\fys{Multiplying both sides of} \eqref{equ:H_kClosedForm} by $q_0$ and employing \eqref{equ:q_ell} and \eqref{equ:alpha_ell}, we obtain
\begin{align}\label{equ:H_kq_0}
H_{k,m}q_0 &=\left(\prod_{j=1}^{m}V_{K-(m-j)}\right)^TH_{k,0}q_m + \left(\prod_{j=2}^{m}V_{K-(m-j)}\right)^Ts_{K-m+1}\alpha_m \\
& + \left(\prod_{j=3}^{m}V_{K-(m-j)}\right)^Ts_{K-m+2}\alpha_{m-1}  +\ldots+V^T_{K}s_{K-1}\alpha_2+s_{K}\alpha_1.\notag
\end{align}
Next, we derive a formula for $r_t$. From line $\#$25 in the algorithm, we have 
\begin{align*}
r_{t-K+m}&=r_{t-K+m-1}+\left(\alpha_{K-t+1}-\rho_ty_t^Tr_{t-K+m-1}\right)s_t \\
&= r_{t-K+m-1}-\rho_ts_t y_t^Tr_{t-K+m-1}+\alpha_{K-t+1}s_t\\
& = V_t^Tr_{t-K+m-1}+\alpha_{K-t+1}s_t, \quad \hbox{for all } t= K-m+1,\ldots,K-1,  K.
\end{align*}
Combining the preceding two relations, we obtain
\begin{align*}
r_{\ell}&= V_{K-(m-\ell)}^Tr_{\ell-1}+\alpha_{m-\ell+1}s_{K-(m-\ell)}, \quad \hbox{for all } \ell= 1,2,\ldots,m.
\end{align*}
Using the preceding equation repeatedly, we obtain
\begin{align}\label{equ:r_m}
r_m &=\left(\prod_{j=1}^{m}V_{K-(m-j)}\right)^Tr_0 +\alpha_m \left(\prod_{j=2}^{m}V_{K-(m-j)}\right)^Ts_{K-m+1} \\
& + \alpha_{m-1} \left(\prod_{j=3}^{m}V_{K-(m-j)}\right)^Ts_{K-m+2} +\ldots+\alpha_2V^T_{K}s_{K-1}+\alpha_1s_{K}.\notag
\end{align}
From \eqref{equ:r_m} and \eqref{equ:H_kq_0}, and the definition of  $r_0$, we obtain $r_m=H_{k,m}q_0$. Taking to account the definition of $q_0$, the desired result holds for any odd $k\geq 2m-1$. Now, consider the case where $k\geq 2m-1$ is an even number. This implies that the ``if'' condition in line $\#$6 is skipped and as such, the value of $i$ is not updated from the iteration $k-1$, i.e.,  $i= \lceil (k-1)/2 \rceil$. Consequently, the LBFGS two-loop recursion at an even $k$ uses the following pairs 
$$\left\{(s_\ell,y_\ell)\mid \ell=\lceil (k-1)/2\rceil-m+1, \lceil (k-1)/2\rceil-m+2,\ldots,\lceil (k-1)/2\rceil\right\}.$$
\fys{Now,} considering the definition \eqref{eqn:H-k-m} for $k-1$, the desired relation can be shown following the same steps discussed for the case the iteration number is odd.}
%This implies the desired rate statement holds. 
\end{proof}

