compact.
\end{assumption}

\begin{assumption} \label{assum:fC22}
The function $f$ is twice uniformly Lipschitz continuously
differentiable on an open neighborhood of $\mathcal{L}_f(x_0)$
\refer{that includes the trial points generated by the algorithm. We
  denote by $L_H$ the Lipschitz constant for $\nabla^2 f$ on this
  neighborhood}.
%% \crcomment{Removed $L_g$ because it is not used anywhere else in
%% the paper and we already have multiple notations for Hessian norms
%% or their approximations. We only need Lipschitz continuous
%% Hessians, and bounded gradients/Hessians (the latter implying that
%% the gradient is Lipschitz continuous).}
%\sjwcomment{I made changes. OK now? CR: Ok.}
\end{assumption}

For any $x$ and $d$ such that Assumption~\ref{assum:fC22} is satisfied at $x$ 
and $x+d$, we have
\begin{equation} \label{eq:LH}
f(x+d) \le f(x) + \nabla f(x)^\top d + \frac12 d^\top \nabla^2 f(x) d
+ \frac{L_H}{6} \| d\|^3.
\end{equation}

\begin{algorithm}[ht!]
\caption{Capped Conjugate Gradient}
\label{alg:ccg}
\begin{algorithmic}
\STATE \emph{Inputs:} Symmetric matrix $H \in \R^{n \times n}$; 
vector $g \ne 0$; damping parameter $\epsilon \in (0,1)$; desired relative 
accuracy \refer{$\zeta \in (0,1)$};
\STATE \refer{\emph{Optional input:} scalar $M$ (set to $0$ if not provided)};
\STATE \refer{\emph{Outputs:} d\_type, $d$;}
\STATE \refer{\emph{Secondary outputs:} final values of $M$, $\kappa$, 
$\hat{\zeta}$, $\tau$, and $T$;}
\STATE Set
\[
\bH:=H+2\eps I, \quad \kappa := \frac{M+2\eps}{\eps}, \quad \hat{\zeta} := \frac{\zeta}{3 \kappa},
\quad
\tau := \frac{\sqrt{\kappa}}{\sqrt{\kappa}+1}, \quad
T:=\frac{4\kappa^4}{(1-\sqrt{\tau})^2};
\]
\STATE $y_0 \leftarrow 0$, $r_0 \leftarrow g$, $p_0 \leftarrow -g$, $j \leftarrow 0$; 
\IF{$p_0^\top \bH p_0 < \eps \|p_0\|^2$}
\STATE Set $d=p_0$ and terminate with d\_type=NC;
\ELSIF{\refer{$\|H p_0\| > M \|p_0\|$}}
\STATE \refer{Set $M \leftarrow {\|H p_0\|}/{\|p_0\|}$ 
and update $\kappa,\hat{\zeta},\tau,T$ accordingly;}
\ENDIF
\WHILE{TRUE}
\STATE $\alpha_j \leftarrow {r_j^\top r_j}/{p_j^\top \bH p_j}$;
\COMMENT{Begin Standard CG Operations}
\STATE $y_{j+1} \leftarrow y_j+\alpha_j p_j$;
\STATE $r_{j+1} \leftarrow r_j + \alpha_j \bH p_j$;
\STATE $\beta_{j+1} \leftarrow {(r_{j+1}^\top r_{j+1})}/{(r_j^\top r_j)}$;
\STATE $p_{j+1} \leftarrow  -r_{j+1} + \beta_{j+1}p_j$;
\COMMENT{End Standard CG Operations}
\STATE $j \leftarrow  j+1$;
\IF{\refer{$\|H p_j\| > M \|p_j\|$}}
\STATE \refer{Set $M \leftarrow {\|H p_j\|}/{\|p_j\|}$ 
and update $\kappa,\hat{\zeta},\tau,T$ accordingly;}
\ENDIF
\IF{\refer{$\|H y_j\| > M \|y_j\|$}}
\STATE \refer{Set $M \leftarrow {\|H y_j\|}/{\|y_j\|}$ 
and update $\kappa,\hat{\zeta},\tau,T$ accordingly;}
\ENDIF
\IF{\refer{$\| H r_j\| > M \|r_j\|$}}
\STATE \refer{Set $M  \leftarrow {\| H r_j\|}/{\|r_j\|}$ 
and update $\kappa,\hat{\zeta},\tau,T$ accordingly;}
\ENDIF
\IF{$y_j^\top \bH y_j < \epsilon \|y_j\|^2$}
\STATE Set $d \leftarrow y_j$ and terminate with d\_type=NC;
%\ELSIF{$\| r_j \| \le \tfrac{1}{2}\min\{\zeta\|r_0\|,\eps \|y_j\|\}$}
\ELSIF{$\| r_j \| \le \hat{\zeta} \|r_0\|$}
\STATE Set $d \leftarrow y_j$ and terminate with d\_type=SOL;
\ELSIF{$p_j^\top \bH p_j < \eps \|p_j\|^2$}
\STATE Set $d \leftarrow p_j$ and terminate with d\_type=NC;
\ELSIF{$\|r_j\| >  \sqrt{T}\tau^{j/2} \|r_0\|$
%\crnote{The key here is 
%that when we terminate because of this condition, we are sure that 
%$\|H v\| \le (M+2\eps)\|v\|$ for $v\in \{p_0,\dots,p_j,y_0,\dots,y_j,r_0,\dots,r_j\}$ 
%and this is all we need. As long as the residual norm decreases at the 
%desired rate, things are okay because $\sqrt{T}\tau^{j/2}$ is an 
%increasing function of $M$.}
}
\STATE Compute $\alpha_j,y_{j+1}$ as in the main loop above;
\STATE Find $i \in \{0,\dotsc,j-1\}$ such that
\begin{equation} \label{eq:weakcurvdir}
	\frac{(y_{j+1}-y_i)^\top \bH (y_{j+1}-y_i)}{\|y_{j+1}-y_i\|^2} \; < \; \eps;
\end{equation}
\STATE Set $d \leftarrow y_{j+1}-y_i$ and terminate with d\_type=NC;
\ENDIF
\ENDWHILE
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[ht!]
\caption{Minimum Eigenvalue Oracle}
\label{alg:meo}
\begin{algorithmic}
%  \STATE \emph{Inputs:} Symmetric matrix $H \in \R^{n \times n}$,
%  scalar $M$ such that $\lambdamax(H) \le M$, and $\epsilon>0$;
%  \STATE Set parameter $\delta \in [0,1)$;
  \STATE \emph{Inputs:} Symmetric matrix $H \in \R^{n \times n}$,
  \refer{tolerance $\epsilon>0$};
  \STATE \refer{\emph{Optional input:} Upper bound on Hessian norm 
  $M$;}
  \STATE \emph{Outputs:} An estimate $\lambda$ of $\lambdamin(H)$
  such that $\lambda \le - \epsilon/2$, and vector $v$
  with $\|v\|=1$ such that $v^\top H v =\lambda$ OR
  a certificate that $\lambdamin(H) \ge -\epsilon$. In the latter case, when
  the certificate is output, it is false with probability $\delta$ 
  \refer{for some $\delta \in [0,1)$}.
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[ht!]
\caption{Damped Newton-CG}
\label{alg:dncg}
\begin{algorithmic}
\STATE \emph{Inputs:} Tolerances  $\epsg>0$, $\epsH>0$; backtracking 
parameter $\theta \in (0,1)$; starting point $x_0$; 
\refer{accuracy parameter $\zeta \in (0,1)$;}
\STATE \refer{\emph{Optional input:} Upper bound  $M > 0$ on Hessian 
norm};
%\STATE \refer{\emph{Optional input:} Upper bound  $U_H > 0$ on Hessian 
%norm}; 
\FOR{$k=0,1,2,\dotsc$}
\IF{$\|\nabla f(x_k)\| > \epsg$}
\STATE Call Algorithm~\ref{alg:ccg} with $H = \nabla^2 f(x_k)$, $\epsilon=\epsH$, 
$g=\nabla f(x_k)$, accuracy parameter $\zeta$ and $M$ if provided, 
to obtain outputs $d$, d\_type; 
\IF{d\_type=NC}
\STATE $d_k \leftarrow -\mathrm{sgn}(d^\top g) \frac{|d^\top \nabla^2 f(x_k) d|}{\|d\|^2} 
\frac{d}{\|d\|}$;
\ELSE[\refer{d\_type=SOL}]
\STATE $d_k \leftarrow d$;
\ENDIF
\STATE Go to \textbf{Line Search};
\ELSE
\STATE Call Procedure~\ref{alg:meo} with $H = \nabla^2 f(x_k)$,
$\epsilon=\epsH$ and $M$ if provided; 
\IF{Procedure~\ref{alg:meo} certifies that $\lambdamin(\nabla^2 f(x_k)) \ge -\epsH$}
\STATE
Terminate; 
\ELSE[\refer{direction of sufficient negative curvature found}]
\STATE 
$d_k \leftarrow -\mathrm{sgn}(v^\top g) \frac{|v^\top \nabla^2 f(x_k) v|}{\|v\|^2} v$
% \sjwnote{Holy smokes, the last $v$ was missing from this formula!}
(where $v$ is the output from Procedure~\ref{alg:meo})
and go to \textbf{Line Search};
\ENDIF
\ENDIF
\STATE \textbf{Line Search}: Compute a step length $\alpha_k=\theta^{j_k}$, 
where $j_k$ is the smallest nonnegative integer such that
\begin{equation} \label{eq:lsdecreasedamped}
	f(x_k + \alpha_k d_k) < f(x_k) - \frac{\eta}{6}\alpha_k^3 \|d_k\|^{3};
\end{equation}
\STATE $x_{k+1} \leftarrow x_k+\alpha_k d_k$;
\ENDFOR
\end{algorithmic}
\end{algorithm}

\begin{assumption} \label{assum:wccmeo}
For every iteration $k$ at which Algorithm~\ref{alg:dncg} calls
Procedure~\ref{alg:meo}, and for a specified failure probability
$\delta$ with $0 \le \delta \ll 1$, Procedure~\ref{alg:meo} either
certifies that $\nabla^2 f(x_k) \succeq -\epsH I$ or finds a vector
of curvature smaller than $-{\epsH}/{2}$ in at most
%% \crcomment{Changed the value to reflect our new bounds on the
%% number of iterations.}
\begin{equation} \label{eq:wccmeo}
		N_{\mathrm{meo}}:=\min\left\{n,
		1+\left\lceil\Cmeo\epsH^{-1/2}\right\rceil\right\}
\end{equation}
Hessian-vector products, \refer{with probability $1-\delta$,} where
$\Cmeo$ depends at most logarithmically on $\delta$ and $\epsH$.
%\sjwcomment{I changed some more. Is this OK? CR: Yes.}
%% \crcomment{Modified the last part of the assumption to cope with 
%% the discussion before Corollary~\ref{coro:wcc2Hv}, where $\Cmeo$ depends 
%% on $\epsH$ through $\delta$. That also avoids mentioning this logarithmic 
%% dependency in the statement of the corollary.}
\end{assumption}

\begin{algorithm}[ht!]
\caption{Conjugate Gradient}
\label{alg:cg}
\begin{algorithmic}
  \STATE \emph{Inputs:} Symmetric matrix $\bH$, vector $g$;
  \STATE $r_0 \leftarrow g$, $p_0 \leftarrow -r_0$, $y_0 \leftarrow 0$, $j \leftarrow 0$;
  \WHILE{$p_j^\top\bH p_j>0$ and $r_j \ne 0$}
  \STATE $\alpha_j \leftarrow {r_j^\top r_j}/{p_j^\top \bH p_j}$;
\STATE $y_{j+1} \leftarrow y_j+\alpha_j p_j$;
\STATE $r_{j+1} \leftarrow r_j + \alpha_j \bH p_j$;
\STATE $\beta_{j+1} \leftarrow {(r_{j+1}^\top r_{j+1})}/{(r_j^\top r_j)}$;
\STATE $p_{j+1} \leftarrow -r_{j+1} + \beta_{j+1}p_j$;
\STATE $j \leftarrow j+1$;
\ENDWHILE
\end{algorithmic}
\end{algorithm}

Here and below, we refer often to the following quadratic function:
\begin{equation} \label{eq:quadraticCG}
	q(y) := \frac{1}{2}y^\top \bH y + g^\top y,
\end{equation}

proof.raw_tex:
\begin{lemma} \label{lemma:ccgits}
The number of iterations of Algorithm~\ref{alg:ccg} is bounded by
\[
\min\{n,J(M,\eps,\zeta)\},
\]
where $J=J(M,\eps,\zeta)$ is the smallest integer such that
$\sqrt{T}\tau^{J/2} \le \hat{\zeta}$ \refer{where $M$, $\hat\zeta$,
  $T$, and $\tau$ are the values returned by the algorithm}. \refer{If
  all iterates $y_i$ generated by the algorithm are stored, the number
  of matrix-vector multiplications required is bounded by
\begin{equation} \label{eq:pv8}
	\min\{n,J(M,\eps,\zeta)\}+1.
\end{equation}
If the iterates $y_i$ must be regenerated in order to define the
direction $d$ returned after \eqref{eq:weakcurvdir}, this bound
becomes $2\min\{n,J(M,\eps,\zeta)\}+1$.}
\end{lemma}

\begin{proof}
  If the full $n$ iterations are performed, without any of the
  termination conditions being tripped, the standard properties of CG
  (see Appendix~\ref{app:cgresults}) ensure that the final residual
  $r_n$ is zero, so that the condition $\|r_n \| \le \hat\zeta
  \|r_0\|$ is satisfied, and termination occurs.

  \refer{Since no more than $n$ iterations are performed, the upper
    bound $M$ is updated at most a finite number of times, so the
    quantity $J$ is well defined.}

  Supposing that $J<n$, we note from the definition of $J$ that
  $\sqrt{T}\tau^{J/2} \|r_0 \| \le \hat\zeta \|r_0\|$. Thus at least
  one of the following two conditions must be satisfied at iteration
  $J$: $\|r_{J} \| \le \hat\zeta \|r_0\|$ or $\|r_{J} \| >
  \sqrt{T}\tau^{J/2} \|r_0\|$. In either case, termination will occur
  at iteration $J$, unless it has occurred already at a previous
  iteration.

  To derive \eqref{eq:pv8}, note that the main workload at each
  iteration $j$ is computation of a single matrix-vector product
%  \refer{$H p_j$ (since matrix-vector products involving the matrices
%    $H$ and $\bH$ and the vectors $y_j$ and $r_j$ can be computed in
%    terms of this vector, in an additional $O(n)$ operations).}
%  \refer{(The ``$+1$'' in \eqref{eq:pv8} is from the additional
%    matrix-vector multiplication required in the case of $\|r_{J} \| >
%    \sqrt{T}\tau^{J/2} \|r_0\|$.)}
  \refer{$H p_j$ after the increment of $j$ (since 
    matrix-vector products involving the matrices
    $H$ and $\bH$ and the vectors $y_j$ and $r_j$ can be computed in
    terms of this vector, in an additional $O(n)$ operations).}
  \refer{(The ``$+1$'' in \eqref{eq:pv8} accounts for the initial
    matrix-vector multiplication $H p_0$ performed prior to entering 
    the loop.)}
%    \crcomment{I think the new tests based on $M$ changed the 
%    places in which we compute the $H p_j$, so I corrected this 
%    paragraph. The result still holds, but the +1 relates to the 
%    initial step (before the loop). Note that the four termination 
%    tests do not require additional matrix-vector products since $Hp_j$ 
%    has already been computed for the $M$-related tests.
%    MO: Changed account to accounts.}

  If we do not store additional information, we need to regenerate the
  information needed to compute the direction $d$ satisfying
  \eqref{eq:weakcurvdir} by re-running the iterations of CG, possibly
  up to the \refer{second-to-last} iteration. This fact accounts for
  the additional cost of $\min\{n,J(M,\eps,\zeta)\}$ in the no-storage
  case. \footnote{\refer{Interestingly, as we show in
      Appendix~\ref{app:cgresults}, the ratios on the left-hand side
      of \eqref{eq:weakcurvdir} can be calculated without knowledge of
      $y_i$ for $i=0,1,\dotsc,j-1$, provided that we store the scalar
      quantities $\alpha_i$ and $\|r_i\|^2$ for $i=0,1,\dotsc,j-1$.}}
\end{proof}

\refer{Note that $J(M,\epsilon,\zeta)$ is an increasing function of
  $M$, since $\hat{\zeta}$ is a decreasing function of $M$, while $T$
  and $\tau$ (and thus $\sqrt{T}\tau^{j/2}$) are increasing in $M$. If
  $U_H$ is known in advance, we can call Algorithm~\ref{alg:ccg} with
  $M = U_H$ and use $J(U_H,\epsilon,\zeta)$ as the bound. Alternately,
  we can call Algorithm~\ref{alg:ccg} with $M=0$ and let it adjust $M$
  as needed during the computation. Since the final value of $M$ will
  be at most $U_H$, and since $J(M,\epsilon,\zeta)$ is an increasing
  function of $M$, the quantity $J(U_H,\epsilon,\zeta)$ provides the
  upper bound on the number of iterations in this case too.}

We can estimate $J$ by taking logs in its definition, as follows:
\[
J \le \frac{2\ln(\hat{\zeta}/\sqrt{T})}{\ln(\tau)} =
\frac{\ln(\hat{\zeta}^2/T)}
     {\ln\left(\frac{\sqrt{\kappa}}{\sqrt{\kappa}+1}\right)} =
     \frac{\ln(T/\hat{\zeta}^2)}{\ln(1+{1}/{\sqrt{\kappa}})} \le
     \left(\sqrt{\kappa}+\frac{1}{2}\right)
     \ln\left(\frac{T}{\hat{\zeta}^2}\right),
\]
where we used $\ln(1+\tfrac{1}{t}) \ge \tfrac{1}{t+1/2}$ to obtain the
latest inequality. By
replacing $T,\tau,\hat{\zeta},\kappa$ by their
definitions in Algorithm~\ref{alg:ccg}, and using
$
\frac{1}{1-\sqrt{\tau}} = \frac{1+\sqrt{\tau}}{1-\tau} \le
\frac{2}{1-\tau},
$
we obtain
\begin{align} \nonumber
%% J(M,\eps,\zeta) &  \le
%% \min\left\{n,\left\lceil \left(\sqrt{\frac{M+2\eps}{\eps}}+\frac{1}{2}\right)
%% \ln\left(\frac{144 \left(\sqrt{\frac{M+2\eps}{\eps}}+1\right)^2
%%   \left(\frac{M+2\eps}{\eps}\right)^6} {\zeta^2}\right) \right\rceil \right\} \\
J(M,\eps,\zeta) &  \le
\refer{\min\left\{n,\left\lceil \left(\sqrt{\kappa}+\frac{1}{2}\right)
\ln\left(\frac{144 \left(\sqrt{\kappa}+1\right)^2
  \kappa^6} {\zeta^2}\right) \right\rceil \right\}} \\
\label{eq:HvcountcappedCG}
 & = \min \left\{ n , \tcO(\eps^{-1/2}) \right\}.
\end{align}


\begin{theorem} \label{theo:cvCGwhilestronglycvx}
Suppose that the main loop of Algorithm~\ref{alg:ccg} terminates with
$j=\hIcg$, where
\[
\hIcg \in \{1,\dotsc,\min\{n,J(M,\eps,\zeta)\}\},
\]
(where $J(M,\eps,\zeta)$ is defined in Lemma~\ref{lemma:ccgits} and
\eqref{eq:HvcountcappedCG}) \refer{because the fourth termination test is
satisfied and the three earlier conditions do not hold, that is, 
$y_{\hIcg}^\top \bH y_{\hIcg} \ge \eps \|y_{\hIcg}\|^2$, 
$p_{\hIcg}^\top \bH p_{\hIcg} \ge \eps \|p_{\hIcg}\|^2$, and
\begin{equation} \label{eq:Kitsstronglycvx}
\|r_{\hIcg}\| > \max\{\hat{\zeta},\sqrt{T}\tau^{\hIcg /2}\}\|r_0\|.
\end{equation}
where $M$, $T$, $\hat{\zeta}$, and $\tau$ are the values returned by
Algorithm~\ref{alg:ccg}. Then
$y_{\hIcg+1}$ is computed by Algorithm~\ref{alg:ccg}, and we have}
\begin{equation} \label{eq:yKp1negcurv}
\frac{(y_{\hIcg +1}-y_i)^\top \bH (y_{\hIcg+1}-y_i)}
{\|y_{\hIcg+1}-y_i\|^2} < \eps, \quad \mbox{for some $i \in \{0,\dotsc,\hIcg-1\}$.}
\end{equation}
\end{theorem}

\begin{lemma} \label{lemma:ccgsteps}
Let Assumptions~\ref{assum:compactlevelset} and~\ref{assum:fC22} hold,
and suppose that Algorithm~\ref{alg:ccg} is invoked at an iterate
$x_k$ of Algorithm~\ref{alg:dncg} (so that $\|\nabla f(x_k)\| >
\epsg>0$).
Let $d_k$ be the vector obtained in Algorithm~\ref{alg:dncg} from the
output $d$ of Algorithm~\ref{alg:ccg}. Then, one of the two following
statements holds:
\begin{enumerate}
\item {\em d\_type=SOL}, and the direction $d_k$ satisfies 
\begin{subequations} \label{eq:ccgstepSOL} 
\begin{align}
\label{eq:ccgstepSOLcurv}
d_k^\top (\nabla^2 f(x_k)+2\epsH I) d_k & \ge \epsH \|d_k\|^2, \\
\label{eq:ccgstepSOLnorm}
% \|d_k\| & \le \epsH^{-1} \sqrt{1+\zeta^2/4} \|\nabla f(x_k)\|,\\
\|d_k\| & \le \refer{1.1 \epsH^{-1} \|\nabla f(x_k)\|,}\\
\label{eq:ccgstepSOLres}
%% \|\hat{r}_k \| \le  
%% \frac{\hat{\zeta}}{1-\hat{\zeta}}(U_H+2\epsH)\|d_k\| & \le 
%% \frac{1}{2}\epsH\zeta \| d_k \|,
\|\hat{r}_k \|  & \le  \refer{\frac{1}{2}\epsH\zeta \| d_k \|,}
\end{align}
\end{subequations}
where
\begin{equation} \label{eq:def.rhat}
\hat{r}_k := (\nabla^2 f(x_k)+2\epsH I) d_k+ \nabla f(x_k);
\end{equation}
\item {\em d\_type=NC}, and the direction $d_k$ satisfies 
  $d_k^\top \nabla f(x_k) \le 0$ as well as
  \refer{
  \begin{equation} \label{eq:ccgstepNC}
    \frac{d_k^\top \nabla^2 f(x_k) d_k}{\|d_k\|^2} = -\|d_k \| \le -\epsH.
  \end{equation}
  }
%% \begin{subequations} \label{eq:ccgstepNC}
%% \begin{align}
%% \label{eq:ccgstepNCcurv}
%% \frac{d_k^\top \nabla^2 f(x_k) d_k}{\|d_k\|^2} \le -\epsH,\\
%% \label{eq:ccgstepNCnorm}
%% \|d_k\| \ge \epsH.
%% \end{align}
%% \end{subequations}
\end{enumerate}
\end{lemma}

\begin{proof}
\refer{For simplicity of notation, we use $H=\nabla^2 f(x_k)$ and
  $g=\nabla f(x_k)$ in the proof.}  Suppose first that d\_type=SOL. In
that case, we have from the termination conditions in
Algorithm~\ref{alg:ccg} and \eqref{eq:def.rhat} that
\begin{subequations} \label{eq:propSOLstep}
\begin{align} 
\label{eq:propSOLstepCURV}
d_k^\top (H+2 \epsH I)d_k & \ge \epsH \|d_k\|^2, \\
\label{eq:propSOLstepRES}
\|\hat{r}_k \| &  \le \hat{\zeta} \|g\|,
\end{align}
\end{subequations}
\refer{where $\hat\zeta$ was returned by the algorithm.}
We immediately recognize~\eqref{eq:ccgstepSOLcurv}
in~\eqref{eq:propSOLstepCURV}.  We now
prove~\eqref{eq:ccgstepSOLnorm}. Observe first 
that \eqref{eq:propSOLstepCURV} yields
\[
\epsH\|d_k\|^2 \le d_k^\top (H+2 \epsH I) d_k \le \|d_k\| \|(H+2\epsH
I) d_k\|,
\]
so from \eqref{eq:def.rhat} we have
\begin{equation*}
\|d_k\| \le \epsH^{-1} \|(H+2\epsH I)d_k\| = \epsH^{-1} \|-g+\hat{r}_k\| 
= \epsH^{-1} \sqrt{\|g\|^2 + \| \hat{r}_k \|^2} \le 
\epsH^{-1} \sqrt{1+\hat{\zeta}^2}  \|g\|,
\end{equation*}
where we used~\eqref{eq:propSOLstepRES} to obtain the final bound,
together with the equality $\|-g+\hat{r}_k\|^2=\|g\|^2+\| \hat{r}_k
\|^2$, which follows from $g^\top \hat{r}_k = r_0^\top \hat{r}_k =
0$, by orthogonality of the residuals in CG (see
Lemma~\ref{lemma:propertiesCGoneiter}, Property 2). Since
\refer{$\hat{\zeta} \le \zeta/(3 \kappa) \le 1/6$ by construction, we
  have $\|d_k \| \le \sqrt{37/36} \epsH^{-1} \|g\| \le 1.1 \epsH^{-1}
  \|g\|$, proving \eqref{eq:ccgstepSOLnorm}.}

The bound \eqref{eq:ccgstepSOLres} follows
from~\eqref{eq:propSOLstepRES} and the logic below:
\begin{align*}
	\| \hat{r}_k \| &\le \hat{\zeta} \|g\| \le 
	\hat{\zeta}\left(\|(H+2 \epsH I) d_k \| + 
	\| \hat{r}_k \|\right)  \le \hat\zeta \left( (M+2\epsH) \|d_k \| +  \| \hat{r}_k \| \right) \\
        \Rightarrow \;\; \| \hat{r}_k \| &\le 
	\frac{\hat{\zeta}}{1-\hat{\zeta}}(M+2 \epsH) \|d_k\|,
\end{align*}
\refer{where $M$ is the value returned by the algorithm.}
We finally use \refer{$\hat\zeta < 1/6$}
%% \[
%% \hat\zeta = \frac{\zeta}{3}\frac{\epsH}{M+2\epsH} \le
%% \frac{\zeta}{3} \frac12 < \frac16,
%% \]
to arrive at
\[
\frac{\hat\zeta}{1-\hat{\zeta}} (M+2\epsH) \le \frac65 \hat{\zeta}
(M+2\epsH) = \frac65 \frac{\zeta \epsH}{3} < \frac12 \zeta \epsH,
\]
yielding  \eqref{eq:ccgstepSOLres}.

In the case of d\_type=NC, we recall that Algorithm~\ref{alg:dncg}
defines
\begin{equation} \label{eq:scaleccgNC}
d_k = -\mathrm{sgn}(d^\top g) \frac{|d^\top H
  d|}{\|d\|^2} \frac{d}{\|d\|}
\end{equation}
where $d$ denotes the direction obtained by
Algorithm~\ref{alg:ccg}. It follows immediately that $d_k^\top g \le
0$. Since $d_k$ and $d$ are collinear, we also have that
\refer{
\[
\frac{d_k^\top (H+2\epsH I)d_k}{\|d_k\|^2} = \frac{d^\top (H+2\epsH
  I)d}{\|d\|^2} \le \epsH \; \Rightarrow \; \frac{d_k^\top H
  d_k}{\|d_k\|^2}
% = \frac{d^\top H d}{\|d\|^2}
\le -\epsH.
\]
By using this bound together with \eqref{eq:scaleccgNC}, we obtain
\[
\|d_k\| = \frac{|d^\top H d|}{\|d\|^2} = \frac{|d_k^\top H d_k|}{\|d_k\|^2} =
-\frac{d_k^\top H d_k}{\|d_k\|^2} \ge \epsH,
\]
proving \eqref{eq:ccgstepNC}.
}
%% establishing \eqref{eq:ccgstepNCcurv}.  By \eqref{eq:scaleccgNC}, we
%% then have
%% \[
%% \|d_k\| = \frac{|d^\top H d|}{\|d\|^2} \ge \epsH,
%% \]
%% proving \eqref{eq:ccgstepNCnorm}.
\end{proof}

\begin{lemma} \label{lemma:LSccgSOL}
Suppose that Assumptions~\ref{assum:compactlevelset}
and~\ref{assum:fC22} hold. Suppose that at iteration $k$ of
Algorithm~\ref{alg:dncg}, we have $\|\nabla f(x_k)\| > \epsg$, so
that Algorithm~\ref{alg:ccg} is called. When Algorithm~\ref{alg:ccg}
outputs a direction $d_k$ with d\_type=SOL, then the backtracking line
search requires at most $j_k \le \jsol+1$ iterations, where
\begin{equation} \label{eq:ccglsitsSOL}
\jsol \; = \; \left[ \frac{1}{2}\log_{\theta}\left(
  \frac{3(1-\zeta)}{L_H+\eta} \frac{\epsH^2}{\refer{1.1} U_g} \right)
  \right]_+,
\end{equation}
and the resulting step $x_{k+1} = x_k + \alpha_k d_k$ satisfies
\begin{equation} \label{eq:ccglsdecreaseSOL}
f(x_k) - f(x_{k+1}) \; \ge \; 
\csol\min\left(\|\nabla f(x_{k+1})\|^3 \epsH^{-3},\epsH^3\right),
\end{equation}
where 
\begin{equation*}
\csol = \frac{\eta}{6}\min\left\{ \left[ \frac{4}{\sqrt{(4+\zeta)^2+8 L_H}+4+\zeta}
  \right]^3, \left[ \frac{3\theta^2 (1-\zeta) }{L_H+\eta}
  \right]^3\right\}.
\end{equation*}
\end{lemma}

\begin{proof}
The proof tracks closely that
of~\cite[Lemma~13]{CWRoyer_SJWright_2018}. The only significant
difference is that equation (65) of~\cite{CWRoyer_SJWright_2018},
which is instrumental to the proof and requires a probabilistic
assumption on $\lambda_{\min}(\nabla^2 f(x_k))$, is now ensured
\emph{deterministically} by~\eqref{eq:ccgstepSOLnorm} from
Lemma~\ref{lemma:ccgsteps}. As a result, both the proof and the result
are deterministic.
\end{proof}

\begin{lemma} \label{lemma:LSccgNC}
  Suppose that Assumptions~\ref{assum:compactlevelset}
  and~\ref{assum:fC22} hold.  Suppose that at iteration $k$ of
  Algorithm~\ref{alg:dncg}, we have $\|\nabla f(x_k)\| > \epsg$, so
  that Algorithm~\ref{alg:ccg} is called. When Algorithm~\ref{alg:ccg}
  outputs d\_type=NC, the direction $d_k$ (computed from $d$ in
  Algorithm~\ref{alg:dncg}) has the following properties: The
  backtracking line search terminates with step length $\alpha_k =
  \theta^{j_k}$ with $j_k \le \jnc +1$, where
\begin{equation} \label{eq:eiglsits}	
\jnc := \left[ \log_{\theta}\left( \frac{3}{L_H+\eta} \right)
  \right]_+,
\end{equation}
and the resulting step $x_{k+1} = x_k + \alpha_k d_k$ satisfies
\begin{equation} \label{eq:decreaseNC}
f(x_k) - f(x_k+\alpha_k\,d_k) \; \geq \; \cnc \epsH^3,
\end{equation}	
with
\begin{equation*}
\cnc := \frac{\eta}{6}
\min\left\{1,\frac{27\theta^3}{(L_H+\eta)^3}\right\}.
\end{equation*}
\end{lemma}

\begin{proof}
  \refer{
By Lemma~\ref{lemma:ccgsteps}, we have from  \eqref{eq:ccgstepNC}
that
\begin{equation} \label{eq:boundnegcurvNCsteps}
		d_k^\top \nabla^2 f(x_k) d_k = -\|d_k\|^3 \le -\epsH \|d_k\|^2
\end{equation}
}
The result can thus be obtained exactly as in
\cite[Lemma~1]{CWRoyer_SJWright_2018}.
\end{proof}

\begin{lemma} \label{lemma:LSgeneralNC}
Suppose that Assumptions~\ref{assum:compactlevelset}
and~\ref{assum:fC22} hold.  Suppose that at iteration $k$ of
Algorithm~\ref{alg:dncg}, the search direction $d_k$ is of negative
curvature type, obtained either directly from Procedure~\ref{alg:meo}
or as the output of Algorithm~\ref{alg:ccg} and d\_type=NC. Then the
backtracking line search terminates with step length $\alpha_k =
\theta^{j_k}$ with $j_k \le \jnc +1$, where $\jnc$ is defined as in
Lemma~\ref{lemma:LSccgNC}, and the decrease in the function value
resulting from the chosen step length satisfies
\begin{equation} \label{eq:LSgeneralNCdecrease}
f(x_k) - f(x_k+\alpha_k\,d_k) \; \geq \; \frac{\cnc}{8} \epsH^3,
\end{equation}	
with $\cnc$ is defined in Lemma~\ref{lemma:LSccgNC}.
\end{lemma}

\begin{proof}
  Lemma~\ref{lemma:LSccgNC} shows that the claim holds (with a factor
  of $8$ to spare) when the direction of negative curvature is
  obtained from Algorithm~\ref{alg:ccg}.  When the direction is
  obtained from Procedure~\ref{alg:meo}, we have \refer{by the scaling
    of $d_k$ applied in Algorithm~\ref{alg:dncg} that}
\begin{equation} \label{eq:boundnegcurvNCproba}
d_k^\top \nabla^2 f(x_k) d_k = -\|d_k\|^3 \le -\frac12 \epsH \|d_k
\|^2 < 0,
\end{equation}
from which it follows that $\|d_k \| \ge \tfrac12 \epsH$. The
result can now be obtained by following the proof of
Lemma~\ref{lemma:LSccgNC}, with $\tfrac12 \epsH$ replacing $\epsH$.
\end{proof}

\begin{theorem} \label{theo:wccits}
Suppose that Assumptions~\ref{assum:compactlevelset},
\ref{assum:fC22}, and ~\ref{assum:wccmeo} hold, and define
\begin{equation} \label{eq:wccits}
\bar{K}_2 :=\left\lceil \frac{3(f(x_0)-\flow)}{\min\{\csol,\cnc/8\}}\max\{\epsg^{-3}
\epsH^3, \epsH^{-3}\} \right\rceil + 2,
\end{equation}
 where constants $\csol$ and $\cnc$
are defined in Lemmas~\ref{lemma:LSccgSOL} and~\ref{lemma:LSccgNC},
respectively.  Then with probability at least
\refer{$(1-\delta)^{\bar{K}_2}$}, Algorithm~\ref{alg:dncg} terminates
at a point satisfying \eqref{eq:2epson} in at most $\bar{K}_2$
iterations. (With probability at most
\refer{$1-(1-\delta)^{\bar{K}_2}$}, it terminates incorrectly within
$\bar{K}_2$ iterations at a point for which $\|\nabla f(x_k) \| \le
\epsg$ but $\lambda_{\min}(\nabla^2 f(x)) <
-\epsH$.)
\end{theorem}

\begin{proof}
Algorithm~\ref{alg:dncg} terminates incorrectly with probability
$\delta$ at any iteration at which Procedure~\ref{alg:meo} is called,
\refer{when Procedure~\ref{alg:meo} certifies erroneously that
  $\lambda_{\min}(\nabla^2 f(x)) \ge -\epsH$.}
%The overall probability of this happening during the first
%$\bar{K}_2$ iterations is \refer{bounded by} $\bar{K}_2
%\delta$. Therefore, with probability at least $1-\bar{K}_2 \delta$,
%no incorrect termination occurs in the first $\bar{K}_2$ iterations.
\refer{Since an erroneous certificate can only lead to termination, an
  erroneous certificate at iteration $k$ means that
  Procedure~\ref{alg:meo} did not produce an erroneous certificate at
  iterations $0$ to $k-1$. By a disjunction argument, we have that the
  overall probability of terminating with an erroneous certificate
  during the first $\bar{K}_2$ iterations is bounded by
  $1-(1-\delta)^{\bar{K}_2}$. Therefore, with probability at least
  $(1-\delta)^{\bar{K}_2} $, no incorrect termination occurs in the
  first $\bar{K}_2$ iterations.} 

Suppose now for contradiction that Algorithm~\ref{alg:dncg} runs for
$\bar{K}_2$ iterations without terminating. That is, for all 
$l=0,1,\dotsc,\bar{K}_2$, we have either $\| \nabla f(x_l) \| > \epsg$ 
or $\lambdamin(\nabla^2 f(x_l)) < -\epsH$. We perform the following 
partition of the set of iteration indices:
\begin{equation} \label{eq:K123}
  \cK_1 \cup \cK_2 \cup \cK_3 = \{0,1,\dotsc,\bar{K}_2-1\},
  \end{equation}
where $\cK_1$, $\cK_2$, and $\cK_3$ are defined as follows.

\medskip

\textbf{Case 1:} $\cK_1 := \{ l =0,1,\dotsc,\bar{K}_2-1 \, : \,
\|\nabla f(x_l) \| \le \epsg \}$.  At each iteration $l \in \cK_1$,
Algorithm~\ref{alg:dncg} calls Procedure~\ref{alg:meo}, which does not
certify that $\lambdamin (\nabla^2 f(x_l)) \ge -\epsH$ (since the
algorithm continues to iterate) but rather returns a direction of
sufficient negative curvature. By Lemma~\ref{lemma:LSgeneralNC}, the
step along this direction leads to an improvement in $f$ that is
bounded as follows:
\begin{equation} \label{eq:wccitsK1decrease}
f(x_l)-f(x_{l+1})  \ge  \frac{\cnc}{8} \epsH^3.
\end{equation}		

\medskip	

\textbf{Case 2:} $\cK_2 := \{ l=0,1,\dotsc,\bar{K}_2-1 \, : \, \|
\nabla f(x_l) \| > \epsg \; \mbox{and} \; \| \nabla f(x_{l+1}) \| >
\epsg \}$.  Algorithm~\ref{alg:dncg} calls Algorithm~\ref{alg:ccg} at
each iteration $l \in \cK_2$, returning either an approximate damped
Newton or a negative curvature direction. By combining
Lemmas~\ref{lemma:LSccgSOL} and \ref{lemma:LSccgNC}, we obtain a 
decrease in $f$ satisfying
\begin{align}
  \nonumber
f(x_l) - f(x_{l+1})  & \ge  \min\{\csol,\cnc\}
\min\left\{\| \nabla f(x_{l+1}) \|^3\epsH^{-3},\epsH^3\right\} \\
  \label{eq:wccitsK2decrease}
& \ge \min\{\csol,\cnc/8\}
\min\left\{\epsg^3\epsH^{-3},\epsH^3\right\}.
\end{align}

\medskip

\textbf{Case 3:} $\cK_3 := \{ l=0,1,\dotsc,\bar{K}_2-1 \, : \, \|
\nabla f(x_l) \| > \epsg \ge \| \nabla f(x_{l+1}) \| \}$.  Because $\|
\nabla f(x_{l+1})\|$ may be small in this case, we can no longer bound
the decrease in $f$ by an expression such as
\eqref{eq:wccitsK2decrease}. We can however guarantee at least that
$f(x_l)-f(x_{l+1}) \ge 0$. Moreover, provided that $l<\bar{K}_2-1$, we
have from $\| \nabla f(x_{l+1}) \| \le \epsg$ that the next iterate
$l+1$ is in $\cK_1$. Thus, a significant decrease in $f$ will be
attained at the {\em next} iteration, and we have
\begin{equation} \label{eq:K13}
  | \cK_3| \le |\cK_1|+1.
\end{equation}

\medskip

We now consider the total decrease in $f$ over the span of $\bar{K}_2$
iterations, which is bounded by $f(x_0)-\flow$ as follows:
\begin{align} 
  f(x_0) - \flow &\ge \sum_{l=0}^{\bar{K}_2-1} (f(x_l)-f(x_{l+1})) \nonumber \\
  \label{eq:sumdecompwccits}
& \ge \sum_{l \in \cK_1} (f(x_l)-f(x_{l+1})) +  \sum_{l \in \cK_2} (f(x_l)-f(x_{l+1})) 
\end{align}
where both sums in the final expression are nonnegative. Using first
the bound \eqref{eq:wccitsK1decrease} for the sum over $\cK_1$, we
obtain
\begin{equation} \label{eq:wccitsboundK1}
f(x_0) - \flow \; \ge \; |\cK_1| \frac{\cnc}{8} \epsH^3 \; \Leftrightarrow \; 
|\cK_1| \le \frac{f(x_0) - \flow}{\cnc/8} \epsH^{-3}.
\end{equation}
%From the sum over $\cK_2$, we obtain
%and~\eqref{eq:wccitsK2decrease} leads to
Applying~\eqref{eq:wccitsK2decrease} to the sum over $\cK_2$ leads to
\begin{equation} \label{eq:wccitsboundK2}
|\cK_2| \le \frac{f(x_0) -
  \flow}{\min\{\csol,\cnc/8\}}\max\{\epsg^{-3} \epsH^3,\epsH^{-3}\}.
\end{equation}
Using these bounds together with \eqref{eq:K13}, we have
\begin{align*}
  \bar{K}_2  & = |\cK_1| + |\cK_2| + |\cK_3| \\
  & \le  2|\cK_1|
  + |\cK_2| + 1 \\
  & \le 3\max\{|\cK_1|,|\cK_2|\} +1  \\
  & \le
\frac{3(f(x_0) - \flow)}
     {\min\{\csol,\cnc/8\}}\max\{\epsg^{-3}\epsH^3,\epsH^{-3}\} +1 \\
     & \le \bar{K}_2-1,
                \end{align*}
                giving the required contradiction.
\end{proof}

\begin{proof}
The proof follows by combining Theorem~\ref{theo:wccits} (which bounds
the number of iterations) with Lemma~\ref{lemma:ccgits} and
Assumption~\ref{assum:wccmeo} (which bound the workload per
iteration).
  \end{proof}

\begin{lemma} \label{lemma:propertiesCGoneiter}
Suppose that $j$ iterations of the CG loop are performed in
Algorithm~\ref{alg:ccg} or~\ref{alg:cg}. Then, we have
\begin{equation} \label{eq:suffcurvuptoj}
	  \frac{p_i^\top \bH p_i}{\|p_i\|^2} > 0 \quad \mbox{for
       all $i=0,1,\dotsc,j-1$}.
\end{equation}	
Moreover, the following properties hold.
\begin{enumerate}
\item $y_i \in \lspan\left\{p_0,\dotsc,p_{i-1}\right\}$,
  $i=1,2,\dotsc,j$.
\item $r_i \in \lspan\left\{p_0,\dotsc,p_i\right\}$ for all $i=1,2,\dotsc,j$, and 
\[
r_i^\top v = 0, \quad \mbox{for all $v \in
  \lspan\left\{p_0,\dotsc,p_{i-1}\right\}$ and all $i=1,2,\dotsc,j$}.
\]
(In particular, $r_i^\top r_l = 0$ if \refer{$0 \le l<i \le j$. If} $j=n$, 
then $r_n=0$.)
\item $\|r_i\| \le \|p_i\|$, $i=0,1,\dotsc,j$.
\item $r_i^\top p_i = -\|r_i\|^2$, $i=0,1,\dotsc,j$.
\item $p_i^\top \bH p_k=0$ for all $i,k =0,1,\dotsc,j$ with $k \neq i$.
\item $p_i = -\sum_{k=0}^i ({\|r_i\|^2}/{\|r_k\|^2}) r_k$, $i=0,1,\dotsc,j$.
\item
  \[
  q(y_{i+1}) = q(y_i) - \frac{\|r_i\|^4}{2 p_i^\top \bH p_i}, \quad i=0,1,\dotsc,j-1.
  \]
\item $r_i^\top \bH r_i \ge p_i^\top \bH p_i$, $i=0,1,\dotsc,j$.
\end{enumerate}		
\end{lemma}

\begin{proof}
Since CG has not terminated prior to iteration $j$,
\eqref{eq:suffcurvuptoj} clearly holds.  All properties then follow
from the definition of the CG process, and most are proved in standard
texts (see, for example,
\cite[Chapter~5]{JNocedal_SJWright_2006}). Property 8 is less commonly
used, so we provide a proof here.

The case $i=0$ is immediate since $r_0=-p_0$ and there is
equality. When $i \ge 1$, we have:
\begin{equation*}
	p_i = -r_i + \frac{\|r_i\|^2}{\|r_{i-1}\|^2}p_{i-1} \; \Leftrightarrow \; 
	r_i = -p_i + \frac{\|r_i\|^2}{\|r_{i-1}\|^2}p_{i-1}.
\end{equation*}
(Note that if iteration $i$ is reached, we cannot have
$\|r_{i-1}\|=0$.)  It follows that
\begin{eqnarray*}
	r_i^\top \bH r_i &=   
	&p_i^\top \bH p_i -2\frac{\|r_i\|^2}{\|r_{i-1}\|^2} p_i^\top \bH p_{i-1} + 
	\frac{\|r_i\|^4}{\|r_{i-1}\|^4}p_{i-1}^\top \bH p_{i-1} \\
	&= &p_i^\top \bH p_i + \frac{\|r_i\|^4}{\|r_{i-1}\|^4}p_{i-1}^\top \bH p_{i-1},
\end{eqnarray*}
as $p_i^\top \bH p_{i-1} = 0$ by Property 5 above. Since iteration $i$
has been reached, $p_{i-1}$ is a direction of \refer{positive
  curvature},
% at least $\eps$,
and we obtain $r_i^\top \bH r_i \ge p_i^\top \bH p_i$, as required.
\end{proof}

\begin{lemma} \label{lemma:cgcurvaturescalars}
Suppose that Algorithm~\ref{alg:ccg} computes iterates up to iteration
$j+1$. Then, for any $i \in \{0,\dotsc,j\}$, we can compute
(\ref{eq:weakcurvdir}) as
\[
\frac{(y_{j+1}-y_i)^\top \bH (y_{j+1}-y_i)}{\|y_{j+1}-y_i\|^2} =
\frac{\sum_{k=i}^{j} \alpha_k \|r_k\|^2}
{\sum_{\ell=0}^j \left[\sum_{k=\max\{\ell,i\}}^j \alpha_k \|r_k\|^2 \right]^2/\|r_{\ell}\|^2}.
\]
\end{lemma}

\begin{proof}
By definition, $y_{j+1}-y_i = \sum_{k=i}^{j} \alpha_k p_k$. By
conjugacy of the $p_k$ vectors, we have
\begin{equation} \label{eq:numeratorcomp}
(y_{j+1}-y_i)^\top \bH (y_{j+1}-y_i)
= \sum_{k=i}^{j} \alpha_k^2 p_k^\top \bH p_k
= \sum_{k=i}^{j} \alpha_k \|r_k\|^2,
\end{equation}
where we used the definition of $\alpha_k$ to obtain the last
equality.  Now we turn our attention to the denominator. Using
Property 6 of Lemma~\ref{lemma:propertiesCGoneiter}, we have that
\[
y_{j+1}-y_i = \sum_{k=i}^{j} \alpha_k p_k =
\sum_{k=i}^{j} \alpha_k \left(-\sum_{\ell=0}^k \frac{\|r_k\|^2}{\|r_\ell\|^2} r_\ell \right),
\]
By rearranging the terms in the sum, we obtain
\begin{equation*}
y_{j+1}-y_i = -\sum_{k=i}^{j} \sum_{\ell=0}^k \alpha_k\|r_k\|^2 \frac{r_\ell}{\|r_{\ell}\|^2} 
= -\sum_{\ell=0}^j \left[\sum_{k=\max\{\ell,i\}}^j \alpha_k \|r_k\|^2 \right] \frac{r_\ell}{\|r_\ell\|^2}.
\end{equation*}
Using the fact that the residuals $\{ r_{\ell} \}_{\ell=0,1,\dotsc,j}$
form an orthogonal set (by Property 2 of
Lemma~\ref{lemma:propertiesCGoneiter}), we have that
\begin{equation*}
  \|y_{j+1}-y_i\|^2 = \sum_{\ell=0}^j \frac{1}{\|r_{\ell} \|^2}
  \left[\sum_{k=\max\{\ell,i\}}^j \alpha_k \|r_k\|^2 \right]^2.
\end{equation*}
Combining this with~\eqref{eq:numeratorcomp} gives the desired result.
\end{proof}

\begin{proof}
  The proof proceeds by contradiction: If we assume that all
  conditions specified in the statement of the theorem hold, and in
  addition that
\begin{equation} \label{eq:curvcondyKp1}
\frac{(y_{\hIcg +1}-y_i)^\top \bH (y_{\hIcg+1}-y_i)}
     {\|y_{\hIcg+1}-y_i\|^2} \ge \eps, \quad \mbox{for all
       $i=0,1,\dotsc,\hIcg-1$,}
\end{equation}
then we must have 
\begin{equation} \label{eq:cvCGwhilestronglycvx}
\|r_{\hIcg}\| \le \sqrt{T} \tau^{\hIcg/2} \|r_0\|,
\end{equation}
contradicting \eqref{eq:Kitsstronglycvx}. Note that
\begin{equation} \label{eq:casehK}
		\frac{(y_{\hIcg +1}-y_{\hIcg})^\top \bH (y_{\hIcg+1}-y_{\hIcg})}
		{\|y_{\hIcg+1}-y_{\hIcg}\|^2} = 
		\frac{\alpha_{\hIcg} p_{\hIcg}^\top \bH (\alpha_{\hIcg} p_{\hIcg})}
		{\|\alpha_{\hIcg} p_{\hIcg}\|^2} = \frac{p_{\hIcg}^\top \bH p_{\hIcg}}
		{\|p_{\hIcg}\|^2} \ge \eps
\end{equation}
by assumption, therefore we can consider \eqref{eq:curvcondyKp1} to
hold for $i=0,1,\dotsc,\hIcg$. Moreover, recalling the definition
\eqref{eq:quadraticCG} of the quadratic function $q$, we have for any
$i=0,1,\dotsc,\hIcg$ that 
\[
		q(y_{\hIcg+1}) = q(y_i) + \nabla q(y_i)^\top (y_{\hIcg+1}-y_i) + 
		\frac{1}{2}(y_{\hIcg+1}-y_i)^\top \bH (y_{\hIcg+1}-y_i).
                \]
Thus, \eqref{eq:curvcondyKp1} can be reformulated as
\begin{equation} \label{eq:stronglycvxyKp1yj}
% 		\forall i \in \{0,\dotsc,\hIcg\}, \quad 
		q(y_{\hIcg+1}) \ge q(y_i) + r_i^\top (y_{\hIcg+1}-y_i) 
		+ \frac{\eps}{2}\|y_{\hIcg+1}-y_i\|^2, \quad
                \mbox{for all $i=0,1,\dotsc,\hIcg$,}
\end{equation}
where we used $\nabla q(y_i)=r_i$ and the definitions
\eqref{eq:curvcondyKp1}, \eqref{eq:casehK} of strong convexity along
the directions $y_{\hIcg+1}-y_i$. In the remainder of the proof, and
similarly to \cite[Proof of Proposition
  1]{YCarmon_JCDuchi_OHinder_ASidford_2017b}, we will show that
\eqref{eq:stronglycvxyKp1yj} leads to the contradiction
\eqref{eq:cvCGwhilestronglycvx}, thus proving that
\eqref{eq:yKp1negcurv} holds.

We define the  sequence of functions $\Phi_j$, $j=0,1,\dotsc\hIcg$ as follows:
\[
    \Phi_0(z) := q(y_0) + \frac{\eps}{2}\|z-y_0\|^2,
    \]
    and for $j=0,\dotsc,\hIcg-1$:
\begin{equation} 
    \label{eq:formulaPhijplus1}
\Phi_{j+1}(z)  := \tau\Phi_j(z) + (1-\tau)\left( q(y_j) + r_j^\top
(z-y_j) +\frac{\eps}{2}\|z-y_j\|^2 \right).
\end{equation}
Since each $\Phi_j$ is a quadratic function with Hessian $\eps I$, it
can be written as follows:
\begin{equation} \label{eq:Phijwithvj}
		\Phi_j(z) \; = \; \Phi_j^* + \frac{\eps}{2}\|z-v_j\|^2,
\end{equation}
where $v_j$ is the unique minimizer of $\Phi_j$, and $\Phi_j^* =
\Phi_j(v_j)$ is the minimum value of $\Phi_j$. (Note that $v_0=y_0=0$
and $\Phi^*_0 = q(y_0) = 0$.)

Defining
\begin{equation} \label{eq:defpsi}
\psi(y) := q(y_0) - q(y) + \frac{\eps}{2}\|y-y_0\|^2 = \Phi_0(y) - q(y),
\end{equation}
we give a short inductive argument to establish that 
\begin{equation} \label{eq:PhiYJp1}
\Phi_j(y_{\hIcg+1}) \le q(y_{\hIcg+1}) + \tau^j \psi(y_{\hIcg+1}),
\quad j=0,1,\dotsc,\hIcg.
\end{equation}
For $j=0$, \eqref{eq:PhiYJp1} holds because $\Phi_0(y) = q(y) +
\psi(y)$ by definition. Assuming that \eqref{eq:PhiYJp1} holds for
some index $j \ge 0$, we find by first applying
\eqref{eq:formulaPhijplus1} (with $z=y_{\hIcg+1}$) and then
\eqref{eq:stronglycvxyKp1yj} (with $i=j$) that
\begin{eqnarray*}
\Phi_{j+1}(y_{\hIcg+1}) &= &\tau\Phi_j(y_{\hIcg+1}) + (1-\tau)\left( q(y_j) + 
r_j^\top (y_{\hIcg+1}-y_j) +\frac{\eps}{2}\|y_{\hIcg+1}-y_j\|^2 \right) \\
&\le &\tau\Phi_j(y_{\hIcg+1}) + (1-\tau) q(y_{\hIcg+1}).
\end{eqnarray*}
Thus, we have
\begin{align*}
\Phi_{j+1}(y_{\hIcg+1}) &\le \tau\Phi_j(y_{\hIcg+1}) + (1-\tau) q(y_{\hIcg+1}) \\
&\le \tau q(y_{\hIcg+1}) + \tau^{j+1} \psi(y_{\hIcg+1}) + 
(1-\tau) q(y_{\hIcg+1}) \quad \mbox{from \eqref{eq:PhiYJp1}} \\
&= q(y_{\hIcg+1}) + \tau^{j+1} \psi(y_{\hIcg+1}),
\end{align*}
which proves \eqref{eq:PhiYJp1} for $j+1$, and thus completes the
inductive argument.

We next prove another technical fact about the relationship between
$q(y_j)$ and $\Phi_j^*$, namely,
\begin{equation} \label{eq:468}
  q(y_j) \le \Phi_j^*, \quad j=0,1,\dotsc, \hIcg.
\end{equation}
We establish this result by an inductive argument that is quite
lengthy and technical; we note the termination of this phase of the
proof clearly below.


This result trivially holds (with equality) at $j=0$.  Supposing that
it holds for some $j =0,1,\dotsc, \hIcg-1$, we will prove that it also
holds for $j+1$.

By using Properties 7 and 8 of Lemma~\ref{lemma:propertiesCGoneiter},
%and also $\|\bH \| \le (M+2\eps)$, we have
\refer{and also $\|\bH r_j\| \le (M+2\eps)\|r_j\|$,} we have
\begin{equation*} 
	q(y_{j+1}) = q(y_j) - \frac{\|r_j\|^4}{2\, p_j^\top \bH p_j} \le 
	q(y_j) - \frac{\|r_j\|^4}{2\, r_j^\top \bH r_j} \le 
	q(y_j) - \frac{\|r_j\|^2}{2(M+2\eps)}.
\end{equation*}
It follows from induction hypothesis $q(y_j) \le \Phi_j^*$ that 
\begin{align} \label{eq:qyjp1Phijstar}
q(y_{j+1}) \le q(y_j) - \frac{\|r_j\|^2}{2(M+2\eps)}
&= \tau q(y_j) + (1-\tau) q(y_j) -\frac{\|r_j\|^2}{2(M+2\eps)} \nonumber \\
&\le \tau \Phi_j^* + (1-\tau) q(y_j) -\frac{\|r_j\|^2}{2(M+2\eps)}.
\end{align}
By taking the derivative in \eqref{eq:formulaPhijplus1}, and using
\eqref{eq:Phijwithvj}, we obtain
\begin{align*}
\nabla \Phi_{j+1}(z) &= \tau \nabla \Phi_j(z) + (1-\tau)\left[r_j + \eps(z-y_j)\right] \\
\Rightarrow \;\; \eps(z-v_{j+1})&=  \eps \tau (z-v_j) + (1-\tau) \left(r_j + \eps (z-y_j) \right).
\end{align*}
By rearranging the above relation (and noting  that the $z$ terms cancel out), we obtain:
\begin{equation} \label{eq:vjp1minPhijp1}
	v_{j+1}  \; = \; \tau v_j - \frac{1-\tau}{\eps}r_j + (1-\tau) y_j.
\end{equation}
It follows from this expression together with Properties 1 and 2 of
Lemma~\ref{lemma:propertiesCGoneiter} that 
\begin{equation} \label{eq:vjinKj}
v_j \in \lspan\left\{p_0,p_1,\dotsc,p_{j-1}\right\}, \quad j=1,2,\dotsc,\hIcg.
\end{equation}
(The result holds for $j=1$, from \eqref{eq:vjp1minPhijp1} we have
$v_1 \in \lspan \{v_0, r_0, y_0\} = \lspan \{r_0\} = \lspan \{p_0 \}$,
and an induction based on \eqref{eq:vjp1minPhijp1} can be used to
establish \eqref{eq:vjinKj} for the other values of $j$.)  By
combining the expressions~\eqref{eq:Phijwithvj} for $\Phi_j$,
$\Phi_{j+1}$ with the recurrence formula~\eqref{eq:formulaPhijplus1}
for $\Phi_{j+1}$, we obtain
\begin{align*} 
		\Phi_{j+1}^* + \frac{\eps}{2}\|y_j-v_{j+1}\|^2 &= \Phi_{j+1}(y_j) \\
%		&= \tau \Phi_j(y_j) + (1-\tau)\left(q(y_j)+r_j^\top (y_j-y_j) + 
%		\frac{\eps}{2}\|y_j-y_j\|^2\right)  \\
		&= \tau\Phi_j(y_j) + (1-\tau) q(y_j) \\
                &= \tau\left(\Phi_j^* + 
		\frac{\eps}{2}\|y_j-v_j\|^2\right) + (1-\tau) q(y_j)
\end{align*}
and therefore
\begin{equation} \label{eq:doubleexpressionPhijp1}
  \Phi_{j+1}^* = \tau \left(\Phi_j^* +
  \frac{\eps}{2}\|y_j-v_j\|^2\right) + (1-\tau) q(y_j) -
  \frac{\eps}{2}\|y_j-v_{j+1}\|^2.
\end{equation}
On the other hand, we have by~\eqref{eq:vjp1minPhijp1} that
\begin{eqnarray} \label{eq:normylminusvlp1}
		\|y_j-v_{j+1}\|^2 &= &\left\| \tau (y_j-v_j) 
		+\frac{1-\tau}{\eps}r_j \right\|^2 \nonumber \\
		&= &(\tau^2 \|y_j-v_j\|^2 + \frac{(1-\tau)^2}{\eps^2}\|r_j\|^2 
		+ \frac{2}{\eps}(1-\tau)\tau r_j^\top (y_j-v_j) \nonumber \\
		&= & \tau^2 \|y_j-v_j\|^2 + \frac{(1-\tau)^2}{\eps^2}\|r_j\|^2,
\end{eqnarray}
where the last relation comes from $r_j \perp
\lspan\{p_0,\dotsc,p_{j-1}\}$ (Property 2 of
Lemma~\ref{lemma:propertiesCGoneiter}) and \eqref{eq:vjinKj} in the
case $j \ge 1$, and immediately in the case $j=0$, since $y_0=v_0=0$.
By combining \eqref{eq:doubleexpressionPhijp1}
and~\eqref{eq:normylminusvlp1}, we arrive at:
\begin{align} \label{eq:phijp1star}
		\Phi_{j+1}^* &= \tau \left(\Phi_j^* + 
		\frac{\eps}{2}\|y_j-v_j\|^2\right) + (1-\tau) q(y_j) 
		- \frac{\eps}{2}\|y_j-v_{j+1}\|^2 \nonumber \\
		&= \tau \left(\Phi_j^* + 
		\frac{\eps}{2}\|y_j-v_j\|^2\right) + (1-\tau) q(y_j) 
		-\frac{\eps}{2}\tau^2 \|y_j-v_j\|^2 - \frac{(1-\tau)^2}{2\eps} \|r_j\|^2 
		\nonumber \\
		&= \tau \Phi_j^* + \frac{\eps}{2}\left[ \tau 
		-\tau^2\right]\|y_j-v_j\|^2 + (1-\tau) q(y_j) 
		- \frac{(1-\tau)^2}{2\eps} \|r_j\|^2 \nonumber \\ 
		&= \tau \Phi_j^* + 
		\frac{\eps}{2}(1-\tau)\tau \|y_j-v_j\|^2 + (1-\tau) q(y_j) 
		- \frac{(1-\tau)^2}{2\eps} \|r_j\|^2 \nonumber \\
		&\ge \tau \Phi_j^* + (1-\tau) q(y_j) 
		- \frac{(1-\tau)^2}{2\eps} \|r_j\|^2 \nonumber \\
                &\ge q(y_{j+1}) + \frac{1}{2(M+2\eps)}\|r_j\|^2 
		- \frac{(1-\tau)^2}{2\eps} \|r_j\|^2.
\end{align}
where the last inequality comes from~\eqref{eq:qyjp1Phijstar}.  By
using the definitions of $\tau$ and $\kappa$ in
Algorithm~\ref{alg:ccg}, we have
\[
		\frac{(1-\tau)^2}{2\eps} = \frac{1}{2\eps(\sqrt{\kappa}+1)^2} \le 
		\frac{1}{2\eps\kappa} = \frac{1}{2(M+2\eps)}.
\]
It therefore follows from \eqref{eq:phijp1star} that $q(y_{j+1}) \le
\Phi_{j+1}^*$. At this point, we have shown that when $q(y_j) \le
\Phi_j^*$ for $j=0,1,\dotsc,\hIcg-1$, it follows that $q(y_{j+1}) \le
\Phi_{j+1}^*$, establishing the inductive step. As a result, our
proof of \eqref{eq:468} is complete.


By substituting $j=\hIcg$ into \eqref{eq:468}, we obtain
$q(y_{\hIcg}) \le \Phi_{\hIcg}^*$,
which in combination with \eqref{eq:PhiYJp1} with $j=\hIcg$, and the
definition \eqref{eq:Phijwithvj}, yields
\begin{equation} \label{eq:desiredecreaseformula}
q(y_{\hIcg}) -q(y_{\hIcg+1}) \le \Phi_{\hIcg}^* - q(y_{\hIcg+1}) 
\le \Phi_{\hIcg}(y_{\hIcg+1}) - q(y_{\hIcg+1})
\le \tau^{\hIcg} \psi(y_{\hIcg+1}).
\end{equation}
By substitution from \eqref{eq:defpsi}, we obtain
\begin{equation} \label{eq:funcdecreasecontrad}
q(y_{\hIcg}) - q(y_{\hIcg+1}) \; \le \; \tau^{\hIcg}
\left(q(y_0)-q(y_{\hIcg+1}) +
\frac{\eps}{2}\|y_0-y_{\hIcg+1}\|^2\right).
\end{equation}

We now depart from the analysis
of~\cite{YCarmon_JCDuchi_OHinder_ASidford_2017b}, and complete the
proof of this result by expressing \eqref{eq:funcdecreasecontrad} in
terms of residual norms.  On the left-hand side, we have
\begin{align*}
  q(y_{\hIcg}) - q(y_{\hIcg+1})
  % &= &\nabla q(y_{\hIcg+1})^\top (y_{\hIcg}-y_{\hIcg+1}) + 
%		\frac{1}{2}(y_{\hIcg}-y_{\hIcg+1})^\top \bH (y_{\hIcg}-y_{\hIcg+1})  \\ 
		&= r_{\hIcg+1}^\top (y_{\hIcg}-y_{\hIcg+1}) + 
		\frac{1}{2}(y_{\hIcg}-y_{\hIcg+1})^\top \bH (y_{\hIcg}-y_{\hIcg+1})  \\
		&= \frac{1}{2}(y_{\hIcg}-y_{\hIcg+1})^\top \bH (y_{\hIcg}-y_{\hIcg+1})
\end{align*}
because $r_{\hIcg+1}^\top (y_{\hIcg}-y_{\hIcg+1}) = r_{\hIcg+1}^\top
(\alpha_{\hIcg} p_{\hIcg}) = 0$ by
Lemma~\ref{lemma:propertiesCGoneiter}, Property 2.
We thus have from \eqref{eq:casehK} that
\begin{alignat}{2}
  \nonumber
  q(y_{\hIcg}) - q(y_{\hIcg+1}) &\ge \frac{\eps}{2}\|y_{\hIcg}-y_{\hIcg+1}\|^2  &&  \\
  \nonumber
  &\refer{= \frac{\eps}{2} \|\alpha_{\hIcg}p_{\hIcg}\|^2} \\
  \nonumber
  &\refer{\ge \frac{\eps}{2 (M+2\eps)^2}\|\bH(\alpha_{\hIcg}p_{\hIcg})\|^2} 
  && \mbox{(since $\|\bH p_{\hIcg}\| \le (M+2\eps)\|p_{\hIcg}\|$)} \\
  \nonumber
%  &\ge \frac{\eps}{2 (M+2\eps)^2} \|\bH(y_{\hIcg}-y_{\hIcg+1})\|^2  && \mbox{(since $\bH \preceq (M+2\eps)I$)} \\
  &= \frac{\eps}{2 (M+2\eps)^2} \|\bH(y_{\hIcg}-y_{\hIcg+1})\|^2   \\
  \nonumber
  &= \frac{\eps}{2 (M+2\eps)^2} \|r_{\hIcg} - r_{\hIcg+1}\|^2  && \mbox{(since $r_j=g+\bH y_j$)} \\
  \nonumber
		&= \frac{\eps}{2 (M+2\eps)^2} (\|r_{\hIcg}\|^2 + \|r_{\hIcg+1}\|^2) & \quad & \mbox{(by Lemma~\ref{lemma:propertiesCGoneiter}, Property 2)} \\
  \label{eq:funcdeccontradLHS}
		& \ge \frac{\eps}{2 (M+2\eps)^2} \|r_{\hIcg}\|^2,
\end{alignat}


On the right-hand side of~\eqref{eq:funcdecreasecontrad}, because of
the strong convexity condition \eqref{eq:stronglycvxyKp1yj} at $i=0$,
we have
\begin{align*}
q(y_0)-q(y_{\hIcg+1}) + \frac{\eps}{2}\|y_0-y_{\hIcg+1}\|^2  & \le 
-\nabla q(y_0)^\top (y_{\hIcg+1}-y_0) \\
&= -r_0^\top (y_{\hIcg+1}-y_0)  \le \|r_0\|\|y_{\hIcg+1}-y_0\|.
\end{align*}
Moreover, we have 
\[
		\|y_{\hIcg+1}-y_0\| \; = \;
		\left\|\sum_{i=0}^{\hIcg} \alpha_i p_i \right\| 
		\; \le \; \sum_{i=0}^{\hIcg} \alpha_i \|p_i\| 
		\; = \; \sum_{i=0}^{\hIcg} \frac{\|r_i\|^2}{p_i^\top \bH p_i}\|p_i\|,
\]
where the last relation follows from the definition of $\alpha_i$. By
combining these last two bounds, and using Property 3 of
Lemma~\ref{lemma:propertiesCGoneiter}, we obtain
\begin{equation} \label{eq:wd12}
		q(y_0)-q(y_{\hIcg+1}) + \frac{\eps}{2}\|y_0-y_{\hIcg+1}\|^2 \; \le \; 
		\|r_0\| \sum_{i=0}^{\hIcg} \|r_i\| \frac{\|p_i\|^2}{p_i^\top \bH p_i} \;
		\le \; \|r_0\| \frac{1}{\eps} \sum_{i=0}^{\hIcg} \|r_i\|,
\end{equation}
where the last inequality holds $p_j^\top \bH p_j \ge \eps \|p_j\|^2$
for $j=0,1,\dotsc,\hIcg$ by assumption.

To bound the sum in \eqref{eq:wd12}, we recall that since
Algorithm~\ref{alg:ccg} did not terminate until iteration $\hIcg$,
\refer{the residual norms $\|r_i \|$ at all iterations
  $i=0,1,\dotsc,\hIcg-1$ must have decreased at the expected
  convergence rate. In particularly, we have $\|r_i\| \le \sqrt{T}
  \tau^{i/2} \|r_0\|$ for the {\em possibly smaller} versions of
  $\sqrt{T}$ and $\tau$ that prevailed at iteration $i$, so certainly
  $\|r_i\| \le \sqrt{T} \tau^{i/2} \|r_0\|$ for the final values of
  these parameters.} Thus for $i=0,1,\dotsc,\hIcg-1$, we have
\[
\|r_i\| \le \sqrt{T} \tau^{i/2} \|r_0\| \le \tau^{(i-\hIcg)/2}\|r_{\hIcg}\|,
\]
where we used $\|r_{\hIcg}\| \ge \sqrt{T} \tau^{\hIcg/2} \|r_0\|$
(from \eqref{eq:Kitsstronglycvx}) for the last inequality. Observing
that this bound also holds (trivially) for $i=\hIcg$, we obtain by
substituting in \eqref{eq:wd12} that
\begin{align}
  \nonumber
q(y_0)-q(y_{\hIcg+1}) + \frac{\eps}{2}\|y_0-y_{\hIcg+1}\|^2
&\le \|r_0\| \frac{1}{\eps} \sum_{i=0}^{\hIcg} \tau^{(i-\hIcg)/2} \|r_{\hIcg}\| \\
\nonumber
&\le \|r_0\| \frac{\tau^{-\hIcg/2}}{\eps}\|r_{\hIcg}\|\,\sum_{i=0}^{\hIcg} (\sqrt{\tau})^{i} \\
\label{eq:funcdeccontradRHS}
& \le \|r_0\| \frac{\tau^{-\hIcg/2}}{\eps}\|r_{\hIcg}\| \frac{1}{1-\sqrt{\tau}}.
\end{align}
Applying successively \eqref{eq:funcdeccontradLHS},
\eqref{eq:funcdecreasecontrad} and \eqref{eq:funcdeccontradRHS}
finally yields:
\begin{align*}
		\frac{\eps}{2 (M+2\eps)^2} \|r_{\hIcg}\|^2 &\le 
		 q(y_{\hIcg}) - q(y_{\hIcg+1}) \\
		 &\le \tau^{\hIcg} \left( q(y_0)-q(y_{\hIcg+1}) + \frac{\eps}{2}\|y_0-y_{\hIcg+1}\|^2 \right) \\
		 &\le \tau^{\hIcg} \|r_0\|\|r_{\hIcg}\| 
		 \frac{\tau^{-\hIcg/2}}{\eps}\frac{1}{1-\sqrt{\tau}}.
\end{align*}
After rearranging this inequality and dividing by $\|r_{\hIcg}\| > 0$,
we obtain
\begin{equation} \label{eq:finalcontrad}
		\|r_{\hIcg}\| \le \frac{2 (M+2\eps)^2}{\eps^2}\frac{\tau^{\hIcg/2}}{1-\sqrt{\tau}} \|r_0\|
		= \sqrt{T} \tau^{\hIcg/2}\|r_0\|.
\end{equation}
We have thus established \eqref{eq:cvCGwhilestronglycvx} which, as we
noted earlier, contradicts \eqref{eq:Kitsstronglycvx}. Thus
\eqref{eq:curvcondyKp1} cannot be true, so we have established
\eqref{eq:yKp1negcurv}, as required.
\end{proof}

