In this paper we consider convex conic programming in the form of
\begin{equation}\label{eq:conic-cp}
\begin{array}{rl}
F^*=\min & \left\{F(x) := f(x) + P(x)\right\} \\
\mbox{s.t.} &  g(x)\preceq_\mcK 0,
\end{array}
\end{equation}
where $f, P:\Re^n\rightarrow(-\infty,\infty]$ are proper closed convex functions, $\mcK$ is a closed convex cone in $\Re^m$, the symbol $\preceq_\mcK$ denotes the partial order induced by $\mcK$, that is, $y\preceq_\mcK z$ if and only if $z-y\in\mcK$, and the mapping $g:\Re^n\rightarrow\Re^m$ is convex with respect to $\mcK$, that is,
\begin{equation}
\label{eq:conic-cvx}
g(\alpha x + (1-\alpha)y) \preceq_\mcK \alpha g(x) + (1-\alpha)g(y), \quad\forall x,y\in\Re^n, \; \alpha\in[0,1].
\end{equation}
The associated Lagrangian dual problem of \eqref{eq:conic-cp} is given by 
\beq \label{dual-prob}
d^*=\sup\limits_{\lambda\in\mcK^{*}} \inf\limits_x\  \{ f(x) + P(x) + \Inner{\lambda}{g(x)}\},
\eeq
where $\mcK^*$ is the dual cone of $\mcK$ (see Section \ref{sec:preliminaries}).

\begin{ass}
	\label{ass:function}
	\begin{itemize}
		\item[(a)] The proximal operator associated with $P$ can be exactly evaluated, and the domain of $P$, denoted by $\dom(P)$, is compact.\footnote{Some problems with unbounded $\dom(P)$ can be reformulated as the ones satisfying this assumption. For example, when $f$ is bounded below and $P$ is coercive, the problem generally can be reformulated as the one with the objective $f+\tilde P$ for some $\tilde P$ with a compact domain. Such a problem often arises in sparse or low-rank learning, in which $f$ is typically a nonnegative loss function and $P$ is the $\ell_1$- or nuclear-norm.}
		\item[(b)] The projection onto $\mcK$ can be exactly evaluated.
		\item[(c)] The functions $f$ and $g$ are continuously differentiable on an open set $\Omega$ containing $\dom(P)$,  and $\nabla f$ and $\nabla g$  are Lipschitz continuous on $\Omega$ with Lipschitz constants $L_{\nabla f}$ and $L_{\nabla g}$, respectively.\footnote{The symbol $\nabla g$ denotes the transpose of the Jacobian of $g$.}
\item[(d)] The strong duality holds for problems \eqref{eq:conic-cp} and \eqref{dual-prob}, that is, both problems have optimal solutions and moreover their optimal values $F^*$ and $d^*$ are equal. 
	\end{itemize}
\end{ass}

The Lagrangian function $l(x,\lambda)$ of problem~\eqref{eq:conic-cp} is defined as
\begin{equation*}
l(x,\lambda) = \left\{
\begin{array}{ll}
f(x) + P(x) + \Inner{\lambda}{g(x)} & \mbox{if}\; x\in \dom(P) \mbox{ and } \lambda \in \mcK^{*}, \\
-\infty & \mbox{if}\; x\in \dom(P) \mbox{ and } \lambda\notin\mcK^{*}, \\
\infty & \mbox{if}\; x\notin \dom(P),
\end{array}
\right.
\end{equation*}
which is a closed convex-concave function. The Lagrangian dual function $d:\Re^m\rightarrow[-\infty,\infty)$ is defined as 
\begin{equation}
\label{eq:lag-dual-func}
d(\lambda) = \inf_x l(x,\lambda) = \left\{
\begin{array}{ll}
\inf\limits_x\  \{ f(x) + P(x) + \Inner{\lambda}{g(x)}\} & \mbox{if}\; \lambda\in\mcK^{*},\\
-\infty & \mbox{if}\; \lambda\notin\mcK^{*},
\end{array}
\right.
\end{equation}
which is a closed concave function. Moreover, the augmented Lagrangian function for problem~\eqref{eq:conic-cp} is defined as (e.g., see~\cite{Shapiro04})

\begin{equation}
\label{eq:al-func}
\mcL(x,\lambda;\rho) = f(x) + P(x) + \frac{1}{2\rho}\Big[\dist^2\big(\lambda + \rho g(x), -\mcK\big) - \|\lambda\|^2\Big],
\end{equation}
where $\rho>0$ is  a penalty parameter. For convenience, we let
\beq \label{S-fun}
\mcS(x,\lambda;\rho):= f(x) + \frac{1}{2\rho} \dist^2\big(\lambda+\rho g(x), -\mcK \big).
\eeq
It is clear to see that 
\[
\mcL(x,\lambda;\rho) = \mcS(x,\lambda;\rho) + P(x) - \frac{\|\lambda\|^2}{2\rho}.
\]
The augmented Lagrangian dual function of~\eqref{eq:conic-cp} is given by
\begin{equation}
\label{eq:aug-dual-func}
d(\lambda;\rho)= \min_{x\in\Re^n} \mcL(x,\lambda;\rho).
\end{equation}

The Lagrangian dual problem \eqref{dual-prob} can thus be rewritten as  
\begin{equation}\label{eq:dual-conic-cp}
d^{*} = \max_\lambda\; d(\lambda).
\end{equation}
Let $\partial l:\Re^n\times\Re^m\rightrightarrows\Re^n\times \Re^m$ and $\partial d:\Re^m\rightrightarrows\Re^m$ be respectively the subdifferential mappings associated with $l$ and $d$ (e.g., see \cite{R97}). We define two set-valued operators associated with problems \eqref{eq:conic-cp} and \eqref{dual-prob} as follows:
\beqa
&&\mcT_d: \lambda \rightarrow \{ u\in\Re^m: -u\in \partial d(\lambda)\},  \quad \forall \lambda\in\Re^m, \label{eq:def-two-opt1} \\
&& \mcT_l: (x,\lambda) \rightarrow \{ (v,u)\in\Re^n\times\Re^m: (v,-u)\in\partial l(x,\lambda)\}, \quad \forall (x,\lambda) \in \Re^n \times \Re^m. \label{eq:def-two-opt2}
\eeqa
It is well known that $\lambda^*$ is an optimal solution of the Lagrangian dual problem~\eqref{eq:dual-conic-cp} if and only if $0\in \partial d(\lambda^*)$, and $(x^*,\lambda^*)$ is a saddle point\footnote{$(x^*,\lambda^*)$ is called a saddle point of $l$ if it satisfies $ \sup_{\lambda}l(x^*,\lambda) = l(x^*,\lambda^*) = \inf_x l(x,\lambda^*)$.} of $l$ if and only if $(0,0)\in\partial l(x^*,\lambda^*)$. In addition, it can be verified that 
\begin{equation}
\label{eq:express-Tl}
\partial l(x,\lambda) = \left\{
\begin{array}{ll}
\left(
\begin{array}{c}
\nabla f(x) + \partial P(x) + \nabla g(x)\lambda \\
g(x) - \mcN_{\mcK^*}(\lambda)
\end{array}
\right), & \mbox{if}\; x\in\dom(P)\; \mbox{and}\; \lambda\in\mcK^*, \medskip
\\ 
\emptyset, & \mbox{otherwise}.
\end{array}\right.
\end{equation}

\begin{equation}
\label{eq:eps-approx-kkt-point}
\dist(0, \nabla f(x) + \partial P(x) + \nabla g(x)\lambda) \leq \epsilon, \quad \dist(g(x), \mcN_{\mcK^*}(\lambda))\leq \epsilon, \quad (x,\lambda) \in \dom(P) \times \mcK^*
\end{equation}

\begin{defi}
	\label{defi:approx-KKT}
	Given any $\epsilon>0$, we say $(x,\lambda)\in\Re^n\times\Re^m$ is an $\epsilon$-KKT solution of~\eqref{eq:conic-cp}  if there exists $(u,v)\in\partial l(x,\lambda)$ such that $\|u\|\leq \epsilon$ and $\|v\|\leq \epsilon$.
\end{defi}

\begin{algo}[An adaptively regularized I-AL method]
	\label{alg:mi-al}
	\normalfont
	\mbox{}
	\begin{itemize}
		\item[0.] Input $\epsilon>0$, $(x^0,\lambda^0)\in\dom(P)\times \mcK^*$,  nondecreasing $\{\rho_k\} \subset \Re_{++}$, and $0<\eta_k \downarrow 0$. Set $k=0$.
		\item[1.] Apply Algorithm~\ref{alg:opt-fom-str} (in Appendix \ref{app-fom}) to the problem $\min_x \varphi_k(x)$ to  find $x^{k+1}\in\dom(P)$ satisfying
		\begin{equation}
		\label{eq:inext-subprob-m}
		\dist (0, \partial \varphi_k(x^{k+1})) \leq \eta_k,\footnote{In view of Proposition \ref{prop:cplx-fom-str-cvx},  one can terminate Algorithm~\ref{alg:opt-fom-str} once a point $x^{k+1}$ satisfying $2L_{\nabla \phi}\|\tilde{x}^{k+1} - x^{k+1}\| \le \eta_k$ is found, where $\phi(\cdot)= \varphi_k(\cdot)-P(\cdot)$, $\tilde{x}^{k+1}= \prox_{P/L_{\nabla \phi}}\left( x^{k+1} - \nabla \phi(x^{k+1})/L_{\nabla \phi} \right)$, and $L_{\nabla \phi}$ is the Lipschitz constant of $\nabla \phi$. Such $x^{k+1}$ clearly satisfies \eqref{eq:inext-subprob-m}.}
		\end{equation}
		where 
		\begin{equation}
		\label{eq:prox-al-func}
		\varphi_k(x) = \mcL(x,\lambda^k;\rho_k) + \frac{1}{2\rho_k}\|x - x^k\|^2.
		\end{equation}
		\item[2.] Set $\lambda^{k+1} = \Pi_{\mcK^*}\big(\lambda^k + \rho_k g(x^{k+1}) \big)$. 
		\item[3.] If $(x^{k+1},\lambda^{k+1})$ satisfies \eqref{eq:eps-approx-kkt-point} or the following two inequalities are satisfied
		\begin{equation}
		\label{eq:check-stop-m}
		\frac{1}{\rho_k}\|(x^{k+1}, \lambda^{k+1}) - (x^k,\lambda^k)\| \leq \frac{\epsilon}{2}, \quad \eta_k \leq \frac{\epsilon}{2},
		\end{equation}
		output $(x^+, \lambda^{+}) = (x^{k+1}, \lambda^{k+1})$ and terminate the algorithm.
		\item[4.] Set $k \leftarrow k+1$ and go to Step 1.
	\end{itemize}
	{\bf End.}
\end{algo}

In the rest of this section we present our main results for Algorithm \ref{alg:i-al}, whose proof is deferred  to Subsection \ref{sec:pf-i-al}. To proceed, we introduce some further notation below. Let $\Lambda^*$ be the set of optimal solutions of problem \eqref{dual-prob} and $\hat\lambda^*\in \Lambda^*$ such that $\|\lambda^0-\hat\lambda^*\|=\dist(\lambda^0,\Lambda^*)$. In addition, we define 
\begin{align}
 & D_X = \max\limits_{x,y\in\dom(P)}\|x - y\|,  \  D_\Lambda = \|\lambda^0 - \hat\lambda^*\|, \ B = L_{\nabla f} + L_{\nabla g}(\|\hat\lambda^*\| + D_\Lambda), \label{param} \\
 & C = L_{\nabla g}M_g + L_g^2, \ \bD=\max\{D_\Lambda,1\}, \ \bB =\max\{B,1\}, \ \bC =\max\{C,1\}, \label{bparam}
\end{align}
where  $L_{\nabla f}$, $L_{\nabla g}$, $L_g$ and $M_g$ are defined above.

\begin{prop}
Under Assumption~\ref{ass:function}, $x^*\in\Re^n$ is an optimal solution of~\eqref{eq:conic-cp} if and only if there exists $\lambda^*\in\Re^m$ such that
\begin{equation}
\label{eq:KKT-condition}
(0,0)\in \partial l(x^*,\lambda^*),
\end{equation}
or equivalently, $(x^*,\lambda^*)$ satisfies the KKT conditions for~\eqref{eq:conic-cp}, that is,
\[
0\in\nabla f(x^*) + \partial P(x^*) + \nabla g(x^*) \lambda^*, \quad \lambda^* \in\mcK^*, \quad g(x^*)\preceq_\mcK 0, \quad \langle \lambda^*, g(x^*) \rangle = 0.
\]
\end{prop}

\begin{proof}
The result \eqref{eq:KKT-condition} follows from \cite[Theorem 36.6]{R97}. By \eqref{eq:express-Tl}, it is not hard to see that \eqref{eq:KKT-condition} holds if and only if $0\in \nabla f(x^*) + \partial P(x^*) + \nabla g(x^*)\lambda^*$, $\lambda^*\in\mcK^*$, and $g(x^*) \in\mcN_{\mcK^*}(\lambda^*)$. By the definition of $\mcK^*$ and $\mcN_{\mcK^*}$, one can verify that $g(x^*)\in\mcN_{\mcK^*}(\lambda^*)$ is equivalent to $g(x^*)\preceq_\mcK 0$ and $\langle\lambda^*, g(x^*) \rangle = 0$. The proof is then completed.
\end{proof}

\begin{proof}
The result \eqref{eq:KKT-condition} follows from \cite[Theorem 36.6]{R97}. By \eqref{eq:express-Tl}, it is not hard to see that \eqref{eq:KKT-condition} holds if and only if $0\in \nabla f(x^*) + \partial P(x^*) + \nabla g(x^*)\lambda^*$, $\lambda^*\in\mcK^*$, and $g(x^*) \in\mcN_{\mcK^*}(\lambda^*)$. By the definition of $\mcK^*$ and $\mcN_{\mcK^*}$, one can verify that $g(x^*)\in\mcN_{\mcK^*}(\lambda^*)$ is equivalent to $g(x^*)\preceq_\mcK 0$ and $\langle\lambda^*, g(x^*) \rangle = 0$. The proof is then completed.
\end{proof}

\begin{lemma}
	\label{lemma:al-func-elp}
	For any $(x,\lambda,\rho)\in\Re^n\times\Re^m\times\Re_{++}$, the following identity holds
	\begin{equation*}
	\mcL(x,\lambda;\rho) = \max_{\eta\in\Re^m} \left\{ l(x,\eta) - \frac{1}{2\rho}\|\eta - \lambda\|^2\right\}.
	\end{equation*}
	In addition, if $x\in\dom(P)$, the maximum is attained uniquely at $\bar{\lambda} = \Pi_{\mcK^*}(\lambda + \rho g(x))$. Consequently, the following statements hold.
	\begin{itemize}
		\item[(i)] For any $(\lambda,\rho)\in\Re^m\times\Re_{++}$, $d(\lambda;\rho)$ satisfies that
		\begin{equation}
		\label{eq:al-dual-func-elp-cp}
		d(\lambda;\rho) = \max_{\eta\in\Re^m}\left\{ d(\eta) - \frac{1}{2\rho}\|\eta - \lambda\|^2\right\}. 
		\end{equation}
		\item[(ii)] $\mcL(x,\lambda;\rho)$ is a convex function in $x$, and for any $x\in\dom(P)$, we have
\[
		\partial_x\mcL(x,\lambda;\rho) = \partial_x l(x,\bar{\lambda}).
\]
		\item[(iii)] $\mcL(x,\lambda;\rho)$ is a concave function in $\lambda$, and for any $x\in\dom(P)$, it is differentiable in $\lambda$ and
\[
		\frac{1}{\rho}(\bar{\lambda} - \lambda) = \nabla_\lambda \mcL(x,\lambda;\rho) \in \partial_\lambda l(x,\bar{\lambda}).
\]
	\end{itemize}
\end{lemma}

\begin{lemma}
\label{lemma:cplx-ippa} 
Let $\mcT:\Re^n\rightrightarrows\Re^n$ be a maximally monotone operator and  $z^*\in\Re^n$  such that $0\in\mcT(z^*)$. Let $\{z^k\}$ be a sequence generated by an inexact PPA, starting with some $z^0$ and obtaining $z^{k+1}$ by approximately evaluating $\mcJ_{\rho_k}(z^k)$ such that 
\begin{equation}
\label{eq:iter-PPA}
\|z^{k+1} - \mcJ_{\rho_k}(z^k)\| \le  e_k
\end{equation}
for some $\rho_k>0$ and $e_k\geq 0$, where $\mcJ_\rho=(\mcI + \rho\mcT)^{-1}$  and $\mcI$ is the identify operator. Then we have
\beqa
\|z^s - z^{*}\| \leq \|z^t - z^{*}\| + \sum_{i=t}^{s-1}e_i, \quad \forall s\geq t\geq 0, \label{eq:iter-ppa-bd} \\
\|z^{k+1} - z^k\| \leq \|z^0 - z^*\| + \sum_{i=0}^k e_i, \quad \forall k\geq 0. \label{eq:ippa-iter-cplx}
\eeqa
Moreover, for any $K\ge 1$, we have
\begin{equation}
\label{eq:ippa-iter-cplx-min}
\min_{K\leq k\leq 2K}\|z^{k+1} - z^k\| \leq \frac{\sqrt{2}\left(\|z^0 - z^{*}\| + 2\sum_{k=0}^{2K}e_k\right)}{\sqrt{K+1}}.
\end{equation}
\end{lemma}

\begin{proof}
Since $0\in\mcT(z^*)$ and $\mcT$ is maximally monotone, it follows from \cite[Proposition 1]{Rock76a} that
\begin{equation}
\label{eq:suff-dec-ppa-1}
\| \mcJ_\rho(z) - z^*\|^2 + \|\mcJ_\rho(z) - z\|^2 \leq \|z - z^*\|^2,
\end{equation}
which implies that 
\begin{equation}
\label{eq:suff-dec-ppa-2}
\|\mcJ_\rho(z) - z^*\| \leq \|z - z^*\|, \quad \|\mcJ_\rho(z) - z\| \leq \|z - z^*\|, \quad \forall z \in \Re^n.
\end{equation}
	Let $\xi^k=z^{k+1} - \mcJ_{\rho_k}(z^k)$ for all $k\ge 0$. By this, \eqref{eq:suff-dec-ppa-2}, and \eqref{eq:iter-PPA} with $\rho = \rho_k$ and $z = z^k$, one has
	\[
	\|z^{k+1} - z^{*}\| \leq \|z^{k+1} - \mcJ_{\rho_k}(z^k)\| + \|\mcJ_{\rho_k}(z^k) - z^{*}\| 
	\leq \|\xi^k\| + \|z^k - z^{*}\|, \quad \forall k \ge 0.
	\]
	Summing up the above inequality from $k=t$ to $k=s-1$ yields 
	\beq \label{bdd-1}
	\|z^s - z^{*}\| \leq \|z^t - z^{*}\| + \sum_{i=t}^{s-1} \|\xi^i\|, \quad \forall s\geq t\geq 0.
	\eeq
	Notice from \eqref{eq:iter-PPA} that $\|\xi^k\| \le e_k$ for all $k\ge 0$, which along with \eqref{bdd-1} leads to \eqref{eq:iter-ppa-bd}. Besides, by~\eqref{eq:suff-dec-ppa-2} with $\rho=\rho_k$ and $z = z^k$, one has $ \|\mcJ_{\rho_k}(z^k) - z^k\|  \leq \|z^k - z^*\|$. These together with \eqref{eq:iter-PPA} and \eqref{eq:iter-ppa-bd} yield
	$$ \|z^{k+1} - z^k\| \leq \|z^{k+1} - \mcJ_{\rho_k}(z^k)\| + \|\mcJ_{\rho_k}(z^k) - z^k\| \leq e_k + \|z^k - z^*\| \leq \|z^0 - z^*\| + \sum_{i=0}^k e_i.  $$
	In addition, by the definition of $\xi^k$, and \eqref{eq:suff-dec-ppa-1} 
	with $\mcJ = \mcJ_{\rho_k}$ and $z = z^k$, one has
	\begin{equation*}
	\begin{split}
	\|\mcJ_{\rho_k}(z^k) - z^k\|^2 & \leq \|z^k - z^{*}\|^2 - \|\mcJ_{\rho_k}(z^k) - z^{*}\|^2 
	= \|z^k - z^{*}\|^2 - \|\mcJ_{\rho_k}(z^k) - z^{k+1} + z^{k+1} - z^{*}\|^2 \\
	& \leq \|z^k - z^{*}\|^2 - \|z^{k+1} - z^{*}\|^2 - \|\xi^k\|^2 + 2\|\xi^k\|\|z^{k+1} - z^{*}\|.
	\end{split}
	\end{equation*}
	Summing up the above inequality from $k = K$ to $k = 2K$ and using \eqref{bdd-1}, we obtain that 
	\begin{align}
	\sum_{k=K}^{2K}\|\mcJ_{\rho_k}(z^k) - z^k\|^2 & \leq \|z^K - z^{*}\|^2 - \sum_{k=K}^{2K}\|\xi^k\|^2 + 2\sum_{k=K}^{2K}\|\xi^k\|\left(\|z^K - z^{*}\| + \sum_{j=K}^k\|\xi^j\|\right) \nn\\
	& = \|z^K - z^{*}\|^2 - \sum_{k=K}^{2K}\|\xi^k\|^2 + 2\|z^K - z^{*}\|\cdot\sum_{k=K}^{2K}\|\xi^k\| + 2\sum_{k=K}^{2K}\sum_{j=K}^k\|\xi^k\|\|\xi^j\| \nn\\
	& = \|z^K - z^{*}\|^2 - \sum_{k=K}^{2K}\|\xi^k\|^2 + 2\|z^K - z^{*}\|\cdot\sum_{k=K}^{2K}\|\xi^k\| + \sum_{k=K}^{2K}\|\xi^k\|^2 + \left(\sum_{k=K}^{2K}\|\xi^k\|\right)^2 \nn\\
	& = \|z^K - z^{*}\|^2 + 2\|z^K - z^{*}\|\cdot\sum_{k=K}^{2K}\|\xi^k\| + \left(\sum_{k=K}^{2K}\|\xi^k\|\right)^2 \nn\\
	& = \left( \|z^K - z^{*}\| + \sum_{k=K}^{2K}\|\xi^k\| \right)^2 \leq \left( \|z^0 - z^{*}\| + \sum_{k=0}^{2K}\|\xi^k\| \right)^2, \label{eq:bound-sum-jz-z}
	\end{align}
	where \eqref{eq:bound-sum-jz-z} follows from \eqref{bdd-1} with $t=0$ and $s = K$. Again, by the definition of $\xi^k$, one has
	$$ \|z^{k+1} - z^k\|^2 = \|\mcJ_{\rho_k}(z^k) + \xi^k- z^k \|^2 \leq 2\left(\|\mcJ_{\rho_k}(z^k) - z^k\|^2 + \|\xi^k\|^2\right). $$
	This together with~\eqref{eq:bound-sum-jz-z} yields
	\begin{align*}
	\sum_{k = K}^{2K}\|z^{k+1} - z^k\|^2 & \leq 2\sum_{k = K}^{2K}\|\mcJ_{\rho_k}(z^k) - z^k\|^2 + 2\sum_{k = K}^{2K}\|\xi^k\|^2 
	 \leq 2\left( \|z^0 - z^{*}\| + \sum_{k=0}^{2K}\|\xi^k\| \right)^2 + 2\sum_{k=0}^{2K}\|\xi^k\|^2 \\
	& \leq 2\left( \|z^0 - z^{*}\| + 2\sum_{k=0}^{2K}\|\xi^k\| \right)^2,
	\end{align*}
	which along with $\|\xi^k\| \le e_k$ leads to \eqref{eq:ippa-iter-cplx-min}. The proof is then completed.
\end{proof}

\begin{proof}
Since $0\in\mcT(z^*)$ and $\mcT$ is maximally monotone, it follows from \cite[Proposition 1]{Rock76a} that
\begin{equation}
\label{eq:suff-dec-ppa-1}
\| \mcJ_\rho(z) - z^*\|^2 + \|\mcJ_\rho(z) - z\|^2 \leq \|z - z^*\|^2,
\end{equation}
which implies that 
\begin{equation}
\label{eq:suff-dec-ppa-2}
\|\mcJ_\rho(z) - z^*\| \leq \|z - z^*\|, \quad \|\mcJ_\rho(z) - z\| \leq \|z - z^*\|, \quad \forall z \in \Re^n.
\end{equation}

In addition, by the definition of $\xi^k$, and \eqref{eq:suff-dec-ppa-1} 
with $\mcJ = \mcJ_{\rho_k}$ and $z = z^k$, one has
\begin{equation*}
\begin{split}
\|\mcJ_{\rho_k}(z^k) - z^k\|^2 & \leq \|z^k - z^{*}\|^2 - \|\mcJ_{\rho_k}(z^k) - z^{*}\|^2 
= \|z^k - z^{*}\|^2 - \|\mcJ_{\rho_k}(z^k) - z^{k+1} + z^{k+1} - z^{*}\|^2 \\
& \leq \|z^k - z^{*}\|^2 - \|z^{k+1} - z^{*}\|^2 - \|\xi^k\|^2 + 2\|\xi^k\|\|z^{k+1} - z^{*}\|.
\end{split}
\end{equation*}

Summing up the above inequality from $k = K$ to $k = 2K$ and using \eqref{bdd-1}, we obtain that 
\begin{align}
\sum_{k=K}^{2K}\|\mcJ_{\rho_k}(z^k) - z^k\|^2 & \leq \|z^K - z^{*}\|^2 - \sum_{k=K}^{2K}\|\xi^k\|^2 + 2\sum_{k=K}^{2K}\|\xi^k\|\left(\|z^K - z^{*}\| + \sum_{j=K}^k\|\xi^j\|\right) \nn\\
& = \|z^K - z^{*}\|^2 - \sum_{k=K}^{2K}\|\xi^k\|^2 + 2\|z^K - z^{*}\|\cdot\sum_{k=K}^{2K}\|\xi^k\| + 2\sum_{k=K}^{2K}\sum_{j=K}^k\|\xi^k\|\|\xi^j\| \nn\\
& = \|z^K - z^{*}\|^2 - \sum_{k=K}^{2K}\|\xi^k\|^2 + 2\|z^K - z^{*}\|\cdot\sum_{k=K}^{2K}\|\xi^k\| + \sum_{k=K}^{2K}\|\xi^k\|^2 + \left(\sum_{k=K}^{2K}\|\xi^k\|\right)^2 \nn\\
& = \|z^K - z^{*}\|^2 + 2\|z^K - z^{*}\|\cdot\sum_{k=K}^{2K}\|\xi^k\| + \left(\sum_{k=K}^{2K}\|\xi^k\|\right)^2 \nn\\
& = \left( \|z^K - z^{*}\| + \sum_{k=K}^{2K}\|\xi^k\| \right)^2 \leq \left( \|z^0 - z^{*}\| + \sum_{k=0}^{2K}\|\xi^k\| \right)^2, \label{eq:bound-sum-jz-z}
\end{align}
where \eqref{eq:bound-sum-jz-z} follows from \eqref{bdd-1} with $t=0$ and $s = K$. Again, by the definition of $\xi^k$, one has
$$ \|z^{k+1} - z^k\|^2 = \|\mcJ_{\rho_k}(z^k) + \xi^k- z^k \|^2 \leq 2\left(\|\mcJ_{\rho_k}(z^k) - z^k\|^2 + \|\xi^k\|^2\right). $$

	This together with~\eqref{eq:bound-sum-jz-z} yields
	\begin{align*}
	\sum_{k = K}^{2K}\|z^{k+1} - z^k\|^2 & \leq 2\sum_{k = K}^{2K}\|\mcJ_{\rho_k}(z^k) - z^k\|^2 + 2\sum_{k = K}^{2K}\|\xi^k\|^2 
	 \leq 2\left( \|z^0 - z^{*}\| + \sum_{k=0}^{2K}\|\xi^k\| \right)^2 + 2\sum_{k=0}^{2K}\|\xi^k\|^2 \\
	& \leq 2\left( \|z^0 - z^{*}\| + 2\sum_{k=0}^{2K}\|\xi^k\| \right)^2,
	\end{align*}
	which along with $\|\xi^k\| \le e_k$ leads to \eqref{eq:ippa-iter-cplx-min}. The proof is then completed.
\end{proof}

\begin{lemma}
\label{lemma:mi-al=i-ppa}
Let $\{(x^k,\lambda^k)\}$ be generated by Algorithm~\ref{alg:mi-al}. For any $k\geq 0$, one has
\begin{equation}
\label{eq:mi-al=i-ppa}
\|(x^{k+1},\lambda^{k+1}) - \mcJ_{\rho_k}(x^k,\lambda^k)\| \leq \rho_k\eta_k,
\end{equation}
where $\mcJ_{\rho_k}=(\mcI + \rho_k\mcT_l)^{-1}$ and $\mcT_l$ is defined in \eqref{eq:def-two-opt2}.
\end{lemma}

\begin{proof}
By Lemma~\ref{lemma:al-func-elp} and $\lambda^{k+1} = \Pi_{\mcK^*}\big(\lambda^k + \rho_k g(x^{k+1})\big)$, one has
\begin{equation}
\label{eq:diff-x-lambda-m}
\partial_x \mcL(x^{k+1},\lambda^k;\rho_k) = \partial_x l(x^{k+1},\lambda^{k+1}), \quad \frac{1}{\rho_k}(\lambda^{k+1} - \lambda^k) \in \partial_\lambda l (x^{k+1},\lambda^{k+1}).
\end{equation}
By~\eqref{eq:inext-subprob-m}, there exists $\|v\|\leq \eta_k$ such that
$$ v \in \partial_x \mcL(x^{k+1},\lambda^k;\rho_k) + \frac{1}{\rho_k}(x^{k+1} - x^k). $$
This together with~\eqref{eq:diff-x-lambda-m} implies that
\begin{equation}
\label{eq:diff-x-lambda-m-v}
x^k + \rho_kv \in \rho_k \partial_x l(x^{k+1},\lambda^{k+1}) +  x^{k+1}, \quad \lambda^k \in -\rho_k\partial_\lambda l(x^{k+1}, \lambda^{k+1}) + \lambda^{k+1},
\end{equation}
which, by the definition of $\mcT_l$, are equivalent to 
$$ (x^k + \rho_kv, \lambda^k) \in (\mcI + \rho_k\mcT_l)(x^{k+1},\lambda^{k+1}). $$
It follows from this and $\mcJ_{\rho_k}=(\mcI + \rho_k\mcT_l)^{-1}$ that  $(x^{k+1},\lambda^{k+1}) = \mcJ_{\rho_k}(x^k+\rho_kv,\lambda^k)$. By this and the non-expansion of $\mcJ_{\rho_k}$, we obtain
$$ \|(x^{k+1}, \lambda^{k+1}) - \mcJ_{\rho_k}(x^k,\lambda^k)\| = \|\mcJ_{\rho_k}(x^k + \rho_kv, \lambda^k) - \mcJ_{\rho_k}(x^k,\lambda^k)\| \leq \|\rho_kv\| \leq \rho_k\eta_k, $$
which yields \eqref{eq:mi-al=i-ppa} as desired. 
\end{proof}

\begin{proof}
By Lemma~\ref{lemma:al-func-elp} and $\lambda^{k+1} = \Pi_{\mcK^*}\big(\lambda^k + \rho_k g(x^{k+1})\big)$, one has
\begin{equation}
\label{eq:diff-x-lambda-m}
\partial_x \mcL(x^{k+1},\lambda^k;\rho_k) = \partial_x l(x^{k+1},\lambda^{k+1}), \quad \frac{1}{\rho_k}(\lambda^{k+1} - \lambda^k) \in \partial_\lambda l (x^{k+1},\lambda^{k+1}).
\end{equation}

By~\eqref{eq:inext-subprob-m}, there exists $\|v\|\leq \eta_k$ such that
$$ v \in \partial_x \mcL(x^{k+1},\lambda^k;\rho_k) + \frac{1}{\rho_k}(x^{k+1} - x^k). $$
This together with~\eqref{eq:diff-x-lambda-m} implies that
\begin{equation}
\label{eq:diff-x-lambda-m-v}
x^k + \rho_kv \in \rho_k \partial_x l(x^{k+1},\lambda^{k+1}) +  x^{k+1}, \quad \lambda^k \in -\rho_k\partial_\lambda l(x^{k+1}, \lambda^{k+1}) + \lambda^{k+1},
\end{equation}

Suppose that $\{\rho_k\}$  and $\{\eta_k\}$ satisfy that
\beq \label{rho-eta-m}
\rho_k>0 \ \mbox{is nondecreasing}, \quad 0<\eta_k \downarrow 0, \quad 
\frac{\sum_{i=0}^{2k}\rho_i\eta_i}{\rho_k\sqrt{k+1}} \to 0.  \footnote{For example,  $\rho_k = \rho_0\alpha^k$ and $\eta_k = \eta_0\beta^k$ satisfy \eqref{rho-eta-m} for any $\rho_0>0$, $\eta_0>0$, $\alpha>1$ and $0<\beta<1/\alpha$.}
\eeq

\item[(iii)] Furthermore, if $N$ is a nonnegative integer such that
\begin{equation}
\label{eq:cplx-out-general-m}
\frac{D + \sum_{k=0}^N \rho_k\eta_k}{\rho_N} \leq \frac{\epsilon}{2}, \quad \eta_N \leq \frac{\epsilon}{2},
\end{equation}

(iii) Let $\hat x^*$ and $\hat\lambda^*$ be defined right above \eqref{param} and \eqref{param-m}, respectively. Suppose for contradiction that Algorithm~\ref{alg:mi-al} does not terminate within $N+1$ outer iterations. It then follows that \eqref{eq:check-stop-m} does not hold for all $0\le k \le N$. Then, by \eqref{param-m}, \eqref{eq:ippa-iter-cplx}, and \eqref{eq:mi-al=i-ppa}, we have that for all $0\le k \le N$,
\begin{equation*}\label{eq:mi-ppa-bd}
\|(x^{k+1},\lambda^{k+1}) - (x^k,\lambda^k)\| \leq \|(x^0,\lambda^0) - (\hat x^*, \hat\lambda^*)\| + \sum_{i=0}^k\rho_i\eta_i \leq D + \sum_{i=0}^k\rho_i\eta_i,
\end{equation*}
where $D$ is given in \eqref{param-m}. 
By this and \eqref{eq:cplx-out-general-m}, one can see that \eqref{eq:check-stop-m} is satisfied when $k = N$, which leads to a contradiction.  
\end{proof}

