and for any $x$, define $P_{\Omega}(x)$ to be the
{(Euclidean-norm)} projection of $x$ onto the optimal set
$\Omega$.
We say that $F$ satisfies the {\em optimal set strong convexity} {(OSSC)}
condition with parameter $\mu \geq 0$, if for any $x$ and any
$\lambda \in [0,1]$, the following holds.
\begin{align}
  \nonumber
F(\lambda x + & (1 - \lambda )
P_{\Omega}(x)) \\
\label{eq:strong}
& \leq \lambda F\left(x\right) + \left(1 - \lambda\right) F^* -
\tfrac12 \mu \lambda \left( 1 - \lambda \right)  \left\|x -
P_{\Omega}\left(x\right)\right\|^2.
\end{align}
\end{definition}

Given any $x^0$, we define
\begin{equation}
R_0 \coloneqq \sup_{x: {F( x ) \leq F( x^0)}}\quad\left\|x - P_\Omega(x)\right\|.
\label{eq:r0}
\end{equation}

