%\right)_{k,\ell=1\dots d}
%P^{-1}D^{1/2}\label{eq:cov}
%\end{equation}
where $C\eqdef P^{-1}D^{1/2}\bE\left(\nabla f(x^*,\xi)\nabla f(x^*,\xi)^T\right)D^{1/2}P$.
\end{theorem}

