\end{aligned}
\right. && \text{where} && \nu = \frac1m \sum_{i=1}^m r_i^2\delta_{\theta_i},
\end{align*}

and the Wasserstein gradient is represented by the vector field
 egin{equation}\label{eq:wassersteingradient}
g_
u(r,	heta) =  ig(2 \alpha r J'_{
u}(	heta),  eta 
abla J'_{
u}(	heta) ig)  \in \RR 	imes T_	heta \Theta,  orall (r,	heta)\in \Omega.
