For now, we will say that the iterates are in a $\delta$-region of zero gradient if the squared-norm of the gradient of the iterate is no greater than $\delta$. If we let $\tau = -1$, then $\tau_\delta$ is the first time the iterates enter a $\delta$-region of zero gradient. Let $T_1(\delta) = \tau_\delta$ when $\tau = -1$. Then, from the above argument, we have shown that $T_1(\delta)$ is a finite stopping time. Now, define $T_j(\delta)$ to be the $j^{th}$ time that the iterates enter a $\delta$-region of zero gradient. Suppose that $T_j(\delta)$ is finite. Then, define $\tau = T_j(\delta)$. Then, $\tau_\delta$ for this $\tau$ is the next time that the iterates enter a $\delta$-region of zero gradient. That is, $T_{j+1}(\delta) = \tau_\delta + T_j(\delta)$. Since we have assumed that $\tau = T_{j}(\delta)$ is finite, we conclude that $\tau_\delta$ is finite, which implies that $T_{j+1}(\delta)$ is finite. Therefore, by induction we have proven the following result.

\begin{theorem} \label{theorem-revisit}
Let $F$ be a Bottou-Curtis-Nocedal function (\ref{bcn}) and let $\lbrace \beta_k \rbrace$ be the iterates generated by Stochastic Gradient Descent satisfying \ref{prop-sympd} to \ref{prop-condnum} (\S \ref{subsection-sgd}), then, for any $\delta > 0$,
\begin{equation}
\condPrb{ \norm{ \dot F( \beta_k)}_2^2 \leq \delta, ~i.o.}{\mathcal{F}_0} = 1 ~\text{with probability 1},
\end{equation}
where $\mathcal{F}_0 = \sigma(\beta_0)$.
\end{theorem}

Again, we will temporarily drop the conditioning on $\mathcal{F}_0$ for simplicity of the notation. By Theorem \ref{theorem-revisit} and the inclusion-exclusion principle, 
\begin{align}
1 &= \Prb{\left\lbrace \norm{ \dot F(\beta_k)}_2 \leq \delta, ~i.o. \right\rbrace \cup \left\lbrace \norm{ \dot F(\beta_k)}_2 > \delta, ~i.o. \right\rbrace } \\
  &\begin{aligned}
  &= \Prb{ \norm{ \dot F(\beta_k)}_2 \leq \delta, ~i.o.} + \Prb{\norm{ \dot F(\beta_k)}_2 > \delta, ~i.o.} \\
  &- \Prb{ \left\lbrace \norm{ \dot F(\beta_k)}_2 \leq \delta, ~i.o. \right\rbrace \cap \left\lbrace \norm{ \dot F(\beta_k)}_2 > \delta, ~i.o. \right\rbrace }.
  \end{aligned}
\end{align}
Applying Theorem \ref{theorem-revisit} again, we conclude that
\begin{equation} \label{eqn-inc-exc}
\begin{aligned}
&\Prb{\norm{ \dot F(\beta_k)}_2 > \delta, ~i.o.} \\
&\quad = \Prb{ \left\lbrace \norm{ \dot F(\beta_k)}_2 \leq \delta, ~i.o. \right\rbrace \cap \left\lbrace \norm{ \dot F(\beta_k)}_2 > \delta, ~i.o. \right\rbrace }.
\end{aligned}
\end{equation}

We will now show that the probability of the right hand side is zero. Note, for any outcome
\begin{equation}
\omega \in \left\lbrace \norm{ \dot F(\beta_k)}_2 \leq \delta, ~i.o. \right\rbrace \cap \left\lbrace \norm{ \dot F(\beta_k)}_2 > \delta, ~i.o. \right\rbrace,
\end{equation}
there must be an infinite subsequence of $\mathbb{N}$ such that $\beta_k$ is in a $\delta^2$-region of zero gradient and then $\beta_{k+1}$ exits this $\delta^2$-region of zero gradient. Suppose this were not true. Then, there are two cases. In the first case, $\beta_k$ enters a $\delta^2$-region of zero gradient and then never leaves, in which case
\begin{equation}
\omega \not\in \left\lbrace \norm{ \dot F(\beta_k)}_2 > \delta, ~i.o. \right\rbrace.
\end{equation}
In the second case, we have that $\beta_k$ exits a $\delta^2$-region of zero gradient, and never enters again, which implies 
\begin{equation}
\omega \not\in \left\lbrace \norm{ \dot F(\beta_k)}_2 \leq \delta, ~i.o. \right\rbrace.
\end{equation}
In both cases, we have a contradiction. Therefore, using just one of the cases, we conclude that
\begin{equation} \label{eqn-set-inc-1}
\begin{aligned}
&\left\lbrace \norm{ \dot F(\beta_k)}_2 \leq \delta, ~i.o. \right\rbrace \cap \left\lbrace \norm{ \dot F(\beta_k)}_2 > \delta, ~i.o. \right\rbrace \\
&\quad \subset \left\lbrace \norm{\dot{F}(\beta_k)}_2 \leq \delta,~ \norm{\dot{F}(\beta_{k+1})}_2 > \delta, ~i.o. \right\rbrace.
\end{aligned}
\end{equation}

We can write this latter event as
\begin{equation} \label{eqn-set-inc-2}
\begin{aligned}
&\left\lbrace \norm{\dot{F}(\beta_k)}_2 \leq \delta,~ \norm{\dot{F}(\beta_{k+1})}_2 > \delta, ~i.o. \right\rbrace \\
&\quad = 
\left\lbrace \norm{ \dot{F}(\beta_{k+1})}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} > \delta, ~i.o. \right\rbrace.
\end{aligned}
\end{equation}

We will now show that this ultimate event occurs with probability zero using Markov's inequality and the Borel-Cantelli lemma. Let $\epsilon > 0$ and recall that $C > 0$ is the parameter in \ref{condition-dg-lipschitz}. Then,
\begin{align}
&\condPrb{ \norm{ \dot{F}(\beta_{k+1})}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} \geq \delta + C \epsilon }{\mathcal{F}_k} \\
&\begin{aligned}
&\leq \mathbb{P}\bigg{[} \left( \norm{ \dot{F}(\beta_{k+1}) - \dot{F}(\beta_k) }_2 + \norm{ \dot{F}(\beta_k)}_2 \right) \1{ \norm{\dot{F}(\beta_k)}_2\leq \delta}  \\
&\quad  \geq \delta + C \epsilon \bigg{\vert} \mathcal{F}_k \bigg{]}
\end{aligned} \\
&\leq \condPrb{ \norm{ \dot{F}(\beta_{k+1}) - \dot{F}(\beta_k)}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} + \delta \geq \delta + C \epsilon}{\mathcal{F}_k}\\
& \leq \condPrb{ C \norm{\beta_{k+1} - \beta_k}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} \geq  C \epsilon}{\mathcal{F}_k} \\
& \leq \condPrb{ \norm{M_k \dot{f}(\beta_k, X_{k+1})}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} \geq   \epsilon}{\mathcal{F}_k}
\end{align}

Applying Markov's inequality to the last conditional probability and using \ref{condition-noise-grad},
\begin{align}
&\condPrb{ \norm{ \dot{F}(\beta_{k+1})}_2 \1{ \norm{\dot{F}(\beta_k)}_2 \leq \delta} \geq \delta + C \epsilon }{\mathcal{F}_k} \\
