In this paper, we consider the regularized nonconvex stochastic programming
\begin{equation}\label{eq:stoc-prob}
\Phi^*= \Min_{\vx\in\RR^n} ~\Phi(\vx):= \big\{F(\vx)\equiv\EE_\xi [f(\vx;\xi)]\big\} + r(\vx), 
\end{equation}

where $f(\,\cdot\,; \xi)$ is a smooth nonconvex function almost surely for $\xi$, and $r$ is a closed convex function on $\RR^n$. Examples of \eqref{eq:stoc-prob} include the sparse online matrix factorization \cite{mairal2010online}, the online nonnegative matrix factorization \cite{zhao2016online}, and the streaming PCA (by a unit-ball constraint) \cite{mitliagkas2013memory}. In addition, as $\xi$ follows a uniform distribution on a finite set $\Xi=\{\xi_1,\ldots,\xi_N\}$, \eqref{eq:stoc-prob} recovers the so-called finite-sum structured problem. It includes most regularized machine learning problems such as the sparse bilinear logistic regression \cite{shi2014sparse}, the sparse convolutional neural network \cite{liu2015sparse}, and the group sparse regularized deep neural networks \cite{scardapane2017group}. 


Let $w$ be a continuously differentiable and 1-strongly convex function on $\dom(r)$, i.e., 
$$w(\vy) \ge w(\vx) + \langle \nabla w(\vx), \vy-\vx\rangle + \frac{1}{2}\|\vy-\vx\|^2,\, \forall\, \vx,\vy\in \dom(r).$$
The Bregman divergence induced by $w$ is defined as
\begin{equation}
V(\vx,\vz)=w(\vx)-w(\vz) - \langle \nabla w(\vz), \vx-\vz\rangle.
\end{equation}


\begin{algorithm}[h]
\caption{Momentum-based variance-reduced proximal stochastic gradient method for \eqref{eq:stoc-prob}}\label{alg:prox-storm}
\DontPrintSemicolon
\textbf{Input:} max iteration numer $K$, minibatch size $m$, and positive sequences $\{\beta_k\}\subseteq(0,1)$ and $\{\eta_k\}$.\;
\textbf{Initialization:} choose $\vx^0\in\dom(r)$ and let $\vd^0 = \frac{1}{m_0}\sum_{\xi\in B_0}\nabla f(\vx^0;\xi)$ with $m_0$ i.i.d. samples $B_0=\{\xi_1^0,\ldots,\xi_{m_0}^0\}$\;
\For{$k=0, 1,\ldots, K-1$}{
Update $\vx$ by
\begin{equation}\label{eq:update-x}
\vx^{k+1}=\argmin_{\vx} \left\{\langle \vd^k, \vx\rangle + \frac{1}{\eta_k}V(\vx,\vx^k) + r(\vx)\right\}.\vspace{-0.3cm}
\end{equation}
\;
Obtain $m$ i.i.d. samples $B_{k+1}=\{\xi_1^{k+1},\ldots,\xi_m^{k+1}\}$ and let 
\begin{equation}\label{eq:def-v-u-k}
\textstyle \vv^{k+1} = \frac{1}{m}\sum_{\xi\in B_{k+1}}\nabla f(\vx^{k+1}; \xi),\quad \vu^{k+1} = \frac{1}{m}\sum_{\xi\in B_{k+1}}\nabla f(\vx^{k}; \xi).\vspace{-0.3cm}
\end{equation}\;
Let $\vd^{k+1} = \vv^{k+1} + (1-\beta_{k})(\vd^{k}-\vu^{k+1})$.\;
}
Return $\vx^\tau$ with $\tau$ selected from $\{0,1,\ldots,K-1\}$ uniformly at random or by the distribution
\begin{equation}\label{eq:select-tau}
\textstyle \Prob(\tau = k) = \frac{\frac{\eta_k}{4}(1-\eta_k L)-\frac{\eta_k^2}{5m\eta_{k+1}}(1-\beta_k)^2}{\sum_{j=0}^{K-1}\left(\frac{\eta_j}{4}(1-\eta_j L)-\frac{\eta_j^2}{5m\eta_{j+1}}(1-\beta_j)^2\right)},\, k = 0,1,\ldots,K-1.
\end{equation}
\vspace{-0.2cm}
\end{algorithm}

We use bold lowercase letters $\vx,\vy,\vg,\ldots$ for vectors. $\EE_{B_{k}}$ denotes the expectation about a mini-batch set $B_{k}$ conditionally on the all previous history, and $\EE$ denotes the full expectation. $|B_k|$ counts the number of elements in the set $B_k$. We use $\|\cdot\|$ for the Euclidean norm. A differentiable function $F$ is called $L$-smooth, if $\|\nabla F(\vx)-\nabla F(\vy)\|\le L\|\vx-\vy\|$ for all $\vx$ and $\vy$.


\begin{definition}[proximal gradient mapping]\label{def:prox-map}
Given $\vd$, $\vx\in\dom(r)$, and $\eta>0$, we define $P(\vx,\vd,\eta)=\frac{1}{\eta}(\vx-\vx^+)$, where 
%\begin{equation*}
$\vx^+ =\argmin_\vy \textstyle \left\{\langle \vd, \vy\rangle  +\frac{1}{\eta}V(\vy,\vx) + r(\vy)\right\}.$
%\end{equation*}
\end{definition}

From \cite[Lemma 1]{ghadimi2016mini}, it holds
\begin{equation}\label{eq:lem1-lan}
\big\langle \vd, P(\vx,\vd,\eta)\big\rangle \ge \|P(\vx,\vd,\eta)\|^2 + \frac{1}{\eta}\big(r(\vx^+)-r(\vx)\big).
\end{equation}

In addition, the proximal gradient mapping is nonexpansive from \cite[Proposition 1]{ghadimi2016mini}, i.e.,
\begin{equation}\label{eq:nonexp-P}
\|P(\vx, \vd_1, \eta) - P(\vx, \vd_2, \eta)\| \le \|\vd_1-\vd_2\|, \ \forall\, \vd_1,\vd_2, \, \forall\, \vx\in \dom(r), \, \forall\, \eta > 0.
\end{equation}

For each $k\ge0$, we denote
\begin{equation}\label{eq:vg-vgbar}
\vg^k = P(\vx^k, \vd^k, \eta_k),\quad \bar\vg^k = P(\vx^k, \nabla F(\vx^k), \eta_k).
\end{equation}

Notice that $\|\bar\vg^k\|$ measures the violation of stationarity of $\vx^k$. The gradient error is represented by
\begin{equation}\label{eq:error-grad}
\ve^k = \vd^k - \nabla F(\vx^k).
\end{equation}

\begin{assumption}[finite optimal objective]\label{assump-obj}
The optimal objective value $\Phi^*$ of \eqref{eq:stoc-prob} is finite.
\end{assumption}

\begin{assumption}[mean-squared smoothness]\label{assump-smooth}
The function $f(\,\cdot\,;\xi)$ satisfies the mean-squared smoothness condition:  
$\EE_\xi \big[\|\nabla f(\vx;\xi) - \nabla f(\vy;\xi)\|^2\big] \le L^2 \|\vx-\vy\|^2,\, \forall\, \vx,\vy\in \dom(r).$
\end{assumption}

\begin{assumption}[unbiasedness and variance boundedness]\label{assump-sgd}
There is $\sigma>0$ such that %for each $\vx\in \dom(r)$, 
\begin{align}
\EE_\xi [\nabla f(\vx; \xi)] = \nabla F(\vx),\quad \EE[\|\nabla f(\vx; \xi) - \nabla F(\vx)\|^2] \le \sigma^2, \ \forall\, \vx\in \dom(r).
%&\EE_{B_k}[\vv^k] = \nabla F(\vx^k),\quad \EE_{B_k}[\vu^k] = \nabla F(\vx^{k-1}),\\
%&\EE[\|\vv^k-\nabla F(\vx^k)\|^2] \le \sigma^2.
\end{align}
\end{assumption}

It is easy to show that under Assumptions~\ref{assump-smooth} and \ref{assump-sgd}, the function $F(\vx)=\EE_\xi [f(\vx;\xi)]$ is $L$-smooth; see the arguments at the end of section~2.2 of \cite{tran2021hybrid}. 


\begin{equation}\label{eq:gamma}
	\Gamma_k = \left\{
	\begin{array}{ll}
		\prod_{i=0}^{k-1}(1-\beta_i)^2, & \text{ if } k\ge 1, \\[0.2cm]
		1, & \text{ if } k=0.
	\end{array}
	\right.
\end{equation}

