\begin{equation}
    \label{eq:sgd-proximal-iterates}
    x_0 \in \R^d, \quad x_{k+1} = \prox_{\gamma_k R} \br{ x_k - \gamma_k g_k },
\end{equation}

\begin{assumption} \label{asm:function-class}
The function $f$ is  $L$--smooth and convex:
\begin{align}
f(y) & \leq f(x) + \langle \nabla f(x), y - x \rangle + \frac{L}{2} \norm{y-x}^2,  \quad \mbox{for all }x,y \in \R^d, \label{eq:Lsmooth}\\
f(y )& \geq f(x) + \langle \nabla f(x), y - x \rangle, \quad \mbox{for all }x,y \in \R^d. \label{eq:convex}
\end{align}
The function $R$ is convex:
\begin{equation}\label{eq:R-convex}
R(\alpha x + (1- \alpha) y) \geq \alpha R(x) + (1-\alpha) R(y), \quad \mbox{for all }x,y \in \R^d, \alpha \in [0,\,1].
\end{equation}

\end{assumption}

\begin{assumption}[Assumption 4.1 in \cite{Gorbunov19}]\label{asm:main_assumption}
Consider the iterates $\br{x_k}_k$ and gradients $\br{g_k}_k$ in \eqref{eq:sgd-proximal-iterates}.
    \begin{enumerate}
        \item The gradient estimates are unbiased:
        \begin{equation}
            \label{eq:asm-gradient-unbiased}
            \ec{g_k \mid x_k} = \nabla f(x_k).
        \end{equation}
        \item There exist constants $A,B,C,D_1, D_2, \rho \geq 0$, and a sequence of random variables $\sigma^2_k \geq 0 $  such that:
        \begin{align}
            \label{eq:asm-gradient-opt-distance}
            \ec{ \norm{g_k - \nabla f(x_\ast)}^2 \mid x_k } &\leq 2 A D_{f} (x_k, x_\ast) + B \sigma_k^2 + D_1, \\
            \label{eq:asm-decreasing-noise}
            \ec{ \sigma_{k+1}^2 \mid x_k } &\leq \br{ 1 - \rho } \sigma_k^2 + 2 C D_{f} (x_k, x_\ast) + D_2.
        \end{align}
    \end{enumerate} 
\end{assumption}

\begin{definition}
    Given a stepsize $\gamma > 0$, the prox-grad mapping is defined as:
    \begin{equation}
        T_{\gamma} (x) \eqdef \prox_{\gamma R} \br{x - \gamma \nabla f(x)}.
    \end{equation}
\end{definition}

\begin{lemma}[Bounding the gradient variance] Assuming that the $g_k$ are unbiased and that Assumption~\ref{asm:main_assumption} holds, we have
    \begin{equation}
        \label{eq:lma-gradient-variance}
        \ecn{g_k - \nabla f(x_k)}  \leq 2 A D_{f} (x_k, x_\ast) + B \sigma_k^2 + D_1
    \end{equation}
\end{lemma}

\begin{proof}
    Starting from the left hand side of \eqref{eq:lma-gradient-variance}, we have
    \begin{align*}
        \ecn{g_k - \nabla f(x_k)} &= \ecn{ g_k - \nabla f(x_\ast) - \br{ \nabla f(x_k) - \nabla f(x_\ast) } } \\
        &= \ecn{ g_k - \nabla f(x_\ast) - \ec{ g_k - \nabla f(x_\ast) } } \\
        &\leq \ecn{g_k - \nabla f(x_\ast)} \leq 2 A D_{f} (x_k, x_\ast) + B \sigma_k^2 + D_1,
    \end{align*}
    where we used that $\ecn{ X - \ec{X} } = \ecn{X} - \norm{\ec{X}}^2 \leq \ecn{X}$ for any random variable $X$.
\end{proof}

\begin{proof}
    Starting from the left hand side of \eqref{eq:lma-gradient-variance}, we have
    \begin{align*}
        \ecn{g_k - \nabla f(x_k)} &= \ecn{ g_k - \nabla f(x_\ast) - \br{ \nabla f(x_k) - \nabla f(x_\ast) } } \\
        &= \ecn{ g_k - \nabla f(x_\ast) - \ec{ g_k - \nabla f(x_\ast) } } \\
        &\leq \ecn{g_k - \nabla f(x_\ast)} \leq 2 A D_{f} (x_k, x_\ast) + B \sigma_k^2 + D_1,
    \end{align*}
    where we used that $\ecn{ X - \ec{X} } = \ecn{X} - \norm{\ec{X}}^2 \leq \ecn{X}$ for any random variable $X$.
\end{proof}

\begin{lemma}
    \label{lemma:atchade-functional-value-bound}
    Suppose that Assumption~\ref{asm:function-class} holds and let $\gamma \in \left (0, \frac{1}{L} \right ]$, then for all $x, y \in \R^d$ and $p = \prox_{\gamma g}(y)$ we have,
    \begin{equation}
        \label{eq:atchade-lemma}
        - 2 \gamma \br{ F(p) - F(x_\ast) } \geq \sqn{p - z } + 2  \ev{p - x_\ast, x - \gamma \nabla f(x) - y} - \sqn{x_\ast - x}.
    \end{equation}
\end{lemma}

\begin{proof}
