\begin{defi} \label{df:cgnep} \rm
The GNEP given by (\ref{eq:GNEP}) is called {\it convex}
\footnote{
In some literature, this is also called player-convex,
to distinguish from jointly-convex GNEPs; see \cite{dreves2012nonsmooth}.}
if for all
$i=1,\ldots, N$ and for all given $\xmi\in\dom(X_i)$,
the objective $f_i(\xpi,\xmi)$ is convex in $x_i$ on $X_i(\xmi)$,
all $g_{i,j}(\xpi,\xmi) \, (j\in\mc{E}_i)$
are affine linear in $\xpi$,
and all $g_{i,j}(\xpi,\xmi) \, (j\in\mc{I}_i)$ are concave in $\xpi$.
\end{defi}

Throughout the paper, a property is said to hold {\it generically}
if it holds for all points in the space of input data
except a set of Lebesgue measure zero.

\be
\label{eq:KKTwithLMalp}
\left\{
\begin{array}{l}
\nabla_{x_i} f_i(x)-\sum_{j=1}^{m_i}\lambda_{i,j}\nabla_{x_i} g_{i,j}(x)=0\,(i\in[N]),\\
\lambda_i\perp g_i(x)\,(i\in[N]),\,g_{i,j}(x)=0\,(i\in[N],j\in\mathcal{E}_i),\\
\lambda_{i,j}\ge0\,(i\in[N],j\in\mathcal{I}_i),\,g_{i,j}(x)\ge0\,(i\in[N],j\in\mathcal{I}_i).\\
\end{array}
\right.
\ee

\be
\label{eq:KKTfeasoptrtn}
\left\{
\begin{array}{rll}
\min\limits_{x\in X} & [x]_1^T\Theta[x]_1 \\
\st &q_i(x)\nabla_{x_i} f_i(x)-\sum\nolimits_{j=1}^{m_i}\hat{\lambda}_{i,j}(x)\nabla_{x_i} g_{i,j}(x)=0\,(i\in[N]),\\
	&\hat{\lambda}_{i,j}(x)\perp g_{i,j}(x)\,(j\in\mathcal{E}_i\cup\mc{I}_i,i\in[N]),\\
	% &g_{i,j}(x)=0\,(j\in\mathcal{E}_i,i\in[N]),\\
	% &g_{i,j}(x)\ge0\,(j\in\mathcal{I}_i,i\in[N]),\\
	&\hat{\lambda}_{i,j}(x)\ge0\,(j\in\mathcal{I}_i,i\in[N]).
\end{array}
\right.
\ee

\be
\label{eq:KKTfeasoptprt}
\left\{
\begin{array}{rll}
\min\limits_{\allx\in X\times\re^s} & \lvt\allx\rvt_1^T\Theta\lvt\allx\rvt_1 \\
\st &\nabla_{x_i} f_i(x)-\sum\nolimits_{j=1}^{m_i}\hat{\lambda}_{i,j}(\allx)\nabla_{x_i} g_{i,j}(x)=0 \, (i\in[N]),\\
	&\hat{\lambda}_{i,j}(\allx)\perp g_{i,j}(x)\,(j\in\mathcal{E}_i\cup\mc{I}_i,i\in[N]),\\
	&\hat{\lambda}_{i,j}(\allx)\ge0\,(j\in\mathcal{I}_i,i\in[N]).
\end{array}
\right.
\ee

\be
\label{eq:KKTfeasopt}
\left\{
\begin{array}{rll}
\min\limits_{\allx} & \lvt\allx\rvt_1^T\Theta\lvt\allx\rvt_1 \\
\st &q_i(x)\nabla_{x_i} f_i(x)-\sum\nolimits_{j=1}^{m_i}\hat{\lambda}_{i,j}(\allx)\nabla_{x_i} g_{i,j}(x)=0 \, (i\in[N]),\\
	&\hat{\lambda}_{i,j}(\allx)\perp g_{i,j}(x)\,(j\in\mathcal{E}_i\cup\mc{I}_i,i\in[N]),\\
	&g_{i,j}(x)=0\,(j\in\mathcal{E}_i,i\in[N]),\\
	&g_{i,j}(x)\ge0\,(j\in\mathcal{I}_i,i\in[N]),\\
	&\hat{\lambda}_{i,j}(\allx)\ge0\,(j\in\mathcal{I}_i,i\in[N]).
\end{array}
\right.
\ee

\begin{equation}
\left\{
\begin{array}{llll}
\delta_i := & \min\limits_{\xpi}& f_i(x_i,u_{-i})-f_i(u_{i},u_{-i})&\\
 &\st  &  g_{i,j}(x_{i},u_{-i})=0 \, (j\in\mc{E}_i), \
 g_{i,j}(x_{i},u_{-i})\ge0 \, (j\in\mc{I}_i).
\end{array}
\right.
\label{eq:checkopt}
\end{equation}

\begin{alg}
\label{ag:KKTSDP} \rm
For the convex GNEP given by (\ref{eq:GNEP}),
do the following:

\begin{description}

\item [Step~0]
Choose a generic positive definite matrix $\Theta$ of length $n+s+1$.

\item [Step~1]
Solve the polynomial optimization \reff{eq:KKTfeasopt}.
If it is infeasible, then there are no KKT points and stop;
otherwise, solve it for a minimizer $(u,w)$.

\item [Step~2]
If all $q_i(u) >0$, then $u$ is a GNE. Otherwise,
for those $i$ with $q_i(u) \le 0$, solve the optimization \reff{eq:checkopt}
for the minimum value $\delta_i$.
If $\delta_i \ge 0$ for all such $i$, then $u$ is a GNE;
otherwise, it is not.

\end{description}
\end{alg}

\begin{prop}
\label{pr:rtn}
For the GNEPP given by (\ref{eq:GNEP}), suppose for each $i\in[N]$,
the Lagrange multiplier vector $\lambda_i$
has the rational expression as in Definition~\ref{LME:rat}.
\begin{enumerate}[(i)]
\item If (\ref{eq:KKTfeasoptrtn}) is infeasible,
then the GNEP has no KKT points. Therefore,
if every GNE is a KKT point,
then the infeasibility of (\ref{eq:KKTfeasoptrtn})
implies the nonexistence of GNEs.

\item Assume the GNEP is convex.
If $u$ is a feasible point of (\ref{eq:KKTfeasoptrtn})
and $q_i(u)>0$ for all $i\in[N]$, then $u$ must be a GNE.
\end{enumerate}
\end{prop}

Suppose for each $i$, there exists a rational expression
$\hat{\lambda}_i/q_i$ for the $i$th player's Lagrange multiplier vector.
Since $q_{i}(x)\lambda_{i,j}=\hat{\lambda}_i(x)$
and $q_i(x)\ge0$ for all $x\in X$,
the following holds for all KKT points
\be
\label{eq:KKTrational}
\left\{
\begin{array}{l}
q_i(x)\nabla_{x_i} f_i(x)-\sum\nolimits_{j=1}^{m_i}
 \hat{\lambda}_{i,j}(x)\nabla_{x_i} g_{i,j}(x)=0 \, (i\in[N]),\\
\hat{\lambda}_i(x)\perp g_i(x),g_{i,j}(x)=0 \, (j\in\mathcal{E}_i,i\in[N]),\\
g_{i,j}(x)\ge0,\hat{\lambda}_{i,j}(x)\ge0\,(j\in\mathcal{I}_i,i\in[N]).
\end{array}
\right.
\ee

The optimality conditions (\ref{eq:KKTwithLMalp})
can be equivalently expressed as
\be
\label{eq:KKTpartial}
\left\{
\begin{array}{l}
\nabla_{x_i} f_i(x)-\sum_{j=1}^{m_i}\hat{\lambda}_{i,j}(\allx)\nabla_{x_i} g_{i,j}(x)=0 \, (i\in[N]),\\
\hat{\lambda}_i(\allx)\perp g_i(x),g_{i,j}(x)=0 \, (j\in\mathcal{E}_i, i\in[N]),\\
g_{i,j}(x)\ge0,\hat{\lambda}_{i,j}(\allx)\ge0\,(j\in\mathcal{I}_i,i\in[N]).
\end{array}
\right.
\ee

\begin{thm}
\label{tm:KKTSDPconv}
For the convex GNEPP given by (\ref{eq:GNEP}),
suppose each Lagrange multiplier vector $\lambda_i$ has a rational expression
as in Definition~\ref{LME:rat}
or a parametric expression as in Definition~\ref{def:para:LME}.

\begin{enumerate}[(i)]


\item If $(u,w)$ is a feasible point of (\ref{eq:KKTfeasopt})
such that $q_i(u)>0$ for all $i$, then $u$ is a GNE.


\item Assume every GNE is a KKT point.
If (\ref{eq:KKTfeasopt}) is infeasible, then the GNEP has no GNEs.
If $\Theta$ is positive definite and every
$q_i(x)>0$ for all feasible $x$ of (\ref{eq:KKTfeasopt}),
then Algorithm~\ref{ag:KKTSDP} will find a GNE if it exists.
\end{enumerate}
\end{thm}

