\begin{theorem} \label{theorem:SPMD_reg}
Suppose that 
$\eta_k = \eta = \tfrac{1-\gamma}{\gamma \mu}$
in the SPMD method. 
If $\varsigma_k =2^{-(\lfloor k/l \rfloor+2)}$ and $\sigma_k^2 = 2^{-(\lfloor k/l \rfloor+2)}$ 
for any $k \ge 0$ with $l :=\left \lceil  \log_\gamma (1/4) \right \rceil
$,
then 
\begin{align}
& \bbe_{\xi_{\lceil k-1 \rceil}} [f(\pi_{k}) - f(\pi^*) 
+ \tfrac{\mu}{1-\gamma} \cD(\pi_{k},\pi^*)]\nn \\
&\le 2^{-\lfloor k/l \rfloor}\left [f(\pi_0) - f(\pi^*) +\tfrac{1}{1-\gamma}( \mu  \log |\cA|
+ \tfrac{5} {2} + \tfrac{ 5}{8 \gamma \mu})\right]. \label{eq:SPMD_reg_MDP_results_uniform_constant1}
\end{align}
\end{theorem}

