    % \end{align}
    $(3+\sigma)L_k\gamma_k^2 D_X^2 \leq \varepsilon$. Applying Lemma \ref{lem:lkgammak}, it follows that such relation holds whenever
    \begin{align}
        \frac{(3+\sigma)C_\nu D_X^2  M_\nu^{\frac{2}{1+\nu}}}{k^{\frac{1+3\nu}{1+\nu}}\varepsilon^{\frac{1-\nu}{1+\nu}}} \leq \varepsilon,\text{ i.e., }k\ge C_\nu^\frac{1+\nu}{1+3\nu}\left(\frac{(3+\sigma)^{\frac{1+\nu}{2}}M_\nu D_X^{1+\nu}}{\varepsilon}\right)^\frac{2}{1+3\nu}.
    \end{align}
    Noting that $C_\nu$ defined in \eqref{eq:c} is a constant that depends only on $\nu\in[0,1]$ and observing that $C_\nu^\frac{1+\nu}{1+3\nu} \leq 16$ for all $\nu \in [0,1]$, we conclude that whenever $k \geq N_{\text{grad}}$, $y_k$ is an $\varepsilon$-solution. Therefore, UCGS requires at most $N_{\text{grad}}$ gradient evaluations of $\grad f$ to compute an $\varepsilon$-solution.
    % \begin{align}
    %     k \geq 24\left(\frac{D_X^{1+\nu}M_\nu^\frac{2}{1+\nu}}{\varepsilon}\right)^\frac{2}{1+3\nu} = N_{grad}
    % \end{align}

    It suffices to compute the number of linear objective optimizations that UCGS requires for computing an $\varepsilon$-solution. This is equivalent to estimating the total number of inner iterations that UCGS requires.
    % Note first that whenever the termination criterion \eqref{eq:actual_termi} is satisfied, then we have
    % \begin{align}
