\begin{lemma} \label{subdifferentials}

\begin{itemize}

 \item[(i)] We have
 \begin{eqnarray}\label{subfi}
  \partial\|{\bfy}_+\|_0
  =\left\{{\bfv}\in {\R}^m: v_i\left\{\begin{array}{ll}
 \geq0,& y_i=0,\\
 =0,& y_i\neq0,
 \end{array}
 \right. i\in{\N}_m\right\}. 
 \end{eqnarray}

 \item[(ii)] Let $g(\bfx):=\|(h(\bfx))_+\|_0$, where $h:\R^n\rightarrow\R^m$ is differentiable,  and $\Gamma:=\{i\in\N_m: h_i(  \bfx)=0\}$ for a given a point $ \bfx\in\R^n$.  If 
 \begin{eqnarray}
 \label{chain-rule-cond}
 \left.
 \begin{array}{r}
 \forall \bfz\in\R^{|\Gamma|},~~\bfz\geq 0,~~
 (\nabla h( \bfx))_{\Gamma}^\top \bfz = 0
 \end{array}\right.~~\Longrightarrow~~\bfz = 0,
 \end{eqnarray}
 then the subdifferential of $g(\bfx)$  at $  \bfx$ is  
 \begin{eqnarray}
 \label{chain-rule-sub} 
 \partial g(  \bfx)=\nabla h( \bfx)^\top \partial \|(h(  \bfx))_+\|_0.
 \end{eqnarray}

\end{itemize}
\end{lemma}

\begin{proof}
i)   It is straight to check that the regular subdifferential $\widehat{\partial}\|{\bfy}_+\|_0$ (see \cite[Definition 8.3]{RW1998})  of $\|{\bfy}_+\|_0$ at ${\bfy}$ takes the following form,
\begin{eqnarray}\label{subfi-0}
 \widehat{\partial}\|{\bfy}_+\|_0=\left\{{\bfv}\in {\R}^m: v_i\left\{\begin{array}{ll}
 \geq0,& y_i=0,\\
 =0,& y_i\neq0,
 \end{array}
 \right. i\in{\N}_m\right\}=:\Omega(\bfy). 
\end{eqnarray}
We next verify $ \partial\|{\bfy}_+\|_0= \Omega({\bfy}) $. By letting $\varphi(\cdot):=\|(\cdot)_+\|_0$, we have
  \begin{eqnarray}\label{sub-lim-reg}
  \arraycolsep=1.4pt\def\arraystretch{1.5}
  \begin{array}{rclll}
\partial\|{\bfy}_+\|_0&=&\limsup_{{\bfz}\stackrel{\varphi}{\rightarrow}{\bfy}}~ \widehat{\partial}\|{\bfz}_+\|_0 ~~~( \text{by  \cite[Equation 8(5)]{RW1998}})\\
&=&\limsup_{{\bfz}\stackrel{\varphi}{\rightarrow}{\bfy}}~\Omega({\bfz}) ~~~~~~( \text{by \eqref{subfi-0}})\\
&=&\{\bfv\in \R^m:\exists~\bfz^k\stackrel{\varphi}{\rightarrow} \bfy,~\bfv^k\rightarrow \bfv ~\text{with}~\bfv^k\in \Omega(\bfz^k) \}=:\Theta,
\end{array}
 \end{eqnarray}
where  $\bfz\stackrel{\varphi}{\rightarrow} \bfy$ represents $\bfz\rightarrow \bfy, \varphi(\bfz)\rightarrow \varphi(\bfy)$. Clearly, $\Omega({\bfy})\subseteq\Theta$. On the other hand, $\Theta \subseteq \Omega({\bfy})$  follows from that $\Omega(\bfz^k)\subseteq \Omega(\bfy)$ for any $\bfz^k\stackrel{\varphi}{\rightarrow} \bfy$ and $\Omega(\cdot)$ is closed.

 ii) Direct verifications yield the following chain of equations,
 \begin{eqnarray*}  \arraycolsep=1.4pt\def\arraystretch{1.5}
  \begin{array}{rclll}
 \partial^\infty \|\bfy_+\|_0&=& {\limsup}_{\sigma\downarrow0,~{\bfz}\stackrel{\varphi}{\rightarrow} {\bfy}} \sigma \widehat{\partial}\|\bfz_+\|_0&~~( \text{by \cite[Equation 8(5)]{RW1998}})\\ 
&=&
 {\limsup}_{{\bfz}\stackrel{\varphi}{\rightarrow} {\bfy}}~ \widehat{\partial}\|\bfz_+\|_0&~~( \text{by \eqref{subfi-0}})\\
 & =& \partial\|{\bfy}_+\|_0,&~~( \text{by \eqref{sub-lim-reg}})\\
 \end{array}
 \end{eqnarray*}
 where $ \partial^\infty \|{\bfy}_+\|_0$ is the horizon subdifferential of $\|{\bfy}_+\|_0$. Therefore, we derive that $\widehat{\partial}\varphi=\partial \varphi=\partial^\infty \varphi$.  One can easily prove that the horizon cone $\widehat{\partial}\varphi(\bfy)^\infty$ (see \cite[Definition 3.3]{RW1998}) of $ \widehat{\partial}\varphi(\bfy)$ satisfies $\widehat{\partial}\varphi(\bfy)^\infty = \partial^ \infty\varphi(\bfy)$. These conditions indicate that  the function $\varphi$ is regular by \cite[Corollary 8.11]{RW1998}, which together with \eqref{chain-rule-cond}, $g(\bfx)=\varphi(h(\bfx))$ and \cite[Theorem 10.6]{RW1998} derives \eqref{chain-rule-sub} immediately. 
\end{proof}

\begin{lemma}\label{first-order-nec}
	The following relationships hold for the problem (\ref{ell-0-1}).
\begin{itemize}

\item[i)] A local minimizer $\bfx^*$   satisfies the following condition 
         if  $A_{\Gamma_*}$ is full row rank,
\begin{eqnarray} \label{lemma-1st-order-nec}
    -\nabla f(\bfx^*) \in A^\top \partial \|(A\bfx^*+\bfb)_+\|_0.
\end{eqnarray}

\item[ii)] A point $\bfx^*$ satisfying (\ref{lemma-1st-order-nec})  is a local minimizer if  the function $f$ is locally convex around $\bfx^*$.
\end{itemize}
\end{lemma}

\begin{proof}
i) It follows from \cite[Theorem 10.1]{RW1998} that a local minimizer of \eqref{ell-0-1} must satisfy $-\nabla f(\bfx^*)\in\lambda\partial g(\bfx^*)$, where $g(\bfx):=\|(A\bfx+\bfb)_+\|_0$. This together with \cref{chain-rule-sub}  and $\lambda \partial\|(\cdot)_+\|_0 = \partial \|(\cdot)_+\|_0$ by \eqref{subfi} derives the result immediately.  

ii)   Since the problem \eqref{ell-0-1} is equivalent to the following problem, 
\begin{eqnarray}\label{ell-0-1-equ-0}
&\underset{\bfx\in\R^n,\bfy\in\R^m}{\min}& f(\bfx)+\lambda \|\bfy_+\|_0,\\
  &{\rm s.t.}& A\bfx+\bfb-\bfy = 0,\nonumber
\end{eqnarray}
it suffices to show that  $(\bfx^*;\bfy^*)$  is a local minimizer of the   problem \eqref{ell-0-1-equ-0}, where $\bfx^*$ satisfies \eqref{lemma-1st-order-nec} and $\bfy^*=A \bfx^*+\bfb$, namely, there is a $\bfz^*$ such that
\begin{eqnarray}
\label{lemma-1st-order-nec-10}
\nabla f(\bfx^*) +A^\top\bfz^*=0,~~ 
A \bfx^*+\bfb-\bfy^*=0, ~~
\partial\|\bfy^*_+\|_0\ni \bfz^*. 
\end{eqnarray} 
It follows from $\bfy^*=A\bfx^*+\bfb$ and \eqref{T-*} that $\Gamma_*=\{i\in\N_m: y^*_i=0\}$. This together with $\partial\|\bfy^*_+\|_0 \ni \bfz^*$ and the expression of the $\partial\|\bfy^*_+\|_0$ in  \eqref{subfi} indicates 
\begin{eqnarray}\label{fact-11}
\bfy_{\Gamma_*}^*=0,~~\bfz_{\Gamma_*}^* \geq 0, ~~~~\bfy_{\overline \Gamma_*}^*\neq 0,~ ~\bfz_{\overline \Gamma_*}^* = 0. 
\end{eqnarray} 
 Define a radius $\delta:=\min\{\delta_1,\delta_2\}$, where
\begin{eqnarray}\label{delta-2}
~~~~~~\delta_1 := 
\begin{cases}
+\infty,&A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}=0\\
\frac{\lambda}{ \|A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}\|},& \text{otherwise}, 
\end{cases}~~~~
\delta_2 := 
\begin{cases}
+\infty,&\bfy^*\leq {\bf0},\\
\min_i\{y_i^*:y_i^*>0\},&\text{otherwise}, 
\end{cases}
\end{eqnarray}
and consider a local region of ${\bfw}^* := (\bfx^*;\bfy^*)$ by
\begin{eqnarray}\label{local-area-1}
~~N( {\bfw}^*,\delta)=\left\{ \left(
\bfx; 
  {\bfy}\right)\in\R^{n+m}   
:~A\bfx+\bfb - \bfy=0, ~
 \|{\bfw}- {\bfw}^*\|<\delta
\right\}.
\end{eqnarray}
Indeed, $N( {\bfw}^*,\delta)$ is a neighbourhood of ${\bfw}^*$ since $A\bfx^*+\bfb - \bfy^*=0$ from \eqref{lemma-1st-order-nec-10}. Next we show that, for any $\bfw\in N( {\bfw}^*,\delta)$,
\begin{eqnarray}\label{y-y*-0}
\|\bfy^*_+\|_0\leq \|\bfy_+\|_0.
\end{eqnarray}
Obviously, it is true if $\bfy^*\leq0$ as $\|\bfy^*_+\|_0=0$. For $\bfy^*\nleq0$,  to guarantee \eqref{y-y*-0}, it suffices to show that for any $i$, $y_i^*>0~\Longrightarrow~y_i>0.$ 
Suppose there is a $j\in\N_m$ such that $y_j^*>0$ but $y_j\leq0$.  This incurs the following contradiction 
\begin{eqnarray*}\delta_2 \geq \delta
& {>}&\|\bfw-\bfw^*\| \hspace{3.5cm} ({\rm by}~ \eqref{local-area-1})\\
&\geq& |y_j-y_j^*|=y_j^*-y_j  \geq y_j^*\geq\delta_2.\hspace{.5cm} ({\rm by}~ \eqref{delta-2}) \end{eqnarray*}
Again, for any $\bfw\in N( {\bfw}^*,\delta)$, we have $A\bfx+\bfb - \bfy=0$, which and \eqref{lemma-1st-order-nec-10} generate
 \begin{eqnarray}\label{y-y*-h-h*}
 \bfy-\bfy^*=A (\bfx- \bfx^*).
  \end{eqnarray}
Next, the convexity of $f$ gives rise to  
 \begin{eqnarray}\label{fx-fx*}
\hspace{15mm} f(\bfx)-f(\bfx^*)&\geq & \langle \nabla f(\bfx^*), \bfx - \bfx^*\rangle~~= -\langle  A^\top \bfz^* , \bfx - \bfx^*\rangle \hspace{1.6cm} ({\rm by}~ \eqref{lemma-1st-order-nec-10})\nonumber\\
% &=& -\langle  A_{\Gamma_*}  (\bfx - \bfx^*),\bfz^* _{\Gamma_*}\rangle-\langle   A_{\overline  \Gamma_*} (\bfx - \bfx^*),\bfz^* _{\overline  \Gamma_*}\rangle\nonumber\\
 &=& -\langle  A_{\Gamma_*}^\top\bfz^* _{\Gamma_*},\bfx - \bfx^*\rangle= -\langle  A_{\Gamma_*}(\bfx - \bfx^*),\bfz^* _{\Gamma_*}\rangle=:\phi\hspace{0.3cm} ({\rm by}~ \eqref{fact-11})
  \end{eqnarray} 
 Now we make the conclusion by two cases.  
 If $\|\bfy^*_+\|_0= \|\bfy_+\|_0$, then   $\bfy_{\Gamma_*}\leq 0$ due to $\bfy^*_{\Gamma_*}=0$. This and \eqref{y-y*-h-h*} yield that
  \begin{eqnarray}\label{y-y*-h-h*-0}
0\geq  \bfy_{\Gamma_*}= \bfy_{\Gamma_*}-\bfy^*_{\Gamma_*}  = A_{\Gamma_*} (\bfx-\bfx^*),
  \end{eqnarray}
which together with $\bfz^* _{\Gamma_*}\geq0$ from \eqref{fact-11} indicates $\phi\geq0$, namely $f(\bfx)\geq f(\bfx^*)$. So $$f(\bfx) +\lambda \|\bfy_+\|_0 \geq f(\bfx^*) + \lambda\|\bfy_+^*\|_0.$$
If $\|\bfy^*_+\|_0 \neq \|\bfy_+\|_0$, we must have $ \|\bfy_+\|_0 \geq 1+\|\bfy^*_+\|_0$ by \eqref{y-y*-0}. If  $A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}=0$, then $\phi=0>-\lambda$. Otherwise, it follows
  \begin{eqnarray*}
\phi&\geq&- \|A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}\|\|\bfx - \bfx^*\| \geq - \|A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}\|\|\bfw - \bfw^*\|\\
 & \geq&- \|A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}\|\delta 
  \geq - \|A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}\|\delta_1=-\lambda.\hspace{.5cm} ({\rm by}~ \eqref{delta-2})
  \end{eqnarray*}
Both lead to $\phi\geq-\lambda$, which results in
  \begin{eqnarray*}\arraycolsep=1.4pt\def\arraystretch{1.5}
  \begin{array}{rclll}
  f(\bfx) +\lambda \|\bfy_+\|_0 &\geq& f(\bfx^*) + \phi +\lambda \|\bfy_+\|_0 &\ ({\rm by}~ \eqref{fx-fx*} )\\
&\geq& f(\bfx^*) -\lambda + \lambda\|\bfy_+\|_0 &\ ({\rm by}~ \phi\geq-\lambda)\\
&\geq& f(\bfx^*) + \lambda\|\bfy_+^*\|_0.&\ ({\rm by}~ \|\bfy_+\|_0 \geq 1+\|\bfy^*_+\|_0 )
 \end{array} \end{eqnarray*}
Overall, the two cases show that $(\bfx^*;\bfy^*)$ is  a local minimizer to \eqref{ell-0-1-equ-0}. Namely, $\bfx^*$ is  a local minimizer to \eqref{ell-0-1}. 
\end{proof}

\begin{theorem} \label{Stationary-Thm}
   The following relationships hold for the problem (\ref{ell-0-1}).
\begin{itemize}
\item[i)]  A local minimizer $\bfx^*$ is a  P-stationary point for any $0<\tau<\tau_*:=\min\{\tau_1,\tau_2\}$ if  $A_{\Gamma_*}$ is full row rank. 
\item[ii)] A P-stationary point with $ \tau>0$  is a local minimizer if  the function $f$ is locally convex around $\bfx^*$. 
\item[iii)] A P-stationary point with $ \tau\geq\|A\|^2/c_f$  is   a global minimizer if  the function $f$ is strongly convex with a constant $c_f>0$.
\end{itemize}
\end{theorem}

\begin{proof} i) As  $\bfx^*$ is a local minimizer of \eqref{ell-0-1},  condition  \eqref{lemma-1st-order-nec} is valid by \cref{first-order-nec} if $A_{\Gamma_*}$ is  full row rank. In other words, there is a $\bfz^*$ such that
\begin{eqnarray}
\label{lemma-1st-order-nec-1}
\nabla f(\bfx^*) +A^\top\bfz^*=0,~~
A \bfx^*+\bfb-\bfy^*=0,~~
\bfz^*\in\partial\|\bfy^*_+\|_0. 
\end{eqnarray} 
Therefore, to show \eqref{p-stationary}, we only need to verify that,  for any $0<\tau<\tau^*$, $$\bfz^*\in \partial\|\bfy^*_+\|_0~ \Rightarrow~\bfy^*\in\P :=\pro (\bfy^*+\tau \bfz^*). $$ 
Recall the definition of $\Gamma_*$ in \eqref{T-*} and the second condition in \eqref{lemma-1st-order-nec-1}, we have $\bfy_{\Gamma_*}=(A \bfx^*+\bfb)_{\Gamma_*}=0$. Same reasoning also allows for obtaining \eqref{fact-11} due to $\bfz^*\in \partial\|\bfy^*_+\|_0$. 
As $A_{\Gamma_*}$ is full row rank, the first condition in \eqref{lemma-1st-order-nec-1} and  $A^\top\bfz^*  =A_{\Gamma_*}^\top\bfz^*_{\Gamma_*}$ derive  that
$$\bfz^*_{\Gamma_*}=\bfp^*.$$
Now, $0<\tau<\tau_*= \min\{\tau_1,\tau_2\}$ in \eqref{tau-*} results in 
\begin{eqnarray}\label{non-negative}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{lllllllllll}
 y_i^*  & \geq & \underset{i:y^*_i>0}{\min} y^*_i &=&  \sqrt{2\tau_1\lambda}&\geq&\sqrt{2\tau_*\lambda} &>&\sqrt{2\tau \lambda}  &~~\text{if}~~& y_i^*>0,\\ 
   z_i^* & \leq &  {\underset{i}{\max}|p^*_i|} &= &\sqrt{2\lambda/\tau_2}&\leq&\sqrt{2\lambda/\tau_*}&< &\sqrt{2\lambda/\tau}& ~~ \text{if}~~ &z_i^*>0.
\end{array}
\end{eqnarray}
These and \eqref{fact-11}  yield the following condition,
\begin{eqnarray*} 
y_i^*\begin{cases}
=0, &   z_i^*=0 ~{\rm or}~ 0< z_i^* < \sqrt{2\lambda/\tau},\\
<0 ~{\rm or}~>\sqrt{2\tau\lambda },& z_i^*=0. 
\end{cases}
\end{eqnarray*}
  {It is easy to see that the above condition satisfies that 
\begin{eqnarray}\label{ugTT-1}
y_i^*  \in \P_i=
\begin{cases}
0, & y_i^*+\tau z_i^*\in(0, \sqrt{2\tau\lambda}),\\
0~{\rm or}~ y_i^*+\tau z_i^*, &y_i^*+\tau z_i^*\in\{0, \sqrt{2\tau\lambda}\},\\
y_i^*+\tau z_i^*,& y_i^*+\tau z_i^*\in(-\infty,0)\cup ( \sqrt{2\tau\lambda},\infty).
\end{cases}
\end{eqnarray}}



ii) Note that the second condition in \eqref{p-stationary} means $\bfy^*\in\P$, which by   \eqref{ugTT-1} implies $z_i^*=0$ if $y_i^*\neq 0$ and  $z_i^*\geq0$ if $y_i^*= 0$, resulting in $\bfz^*\in\partial\|\bfy^*_+\|_0$ by \eqref{subfi}. Consequently, we obtain \eqref{lemma-1st-order-nec-1} and \eqref{lemma-1st-order-nec}.
% In other words, a  P-stationary point satisfies \eqref{lemma-1st-order-nec} and thus is a local minimizer  if  $f$ is locally convex around $\bfx^*$ by
The claim follows from  \cref{first-order-nec} ii).


iii) Let $(\bfx^*;\bfz^*)$ be a  P-stationary point with $ \tau\geq\|A\|^2/c_f$. Then the second condition in \eqref{p-stationary} indicates that
\beq
&&({1}/{2\tau})\|A\bfx^*+\bfb-(A\bfx^*+\bfb+\tau \bfz^*)\|^2+\lambda\|(A\bfx^*+\bfb)_+\|_0 \nonumber \\
&\leq& ({1}/{2\tau})\|A\bfx+\bfb-(A\bfx^*+\bfb+\tau \bfz^*)\|^2+\lambda\|(A\bfx+\bfb)_+\|_0\nonumber
\eeq
for any $\bfx\in\R^n$, which after simplifying leads to 
\beq\label{Ax*b-Axb}
&& \lambda\|(A\bfx^*+\bfb)_+\|_0 - \|A(\bfx-\bfx^*)\|^2 /(2\tau) \nonumber\\
&\leq& \lambda\|(A\bfx+\bfb)_+\|_0 - \langle  \bfz^*, A(\bfx-\bfx^*) \rangle\nonumber\\
&=& \lambda\|(A\bfx+\bfb)_+\|_0 - \langle  A^\top \bfz^*, \bfx-\bfx^*    \rangle\nonumber\\
&=& \lambda\|(A\bfx+\bfb)_+\|_0 + \langle  \nabla f(\bfx^*), \bfx-\bfx^*  \rangle. \hspace{.5cm} ({\rm by}~  \eqref{p-stationary}) 
\eeq
The strong convexity of $f$ implies
\begin{eqnarray*} 
&&f(\bfx)+\lambda\|(A\bfx+\bfb)_+\|_0-f(\bfx^*)-\lambda\|(A\bfx^*+\bfb)_+\|_0\\
&\geq&({c_f}/{2})\|\bfx-\bfx^*\|^2+\langle  \nabla f(\bfx^*), \bfx-\bfx^*   \rangle+\lambda\|(A\bfx+\bfb)_+\|_0-\lambda\|(A\bfx^*+\bfb)_+\|_0\\
&\geq&({c_f}/{2})\|\bfx-\bfx^*\|^2-1/({2\tau})\|A(\bfx-\bfx^*)\|^2    \hspace{.25cm} ({\rm by}~  \eqref{Ax*b-Axb})\\
&\geq&({c_f/2-\|A\|^2/(2\tau}))\|\bfx-\bfx^*\|^2   \geq 0. \hspace{1cm} ({\rm by}~  \tau\geq\|A\|^2/c_f) 
\end{eqnarray*}
This shows the global optimality of $\bfx^*$ to the problem \eqref{ell-0-1}.
\end{proof}

\begin{theorem}\label{cor-p-staionary}
A point $\bfw^*=(\bfx^*;\bfz^*)$ is a  P-stationary point with $\tau>0$ of the problem (\ref{ell-0-1}) if and only if   $F(\bfw^*; \Gamma_*)=0$ and $ \Gamma_*=(\S_* \cup \E^o_*)$, where $\Gamma_*$ is defined by (\ref{T-*}).
%the following equations hold
%\begin{eqnarray}
%\label{sta-eq-1}
%F(\bfw^*; \Gamma_*)=\left[\begin{array}{rrl}
%\nabla f(\bfx^*)  + A_{\Gamma_*}^\top \bfz_{\Gamma_*}^*  \\
%A_{\Gamma_*} \bfx^* + \bfb_{\Gamma_*} \\
%\bfz^*_{\overline \Gamma_*} 
%\end{array}
%\right]=0. 
%\end{eqnarray} 
The Jacobian  $\nabla F(\bfw^*;\Gamma_*)$ is   non-singular if \cref{ass} holds.
\end{theorem}

\begin{proof} 
The second claim is obvious due to Assumption \ref{ass}.
 We only need to prove the first claim. 
We start with the sufficiency.
 The definitions  in \eqref{p-stationary-T} show the following relationships,
\beq\label{TSE}
\Gamma_*= \S_* \cup \E^o_*,~~~~\overline{\Gamma}_*=\O_*\cup(\E_* \setminus \E^o_*).
\eeq
We recall $\bfy^*=A\bfx^*+\bfb$ and $\P:=\text{Prox}_{\tau\lambda\|({\cdot})_{+}\|_{0}}( \bfy^*+\tau \bfz^*)$.
It follows that 
 \allowdisplaybreaks \begin{eqnarray*} 
 \P_i 
=
\begin{cases}
0, & i\in \S,\\
0~{\rm or}~y^*_i+\tau z^*_i, &i\in\E_*,\\
 y_i+\tau z^*_i,& i\in \O_*,
\end{cases} 
=
\begin{cases}
0, & i\in \S_*\subseteq \Gamma_*,\\
0~{\rm or}~\tau z^*_i, &i\in \E^o_* \subseteq \Gamma_*,\\
0~{\rm or}~ y^*_i, &i\in(\E_*\setminus \E^o_*) \subseteq \overline \Gamma_*,\\
y^*_i,& i\in \O_*\subseteq \overline \Gamma_*,
\end{cases} 
\end{eqnarray*}
where the first equation is by \eqref{proximal-operator} and second one is by \eqref{sta-eq-1} and \eqref{TSE}, which indicates $y^*_i \in \P_i$ due to $ \bfy^*_{\Gamma_*}=0$ from \eqref{sta-eq-1}. Moreover,   
the first and third equations in \eqref{sta-eq-1} suffice to $\nabla f(\bfx^*)  + A^\top \bfz^*  =  0$, showing \eqref{p-stationary}. Namely,  $ \bfw^*$ is a  P-stationary point. 

{Necessity.}  Let $ \bfw^*$ be a  P-stationary point satisfying \eqref{p-stationary} and $T_*:= \S_* \cup \E^o_*$.  Then $\overline{T}_*=\O_*\cup(\E_* \setminus \E^o_*)$. It follows from $y^*_i\in \P_i$ and \eqref{proximal-operator} that
\begin{eqnarray*} 
y^*_i\in 
%\Big[\text{Prox}_{\gamma C\|({\cdot})_{+}\|_{0}}(  \bfy^*+\tau \bfz^*)\Big]_i \\
\begin{cases}
0, & i\in \S_*,\\
0~{\rm or}~ y^*_i+\tau z^*_i, &i\in\E_*,\\
y^*_i+\tau z^*_i,& i\in \O_*,
\end{cases} =
\begin{cases}
0, & i\in \S_*,\\
0~{\rm or}~\tau z^*_i, &i\in\E^o_*,\\
0~{\rm or}~ y^*_i+\tau z^*_i, &i\in\E_*\setminus \E^o_*,\\
y^*_i+\tau z^*_i,& i\in \O_*,
\end{cases} 
\end{eqnarray*}
where the equality is by the definition  of $\E^o_*$, which together with $ y^*_i= 0 , i\in \E^o_*$ and $y^*_i\neq 0, i\in \E_*\setminus \E^o_*$ suffices to
\begin{eqnarray*} 
\begin{cases}
y^*_i=0, & i\in \S_*\cup\E^o_*=T_*,\\
y^*_i = y^*_i+\tau z^*_i, &i\in\E_*\setminus \E^o_*,\\
y^*_i= y^*_i+\tau z^*_i,& i\in \O_*,
\end{cases} ~~\Longleftrightarrow~~
\begin{cases}
y^*_i &=0, ~ i\in T_*,\\
 z^*_i&=0, ~i\in\overline{T}_*.
\end{cases} 
\end{eqnarray*}
This gives rise to the last two conditions $\bfy^*_{T_*}=0,~
\bfz^*_{\overline T_*}=0$  in \eqref{sta-eq-1}. 
Furthermore, the first condition in \eqref{p-stationary} and $\bfz^*_{\overline{T}_*}=0$ derive the first condition of \eqref{sta-eq-1}.
Overall, we have $F(\bfw^*; T_*)=0$. 
Now we show $T_*=\Gamma_*$. By  (\ref{T-*}) that $\Gamma_*=\{i\in\N_m: y^*_i=0\}$, it follows $T_*\subseteq \Gamma_*$. Suppose, there is a $j\in \Gamma_*$ but $j\notin T_*$, then
we have $y_j^*=z_j^*=0$ and thus $j\in \E^o_* \subseteq T_*$  by \eqref{p-stationary-T}, a contradiction. Therefore, $T_*=\Gamma_*$, finishing the proof. \end{proof}

\begin{lemma}\label{lemma-neighbour-1}
	 Let $\bfw^*$ be a \ts\  with $0<\tau<\tau_*:=\min\{\tau_1,\tau_2\}$ of the problem (\ref{ell-0-1}),  $\tau_1,\tau_2$ and $\Gamma_*$  be given by (\ref{tau-*}) and (\ref{T-*}).  Then there is a $\delta_1^*>0$ such that, for any $\bfw\in N(\bfw^*,\delta_1^*)$ with its associated indices $\S$ and $\E^o$, it holds 
 \beq\label{gw*-0} 
 F(\bfw^*;T)=0 ~~~~{\rm and}~~~T:=(\S\cup\E^o)\subseteq \Gamma_*.
 \eeq
\end{lemma}

\begin{proof} i) \cref{cor-p-staionary} states that the \ts\ $\bfw^*$ of (\ref{ell-0-1}) satisfies
\begin{eqnarray}
\label{sta-eq-1-*}
\nabla f(\bfx^*)  + A_{\Gamma_*} \bfz^*_{\Gamma_*}=0,~~
 \bfy^*_{\Gamma_*}=0, ~~
\bfz^*_{\overline \Gamma_*}  =0 
\end{eqnarray} 
 for $0<\tau<\tau_*$, where $\Gamma_*=\S_*\cup\E^o_*$. Note that $\E_*\setminus\E^o_*\subseteq \overline{\Gamma}_*$ which by \eqref{sta-eq-1-*} leads to
\begin{eqnarray} \label{sta-eq-1-*-z}
   \bfz^*_{\E_*\setminus\E^o_*}=0.
\end{eqnarray} 
Using the same reasoning for proving \eqref{non-negative},  
we can prove for $ 0<\tau<\tau_*= \min\{\tau_1,\tau_2\}$ in \eqref{tau-*} that
\begin{eqnarray} \label{yz-tau-lambda} 
 y_i^*  >\sqrt{2\tau\lambda}  ~~{\rm if}~~y_i^*> 0,~~~~~~ \tau z^*_i <   \sqrt{2\tau \lambda   } ~~{\rm if}~~z^*_i> 0.
\end{eqnarray}
Therefore,  we have the following facts {
\allowdisplaybreaks
\begin{eqnarray*}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
\E^o_*&=& \{i\in\N_m: y_i^*=0, \tau z_i^* \in \{0, \sqrt{2\tau\lambda}\} \}&~~(\text{by} ~\eqref{p-stationary-T})\\
&=& \{i\in\N_m: y_i^*=0, z_i^*=0 \}, &~~(\text{by}~\eqref{yz-tau-lambda})\\
\E_*\setminus\E^o_*&=& \{i\in\N_m: y_i^*\neq0, y_i^*+\tau z_i^* = \sqrt{2\tau\lambda } \}&~~(\text{by} ~\eqref{p-stationary-T})\\
 &=& \{i\in\N_m: y_i^* = \sqrt{2\tau\lambda} \}&~~(\text{by}~\eqref{sta-eq-1-*-z})\\
&=&\emptyset, &~~(\text{by}~\eqref{yz-tau-lambda})
 \end{array}\end{eqnarray*}}
These facts lead to
\begin{eqnarray}\label{E*0}
\E_*=\E^o_*\cup(\E_*\setminus\E^o_*)=\E^o_*
=\Big\{i\in\N_m: y_i^*= z_i^*=0\Big\},
\end{eqnarray}
which yields the following relations
\begin{eqnarray}\label{TSETO}
\Gamma_*=\S_*\cup \E_*^o=\S_*\cup \E_*,~~~~\overline \Gamma_*= \O_*. 
\end{eqnarray}   
 {For a sufficiently small $\delta_1^*$, any $\bfw\in N(\bfw^*,\delta_1^*)$ satisfies,
\allowdisplaybreaks\begin{eqnarray}\label{hz-h*z*}
&&  {| y_i +\tau z_i - y_i^* -\tau z^*_i |\leq c\delta_1^*},~~\forall~i\in\N_m,   
\end{eqnarray} 
 {where $c>0$ is a constant relied on $A$ and $\tau$.} The definitions of $\S$ and $\S_*$  in \eqref{p-stationary-T} mean that, for any $i\in\S$ or $i\in\S_*$,
\begin{eqnarray} \label{facts-S}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
 y_i+\tau z_i\in (0, \sqrt{2\tau\lambda})~~ &\Longleftrightarrow&~~  |y_i+\tau z_i-\sqrt{\tau\lambda/2} |< \sqrt{\tau\lambda/2},\\
y_i^*+\tau z_i^*\in (0, \sqrt{2\tau\lambda})~~ &\Longleftrightarrow&~~  |y_i^*+\tau z_i^*-\sqrt{\tau\lambda/2} |< \sqrt{\tau\lambda/2}.
\end{array}
\end{eqnarray} 
Using this fact, if $\S_* \nsubseteq \S$, then there is an $i\in \S_*$ but $i\notin\S$ such that
\allowdisplaybreaks
\begin{eqnarray*}  
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
|y_i +\tau z_i - y_i^* -\tau z^*_i|
&=&|y_i+\tau z_i-\sqrt{\tau\lambda/2}  - y_i^*-\tau z^*_i+\sqrt{\tau\lambda/2}|\nonumber\\
&\geq&   \sqrt{\tau\lambda/2} -|y_i^*+\tau z^*_i-\sqrt{\tau\lambda/2}| ~~~~ (\text{by}~i\notin\S~\text{and}~\eqref{facts-S})\\
  &\geq&   \sqrt{\tau\lambda/2} -\max_{i\in\S_*} |y_i^*+\tau z^*_i-\sqrt{\tau\lambda/2}| =:\delta_s\\
&>&0, ~~~~(\text{by}~\eqref{facts-S})
\end{array}
\end{eqnarray*}  {Since $c\delta_1^*$} can be smaller than $\delta_s$, the above fact contradicts with \eqref{hz-h*z*}.  }Hence, it holds $\S_* \subseteq \S$. Similar reasoning also derives $\O_* \subseteq \O$. These allow us to obtain $$\E = \N_m \setminus (\S\cup\O)\subseteq \N_m \setminus (\S_*\cup\O_*)= \E_*.$$
Overall, for any $\bfw\in N(\bfw^*,\delta_1^*)$, it holds
\begin{eqnarray}\label{SSOOEE}
\S_* \subseteq \S,~~ \O_* \subseteq \O,~~ \E\subseteq \E_*.
\end{eqnarray} 
The above relations enable us to claim that 
\begin{eqnarray}\label{SS*E*}
(\S\setminus \S_*) \subseteq \E_*,~~~~(\O\setminus \O_*) \subseteq \E_*.
\end{eqnarray}
Now, we can show
\allowdisplaybreaks
\begin{eqnarray*} 
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
\bfy^*_{ \S_*}&=&0,&~~(\text{by}~\S_*\subseteq \Gamma_*~\text{and}~\eqref{sta-eq-1-*})\\
\bfy^*_{\S\setminus \S_*} &=&0, &~~(\text{by}~ \S\setminus \S_*\subseteq\E_*~\text{from}~\eqref{SS*E*}~\text{and}~\eqref{E*0})\\
\bfy^*_{\E^o} &=&0,&~~(\text{by}~ \E^o\subseteq\E\subseteq\E_*~\text{from}~\eqref{SSOOEE}~\text{and}~\eqref{E*0})\\
\bfz^*_{ \O_*}  &=&0, &~~(\text{by}~\O_*\subseteq \overline \Gamma_*~\text{and}~\eqref{sta-eq-1-*})\\
\bfz^*_{\O\setminus \O_*} &=&0, &~~(\text{by}~ \O\setminus \O_*\subseteq\E_*~\text{from}~\eqref{SS*E*}~\text{and}~\eqref{E*0})\\
\bfz^*_{\E\setminus\E^o} &=&0.&~~(\text{by}~ \E\setminus\E^o\subseteq\E\subseteq\E_*~\text{from}~\eqref{SSOOEE}~\text{and}~\eqref{E*0})
\end{array}
\end{eqnarray*}
These conditions combining with
\begin{eqnarray*}T&=&\S\cup\E^o=\S_*\cup(\S\setminus \S_*)\cup\E^o,\\
 \overline T&=&\O\cup(\E\setminus\E^o)=\O_*\cup(\O\setminus \O_*)\cup(\E\setminus\E^o),
 \end{eqnarray*}
imply $\bfy^*_{ T} =0$ and $\bfz^*_{\overline T}=0$. 
As a consequence of this and $\bfz^*_{\overline \Gamma_*}=0$ from \eqref{sta-eq-1-*}, 
\begin{eqnarray*}
  0= f(\bfx^*)+ A_{\Gamma_*} ^\top\bfz^*_{\Gamma_*}=f(\bfx^*)+ A^\top\bfz^*= f(\bfx^*)+ A_{T} ^\top\bfz^*_{T}.
 \end{eqnarray*}
Overall, we verify $F(\bfw^*;T)=0$,  as desired. 
Finally, we observe that
 \beq 
\arraycolsep=1.4pt\def\arraystretch{1.5}
 \begin{array}{rcll}
T=\S\cup\E^o&=&\S_*\cup(\S\setminus \S_*)\cup\E^o\nonumber\\
&\subseteq&   \S_*\cup\E_* \cup\E^o&(\text{by}~ \S\setminus \S_*\subseteq\E_*~\text{from}~\eqref{SS*E*})\nonumber\\
&\subseteq&   \S_*\cup\E_* \cup \E_*  &(\text{by}~\E^o\subseteq\E\subseteq\E_*~\text{from}~\eqref{SSOOEE})\nonumber\\
&=&   \Gamma_*.  &(\text{by}~\eqref{TSETO})\nonumber
\end{array}
 \eeq
The whole proof is completed.   \end{proof}

\begin{lemma}\label{lemma-neighbour-2} Let $\bfw^*$ be a \ts\  with $0<\tau<\tau_*$ of the problem (\ref{ell-0-1}) and $\tau_*$ be given by (\ref{tau-*}).   Assume  \cref{ass} and \cref{ass2}. It holds 
 \beq \label{bd-jacobian-F-w-T}
  && C_*  \geq \|\nabla F_{\mu}(\bfw;T)\|\geq\sigma_{\min}( \nabla F_{\mu}(\bfw;T)) \geq   c_*>0, 
\eeq
for any $\bfw\in N(\bfw^*,\delta_2^*)$ and any $0\leq\mu\leq c_*/2$, where $T=\S\cup\E^o$ and
 \beq\label{radius-2}
C_*&:=&2\max\{1, \|H(\Gamma_*)\|\} ,~~~~ c_* := 0.5{\min\{1,\min_{\Gamma\subseteq\Gamma_*}\sigma_{\min}(H(\Gamma))\}}, \\
\label{H*}\delta_2^* &:=& \min\left\{\delta_1^*,   \frac{c_*}{ 2L_*}     \right\},~~~~H(\Gamma):=\left[  
     \begin{array}{ccc}
    \nabla^2 f(\bfx^*)& A^\top_{\Gamma}\\
     A_{\Gamma}&0
     \end{array}
     \right]. 
\end{eqnarray}
\end{lemma}

\begin{proof}  
Since  $\nabla^2 f(\bfx^*)$ is  {positive definite} and $A_{\Gamma_*}$ is full row rank by \cref{ass}, $A_\Gamma$ is full row rank for any $ \Gamma \subseteq   \Gamma_*$ and thus $H(\Gamma)$ is non-singular. 
We have $\sigma_{\min}(H(\Gamma)) > 0$ for any 
$ \Gamma \subseteq   \Gamma_*$ 
and  $c_*>0$. 
Now we build the bounds of $\nabla F_{\mu}(\bfw;T)$. 
For any given two matrices $D'$ and $D$, we have the first fact
\begin{eqnarray} \label{lower-bd-HH}
 \|D'-D\|
&\geq& \max_{i}|\sigma_i(D')-\sigma_i(D )|   \geq |\sigma_{i_0}( D')-\sigma_{i_0}(D)|\nonumber\\
&\geq& \sigma_{i_0}(D')-\sigma_{\min}(D) \geq \sigma_{\min}(D')-\sigma_{\min}(D), 
\end{eqnarray}
where the first inequality is from \cite[Reminder (2), on Page 76]{lutkepohl1996handbook} and  $i_0$ satisfies that $\sigma_{i_0}(D)=\sigma_{\min}(D)$.  Recall that
 \begin{eqnarray*}
 \label{FH*-FG}H(\Gamma)\overset{\eqref{H*}}{=}\left[  
     \begin{array}{ccc}
    \nabla^2 f(\bfx^*)& A^\top_{\Gamma }\\
     A_{\Gamma }&0
     \end{array}
     \right],~~~~ \nabla F(\bfw^*;T) =\left[  
     \begin{array}{cc}
    H(T)&0\\
     0&I  
     \end{array}
     \right].
    \end{eqnarray*}
For any $\bfw\in N(\bfw^*,\delta_2^*)$ and $\delta_2^*\leq\delta_1^*$,   \cref{lemma-neighbour-1} contributes to $T \subseteq   \Gamma_*$. So $H(T)$ is a submatrix of $H(\Gamma_*)$. Hence, %It follows from \cite[Theorem 1]{thompson1972principal} that the maximum  singular value of a  matrix is no less than the maximum singular value of its sub-matrix. Namely, 
\beq 
\|H(T)\| \leq \|H(\Gamma_*)\|,~~ \sigma_{\min}(H(T)) \geq \min_{\Gamma \subseteq \Gamma_*} \sigma_{\min} (H(\Gamma)),\nonumber
\eeq
where the latter is by $T \subseteq   \Gamma_*$, which gives us the second fact 
\beq\label{JJogG0}
\sigma_{\min}(\nabla F(\bfw^*;T))&=&\min\{1,\sigma_{\min}(H(T))\}\\
& \geq&\min\{1, \min_{\Gamma \subseteq \Gamma_*} \sigma_{\min} (H(\Gamma))\}=2c_*, \nonumber\\
\label{JJogG1}
\|\nabla F(\bfw^*;T)\| &=& \max\{1, \|H(T)\|\} \leq \max\{1, \|H(\Gamma_*)\|\} =C_*/2. 
\eeq
The locally Lipschitz continuity of $\nabla^2 f$  around $\bfx^*$ with $L_*$  yields the third fact,
\begin{eqnarray}
\label{HH*2}
\|\nabla F (\bfw^*;T)-\nabla F (\bfw;T)\|&=&\|\nabla^2  f (\bfx)-\nabla^2  f (\bfx^*)\|  \leq
   L_* \| \bfx -\bfx^* \| \nonumber\\
   &\leq& L_* \| \bfw -\bfw^* \| 
 \leq   L_* \delta_2^*
\leq c_*/2.   \hspace{.5cm}(\text{by}~\eqref{H*})
\end{eqnarray} 
Now these three facts allow us to derive
\allowdisplaybreaks 
\begin{eqnarray}\label{lower-bd-FF}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rclr}
&& \sigma_{\min}(\nabla F_{\mu}(\bfw;T))\\
 &\geq& \sigma_{\min}(\nabla F (\bfw ;T))- \|\nabla F(\bfw;T)-\nabla F_{\mu}  (\bfw;T)\| &(\text{by}~\eqref{lower-bd-HH})  \\
&=& \sigma_{\min}(\nabla F(\bfw ;T))- \mu &(\text{by}~\eqref{sta-eq-1}) \\
&\geq& \sigma_{\min}(\nabla F(\bfw^*;T))- \|\nabla F (\bfw^*;T)-\nabla F (\bfw;T)\|- \mu   &(\text{by}~\eqref{lower-bd-HH}) \\
&\geq&\sigma_{\min}(\nabla F(\bfw^*;T))- c_*/2 - \mu&(\text{by}~\eqref{HH*2}) \\
&\geq&\sigma_{\min}(\nabla F(\bfw^*;T))-  c_* &(\text{by}~\mu\leq c_*/2)   \\
&\geq&c_*. &(\text{by}~\eqref{JJogG0})  
\end{array}
\end{eqnarray}
Similarly, we also have
\allowdisplaybreaks 
\begin{eqnarray}\label{upper-bd-FF}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rclr}
&&\|\nabla F_{\mu}(\bfw;T)\|\\
 &\leq& \|\nabla F (\bfw ;T)\|+ \|\nabla F(\bfw;T)-\nabla F_{\mu}  (\bfw;T)\| \\
&=& \|\nabla F (\bfw ;T)\|+ \mu &(\text{by}~\eqref{sta-eq-1})\\
&\leq& \|\nabla F(\bfw^*;T)\|+ \|\nabla F (\bfw^*;T)-\nabla F (\bfw;T)\|+ \mu   &(\text{by}~\eqref{lower-bd-HH})  \\
&\leq& \|\nabla F(\bfw^*;T)\|+ c_*/2 + \mu&(\text{by}~\eqref{HH*2}) \\
&\leq& \|\nabla F(\bfw^*;T)\|+ c_* &(\text{by}~\mu\leq c_*/2)   \\
&\leq& C_*/2+c_* &(\text{by}~\eqref{JJogG1}) \\
&\leq& C_*. &(\text{by}~c_*\leq C_*/2)   
\end{array}
\end{eqnarray}
The whole proof is completed. 
\end{proof}

\begin{proof} a) It is easily observed   
\begin{eqnarray}\label{mu-k}
0< \mu_{k} \leq \mu_{k-1}, ~k=1,2,3,\ldots, ~~~~{\rm and}~~~~ \lim_{k\rightarrow\infty}\mu_k=0.
\end{eqnarray} 
It follows from \cref{lemma-neighbour-1} and the facts
$\delta_*\leq \delta_2^*\leq\delta_1^*$ and $\bfw^0\in N(\bfw^*,\delta_*)$ that     
\beq\label{F-w*-T0-0}F (\bfw^{*};T_0) =0  
\eeq
with $T_0=\S_0\cup\E_0^o$ and from \cref{lemma-neighbour-2} that     
\beq\label{grad-F-w*-T0-c} C_*  \geq \|\nabla F_{\mu_0}(\bfw^0;T_0)\|\geq\sigma_{\min}( \nabla F_{\mu_0}(\bfw^0;T_0)) \geq  c_*
\eeq
Here, we used the fact that $\mu_0\leq \mu_{-1}\leq c_*/2$ by  \eqref{mu-k}. 
From \eqref{newton-dir-0}, we have
\beq\label{dkt}
\nabla F_{\mu_0} (\bfw^{0};T_0)~\bfd^{0}=- F (\bfw^{0};T_0).
\eeq
  \cref{lemma-neighbour-2} states that $\nabla F_{\mu_0} (\bfw^{0};T_0)$ is non-singular and thus $\bfd^{0}$ is well defined.
Let 
\beq\label{w0-beta-w*}
\bfw^{0}_\beta= \bfw^{*} + \beta(\bfw^{0}-\bfw^{*})=(\bfx^{0}_\beta;\bfz^{0}_\beta)
\eeq
where $\beta\in[0,1].$ One can easily check that $\bfw^{0}_\beta\in N(\bfw^*,\delta_*)$ as $$\|\bfw^{0}_\beta-\bfw^{*}\|= \beta\|\bfw^{0}-\bfw^{*}\|\leq  \delta_*.$$
The definition  in \eqref{sta-eq-1} enables us to obtain
\allowdisplaybreaks 
\begin{eqnarray*}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
&&\|\nabla F_{\mu_0} (\bfw^{0};T_0)- \nabla F (\bfw^{0}_\beta;T_0) \|  \\
&\leq&\|\nabla^2 f(\bfx^0)- \nabla^2 f(\bfx^0_\beta)\| + \mu_0&(\text{by}~\eqref{sta-eq-1})  \\
& \leq& L_* \|\bfx^0-\bfx^0_\beta\|+ \rho  \|F(\bfw^0;T_0)\|&(\text{by}~\eqref{update-mu}) \\ 
& \leq& L_* \|\bfw^0-\bfw^0_\beta\|+ \rho \|\nabla F_{\mu_0} (\bfw^{0};T_0)\| \|\bfd^0\|&(\text{by}~\eqref{newton-dir-0}) \\ 
& \leq& L_* \|\bfw^0-\bfw^0_\beta\|+ \rho C_* \|\bfw^1-\bfw^0\|&(\text{by}~\eqref{grad-F-w*-T0-c}) \\ 
& \leq& L_*(1-\beta)\|\bfw^0-\bfw^*\|+ \rho C_* (\|\bfw^1-\bfw^*\|+\|\bfw^0-\bfw^*\|) &(\text{by}~\eqref{w0-beta-w*})  \\ 
& =& (L_*(1-\beta)+\rho C_*)\|\bfw^0-\bfw^*\|+ \rho C_* \|\bfw^1-\bfw^*\|.
\end{array} \end{eqnarray*}
Denote $\Theta_{\mu_0}:=\nabla F_{\mu_0} (\bfw^{0};T_0)$ and $\Theta(\beta):= \nabla F (\bfw^{0}_\beta;T_0)$.  The above condition yields
  \beq\label{lipschitz}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
 \int_0^1 \|\Theta_{\mu_0}  - \Theta(\beta)\|d\beta
\leq (L_*/2+\rho C_*)\|\bfw^0-\bfw^*\|+ \rho C_* \|\bfw^1-\bfw^*\|.
\end{array} \eeq
For the fixed $T_0$, the function $F(\cdot,T_0)$ is differentiable, which by \eqref{F-w*-T0-0} derives
\beq\label{mean-value}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
F (\bfw^{0};T_0)=F (\bfw^{*};T_0)+\int_0^1 \Theta(\beta)(\bfw^{0}-\bfw^{*})d\beta=\int_0^1 \Theta(\beta) (\bfw^{0}-\bfw^{*})d\beta.
\end{array}\eeq
Now the following chain of inequalities holds.
\begin{eqnarray*}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
c_*\|\bfw^{1}-\bfw^{*}\| &=& c_*\|\bfw^{0}+\bfd^{0}-\bfw^{*}\|\\
& {=} &c_*\|\bfw^{0}-\bfw^{*}-\Theta_{\mu_0}^{-1}   F(\bfw^{0};T_0) \|&~~(\text{by}~\eqref{dkt})\\
& {\leq} & \|\Theta_{\mu_0} (\bfw^{0}-\bfw^{*})-   F(\bfw^{0};T_0) \|&~~(\text{by}~\eqref{grad-F-w*-T0-c})\\
&= & \|\Theta_{\mu_0}  (\bfw^{0}-\bfw^{*})-  \int_0^1 \Theta(\beta)(\bfw^{0}-\bfw^{*})d\beta \| &~~(\text{by}~\eqref{mean-value}) \\
& \leq& \int_0^1 \|\Theta_{\mu_0} -\Theta(\beta) \|\|\bfw^{0}-\bfw^{*}\|d\beta \\
& =& ({\theta_*}/2) \|\bfw^{0} -\bfw^{*}\|^2+   {\rho C_*}  \|\bfw^1-\bfw^*\|\|\bfw^{0}-\bfw^{*}\| &~~(\text{by}~\eqref{lipschitz}) \\
&\leq& ({\theta_*}/2) \|\bfw^{0} -\bfw^{*}\|^2+ {\rho C_*\delta_*}  \|\bfw^1-\bfw^*\|   \\
&\leq& ({\theta_*}/2) \|\bfw^{0} -\bfw^{*}\|^2+ (c_*/2) \|\bfw^1-\bfw^*\|, 
\end{array}
\end{eqnarray*}
where $\theta_*:=L_* +2\rho C_*$ and the last inequality is from $\delta_*\leq  {c_*}/(2 \theta_*)$ by \eqref{delta-*} and
\beq\label{w0-w*-delta*}
\|\bfw^{0}-\bfw^{*}\|<\delta_*\leq  {c_*}/(2 \theta_*)<  {c_*}/({2\rho  C_*}).
\eeq
 The above chain of inequalities  suffices to the following fact
\beq\label{quadratic-chain}
\|\bfw^{1}-\bfw^{*}\|\leq  (\theta_*/c_*) \|\bfw^{0} -\bfw^{*}\|^2.
\eeq
This together with $\|\bfw^{0}-\bfw^{*}\|<\delta_*$ and \eqref{w0-w*-delta*} derives
\beq 
\|\bfw^{1}-\bfw^{*}\|  &\leq& 
   (\theta_*/c_*)  \delta_* \|\bfw^{0}-\bfw^{*} \|\leq (1/2)\|\bfw^{0}-\bfw^{*} \|< \delta_*,  \nonumber
 \eeq
which means $\bfw^1\in N(\bfw^*,\delta_*)$. In addition, $\mu_1\leq\mu_0\leq c_*/2$ by  \eqref{mu-k}. Hence, replacing $T_0 $ by $T_1$, the same reasoning allows us to show that $\bfd^{1}$ is well defined and $$\|\bfw^{2}-\bfw^{*}\|  \leq (\theta_*/c_*)   \|\bfw^{1}-\bfw^{*} \|^2 .$$ By the induction, we can conclude that $\bfw^k\in N(\bfw^*,\delta_*)$, $\bfd^{k}$ is well defined and 
\beq\label{quadratic-rate}
\hspace{10mm}\|\bfw^{k+1}-\bfw^{*}\|  &\leq& (\theta_*/c_*) \|\bfw^{k}-\bfw^{*} \|^2, \\
\label{quadratic-rate-1}&\leq& (\theta_*/c_*)  \|\bfw^{k}-\bfw^{*} \|\delta_* \leq (1/2) \|\bfw^{k}-\bfw^{*} \|.\hspace{.2cm}(\text{by}~\eqref{w0-w*-delta*})
\eeq
Therefore, \eqref{quadratic-rate} claims b). The conclusion of a) can be made by \eqref{quadratic-rate-1}  that   $$\bfw^{k}\rightarrow\bfw^{*},~~ \bfd^k=\bfw^{k+1}-\bfw^{k}=\bfw^{k+1}-\bfw^{*}+\bfw^{*}-\bfw^{k}\rightarrow0.$$ 

c)  The  above  proof shows $\bfw^k\in N(\bfw^*,\delta_*)$ and hence \eqref{gw*-0} results in
\beq\label{wk-in-N}  F(\bfw^{*};T_k){=}0,\eeq
where $T_k=\S_k\cup\E_k^o$.
By letting $\bfw^{k}_\beta= \bfw^{*} + \beta(\bfw^{k}-\bfw^{*}),$ where $\beta\in[0,1]$, we have $\bfw^k_\beta\in N(\bfw^*,\delta_*)$. To show \eqref{bd-jacobian-F-w-T} in \cref{lemma-neighbour-2}, we verified the lower and upper bounds by \eqref{lower-bd-FF} and \eqref{upper-bd-FF}. Similarly, we can prove these bounds hold for $\nabla F (\bfw^{k}_\beta;T_k)$. (In fact, since $\bfw^k_\beta\in N(\bfw^*,\delta_*)\subseteq N(\bfw^*,\delta_2^*)$ by $\delta_*\leq \delta_2^*$, one just needs to set $\mu=0$ and $\bfw= \bfw^{k}_\beta$ in  \eqref{lower-bd-FF} and \eqref{upper-bd-FF}. Therefore,
\beq\label{C-F-w-beta-c}
C_*  \geq \|\nabla F (\bfw^{k}_\beta;T_k)\|\geq\sigma_{\min}( \nabla F (\bfw^{k}_\beta;T_k)) \geq  c_*, 
\eeq
Again, the function $F(\cdot,T_k)$ is differentiable for the fixed $T_k$, so the Mean-value theorem states that there is a $\beta_0\in(0,1)$ satisfying
\beq\label{FkTk}
\|F(\bfw^{k},T_k)\|&=&\|F(\bfw^{*};T_k)+  \nabla F (\bfw^{k}_{\beta_0};T_k) (\bfw^{k}-\bfw^{*})\|\nonumber\\
&=&\| \nabla F (\bfw^{k}_{\beta_0};T_k) (\bfw^{k}-\bfw^{*}) \|\hspace{1.7cm}(\text{by}~\eqref{wk-in-N})\nonumber\\
&\in&  [~c_*\|\bfw^{k}-\bfw^{*} \|, C_*\|\bfw^{k}-\bfw^{*} \|~], \hspace{0.8cm}(\text{by}~\eqref{C-F-w-beta-c})
\eeq
This contributes to 
\allowdisplaybreaks
\begin{eqnarray*}\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rclr}
\|F(\bfw^{k};T_{k})\| \leq  C_*\|\bfw^{k}-\bfw^{*}\|  
 & {\leq} & (\theta_*C_*/c_*)   \|\bfw^{k-1}-\bfw^{*} \|^2 &(\text{by}~\eqref{quadratic-rate}) \\
 & {\leq}& (\theta_*C_*/c_*^{3})  \|F(\bfw^{k-1};T_{k-1})\|^2&(\text{by}~\eqref{FkTk})\\
 &{\leq}& (\theta_*C_*^3/c_*^{3})      \|\bfw^{k-1}-\bfw^{*} \|^2&(\text{by}~\eqref{FkTk})\\
& {\leq}& (\theta_*C_*^3/c_*^{3})  2^{-2}  \|\bfw^{k-2}-\bfw^{*} \|^2&~~(\text{by}~\eqref{quadratic-rate-1})\\
    &\vdots&\\
 & \leq& (\theta_*C_*^3/c_*^{3})   2^{2-2k} \|\bfw^{0}-\bfw^{*} \|^2,&(\text{by}~\eqref{quadratic-rate-1})
 \end{array}  \end{eqnarray*}
where the third inequality yields the first conclusion in c). This also enable to verify that $\|F(\bfw^{k};T_k)\|$ $< {\epsilon}$ if $k$ satisfies \eqref{k-tol}.
%$$k\geq  \lceil \log_2 (2 \sqrt{\theta_* (C_* /c_*)^3}\|\bfw^{0}-\bfw^{*} \| )-\log_2(\sqrt{\epsilon}) \rceil.$$ 
The whole proof is completed.
\end{proof}

