This paper is concerned with the $0/1$-loss optimization:
\begin{equation}\label{ell-0-1}
\underset{\bfx\in\R^n}{\min}~ f(\bfx)+\lambda \|( A\bfx +\bfb )_+\|_0, 
\end{equation}

where $f:\R^n\rightarrow\R$ is  twice continuously differentiable, 
$\lambda>0 $ is a penalty parameter and $A\in \R^{m\times n}, \bfb\in \R^m$. 
Moreover, ${\bfz}_+:=((z_1)_+, \ldots, (z_m)_+)^\top $ with $z_+:=\max\{z,{0}\}$ 
and $\|\bfz\|_0$ is the $\ell_0$ norm of $\bfz$, counting the number of its non-zero entries. 
Hence, $\|\bfz_+\|_0$ counts the number of positive entries of $\bfz$,
i.e., $\|\bfz_+\|_0=\sum_{i=1}^m \ell_{0/1}(z_i)$, where
\begin{eqnarray*}
\ell_{0/1}(z)=
\begin{cases}
1, &z>0,\\
0& z\leq 0.
\end{cases}
\end{eqnarray*}

The assumption in (\ref{chain-rule-cond}) can be regarded as a constraint qualification for the chain rule in (\ref{chain-rule-sub}) to hold. We finish this section with a formula to compute the proximal operator of  $\|(\cdot)_+\|_0$.  Let $\alpha>0$, the proximal operator of $\alpha \|(\cdot)_+\|_0$ at  {$\bfo$ is defined by 
\begin{eqnarray*} %\label{proximal-operator-0}
\prox(\bfo)=\underset{\bfy\in\R^m}{\rm argmin} ~\frac{1}{2}\|\bfy-\bfo\|^2+ \alpha \|\bfy_+\|_0.
\end{eqnarray*}

\begin{eqnarray} \label{proximal-operator}
\Big[\prox(\bfo)\Big]_i=
%&=&
%\begin{cases}
%0,&    \nu_i \in [0, \sqrt{2\alpha}),\\
%0~ \text{or}~ \nu_i ,& \nu_i=\sqrt{2\alpha},\\
%\nu_i,&\nu_i\in(-\infty,0)\cup (\sqrt{2\alpha},\infty),
%\end{cases} \nonumber\\
%&=&
\begin{cases}
0,&    \nu_i \in (0, \sqrt{2\alpha}),\\
0~ \text{or}~ \nu_i ,& \nu_i\in\{0,\sqrt{2\alpha}\},\\
\nu_i,&\nu_i\in(-\infty,0)\cup (\sqrt{2\alpha},\infty).
\end{cases} 
\end{eqnarray}

\begin{eqnarray}\label{T-*}
  \Gamma_*&:=&\{i\in\N_m: A_i\bfx^*+b_i=0\}.
\end{eqnarray}

\begin{definition}\label{def-p-sta} 
	A point $\bfx^*$ is called a P-stationary point of the problem (\ref{ell-0-1})  if there exist a constant $\tau > 0$ and
	a point $\bfz^*\in\R^m$  such that
\begin{eqnarray} \label{p-stationary}
 \begin{cases}
\hspace{21mm}\nabla f(\bfx^*)  + A^\top \bfz^* &=~ 0 \\
\pro (A\bfx^*+\bfb+\tau \bfz^*) &\ni~A\bfx^*+\bfb.
\end{cases}
\end{eqnarray}
\end{definition}

\begin{eqnarray}
\label{tau-*} 
~~~~\tau_1 := 
\begin{cases}
+\infty, & \bfy^*\leq0,\\
{\min} \left\{\frac{(y^*_i)^2}{2\lambda}:y_i^*>0\right\},& {\rm otherwise},\\
\end{cases}~~
\tau_2:=\begin{cases}
+\infty, & \Gamma_*=\emptyset,\\
 \frac{2\lambda}{\max_i|p^*_i|^2},& {\rm otherwise},
\end{cases}
\end{eqnarray}

\begin{assumption} \label{ass}
	 Suppose $f$ is twice continuously differentiable, $\nabla^2 f(\bfx^*)$ is {positive definite} and $A_{\Gamma_*}$ is full row rank, where $\Gamma_*$ is given by (\ref{T-*}).
 \end{assumption}

\begin{assumption} \label{ass2} 
Suppose $\nabla^2 f$ is locally Lipschitz continuous around $\bfx^*$ with a constant $L_*>0$, namely 
\begin{eqnarray*} \|\nabla^2 f(\bfx)-\nabla^2 f(\bfx')\|\leq L_* \|   \bfx -\bfx' \| \end{eqnarray*}
for any $\bfx$ and $\bfx'$ in the neighbourhood of $\bfx^*$.
 \end{assumption}

 For a point  $\bfw:=(\bfx; \bfz)$, we define the sets {
\begin{eqnarray}\label{p-stationary-T}
\arraycolsep=1.4pt\def\arraystretch{1.5}
 \begin{array}{rcll}
\S&:=& \left\{i\in\N_m:  A_i\bfx+b_i+\tau z_i   \in (0, \sqrt{2\tau\lambda}) \right\}, \\
 \E&:=& \left\{i\in\N_m: A_i\bfx+b_i +\tau z_i \in\{0,\sqrt{2\tau\lambda}\} \right\},\\
\O&:=& \left\{i\in\N_m:  A_i\bfx+b_i+ \tau z_i \in(-\infty,0)\cup ( \sqrt{2\tau\lambda},\infty) \right\},\\
\E^o&:=& \left\{i\in\N_m: A_i\bfx+b_i =0, \tau z_i   \in\{0,\sqrt{2\tau\lambda}\} \right\}, 
\end{array}
\end{eqnarray}

\begin{eqnarray}
\label{sta-eq-1}
\hspace{8mm} F(\bfw; \Gamma) =\left[\begin{array}{rrl}
\nabla f(\bfx)  + A_{\Gamma}^\top \bfz_{\Gamma}  \\
A_{\Gamma} \bfx + \bfb_{\Gamma} \\
\bfz_{\overline \Gamma} 
\end{array}
\right] = 0, \quad 
%\label{def-Jacobian}
\nabla F_{\mu}(\bfw;\Gamma) =\left[\begin{array}{ccc}
\nabla^2 f(\bfx)   & A_{\Gamma} ^\top &0\\
A_{\Gamma} &-\mu I&0 \\
0&0&I
\end{array}
\right].
\end{eqnarray}

\beq \label{T-k}
      T_k := \S_k\cup \E_k^o.  
 \eeq

\[ %\beq \label{newton-d}
 \nabla F(\bfw^k;T_k)~\bfd = - F(\bfw^k;T_k). 
 \]

\beq \label{newton-dir-0}
 \nabla F_{\mu_k}(\bfw^k;T_k)~\bfd = - F(\bfw^k;T_k), 
 \eeq

\beq \label{newton-dir} 
 \left[  
     \begin{array}{ccc}
     {\nabla^2  f(\bfx^k)}& A_{T_k}^\top&0\\
   A_{T_k}&-\mu_k I&0\\
    0&0&I
     \end{array}
     \right]  
     \left[  
     \begin{array}{l}
    \bfu^k\\
    \bfv^k_{T_k}\\
    \bfv^k_{\overline T_k}
     \end{array}
     \right]
     =-\left[  
     \begin{array}{r}
    \nabla  f(\bfx^k)+A_{T_k}^\top\bfz^k_{T_k}\\
   A_{T_k}\bfx^k+\bfb_{T_k} \\
    \bfz^k_{\overline T_k}
     \end{array}
     \right].
 \eeq

\begin{algorithm}[H]
	\caption{\nhs: Newton's method for $0/1$-loss optimization}
	\begin{algorithmic}[1] \label{Alg-NM01}
		%\scriptsize
		\STATE Initialize $\bfw^0=(\bfx^0;\bfz^0)$ and $\mu_{-1}>0$. Set the parameter $\tau,\lambda,\rho>0, \alpha\in(0,1)$.\\
		 Compute $T_0$ by \eqref{T-k} and set $k :=0$.
\IF{ $\|F(\bfw^k;T_k)\|>0$}		 
         \STATE  Update $\mu_{k}$ by \eqref{update-mu}.	
		\STATE  Update $\bfd^k$ by solving \eqref{newton-dir}.
		\STATE  Update $\bfw^{k+1}~=~\bfw^k+\bfd^k$.
		\STATE  Update $T_{k+1}$ by \eqref{T-k} and  set $k := k+1$.   		
\ENDIF		
\RETURN $\bfw^{k}$.
	\end{algorithmic}
\end{algorithm}

\begin{lemma} \label{subdifferentials}

\begin{itemize}

 \item[(i)] We have
 \begin{eqnarray}\label{subfi}
  \partial\|{\bfy}_+\|_0
  =\left\{{\bfv}\in {\R}^m: v_i\left\{\begin{array}{ll}
 \geq0,& y_i=0,\\
 =0,& y_i\neq0,
 \end{array}
 \right. i\in{\N}_m\right\}. 
 \end{eqnarray}

 \item[(ii)] Let $g(\bfx):=\|(h(\bfx))_+\|_0$, where $h:\R^n\rightarrow\R^m$ is differentiable,  and $\Gamma:=\{i\in\N_m: h_i(  \bfx)=0\}$ for a given a point $ \bfx\in\R^n$.  If 
 \begin{eqnarray}
 \label{chain-rule-cond}
 \left.
 \begin{array}{r}
 \forall \bfz\in\R^{|\Gamma|},~~\bfz\geq 0,~~
 (\nabla h( \bfx))_{\Gamma}^\top \bfz = 0
 \end{array}\right.~~\Longrightarrow~~\bfz = 0,
 \end{eqnarray}
 then the subdifferential of $g(\bfx)$  at $  \bfx$ is  
 \begin{eqnarray}
 \label{chain-rule-sub} 
 \partial g(  \bfx)=\nabla h( \bfx)^\top \partial \|(h(  \bfx))_+\|_0.
 \end{eqnarray}

\end{itemize}
\end{lemma}

\begin{proof}
i)   It is straight to check that the regular subdifferential $\widehat{\partial}\|{\bfy}_+\|_0$ (see \cite[Definition 8.3]{RW1998})  of $\|{\bfy}_+\|_0$ at ${\bfy}$ takes the following form,
\begin{eqnarray}\label{subfi-0}
 \widehat{\partial}\|{\bfy}_+\|_0=\left\{{\bfv}\in {\R}^m: v_i\left\{\begin{array}{ll}
 \geq0,& y_i=0,\\
 =0,& y_i\neq0,
 \end{array}
 \right. i\in{\N}_m\right\}=:\Omega(\bfy). 
\end{eqnarray}
We next verify $ \partial\|{\bfy}_+\|_0= \Omega({\bfy}) $. By letting $\varphi(\cdot):=\|(\cdot)_+\|_0$, we have
  \begin{eqnarray}\label{sub-lim-reg}
  \arraycolsep=1.4pt\def\arraystretch{1.5}
  \begin{array}{rclll}
\partial\|{\bfy}_+\|_0&=&\limsup_{{\bfz}\stackrel{\varphi}{\rightarrow}{\bfy}}~ \widehat{\partial}\|{\bfz}_+\|_0 ~~~( \text{by  \cite[Equation 8(5)]{RW1998}})\\
&=&\limsup_{{\bfz}\stackrel{\varphi}{\rightarrow}{\bfy}}~\Omega({\bfz}) ~~~~~~( \text{by \eqref{subfi-0}})\\
&=&\{\bfv\in \R^m:\exists~\bfz^k\stackrel{\varphi}{\rightarrow} \bfy,~\bfv^k\rightarrow \bfv ~\text{with}~\bfv^k\in \Omega(\bfz^k) \}=:\Theta,
\end{array}
 \end{eqnarray}
where  $\bfz\stackrel{\varphi}{\rightarrow} \bfy$ represents $\bfz\rightarrow \bfy, \varphi(\bfz)\rightarrow \varphi(\bfy)$. Clearly, $\Omega({\bfy})\subseteq\Theta$. On the other hand, $\Theta \subseteq \Omega({\bfy})$  follows from that $\Omega(\bfz^k)\subseteq \Omega(\bfy)$ for any $\bfz^k\stackrel{\varphi}{\rightarrow} \bfy$ and $\Omega(\cdot)$ is closed.

 ii) Direct verifications yield the following chain of equations,
 \begin{eqnarray*}  \arraycolsep=1.4pt\def\arraystretch{1.5}
  \begin{array}{rclll}
 \partial^\infty \|\bfy_+\|_0&=& {\limsup}_{\sigma\downarrow0,~{\bfz}\stackrel{\varphi}{\rightarrow} {\bfy}} \sigma \widehat{\partial}\|\bfz_+\|_0&~~( \text{by \cite[Equation 8(5)]{RW1998}})\\ 
&=&
 {\limsup}_{{\bfz}\stackrel{\varphi}{\rightarrow} {\bfy}}~ \widehat{\partial}\|\bfz_+\|_0&~~( \text{by \eqref{subfi-0}})\\
 & =& \partial\|{\bfy}_+\|_0,&~~( \text{by \eqref{sub-lim-reg}})\\
 \end{array}
 \end{eqnarray*}
 where $ \partial^\infty \|{\bfy}_+\|_0$ is the horizon subdifferential of $\|{\bfy}_+\|_0$. Therefore, we derive that $\widehat{\partial}\varphi=\partial \varphi=\partial^\infty \varphi$.  One can easily prove that the horizon cone $\widehat{\partial}\varphi(\bfy)^\infty$ (see \cite[Definition 3.3]{RW1998}) of $ \widehat{\partial}\varphi(\bfy)$ satisfies $\widehat{\partial}\varphi(\bfy)^\infty = \partial^ \infty\varphi(\bfy)$. These conditions indicate that  the function $\varphi$ is regular by \cite[Corollary 8.11]{RW1998}, which together with \eqref{chain-rule-cond}, $g(\bfx)=\varphi(h(\bfx))$ and \cite[Theorem 10.6]{RW1998} derives \eqref{chain-rule-sub} immediately. 
\end{proof}

