\begin{equation} \label{eq:here-esti3} -\iprod{d+e}{p_\alpha - x} = - \frac{1}{\lambda\alpha}\iprod{z + \lambda\alpha (d+e) - z}{p_\alpha - x} \leq - \frac{1}{\lambda\alpha} \|p_\alpha - x\|^2. \end{equation}
