\begin{lemma}\label{lemma: independent_unbiasedness}
Under \cref{ass: independent_DCT}, $\nabla_{x} h(x, \xi)$ with $\xi \sim f(\cdot;\theta)$ and $\theta \sim \pi_t$ is an unbiased gradient estimator of the objective function in \cref{eq: independent}.
\end{lemma}

\begin{proof}
For every fixed $x\in\mathcal{X}$, 
\begin{align*}
    \mathbb{E}_{\pi_{t}}\left[\mathbb{E}_{f(\cdot;\theta)} [\nabla_x h(x, \xi)]\right] & = \mathbb{E}_{\pi_{t}}\left[\nabla_{x} \mathbb{E}_{f(\cdot;\theta)} [h(x, \xi)]\right]\\
    & = \nabla_{x} \mathbb{E}_{\pi_{t}}\left[\mathbb{E}_{f(\cdot;\theta)} [h(x, \xi)]\right],
\end{align*}
where the first equality holds because the gradient $\nabla_x h(x,\xi)$ is Lipschitz continuous, and the interchange between expectation and differentiation is justified by dominated convergence theorem (DCT). Similarly, the second equality above is again justified by DCT. Therefore, the proposed estimator in \cref{eq: SGD_independent_2} is unbiased gradient estimator of the objective function in \cref{eq: independent}.
\end{proof}

\begin{lemma}\label{lemma: independent_concentration}
Under \cref{ass: independent_rate}, there exists a constant $C_1>0$ such that for any $\delta>0$, with probability at least $1-\delta$ we have
\begin{align*}
	||\mathbb{E}_{\pi_t}\nabla_x H(x, \theta)-\mathbb{E}_{\pi_t}\nabla_x H(x, \theta^c)||_2^2\leq C_1 \frac{\log Dt + \log \frac{1}{\delta}}{Dt}, \forall x\in \mathcal{X}, \forall t>0. 
\end{align*}
\end{lemma}

\begin{proof}
Define the Hellinger distance between $\theta_1$ and $\theta_2$ as
\begin{align*}
    d(\theta_1,\theta_2) =\sqrt{\frac{1}{2}\int_\mathcal{Y} (\sqrt{f(y;\theta_1)}-\sqrt{f(y;\theta_2)})^2}.
\end{align*}
One can easily verify that there exist a constant $A$ such that $\|\theta_1-\theta_2\|\leq Ad(\theta_1,\theta_2)$, where $||\cdot||$ is the Euclidean norm. Let $B_k^t = B(\theta^c, k/\sqrt{Dt})$ be a ball centered at $\theta^c$ with radius $k/\sqrt{Dt}$ under distance $d.$ Since $\Theta$ is finite, we can directly apply Proposition 1 in \cite{birge2015non}. Then for $t\leq T, \epsilon,\delta\in(0,1)$ with probability at least $1-\frac{6\delta}{\pi^2 t^2}$ with respect to $\mathbb{P}_{\theta^c}^{t}$, we have
\begin{align*}
	\pi_t(B_{k(t)}^t) \geq 1-\epsilon,
\end{align*}
where 
\begin{align*}
    k(t) =\inf\left\{j\geq 1\Big| \sum_{i\geq j}|\Theta|e^{-i^2}\leq \frac{6\delta}{\pi^2 t^2}\sqrt{\epsilon \pi_0(\theta^c)}\right\}.
\end{align*}
Note that $\sum_{i\geq j}e^{-i^2}\leq \frac{e}{e-1} e^{-j^2}$, we can set $k(t)$ to be the solution of next equation. 
\begin{align*}
    \frac{e}{e-1}|\Theta| e^{-k(t)^2} =\frac{6\delta}{\pi^2 t^2}\sqrt{\epsilon \pi_0(\theta^c)}.
\end{align*}
By simple calculation, we have $k(t) = \sqrt{\log \frac{e|\Theta|\pi^2 t^2}{6\delta(e-1)\sqrt{\epsilon\pi_0(\theta^c)}}}$. Now we are ready to bound the bias in the gradient estimator.
\begin{align*}
	& \|\mathbb{E}_{\pi_t}\nabla_x H(x, \theta)-\mathbb{E}_{\pi_t}\nabla_x H(x, \theta^c)\|_2^2 \\
	& = \left\|\int (\nabla_x H(x, \theta)- \nabla_x H(x, \theta^c))\pi_t(\theta) d\theta\right\|_2^2\\
	&\leq \int  \left\|(\nabla_x H(x, \theta)- \nabla_x H(x, \theta^c))\right\|_2^2\pi_t(\theta) d\theta\\
	&\leq  \int L_{H}^2||\theta-\theta^c||_2^2 \pi_t(\theta) d\theta\\
	&=  \int_{B_{k(t)}^t} L_{H}^2||\theta-\theta^c||_2^2 \pi_t(\theta) d\theta + \int_{(B_{k(t)}^t)^c} L_{H}^2||\theta-\theta^c||_2^2 \pi_t(\theta) d\theta\\
	&\leq A^2 L_{H}^2 \frac{k(t)^2}{Dt}  \int_{B_{k(t)}^t} \pi_t(\theta) d\theta + L_{H}^2 \max_{\theta\in\Theta}\|\theta-\theta^c\|^2_2\int_{(B_{k(t)}^t)^c}  \pi_t(\theta) d\theta\\
	&\leq  A^2 L_{H}^2 \frac{k(t)^2}{Dt} +  L_{H}^2 \max_{\theta\in\Theta}\|\theta-\theta^c\|^2_2\epsilon.
\end{align*}
Recall that $D$ is the data batch size. Take $\epsilon =\frac{1}{Dt}$, note that $k(t) =\sqrt{\log \frac{e|\Theta|\pi^2 t^2\sqrt{Dt}}{6\delta(e-1)\sqrt{\pi_0(\theta^c)}}}$. We further have
\begin{align*}
	\|\mathbb{E}_{\pi_t}\nabla_x H(x, \theta)-\mathbb{E}_{\pi_t}\nabla_x H(x, \theta^c)\|_2^2
	&\leq  A^2 L_{H}^2 \frac{k(t)^2}{Dt} +  L_{H}^2 \max_{\theta\in\Theta}\|\theta-\theta^c\|^2_2\epsilon\\
	&\leq 2A^2 L_{H}^2\max_{\theta\in\Theta}\|\theta-\theta^c\|^2_2\frac{\log \frac{e|\Theta|\pi^2 t^2\sqrt{Dt}}{6\delta(e-1)\sqrt{\pi_0(\theta^c)} }}{Dt}\\
	&= O(\frac{\log Dt + \log \frac{1}{\delta}}{Dt}).
\end{align*}

Let $\mathcal{E}_t$ denote the event that the above inequality holds, and $\mathcal{E}_t^c$ denote the complement event. Then we have $\mathbb{P}(\mathcal{E}_t^c) \leq \frac{6\delta}{\pi^2 t^2}$. Therefore,
\begin{align*}
    \mathbb{P}(\cap_{t=1}^\infty \mathcal{E}_t) & = 1- \mathbb{P}(\bigcup_{t=1}^{\infty} \mathcal{E}^c_t) \\
    & \geq 1 - \sum_{t=1}^{\infty} \mathbb{P}(\mathcal{E}_t^c) \quad (\text{union bound}) \\
    & \geq 1 - \sum_{t=1}^{\infty} \frac{6\delta}{\pi^2 t^2} \\
    & = 1 - \delta.
\end{align*}
\end{proof}

\begin{proof}
By the update \cref{eq: SGD_independent_2}, we know that for any $t\leq T$,
\begin{align*}
    x_{t+1} &= x_{t} - a_{t} \nabla_x H(x_{t},\theta^c) -  a_{t}[\mathbb{E}_{\pi_t}\nabla_x H(x_{t}, \theta)-\nabla_x H(x_{t}, \theta^c)]	\\
    &~~~~~~~~- a_{t}[\nabla_x h(x_{t}, \xi_{t})-\mathbb{E}_{\pi_t}\nabla_x H(x_{t}, \theta)]\\
    & =  x_{t} - a_{t}	\nabla_x H(x_{t},\theta^c) -  a_{t} B_{t} - a_{t} N_{t},
\end{align*}
where $B_{t}$ is the bias and $N_{t}$ is the noise. By \cref{lemma: independent_concentration}, we know $\mathbb{E}[\|B_{t}\|_2^2]\leq  C_1 \frac{\log Dt + \log \frac{1}{\delta}}{Dt}.$ From \cref{ass: independent_rate} we have $\mathbb{E}[\|N_{t}\|_2^2]\leq \sigma^2.$ By the proof of Lemma 2 in \cite{ajalloeian2020analysis}, we know that 
\begin{align*}
    \mathbb{E}[H(x_{t+1},\theta^c)] - H(x_{t},\theta^c)\leq -\frac{a_{t}}{2}\|\nabla_x H(x_{t},\theta^c) \|_2^2 +\frac{a_{t}}{2}C_1 \frac{\log Dt + \log \frac{1}{\delta}}{Dt} +\frac{a_{t}^2}{2}L_{h} \sigma^2,
\end{align*} 
Rearranging the terms in the inequality above, summing over $t$ from 1 to $T$, and noting that $H(x_{t}, \theta^c) \leq \min_{x \in \mathcal{X}} H(x, \theta^c), \forall t$, we have 
{\small
\begin{align*}
    \sum_{t=1}^{T} a_t \mathbb{E}[\|\nabla_x H(x_{t},\theta^c) \|_2^2]\leq 2
    (H(x_1,\theta^c) - \min_{x \in \mathcal{X}} H(x,\theta^c))
    + C_1 \sum_{t=1}^{T} a_t \frac{\log Dt + \log \frac{1}{\delta}}{Dt} + L_{h}\sigma^2 \sum_{t=1}^{T} a_t^2,
\end{align*}
}
Dividing both sides of the above inequality by $\sum_{t=1}^{T} a_t$, and noting that 
\begin{align*}
    \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2] = \frac{1}{\sum_{t=1}^{T} a_t} \sum_{t=1}^{T} a_t \mathbb{E}[\|\nabla_x H(x_{t},\theta^c) \|_2^2],
\end{align*}
we have
{\small
\begin{align*}
    \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2] \leq \frac{1}{\sum_{t=1}^{T} a_t}\left[2 (H(x_1,\theta^c) - \min_{x \in \mathcal{X}} H(x,\theta^c)) +C_1 \sum_{t=1}^{T} a_t \frac{\log Dt + \log \frac{1}{\delta}}{Dt} + L_{h} \sigma^2\sum_{t=1}^{T}a_t^2.
    \right]
\end{align*}
}
(i) $a_t=\frac{a}{\sqrt{T}}$, $\forall t \leq T$, for some constant $a<\frac{\sqrt{T}}{L_{h}}$. Note that $\sum_{t=1}^{T} \frac{1}{t} \leq \log T+1$ and $\sum_{t=1}^{T} \frac{\log t}{t} \leq \log (\log T+1)$.
Then
{\small
\begin{align*}
    & \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2]\\
    &\leq \frac{2(H(x_1,\theta^c)- \min_{x}H(x,\theta^c))}{a\sqrt{T}} + \frac{C_1 (\log D - \log \delta) (\log T + 1)}{L_{h} D T} + \frac{C_1 \log T (\log T + 1)}{L_{h} D T} \\ 
    & = \frac{2(H(x_1,\theta^c)- \min_{x}H(x,\theta^c))}{a\sqrt{T}} + \frac{C_1 (\log D - \log \delta)}{L_{h} D T} + \frac{C_1 (\log D - \log \delta) \log T}{L_{h} D T} + \frac{C_1 \log^2 T}{L_{h} D T} + \frac{L_{h} a\sigma^2}{\sqrt{T}}
\end{align*}
}
(ii) $a_t = \frac{a}{t}$, $\forall t \leq T$, for some constant $a < \frac{1}{L_{h}}$. Let $M_T=\sum_{t=1}^{T}\frac{1}{t}$. Note that 
\begin{align*}
    \sum_{t=1}^{T}\frac{\log t}{t^2} < \sum_{t=1}^{\infty}\frac{\log t}{t^2} = \frac{\pi^2}{6}(12 \ln A - \gamma - \ln 2\pi) < 1,
\end{align*}
where $A \approx 1.28$ is the Glaisher-Kinkelin constant and $\gamma \approx 0.58$ is the Euler-Mascheroni constant. Then we have
\begin{align*}
	& \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2]\\
	&\leq \frac{2(H(x_1,\theta^c)- \min_{x\in\mathcal{X}}H(x,\theta^c))}{a M_T} +\frac{C_1}{M_T}\sum_{t=1}^T \frac{\log Dt + \log \frac{1}{\delta}}{Dt^2} +\sum_{t=1}^T \frac{L_{h} a \sigma^2}{M_T t^2}\\
	& \leq \left[\frac{2(H(x_1,\theta^c)- \min_{x\in\mathcal{X}}H(x,\theta^c))}{a} +\frac{6C_1 + \pi^2C_1 (\log D - \log \delta)}{6D}+\frac{\pi^2 L_{h} a \sigma^2}{6}\right]\frac{1}{\log T}.
\end{align*}
(iii) $a_t = \frac{a}{\sqrt{t}}$, $\forall t \leq T$, for some constant $a < \frac{1}{L_{h}}$. Let $Q_t=\sum_{t=1}^{T}\frac{1}{\sqrt{t}}$. Note that $\sum_{t=1}^{\infty}\frac{1}{t\sqrt{t}}=\zeta(1.5)\approx2.61<3$, $\sum_{t=1}^{\infty} \frac{\log t}{t\sqrt{t}} < 4$, $\sum_{t=1}^{T}\frac{1}{\sqrt{t}} \geq \sqrt{T}$, where $\zeta(\cdot)$ is the Riemann’s zeta function. Then we have
{\small
\begin{align*}
	& \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2]\\
	&\leq \frac{2(H(x_1,\theta^c)- \min_{x}H(x,\theta^c))}{a Q_T} +\frac{C_1(\log D - \log \delta)}{D Q_T}\sum_{t=1}^T \frac{1}{t\sqrt{t}} + \frac{C_1}{D Q_T}\sum_{t=1}^{T}\frac{\log t}{t \sqrt{t}} +  \frac{L_{h} a \sigma^2}{Q_T} \sum_{t=1}^T \frac{1}{t}\\
	&\leq \left[\frac{2(H(x_1,\theta^c)- \min_{x}H(x,\theta^c))}{a\sqrt{T}} + \frac{3C_1(\log D - \log \delta) + 4C_1}{D\sqrt{T}} + \frac{L_{h} a \sigma^2}{\sqrt{T}}\right] + \frac{L_{h} a \sigma^2 \log T}{\sqrt{T}}.
\end{align*}
}
\end{proof}

