\begin{theorem} (\textbf{Sublinear convergence rate of SA2GD in the smooth and strongly convex case})
\label{th:smooth_strongcov}
Let Assumptions~\ref{ass:limit_pts}-\ref{ass:gradient} hold and $x_*$ be the unique minimizer of the weighted function $S(\cdot, \lambda_*)$ in~$\mathcal{X}$, where $\lambda_* = \lambda(n_a, n_b) = n_a/(n_a + n_b)$. Choosing a diminishing step size sequence
$\alpha_t = \frac{2}{c(t+1)(n_a + n_b)}$, the sequence of iterates generated by the SA2GD algorithm satisfies
\begin{equation*}
    \min_{t = 1, \ldots,T} \mathbb{E}[S(x_t, \lambda_*)] - S(x_*, \lambda_*) \;\leq\; \frac{4}{c(T + 1)} \left(\hat{G}^2 +  L\Theta\hat{G}\right).   
\end{equation*}
 where $\hat{G} = \sqrt{G + \bar{G}M_{\nabla}}$, $L = \max(L_a, L_b)$, $G = \max(G_a, G_b)$, $\bar{G} = \max(\bar{G}_a, \bar{G}_b)$, and $M_\nabla = \max(M_\nabla^a, M_\nabla^b)$.
\end{theorem}

