Then, with probability $1 - \delta\pi^2/6$, 
we have $\xb_t\in \N_\nu$, for all $t\geq \T$ where~$\T = \T_1 + \T_2$ with $\T_1$ defined in \eqref{T1} and
\begin{equation}\label{T2}
\T_2 =  \frac {\kappa^2(1+\epsilon)}{4\rho\beta(1-\beta)(1-\epsilon)}\log\rbr{\frac{3L^2(f(\xb_0) - f(\ttxb))}{\nu^2\lambda_{\min}^3}}.
\end{equation}	
\end{corollary}

\begin{proof}
See Appendix \ref{pf:cor:1}.
\end{proof}

\begin{lemma}\label{lem:5}
