In this paper we consider nonconvex equality constrained optimization problem
\beq\label{model:equa-cnstr}
\min_{x\in \bR^n}\ f(x)\quad \st\ c(x)=0,
\eeq

where $f:\bR^n\to\bR$ and $c:\bR^n\to\bR^m$ are twice continuously differentiable, and we assume that problem~\eqref{model:equa-cnstr} has at least one optimal solution. Since \eqref{model:equa-cnstr} is a nonconvex optimization problem, it may have many local but non-global minimizers and finding its global minimizer is generally NP-hard. A first-order stationary point (FOSP) of it is usually found in practice instead. Nevertheless,  a mere FOSP may sometimes not suit our needs and a  \emph{second-order stationary point} (SOSP) needs to be sought. For example, in the context of linear semidefinite programming (SDP), a powerful approach to solving it is by solving an equivalent nonconvex equality constrained optimization problem \cite{BuMo03-1,BuMo05-1}. It was shown in \cite{BuMo05-1,BVB16} that under some mild conditions an SOSP of the latter problem can yield an optimal solution of  the linear SDP, while a mere FOSP generally cannot.  It is therefore important to find an SOSP of problem~\eqref{model:equa-cnstr}.


Throughout this paper, we let $\bR^n$ denote the $n$-dimensional Euclidean space. We use $\|\cdot\|$ to denote the Euclidean norm of a vector or the spectral norm of a matrix. For a real symmetric matrix $H$, we use $\lambda_{\min}(H)$ to denote its minimum eigenvalue.
The Euclidean ball centered at the origin with radius $R\ge0$ is denoted by $\mathcal{B}_R:=\{x:\|x\|\le R\}$, and we use $\Pi_{\mathcal{B}_R}(v)$ to denote the Euclidean projection of a vector $v$ onto $\mathcal{B}_R$. For a given finite set $\cA$, we let $|\cA|$ denote its cardinality. For any $s\in \mathbb{R}$, we let ${\rm sgn}(s)$ be $1$ if $s \ge 0$ and let it be $-1$ otherwise. In addition, $\widetilde{\cO}(\cdot)$ represents $\cO(\cdot)$ with logarithmic terms omitted. %In addition, for any $s\in \mathbb{R}$, we let ${\rm sgn}(s)$ be $1$ if $s \ge 0$ and let it be $-1$ otherwise.


$\nabla c(x^*):=[\nabla c_1(x^*) \ \nabla c_2(x^*) \ \cdots \ \nabla c_m(x^*)]$


\begin{equation}\label{def:critical-cone} 
\cC(x):=\{d\in\bR^n:\nabla c(x)^T d=0\}.
\end{equation}

\begin{definition}[{{\bf $\epsilon_1$-first-order stationary point}}]\label{def:FOSP}
Let $\epsilon_1>0$. We say that $x\in\bR^n$ is an $\epsilon_1$-first-order stationary point {\rm ($\epsilon_1$-FOSP)} of problem \eqref{model:equa-cnstr} if it, together with some $\lambda\in\bR^m$, satisfies 
\begin{equation}\label{optcond:1st-equa-cnstr} 
\|\nabla f(x)+\nabla c(x)\lambda\|\le \epsilon_1,\quad \|c(x)\|\le \epsilon_1.
\end{equation}
\end{definition}

\begin{definition}[{{\bf $(\epsilon_1,\epsilon_2)$-second-order stationary point}}]\label{def:SOSP}
Let $\epsilon_1,\epsilon_2>0$. We say that $x\in\bR^n$ is an $(\epsilon_1,
\epsilon_2)$-second-order stationary point {\rm (($\epsilon_1,
\epsilon_2$)-SOSP)} of problem \eqref{model:equa-cnstr} if it, together with some $\lambda\in\bR^m$, satisfies \eqref{optcond:1st-equa-cnstr} and additionally 
\begin{equation}\label{optcond:2nd-equa-cnstr} 
d^T\left(\nabla^2 f(x)+\sum_{i=1}^m\lambda_i\nabla^2 c_i(x)\right)d\ge-\epsilon_2\|d\|^2,\quad \forall d\in\cC(x),
\end{equation}
where $\cC(\cdot)$ is defined as in \eqref{def:critical-cone}.
\end{definition}

\begin{equation}\label{unconstrained-prob} 
\min_{x\in\bR^n}\ F(x),
\end{equation}

\begin{assumption}\label{asp:NCG-cmplxity}
\begin{enumerate}[{\rm (a)}]
\item The level set $\scL_F(u^0):=\{x: F(x)\le F(u^0)\}$ is compact for some $u^0\in \bR^n$.%, where $z^0\in\bR^n$ is the initial iterate of the Newton-CG method in \cite{RNW18}.
\item The function $F$ is twice Lipschitz continuously differentiable in
%{\color{black}some} convex open neighborhood $\Omega$ of $\{x|\  F(x)\le F(u^0)\}$,
%the convex hull of $\Omega$, denoted by $\conv(\Omega)$,
a convex open neighborhood, denoted by $\Omega$, of $\scL_F(u^0)$,
that is, there exists $L_{H}^F>0$ such that
\begin{equation}\label{F-Hess-Lip}
\|\nabla^2 F(x)-\nabla^2 F(y)\|\le L_{H}^F\|x-y\|,\quad \forall x,y\in \Omega.
\end{equation}
\end{enumerate}
\end{assumption}

By Assumption \ref{asp:NCG-cmplxity}, there exist $\Fl\in \bR$, $U_g^F>0$ and $U_H^F>0$ such that
\begin{equation}\label{lwbd-Hgupbd}
F(x)\ge \Fl,\quad \|\nabla F(x)\|\le U_g^F,\quad \|\nabla^2 F(x)\|\le U_H^F, \quad \forall x\in\scL_F(u^0).
\end{equation}


The first main component of the Newton-CG method in \cite{RNW18} is a {\it capped CG method} \cite[Algorithm~1]{RNW18}, which is a modified CG method, for solving a possibly indefinite linear system 
\begin{equation}\label{indef-sys} 
(H+2\varepsilon I)d=-g,
\end{equation}

where $0\neq g\in\bR^n$, $\varepsilon>0$, and $H\in\bR^{n\times n}$ is a symmetric matrix. This capped CG method terminates within a finite number of iterations. It outputs either an approximate solution $d$ to \eqref{indef-sys} such that $\|(H+2\varepsilon I)d+g\|\le\widehat{\zeta}\|g\|$ and $d^THd\ge-\varepsilon\|d\|^2$ for some $\widehat{\zeta}\in(0,1)$ or a sufficiently negative curvature direction $d$ of $H$ with $d^THd<-\varepsilon\|d\|^2$. The second main component of the Newton-CG method in \cite{RNW18} is a minimum eigenvalue oracle that either produces a sufficiently negative curvature direction $v$ of $H$ with $\|v\|=1$ and  $v^THv\le-\varepsilon/2$ or certifies that $\lambda_{\min}(H)\ge-\varepsilon$ holds with high probability. For ease of reference, we present these two components in Algorithms~\ref{alg:capped-CG}  and \ref{pro:meo} in Appendices~\ref{appendix:capped-CG} and \ref{appendix:meo}, respectively.


\begin{algorithm}[h]
\caption{A Newton-CG method for problem \eqref{unconstrained-prob}}
\label{alg:NCG}
{\footnotesize
\begin{algorithmic}
\State \noindent\textit{Input}: Tolerances $\epsilon_g,\epsilon_H\in(0,1)$, backtracking ratio $\theta\in(0,1)$, starting point $u^0$, CG-accuracy parameter $\zeta\in(0,1)$, line-search parameter $\eta\in(0,1)$, probability parameter $\delta\in(0,1)$.\\
Set $x^0=u^0$;
\For{$t=0,1,2,\ldots$}
\If{$\|\nabla F(x^t)\|>\epsilon_g$}
\State Call Algorithm~\ref{alg:capped-CG} with $H=\nabla^2 F(x^t)$, $\varepsilon=\epsilon_H$, $g=\nabla F(x^t)$, accuracy parameter $\zeta$, and $U=0$ to obtain outputs $d$,
\State d$\_$type;
\If{d$\_$type=NC}
%\State
\begin{equation}\label{dk-nc}
d^t\leftarrow -\sgn(d^T\nabla F(x^t))\frac{|d^T\nabla^2 F(x^t) d|}{\|d\|^3}d;
\end{equation}
\Else\ \{d$\_$type=SOL\}
%\State
\begin{equation}\label{dk-sol}
d^t\leftarrow d;
\end{equation}
\EndIf
\State Go to {\bf Line Search};
\Else
\State Call Algorithm~\ref{pro:meo} with $H=\nabla^2 F(x^t)$, $\varepsilon=\epsilon_H$, and probability parameter $\delta$;
\If{Algorithm~\ref{pro:meo} certifies that $\lambda_{\min}(\nabla^2 F(x^t))\ge-\epsilon_H$}
\State Output $x^t$ and terminate;
\Else\ \{Sufficiently negative curvature direction $v$ returned by Algorithm~\ref{pro:meo}\}
\State Set d$\_$type=NC and
\begin{equation}\label{dk-2nd-nc}
d^t\leftarrow -\sgn(v^T\nabla F(x^t))|v^T\nabla^2F(x^t)v|v;
\end{equation}
\State Go to {\bf Line Search};
\EndIf
\EndIf
\State{\bf Line Search:}
\If{d$\_$type=SOL}
\State Find $\alpha_t=\theta^{j_t}$, where $j_t$ is the smallest nonnegative integer $j$ such that
\begin{equation}\label{ls-sol}
F(x^t+\theta^jd^t)<F(x^t)-\eta\epsilon_H\theta^{2j}\|d^t\|^2;
\end{equation}
\Else\ \{d$\_$type=NC\}
\State Find $\alpha_t=\theta^{j_t}$, where $j_t$ is the smallest nonnegative integer $j$ such that
\begin{equation}\label{ls-nc}
F(x^t+\theta^jd^t)<F(x^t)-\eta\theta^{2j}\|d^t\|^3/2;
\end{equation}
\EndIf
\State $x^{t+1}=x^t+\alpha_td^t$;
\EndFor
\end{algorithmic}
}
\end{algorithm}

\begin{assumption}\label{asp:lowbd-knownfeas}		
\begin{enumerate}[{\rm (a)}]
\item An $\epsilon_1/2$-approximately feasible point $z_{\epsilon_1}$ of problem~\eqref{model:equa-cnstr}, namely satisfying $\|c(z_{\epsilon_1})\|\le\epsilon_1/2$, is known.	
\item There exist constants $\fh$, $\fl$ and $\gamma>0$, independent of $\epsilon_1$ and $\epsilon_2$,  such that
\begin{eqnarray}
&& f(z_{\epsilon_1})\le\fh, \label{hbd}\\
&& f(x)+\gamma\|c(x)\|^2/2\ge \fl,\quad \forall x\in\bR^n, \label{lbd}
\end{eqnarray}
 where $z_{\epsilon_1}$ is given in (a).
\item %{  For any $\epsilon \in (0,1)$ and the corresponding $z^0$ from (b),}
There exist some $\bdelta_f,\bdelta_c>0$ such that the set
\begin{equation}\label{nearly-feas-level-set}
\cS(\bdelta_f,\bdelta_c):=\{x:f(x)\le \fh+\bdelta_f,\ \|c(x)\|\le1+\bdelta_c\}
\end{equation}
%is compact, { with $\fh$ as in \eqref{hbd}}. 
is compact with $\fh$ given above. Also, $\nabla^2 f$ and $\nabla^2 c_i,\ i=1,2,\ldots,m$, are Lipschitz continuous in a convex open neighborhood, denoted by $\Omega(\bdelta_f,\bdelta_c)$, of $\cS(\bdelta_f,\bdelta_c)$.
\end{enumerate}
\end{assumption}

\begin{equation}\label{model:equa-cnstr-pert}
\min_{x\in \bR^n}\ f(x)\quad \st\ \tilde{c}(x):=c(x)-c(z_{\epsilon_1})=0,
\end{equation}

\begin{equation}\label{tL-tc}
\min_{x\in\bR^n} \big\{\widetilde{\cL}(x,\lambda^k,\rho_k):= f(x)+(\lambda^k)^T\tilde{c}(x)+\rho_k\|\tilde{c}(x)\|^2/2\big\}
\end{equation}

\begin{algorithm}[h]
\caption{A Newton-CG based AL method for problem
\eqref{model:equa-cnstr}}
\label{alg:2nd-order-AL-nonconvex}
{\small
Let $\gamma$ be given in Assumption \ref{asp:lowbd-knownfeas}.\\
\noindent\textbf{Input}: $\epsilon_1,\epsilon_2\in(0,1)$, $\Lambda>0$, $x^0\in\bR^n$, $\lambda^0 \in \mathcal{B}_{\Lambda}$, $\rho_0>2\gamma$, $\alpha\in(0,1)$, ${r}>1$, $\delta\in(0,1)$, and  $z_{\epsilon_1}$ given in Assumption~\ref{asp:lowbd-knownfeas}.
\begin{algorithmic}[1]
\State Set $k=0$.
\State Set $\tau_k^g=\max\{\epsilon_1, {r}^{k\log\epsilon_1/\log 2}\}$ and $\tau_k^H=\max\{\epsilon_2, {r}^{k\log\epsilon_2/\log 2}\}$.
\State  Call Algorithm \ref{alg:NCG} with $\epsilon_g=\tau_k^g$, $\epsilon_H=\tau_k^H$ and $u^0=x^{k}_{\init}$ to find an approximate solution $x^{k+1}$ to $\min_{x\in\bR^n}\widetilde{\cL}(x,\lambda^k;\rho_k)$ such that 
\begin{eqnarray}
&&\widetilde{\cL}(x^{k+1},\lambda^k;\rho_k)\le f(z_{\epsilon_1}),\ \|\nabla_x \widetilde{\cL}(x^{k+1},\lambda^k;\rho_k)\|\le\tau_k^g,\label{algstop:1st-order}\\
&&\lambda_{\min}(\nabla^2_{xx}\widetilde{\cL}(x^{k+1},\lambda^k;\rho_k))\ge-\tau_k^H\  \text{with probability at least } 1-\delta, \label{algstop:2nd-order}
\end{eqnarray}
where
\begin{equation}\label{def:initial-iterate-subprob}
x^k_{\init}=\left\{\begin{array}{ll}
z_{\epsilon_1}&\text{if }\ \widetilde{\cL}(x^k,\lambda^k;\rho_k)> f(z_{\epsilon_1}),\\
x^{k}&\text{otherwise},
\end{array}\right.\quad\text{for } k\ge 0.
\end{equation}\label{algstp:ALsubpb}
\State Set $\tilde{\lambda}^{k+1}=\lambda^k+\rho_k\tilde{c}(x^{k+1})$.
\State If $\tau_k^g\le\epsilon_1$, $\tau_k^H\le\epsilon_2$ and $\|c(x^{k+1})\|\le\epsilon_1$, then output $(x^{k+1},\tilde{\lambda}^{k+1})$ and terminate.\label{algstep:stop}
\State Set $\lambda^{k+1}=\Pi_{\mathcal{B}_\Lambda}(\tilde{\lambda}^{k+1})$.\label{algstep:proj-multiplier}
\State If $k=0$ or $\|\tilde{c}(x^{k+1})\|>\alpha\|\tilde{c}(x^k)\|$, set $\rho_{k+1}={r}\rho_k$. Otherwise, set $\rho_{k+1}=\rho_k$.\label{altstep:penalty}
\State Set $k\leftarrow k+1$, and go to step 2.
\end{algorithmic}
}
\end{algorithm}

In the rest of this section, we study the worst-case complexity of Algorithm \ref{alg:2nd-order-AL-nonconvex}. Since our method has two nested loops, particularly,  outer loops executed by the AL method and inner loops executed by the Newton-CG method for solving the AL subproblems, we consider the following measures of complexity for Algorithm \ref{alg:2nd-order-AL-nonconvex}.
\begin{itemize}
\item \emph{Outer iteration complexity}, which measures the number of outer iterations of Algorithm \ref{alg:2nd-order-AL-nonconvex};
\item  \emph{Total inner iteration complexity}, which measures the total number of iterations of the Newton-CG method that are performed in Algorithm \ref{alg:2nd-order-AL-nonconvex};
\item \emph{Operation complexity}, which measures the total number of matrix-vector products involving the Hessian of the augmented Lagrangian function that are evaluated in Algorithm \ref{alg:2nd-order-AL-nonconvex}.
\end{itemize}


For notational convenience, we rewrite $(\tau_k^g,\tau_k^H)$ arising in Algorithm \ref{alg:2nd-order-AL-nonconvex} as
\begin{equation}\label{omega-tolerance}
(\tau_k^g,\tau_k^H)=(\max\{\epsilon_1,\omega_1^k\},\max\{\epsilon_2,\omega_2^k\})\ \mbox{ with }\ (\omega_1,\omega_2):=({r}^{\log\epsilon_1/\log 2},{r}^{\log\epsilon_2/\log 2}),
\end{equation}
where $\epsilon_1$, $\epsilon_2$ and $r$ are the input parameters of Algorithm \ref{alg:2nd-order-AL-nonconvex}. Since $r>1$ and $\epsilon_1,\epsilon_2\in(0,1)$, it is not hard to verify that $\omega_1,\omega_2\in(0,1)$.
Also, we introduce the following quantity that will be used frequently later:
\begin{equation}
K_{\epsilon_1}:= \left\lceil \min\{k\ge 0:\omega_1^{k}\le\epsilon_1\} \right\rceil=\left\lceil\log\epsilon_1/\log\omega_1\right\rceil. \label{T-epsilon-g}
