\begin{Thm}\label{Thm:5-4}
  Suppose GPA generates an infinite sequence of iteration points $\{\xv_c\}$ that converges to a critical point $\xv_*$. Then, we have the following estimations on convergence rate.
  \begin{itemize}
    \item If $\theta=1/2$, there exist $\gamma>0$ and $\mu\in(0,1)$ such that
      \begin{equation*}
        \|\xv_c-\xv_*\| \le \gamma\mu^c.
      \end{equation*}
    \item If $\theta\in(1/2,1)$, there exist $\gamma_1>0$ and $\gamma_2>0$ such that
      \begin{equation*}
        |f(\xv_c)-f(\xv_*)| \le \gamma_1 c^{-\frac{1}{2\theta-1}} \qquad\text{ and }\qquad
        \|\xv_c-\xv_*\| \le \gamma_2 c^{-\frac{1-\theta}{2\theta-1}}.
      \end{equation*}
  \end{itemize}
\end{Thm}

\begin{proof}
  Without loss of generality, we assume $\xv_0\in\mathds{B}(\xv_*,\sigma)$. Define
  \begin{equation*}
    \zeta_c:=\sum_{\ell=c}^{\infty} \|\xv_{\ell}-\xv_{\ell+1}\| \ge \|\xv_c-\xv_*\|.
  \end{equation*}
  From Lemma \ref{Lem:5-2} and Theorem \ref{Thm:5-1}, we have
  \begin{eqnarray*}
    \zeta_c &\le& \frac{\max\{1,\overline{\alpha}\}}{\eta C(1-\theta)}|f(\xv_c)-f(\xv_*)|^{1-\theta} \\
      &=& \frac{\max\{1,\overline{\alpha}\}}{\eta C^{1/\theta}(1-\theta)}\left(C|f(\xv_c)-f(\xv_*)|^{\theta}\right)^{(1-\theta)/\theta} \\
      &\le& \frac{\max\{1,\overline{\alpha}\}}{\eta C^{1/\theta}(1-\theta)}\left(\|\gv^1(\xv_c)\|\right)^{(1-\theta)/\theta}.
  \end{eqnarray*}
  It can be obtained from Lemma \ref{Lem:4-2} and \eqref{gc-lowbd} that
  \begin{equation*}
