	  & a_j =\# A_j\,,\\
    B_j & =\{1\leq k\leq j\;|\;\; 
   \text{$\lambda_k\norm{y_k - x_{k-1}} < \eta$\; holds at iteration $k$}\},
    & b_j =\# B_j\,,
  \end{aligned}
\end{align}
%
\begin{align}
 \lab{eq:uni.ab}
 A =\bigcup_{j=1}^\infty A_j\;\;\mbox{and}\;\; B =\bigcup_{j=1}^\infty B_j.
\end{align}
%
We also define
%
\begin{align}
\lab{eq:s70}
