	\begin{align*}
		g(\xpp) - g(u) \le \frac{\eta}{2}\|u - x\|^2 - \frac{\eta}{2}\|u - \xpp\|^2 - \frac{\eta}{4}\|\xpp - x\|^2, \ \forall u\in \R^n.
	\end{align*}

	Letting $u=x^*$ in the above relation, using the optimality of $x^*$ and the fact that $\xpp - x = -(1/\eta)\nabla g(x)$ we conclude that 
	$	\|\nabla g(x)\|^2 \le 2\eta^2\|x^* -x\|^2$.
\qedsymbol\end{proof}

\begin{lem}
	\label{lem:grad_map_properties}
	For any $x, \xu\in\R^n$ and $\eta>0$, $\sigma\ge0$, we have the following properties for the (perturbed) gradient mappings:
	\begin{align}
		\label{eq:xp_lip}
		& \|x^+(\eta+\sigma; x) - x^{++}(\eta, \sigma, \xu; x)\| \le \frac{\sigma}{\eta+\sigma}\|x - \xu\|;
		\\
		\label{eq:xp_monotonicity}
		& \|G_\eta(x)\| \le \|G_{\sigma + \eta}(x)\|.
	\end{align}
	Moreover, if $x^{++}:=x^{++}(\eta, \sigma, \xu; x)$ satisfies 
	\begin{align}
		\label{eq:local_lip}
		f(x^{++}) - f(x) - \langle \nabla f(x), x^{++} - x\rangle \le \frac{M}{2}\|x^{++} - x\|^2
	\end{align}
	for some $M>0$,  we have
	\begin{align}
		\label{eq:3point}
		\begin{aligned}
			&  \left[f(x^{++}) + \phi(x^{++}) + \frac{\sigma}{2}\|x^{++} - \xu\|^2\right] - \left[f(u) + \phi(u) + \frac{\sigma}{2}\|u - \xu\|^2\right]
			\\
			\le\ & \frac{\eta}{2}\|u - x\|^2 - \frac{\sigma + \eta}{2}\|u - x^{++}\|^2 - \frac{\eta-M}{2}\|x^{++} - x\|^2 ,\ \forall u\in X.
		\end{aligned}
	\end{align}
\end{lem}

\begin{proof}
	Let us denote $x^+:=x^+(\eta+\sigma; x)$, $x^{++}:=x^{++}(\eta, \sigma, \xu; x)$ and $x' := x^+(\eta; x)$. By the optimality conditions of \eqref{eq:xp} and \eqref{eq:xpp} we have 
	\begin{align}
		\langle \nabla f(x) + (\eta+\sigma)(x^+ - x), u - x^{+}\rangle + \phi(u) - \phi(x^{+}) \ge 0, \label{eq:oc_simple_1} \\
		\langle \nabla f(x) + \sigma (x^{++}-\bar x) +\eta (x^{++} - x), u - x^{++}\rangle + \phi(u) - \phi(x^{++})\ge 0, \label{eq:oc_simple_2} \\
		\langle \nabla f(x) + \eta (x' - x), u - x'\rangle + \phi(u) - \phi(x') \ge 0 \label{eq:oc_simple_3}
	\end{align}
	for any $u \in X$.

In order to show \eqref{eq:3point}, we first notice that
\eqref{eq:oc_simple_2} is equivalent to 

\begin{align*}
	\begin{aligned}
		\langle \nabla f(x), x^{++} - u\rangle + \phi(x^{++}) - \phi(u)
		&\le ({\sigma}/{2})(\|u - \xu\|^2 - \|x^{++} - \xu\|^2 - \|u - x^{++}\|^2) \\
		& + ({\eta}/{2})(\|u - x\|^2 - \|x^{++} - x\|^2 - \|u - x^{++}\|^2)
	\end{aligned}
\end{align*}	
for any $u\in X$.

Specifically, 
noting the $L$-Lipschitz continuity of $\nabla f(x)$ and using the optimality condition $\nabla f_s(x_s^*)=\nabla f(x_s^*) + \sigma_s(x_s^* - \xu_s) = 0$ at $x_s^*$,
we have
\begin{align}
	\label{eq:xs_norm_bound_unconstrained}
	\begin{aligned}
		& \|\nabla f(x_s)\| = \|\nabla f(x_s) - \nabla f(x_s^*) - \sigma_s(x_s^* - \xu_s)\| 
		\\
		\le \ & \|\nabla f(x_s) - \nabla f(x_s^*)\| + \sigma_s\|x_s^* - \xu_s\| 
		\\
		\le\ &  L\|x_s - x_s^*\| + \sigma_s\|x_s^* - \xu_s\|.
	\end{aligned}
\end{align}
We will show later that with the increasing regularization parameter $\sigma_s$ and convex combination design of prox-center in \eqref{eq:xus_unconstrained}, the distance $\sigma_s\|x_s^* - \xu_s\|$ can be further bounded:
\begin{align}
	\label{eq:claim_on_distance_unconstrained}
	\sigma_s\|x_s^* - \xu_s\| \le \sigma_1\|x^* - x_0\| + \sum_{i=2}^s(\sigma_{i-1} + \sigma_i)\|x_{i-1}^* - x_{i-1}\|.
\end{align}
Therefore, $\|\nabla f(x_s)\|$ can be controled by
\begin{align}
	\label{eq:gradS_estimate_unconstrained}
	\|\nabla f(x_s)\| \le\ &  L\|x_s - x_s^*\| + \sigma_1\|x^* - x_0\| + \sum_{i=2}^s(\sigma_{i-1} + \sigma_i)\|x_{i-1}^* - x_{i-1}\|.
\end{align}
Note that the right-hand-side of the above estimate is the summation of terms of form $\|x_i - x_i^*\|$, i.e., the distance from an approximate solution $x_i$ to the optimal solution $x_i^*$ of the $i$-th strongly convex subproblem.
By studying the convergence properties of subroutine $\cA$ for minimizing smooth and strongly convex functions in subproblem \eqref{eq:subproblem_unconstrained}, we will then bound the total number of gradient evaluations needed to reduce the right-hand-side of the above estimate to the accuracy $\varepsilon$.

Specifically, 
noting the $L$-Lipschitz continuity of $\nabla f(x)$ and using the optimality condition $\nabla f_s(x_s^*)=\nabla f(x_s^*) + \sigma_s(x_s^* - \xu_s) = 0$ at $x_s^*$,
we have
\begin{align}
	\label{eq:xs_norm_bound_unconstrained}
	\begin{aligned}
		& \|\nabla f(x_s)\| = \|\nabla f(x_s) - \nabla f(x_s^*) - \sigma_s(x_s^* - \xu_s)\| 
		\\
		\le \ & \|\nabla f(x_s) - \nabla f(x_s^*)\| + \sigma_s\|x_s^* - \xu_s\| 
		\\
		\le\ &  L\|x_s - x_s^*\| + \sigma_s\|x_s^* - \xu_s\|.
	\end{aligned}
\end{align}

We will show later that with the increasing regularization parameter $\sigma_s$ and convex combination design of prox-center in \eqref{eq:xus_unconstrained}, the distance $\sigma_s\|x_s^* - \xu_s\|$ can be further bounded:
\begin{align}
	\label{eq:claim_on_distance_unconstrained}
	\sigma_s\|x_s^* - \xu_s\| \le \sigma_1\|x^* - x_0\| + \sum_{i=2}^s(\sigma_{i-1} + \sigma_i)\|x_{i-1}^* - x_{i-1}\|.
\end{align}

Therefore, $\|\nabla f(x_s)\|$ can be controled by
\begin{align}
	\label{eq:gradS_estimate_unconstrained}
	\|\nabla f(x_s)\| \le\ &  L\|x_s - x_s^*\| + \sigma_1\|x^* - x_0\| + \sum_{i=2}^s(\sigma_{i-1} + \sigma_i)\|x_{i-1}^* - x_{i-1}\|.
\end{align}
Note that the right-hand-side of the above estimate is the summation of terms of form $\|x_i - x_i^*\|$, i.e., the distance from an approximate solution $x_i$ to the optimal solution $x_i^*$ of the $i$-th strongly convex subproblem.
By studying the convergence properties of subroutine $\cA$ for minimizing smooth and strongly convex functions in subproblem \eqref{eq:subproblem_unconstrained}, we will then bound the total number of gradient evaluations needed to reduce the right-hand-side of the above estimate to the accuracy $\varepsilon$.

The above lemma allows us to design a backtracking function described in Algorithm~\ref{alg:_searchL}. Applying Lemma~\ref{thm:Mlemma} with $x = x_s$, $x^* = x_s^*$, $g = f_s$, $M=M_s+\sigma_s$, and $\eta = 2(M_s+\sigma_s)$, we conclude that whenever \eqref{eq:M} holds, 
we have $\|\nabla f_s(x_s)\|\le 2\sqrt{2}(M_s+\sigma_s)\|x_s - x_s^*\|$. As a consequence,
\begin{align}
	\label{eq:xs_norm_bound_unconstrained_est}
	\begin{aligned}
		& \|\nabla f(x_s)\| = \|\nabla f_s(x_s) - \sigma_s(x_s - \xu_s)\| 
		=  \|\nabla f_s(x_s) - \sigma_s(x_s - x_s^*) - \sigma_s(\xu_s-x_s^*)\| 
		\\
		\le &  (2\sqrt{2}M_s+(2\sqrt{2}+1)\sigma_s)\|x_s - x_s^*\| + \sigma_s\|x_s^* - \xu_s\|,
	\end{aligned}
\end{align}
which is analogous to the gradient-to-distance relation \eqref{eq:xs_norm_bound_unconstrained} but with $L$ replaced by $M_s$.
Apparently, we can apply one single gradient descent step with backtracking, i.e., Algorithm~\ref{alg:_searchL} with input $g=f_s$, $\sigma =\sigma_s$, $x= x_s$ and initial guess $M_0$, to estimate the local Lipschitz constant $M_s$.

\begin{align}
	\label{eq:xs_norm_bound_unconstrained_est}
	\begin{aligned}
		& \|\nabla f(x_s)\| = \|\nabla f_s(x_s) - \sigma_s(x_s - \xu_s)\| 
		=  \|\nabla f_s(x_s) - \sigma_s(x_s - x_s^*) - \sigma_s(\xu_s-x_s^*)\| 
		\\
		\le &  (2\sqrt{2}M_s+(2\sqrt{2}+1)\sigma_s)\|x_s - x_s^*\| + \sigma_s\|x_s^* - \xu_s\|,
	\end{aligned}
\end{align}

The basic problem of interest in this paper is to compute an
approximate stationary point $\hat x$ to  
the unconstrained optimization problem
\begin{equation} \label{eq:basic_problem}
	f^* = \min_{x\in\R^n}f(x),
\end{equation}

\begin{algorithm}[h]
	\caption{\label{alg:proposed_unconstrained} An accumulative regularization method for gradient minimization}
	\begin{algorithmic}
		\Require Total number of subproblems $S$, strictly increasing regularization parameters $\{\sigma_s\}_{s=0}^{S}$ with $\sigma_0=0$, and initial point $x_0\in\R^n$. \State Set initial prox-center to $\xu_0 := x_0$.
		\For {$s=1,\ldots, S$}
		\State Set
		\begin{align}
			\label{eq:xus_unconstrained}
			\xu_s = (1-\gamma_s) \xu_{s-1} + \gamma_s x_{s-1}\text{ with }\gamma_s =1 - \sigma_{s-1}/\sigma_s.
		\end{align}
		\State Compute an approximate solution $x_s$ of the proximal mapping subproblem
		\begin{align}
			\label{eq:subproblem_unconstrained}
			x_s^*:=\argmin_{x\in \R^n} \{f_s(x):=f(x) + \frac{\sigma_s}{2}\|x - \xu_s\|^2\}
		\end{align}
		by running subroutine $\cA(f, \sigma_s, \xu_s, x_{s-1}, N_s)$ with $N_s$ gradient evaluations of $\nabla f$ and initial point $x_{s-1}$.
		\EndFor
		\State Output $x_S$.
	\end{algorithmic}
\end{algorithm}

In this section, we show that the accumulative regularization technique we introduce in the previous section can be adapted to problems with constrained feasible sets, and (nested) composite objective function. We consider the problem with simple feasible set $X$ and composite function $\phi$:
\begin{align}
	\label{eq:problem} \min_{x\in X}\{ F(x):=f(x) + \phi(x)\}.
\end{align}

\begin{align}
	\label{eq:xpp}
	x^{++}(\eta, \sigma, \xu; x):=\argmin_{u\in X}\langle \nabla f(x), u\rangle + \phi(u) + \frac{\sigma}{2}\|u - \xu\|^2 + \frac{\eta}{2}\|u - x\|^2.
\end{align}

Clearly, $x^*$ is an optimal solution of \eqref{eq:problem} if and only if the \emph{projected gradient} $G_\eta(x^*) = 0$ for some $\eta>0$, where
\begin{align}
	\label{eq:G}
	G_{\eta}(x) :=\ & \eta(x - x^+(\eta;x))\text{ and }
	\\
	\label{eq:xp}
	x^+(\eta;x):=\ &x^{++}(\eta, 0, x;x) = \argmin_{u\in X}\langle\nabla f(x), u\rangle + \phi(u) + \frac{\eta}{2}\|u - x\|^2\ \forall x\in \R^n.
\end{align}

\begin{algorithm*}[h] 
	\caption{$M$=Backtracking($g$, $\sigma$, $x$, $M_0$) \label{alg:_searchL}}
	\begin{algorithmic}
		\For{$j=0,1,\ldots,$}
		\State Set
		$			\xpp = x - ({1}/{(2(M_j + \sigma))})\nabla g(x).
		$
		\State If 
		\begin{align}
			\label{eq:linesearch_estL_success_criterion}
			g(\xpp) - g(x) - \langle \nabla g(x), \xpp - x\rangle \le ({(M_j + \sigma)}/{2})\|\xpp - x\|^2, 
		\end{align}
		then {\bf terminate} with $M=M_j$. Otherwise, set $M_{j+1} = 2M_{j}$. 
		\EndFor
	\end{algorithmic}
\end{algorithm*}

\begin{algorithm}[!h]
	\caption{\label{alg:proposed_unconstrained_searchL} Accumulative regularization (AR) without the knowledge of $L$}
	\begin{algorithmic}
		\Function{$(\hat x, M)=\ $AR}{$f, x_0, \sigma_1, M_0$}
		\State Set the initial prox-center $\xu_0 = x_0$, and denote $\sigma_0=0$.
		\For {$s=1,2,\ldots$}
		\State If $s>1$, then set $\sigma_s=4\sigma_{s-1}$.
		\State Set $\xu_s =  (1-\gamma_s) \xu_{s-1} + \gamma_s x_{s-1}$ with $\gamma_s=1 - \sigma_{s-1}/\sigma_s$.

		\State Compute an approximate solution $x_s\in \R^n$ of
		\begin{align}
			\label{eq:subproblem_unconstrained_searchL}
			x_s^*:=\argmin_{x\in \R^n} \{ f_s(x):=f(x) + \dfrac{\sigma_s}{2}\|x - \xu_s\|^2\}
		\end{align}
		by running subroutine $x_s = \cA(f, \sigma_s, \xu_s, x_{s-1})$ with initial point $x_{s-1}$. 

		\State Set $M_s=$ Backtracking ($f_s$, $\sigma_s$, $x_s$, $M_{s-1}/2$).
		\State If $\sigma_s\ge M_s$, then {\bf terminate} with $\hat x=x_s$ and $M=M_s$ . 
		\EndFor
		\EndFunction
	\end{algorithmic}
\end{algorithm}

\begin{assumption}
	\label{assum:A_unconstrained_searchL}
	The subroutine $x_s =\cA(f, \sigma_s, \xu_s, x_{s-1})$ has the following performance guarantees after the $k$-th gradient evaluation of $\nabla f$:
	\begin{align}
		\label{eq:A_cond_unconstrained_searchL}
		f_s(x_s^k) - f_s(x_s^*) \le ({L_s^k}/{k^2})\|x_{s-1} - x_s^*\|^2.
	\end{align} 
	Here $x_s^k$ is the computed approximate solution and $L_s^k$ is an estimate of Lipschitz constant $L$ such that $L_s^k\le c_\cA L$, where $c_\cA$ is a universal constant that depends on algorithm $\cA$. 
	Subroutine $\cA$ will terminate whenever $k\ge 8\sqrt{2L_s^k/\sigma_s}$ and output the approximate solution $x_s = x_s^k$.
\end{assumption}

\begin{algorithm}[h]
		\caption{\label{alg:proposed_SCAR_noflag} A parameter-free strongly convex accumulative regularization (SCAR) algorithm}
		\begin{algorithmic}
			\Function{($\hat x$, $\hat M$) = SCAR}{$f$, $\varepsilon$, $y_0$, $\mu_0$, $M_0$}
			\For {$t=1,2,\ldots$}
			\State Set
			$
			(y_{t},M_{t}) = \text{AR}(f, y_{t-1}, \mu_{t-1}/10, M_{t-1})
			$ (see Algorithm~\ref{alg:proposed_unconstrained_searchL}).
			\State If {$\|\nabla f(y_t)\|>\|\nabla f(y_{t-1})\|/2$}, then set $\mu_t = \mu_{t-1}/4$ and $y_t = y_{t-1}$. 		
			\State If $\|\nabla f(y_{t})\|\le \varepsilon$, then \textbf{terminate} with $\hat x = y_{t}$ and $\hat M = M_t$.\EndFor
			\EndFunction
		\end{algorithmic}
	\end{algorithm}

