\begin{lemma}\label{lemma:mon_G} \em Suppose $\eta > 0$ and $\{\gamma_k\}$ is a diminishing sequence. Then, for any $\x$ and $k \geq 0$, $\| G_{\eta,1/\gamma_k} (\x)\| \, \leq \,\| G_{\eta,1/\gamma_{k+1}} (\x)\|$. 
				\end{lemma}

\begin{lemma}[{\bf Bias and moment properties of ${\bf e}$}] \label{lem:stoch_error_var}\em
					%Consider Definition \ref{def:stoch_errors}. 
					Let Assumptions \ref{ass-1} and \ref{assum:random_vars} hold. Then (i) and (ii) hold a.s. for $k\geq 0$, $N_k \geq 1$, and $j = 1, \hdots, N_k$.

					\noindent (i) $\mathbb{E}[\mathbf{e}_{j,k}\mid \mathcal{F}_k] = 0$;  \noindent (ii) $\mathbb{E}[\|\mathbf{e}_{k}\|^2\mid \mathcal{F}_k] \leq  \tfrac{16\sqrt{2\pi} L_0^2 n}{N_k}$.
				\end{lemma}

\begin{proof}
						(i) To show the conditional unbiasedness of $\mathbf{e}_{j,k}$, we proceed as follows.
						\begin{align*}
							\mathbb{E}_{\bxi,\! \vv}\left[ {g_{\eta}(\x_k,\!\vv_{j,k},\!\bxi_{j,k})}  \mid {\cal F}_k\right]\! & =\mathbb{E}_{\vv}\!   
							\left[\mathbb{E}_{\bxi}\left[ \tfrac{n(\f(\x_k+v_{j,k},\xi_{j,k})-\f(\x_k-v_{j,k},\xi_{j,k}))v_{j,k}}{2\eta \|v_{j,k}\|} \hspace{-0.05in} \mid {\cal F}_k \cup \{v_{j,k}\} \right] \right] \\
							&\hspace{-1in}  \overset{\tiny \mbox{Lemma~\ref{lemma:props_local_smoothing}~{(i)}}}{=}
							\mathbb{E}_{\vv}\left[ \tfrac{n}{2\eta}\tfrac{(f(\x_k+v_{j,k})-f(\x_k\lm{-}v_{j,k}))v_{j,k}}{\|v_{j,k}\|} \mid {\cal F}_k \right]  = \nabla_{\x} f_{\eta}(\x_k).    
						\end{align*} 
						By leveraging Lemma~\ref{lemma:props_local_smoothing}~{(v)}, we have that 
						\begin{align*}
							\mathbb{E}_{{\bxi, \vv}}\left[\, \|\mathbf{e}_{j,k}\|^2 \mid {\cal F}_k \, \right] &= 
							\mathbb{E}_{{\bxi}}\left[\, \mathbb{E}_{ {\vv}}\left[\, \|\mathbf{e}_{j,k}\|^2  \, \mid{\cal F}_{k}\cup\{\xi_{j,k}\} \right] \right]\\
							& \le 
							\mathbb{E}_{{\bxi}}\left[\, 16\sqrt{2\pi}\tilde{L}_0(\bxi_{{j,k}})^2n \right] \le 16\sqrt{2\pi} L_0^2 n. 
						\end{align*}
						It follows that $\mathbb{E}\left[\, \|\mathbf{e}_{k}\|^2  \, \mid {\cal F}_k\right] \le \tfrac{16\sqrt{2\pi} L_0^2 n}{N_k}.$
				\end{proof}

\begin{lemma}\label{lemma:zog_ineq}\em 
					Let Assumption \ref{ass-1} hold {and suppose} $\left\{\x_k\right\}$ is generated by
					Algorithm~\ref{algorithm:zo_nonconvex}. Let $\{\gamma_k\}$ be a
					non-increasing stepsize sequence (e.g., constant or diminishing) where
					$\gamma_0 \in (0,{\tfrac{\eta}{{\sqrt{n}}L_0}})$ for $\eta>0$. Then  the
					following hold. 

					\noindent (i) For $k\geq 0$, we have 
					\begin{align}\label{eqn:recursive_ineq_lemma5} 
						\left( 1-\tfrac{{\sqrt{n}}L_0\gamma_k}{\eta}\right)\tfrac{\gamma_k \|G_{\eta,1/\gamma_0} (\x_k)\|^2}{4}     &   \leq   f_{\eta}(\x_k)-      f_{\eta}(\x_{k+1}) 
						+{\left( 1-\tfrac{{\sqrt{n}}L_0\gamma_k}{2\eta}\right)} \gamma_k \|e_k\|^2.
					\end{align}

					\noindent (ii) Let $R_{\ell,K}$ be a random integer taking values in $\{\ell, \ldots, K-1\}$ with mass function $\mathbb{P}{[} R_{\ell,K} = j {]} = \tfrac{\gamma_j}{\sum_{i=\ell}^{K-1} \gamma_i}$ for any $j \in \{\ell, \ldots, K-1\}$.  Then, for all $k\geq 0$ we have 
					\begin{align}\label{ineq:residual_map_ineq_VRGZO_2}
						\mathbb{E}\left[ \|G_{\eta,{1/\gamma_0}} (\x_{R_{\ell,K}})\|^2\right]
						&\leq 
						\tfrac{\left( \mathbb{E}\left[f(\x_{\ell})\right] -f^* +2L_0\eta+ \left({16 \sqrt{2\pi} L_0^2{n} }\right)\sum_{k=\ell}^{K-1} \tfrac{\gamma_k}{N_k}\right)}{\left(\left( \tfrac{1}{4}-\tfrac{{\sqrt{n}} L_0\gamma_0}{4\eta}\right) \sum_{k=\ell}^{K-1} \gamma_k\right)} .
					\end{align}
				\end{lemma}

\begin{proof}
					(i) From Lemma~\ref{lemma:props_local_smoothing} (iv), the gradient mapping $\nabla f_\eta$ is Lipschitz continuous with the parameter $L_{\eta}\triangleq \tfrac{\sqrt{n}L_0}{\eta}$. From the descent lemma, 
					\begin{align}\label{eqn:descent_lem_proof_eq1}
					\notag	f_{\eta}(\x_{k+1}) & \leq f_{\eta}(\x_{k}) + \nabla f_{\eta}(\x_k)^\top(\x_{k+1}-\x_k)
						+\tfrac{L_{\eta}}{2}\|\x_{k+1}-\x_k\|^2\\
					\notag	&=f_\eta(\x_k) + \left(\nabla f_{\eta}(\x_k)+{e_k}\right)^\top(\x_{k+1}-\x_k)\\
		& -{e_k}^\top(\x_{k+1}-\x_k)+\tfrac{L_{\eta}}{2}\|\x_{k+1}-\x_k\|^2.
					\end{align}
