{\bbl See Appendix~\ref{th41}.}
\end{proof}

\begin{theorem}\cite[Theorem~2]{blanchet2016convergence}\label{theorComplexity1}
Under Assumption~\ref{assumptionRenewal}, 
$\E{\Tepsilon}\leq \frac{q}{2q-1}\cdot\frac{\PhiZero}{\varrho h\left(\depsilon\right)}+1.$
\end{theorem}

As in~\cite{blanchet2016convergence,dzahini2020expected,DzaWildSub2022,paquette2018stochastic}, the occurrence of the event $\accolade{\Tepsilon=k}$ is determined by observing $\left(\PhiZero,\Dzero,\WtildeZero\right),\dots,\left(\Phikmun,\Dkmun,\Wtildekmun\right)$, which means that~$\Tepsilon$ is a stopping time for the stochastic process generated by Algorithm~\ref{algoStoDARS}, and hence with respect to the filtration $\accoladekinN{\mathcal{H}_k}:=\accoladekinN{\falgebra}$. Bounding $\E{\Tepsilon}$ by applying Theorem~\ref{theorComplexity1} requires showing next that Assumption~\ref{assumptionRenewal} is satisfied for Algorithm~\ref{algoStoDARS}.

Regarding Assumption~\ref{assumptionRenewal} {\it (i)} and~{\it (iii)}, the arguments are basically those in~\cite{dzahini2020expected} and~\cite{DzaWildSub2022}, respectively. More precisely,~{\it (i)} is trivially satisfied for $\lambda:=-\log(\tau)$ while, on the other hand, it follows from~\eqref{PhikDynamics} and the inclusion $\falgebra\subset\fqdalgebra$ that almost surely
\begin{equation}\label{tower1}
\E{\Phikun-\Phik|\falgebra}=\E{\E{\Phikun-\Phik|\fqdalgebra}|\falgebra}\leq \E{-\varrho\Dk^2|\falgebra}=-\varrho\Dk^2.
\end{equation}
This shows that~{\it (iii)} is satisfied with the function $h:\scalebox{0.75}{$\vartheta$}\mapsto\scalebox{0.75}{$\vartheta$}^2$ since~\eqref{tower1} holds for any realization of the random variable $\E{\Phikun-\Phik|\falgebra}$, and hence on the event $\accolade{\Tepsilon>k}$ in particular.


\begin{lemma}\label{AkLemma1}
Let Assumption~\ref{QkHaarAssumpt} hold, and consider ${\ubar{\hat{\di}}^p_k}:=\hat{\di}^p_k({\footnotesize{\X}},\qrandom,\drandom)\in\argmax\accolade{-\nabla f(\Xk)^{\top}\left(\QkRandom\diRandom\right):\diRandom\in\pollDrandom_k}$. Then the event $A_k$ defined in~\eqref{AkEventDef} satisfies $\prob{A_k|\falgebra}=\E{\iak|\falgebra}\geq 1-\beta_Q$ almost surely.
\end{lemma}

\begin{proof}
By construction, $\nabla f(\Xk)$ is $\falgebra$-measurable while $\QkRandom$ and $\pollDrandom_k$ are independent of $\falgebra$. The conditions of Proposition~\ref{propKappaD2} are therefore satisfied, and the result straightforwardly follows from~\eqref{kdprob2prime}.
\end{proof}

\begin{lemma}\label{smallLemmaHaar}
Let Assumptions~\ref{QkHaarAssumpt},~\ref{kapminAssump} and~\ref{gradLipAssump} hold, and assume that $\dk\leq \depsilon$. Let $\fok$ and $\fuk$ be $\ef$-accurate estimates of $f(\xk)$ and  $f(\xk+\dk\ub)$, respectively. Assume that the event $A_k$ occurs. If $\normii{\nabla f(\xk)}>\epsilon$, then there exists $\ub\in \mathbb{U}_k^n:=\{\Ukp\di^p:\di^p\in \pollD_k\}$ such that $\fuk-\fok\leq -\gamma\ef\dk^2$; that is, the iteration $k$ is successful. 
\end{lemma}

\begin{proof}
{\bbl See Appendix~\ref{lem52}.}
\end{proof}

\begin{lemma}\label{dynamicsLemma}
{\bl Let Assumption~\ref{QkHaarAssumpt} hold with $0<\beta_Q<1-\frac{1}{2\beta_f}$ and let Assumptions~\ref{QkHaarAssumpt},~\ref{efkfAssump},~\ref{boundedFassumpt},~\ref{kapminAssump}, and~\ref{gradLipAssump} hold.}
%and all assumptions made in Theorem~\ref{zerothOrdTheor} hold. 
Then Assumption~\ref{assumptionRenewal}-$(ii)$ is satisfied for $\Wtildek:=2\left(\iak\ijk-\frac{1}{2}\right)$, with $\lambda=-\log(\tau)$ and some fixed $q\in (\tilde{\beta}, 1)$, where $\tilde{\beta}=\beta_f(1-\beta_Q)$.
\end{lemma}

\begin{proof}
The result is proved by suitably adapting the proof of~\cite[Lemma~7]{blanchet2016convergence}, as was also done in~\cite[Lemma~3]{dzahini2020expected}, \cite[Lemma~5.3]{DzaWildSub2022} and~\cite[Lemma~4.8]{paquette2018stochastic}. First, observe that~\eqref{dynamicsRenewal} trivially holds when $\itksup=0$. It is shown next that when $\itksup=1$ (which is assumed in the remainder of the proof), then 
\[\Dkun\geq \min\accolade{\depsilon, \min\accolade{\dmax,\tau^{-1}\Dk}\iak\ijk+\tau\Dk\left(1-\iak\ijk\right)}.\] 
Recall that $\dk=\tau^{i_k}\depsilon$ for some integer $i_k$ so that if $\dk>\depsilon$, then $\dk\geq \tau^{-1}\depsilon$, whence $\dkun\geq \tau\dk\geq \depsilon$. Next, assume that $\dk\leq \depsilon$, and observe that $\normii{\nabla f(\xk)}>\eps$ since $\Tepsilon>k$. If $\iak\ijk=1$, it follows from Lemma~\ref{smallLemmaHaar} that the iteration is successful. Consequently, $\dkun=\min\accolade{\tau^{-1}\dk,\dmax}$. But if $\iak\ijk=0$, then it always holds that $\dkun\geq \tau\dk$. The proof is completed by observing that $\prob{\iak\ijk=1|\falgebra}=q$ for some $q\geq\tilde{\beta}$.
\end{proof}

