\begin{lemma}\label{lemetab} 
Define 
 \begin{align}
	 s &:= \frac{x^- - x}{\lam}, \label{defsb}\\
	 \eta &:= \phi(y) - \Gamma(x) - \inner{s}{y- x}. \label{defetab}
	\end{align}

Then, the following statements hold:
\begin{itemize}
\item[a)]
  $s \in \partial \Gamma (x)$, i.e., for every $u \in \R^n$,
 \begin{equation}\label{eq:subdifb}
    \Gamma(u) \ge \Gamma(x) + \inner{s}{u-x}; 
 \end{equation}  
  \item[b)] $s \in \partial_{\eta} \phi(y)$ and
  \begin{equation}\label{ineqetab}
  0 \le 2 \lam \eta \le  2 \lam \varepsilon - 
	    \|y- x\|^2 + (1-\chi)\|y- x^-\|^2.
     \end{equation}
\end{itemize}
\end{lemma}

\begin{proof} 
 (a) The optimality condition of \eqref{defxhatk} yields $0 \in \partial \Gamma_k(x) +(x-x^-)/\lambda$, which together with the definition of $s$ in \eqref{defsb} implies that the inclusion in a) holds.
 Relation \eqref{eq:subdifb} immediately follows from the inclusion in a) and the definition of the subdifferential.

(b) The relation $\phi \geq \Gamma$ (see step 1 of FSCO), \eqref{eq:subdifb}, the definition of $\eta$ in \eqref{defetab} imply that for every $u\in \dom \phi$,
	\[
	\phi(u) \ge \Gamma(u) \stackrel{\eqref{eq:subdifb}}\ge  \Gamma(x) + \inner{s}{u- x}
      \stackrel{\eqref{defetab}}=  \phi(y) + \inner{s}{u- y} - \eta,
	\]
which yields the inclusion in b). 
Taking $u=y$ in the above inequality gives $\eta \ge 0$, and hence the first inequality in \eqref{ineqetab} holds.
Using the definitions of $s$ and $\eta$ in \eqref{defsb} and \eqref{defetab}, respectively, and \eqref{propyb} and \eqref{defxhatk}, we have
\[
\begin{array}{lcl}
    \eta &\stackrel{\eqref{defetab}}=& \displaystyle \phi(y) - \Gamma(x) - \inner{s}{y- x} \\
     & \stackrel{\eqref{propyb},\eqref{defxhatk}}{\le} &\displaystyle \left[ \varepsilon - \frac\chi{2\lam}\|y- x^-\|^2 + \frac{1}{2\lam}\|x- x^- \|^2 \right] - \inner{s}{y- x}\\
	    &\stackrel{\eqref{defsb}}{=} &  \displaystyle \varepsilon - \frac\chi{2\lam}\|y- x^-\|^2  +  \frac1{2\lam}\|x- x^-\|^2 + \Inner{\frac{x- x^-}{\lam}}{y- x} \\
     &=&\displaystyle  \varepsilon + \frac{1-\chi}{2\lam}
	    \|y- x^- \|^2 - \frac1{2\lam}
	    \|y- x\|^2.
	\end{array}
\]
Hence, the second inequality in \eqref{ineqetab} holds.
% (c) Since $\phi-\mu\|\cdot\|^2/2$ is convex, using the inclusion in part (b) and Lemma \ref{lem:app} with $\tau=(1-\zeta)/\zeta$ for $\zeta \in [0,1)$, we obtain
% \[
% \phi(u) \ge \phi(y) + \inner{s}{u- y} + \frac{\zeta \mu}{2} \|u- y\|^2 - \frac{\eta}{1-\zeta}.
% \]
% That is \eqref{qphi-1} with $\nu = 0$.
\end{proof}

\begin{lemma}\label{lem:zeta}
    Let $\mu=\mu_\phi$ and assume that $\Gamma \in \nConv{n}$ for some $\nu \in [0,\mu]$.
    For any $\zeta \in [0,1)$ and every $u\in \dom \phi$, we have
     \begin{equation}\label{qphi-1}
    \phi(u) \ge \phi(y) + \inner{s}{u- y} + \frac{\zeta (\mu-\nu)}{2} \|u- y\|^2 - \frac{\eta}{1-\zeta} + \frac{\zeta}{1-\zeta} \frac{\nu}{2}\|y - x\|^2 + \frac{\nu}{2}\|u - x\|^2,
	\end{equation}
    where $s$ and $\eta$ are as in \eqref{defsb} and \eqref{defetab}, respectively.
\end{lemma}

\begin{proof}
    Define
\begin{equation}\label{eq:tilde}
    \tilde s = s + \nu(x^- - x), \quad \tilde \eta = \eta - \frac{\nu}{2}\|y - x\|^2, \quad \tilde \phi = \phi - \frac{\nu}{2}\|\cdot - x^-\|^2, \quad \tilde \Gamma = \Gamma - \frac{\nu}{2}\|\cdot - x^-\|^2.
\end{equation}
It follows from Lemma \ref{lemetab}(a) and the above definitions of $\tilde s$ and $\tilde \Gamma$ that
$\tilde s \in \partial \tilde \Gamma(x)$.
In view of \eqref{eq:tilde} and the assumption that $\Gamma \in \nConv{n}$ for some $\nu \in [0,\mu]$, we observe that $\tilde \Gamma$ is convex and $\tilde \phi \ge \tilde \Gamma$.
Hence, following a similar argument as in Lemma~\ref{lemetab}(b), we conclude that
$\tilde s \in \partial_{\tilde \eta} \tilde \phi(y)$.
Using this inclusion, the fact that $\tilde \phi$ is 
$(\mu -\nu)$-convex, and Lemma \ref{lem:app} with $(\psi,\xi,y,v,\eta,Q)=(\tilde \phi, \mu-\nu,y,\tilde s, \tilde \eta,I)$, we have for any $\tau\in (0,\infty]$ and every $u\in \dom \phi$,
\[
\tilde \phi(u) \stackrel{\eqref{ineq:app}}\ge \tilde \phi(y) + \inner{\tilde s}{u- y} + \frac{\mu -\nu}{2(1+\tau)} \|u- y\|^2 -  (1+\tau^{-1}) \tilde \eta.
\]
Taking $\tau=(1-\zeta)/\zeta$ for $\zeta \in [0,1)$ in the above inequality, we obtain
\[
     \tilde \phi(u) \ge \tilde \phi(y) + \inner{\tilde s}{u- y} + \frac{\zeta (\mu -\nu)}{2} \|u- y\|^2 -   \frac{\tilde \eta}{1-\zeta}.
	\]
Finally, \eqref{qphi-1} follows from using the definitions of $\tilde \phi$, $\tilde s$, and $\tilde \eta$ in \eqref{eq:tilde}, and rearranging the terms in the above inequality.
\end{proof}

{\bf Proof of Proposition \ref{propouter}.}
It follows from the definition of $s$ in \eqref{defsb} and Lemma \ref{lem:zeta} with $\zeta =\chi$,
\begin{align}
&\|x^--u \|^2  - \|x-u\|^2 -\left(\|x^--y\|^2 - \|x-y\|^2\right) 
= -2\lam \inner{s}{u-y} \nn \\
\stackrel{\eqref{qphi-1}}\ge & 2 \lambda \left[\phi(y)- \phi(u)\right] + \chi (\mu -\nu) \lam \|u-y\|^2 -   \frac{2\lam \eta}{1-\chi} + \frac{\chi \nu \lam}{1-\chi} \|y - x\|^2 + \nu \lam\|u - x\|^2. \label{ineq:long}
\end{align}
Rearranging the terms in \eqref{ineq:long} and using Lemma \ref{lemetab}(b), we have
\begin{align}
&\left\|x^--u \right\|^2  - (1+\nu \lam)\|x-u\|^2  -2 \lambda \left[\phi(y)- \phi(u)\right] \nn \\
& \stackrel{\eqref{ineq:long}}\ge \|x^--y\|^2 + \left( \frac{\chi \nu \lam}{1-\chi} - 1 \right)\|x-y\|^2 + \chi (\mu -\nu) \lam \|u-y\|^2 -   \frac{2\lam \eta}{1-\chi} \nn \\
& \stackrel{\eqref{ineqetab}}\ge  -\frac{2 \lam \varepsilon}{1-\chi} + \frac{\chi(1+\nu \lambda)}{1-\chi} \|x-y\|^2 + \chi (\mu -\nu) \lam \|u-y\|^2. \label{ineq:imp}
\end{align}
Rearranging the terms in the above inequality, we have
\begin{align}
    2\lambda \left[\phi(y)- \phi(u)\right] \le& 
\frac{2 \lam \varepsilon}{1-\chi} + \left\|x^--u \right\|^2  - (1+\nu \lam)\|x-u\|^2 \nn \\
&- \chi \left(\frac{1+\nu \lam}{1-\chi} \|x-y\|^2 + (\mu -\nu) \lam \|u-y\|^2\right). \label{telescopic1}
\end{align}
Using the triangle inequality and the fact that $(a_1+a_2)^2 \le (b_1^{-1}+b_2^{-1}) (a_1^2 b_1 + a_2^2 b_2)$ with $(a_1,a_2) =(\|x-y\|,\|u-y\|)$ and $(b_1,b_2) =((1+\nu \lam)/(1-\chi), (\mu -\nu) \lam)$
we have
\begin{equation}\label{ineqxku}
    \|x-u\|^2 \le \left(\frac{1-\chi}{1+\nu \lam} + \frac{1}{(\mu -\nu)\lam}\right) \left(\frac{1+\nu \lam}{1-\chi} \|x-y\|^2 + (\mu -\nu) \lam \|u-y\|^2\right).
\end{equation}
Plugging the above inequality into \eqref{telescopic1}, we have
\[
2\lambda \left[\phi(y)-\phi(u)\right] 
\le   \frac{2 \lam \varepsilon}{1-\chi} +  
\left\|x^--u\right\|^2  - 
\left[ 1 + \nu \lam + \chi \left(\frac{1-\chi}{1+\nu \lam} + \frac{1}{(\mu -\nu)\lam}\right)^{-1} \right]
\|x-u\|^2,
\]
which is the same as \eqref{ineq:contraction} after simplification.
