    \end{equation*}

\begin{align*}
        \partial_\eps f(x) := \conv \left( \bigcup_{y \in \Bcl_\eps(x)} \partial f(y) \right),
    \end{align*}

where $\Bcl_\eps(x) := \{ y \in \R^n : \| y - x \| \leq \eps \}$ and $\| \cdot \|$ is the Euclidean norm. For $\eps, \delta \geq 0$ we say that $x$ is $(\eps,\delta)$\emph{-critical}, if $\min(\| \partial_\eps f(x) \|) \leq \delta$, i.e., if there is some $\xi \in \partial_\eps f(x)$ with $\|\xi \| \leq \delta$. Clearly, $(\eps,\delta)$-criticality is a weaker optimality condition than criticality. However, upper semicontinuity of $\partial f$ implies that if there are sequences $(x^j)_j \in \R^n$, $(\eps_j)_j, (\delta_j)_j \in \R^{\geq 0}$ with $x^j \rightarrow x^*$, $\eps_j \rightarrow 0$ and $\delta_j \rightarrow 0$ such that $x^j$ is $(\eps_j,\delta_j)$-critical for all $j \in \N$, then $x^*$ is critical (cf. Lemma 4.4.4 in \cite{G2022}). In addition to subdifferentials, we also require directional derivatives of $f$. To assure that they exist and are well-behaved, we occasionally assume that $f$ is \emph{semismooth} \cite{M1977}, which means that $f$ is locally Lipschitz continuous and for any $x \in \R^n$ and $d \in \R^n$, the limit
\begin{align} \label{eq:def_semismooth}
    \lim_{\xi \in \partial f(x + t d'), t \searrow 0, d' \rightarrow d} \langle \xi, d' \rangle
\end{align}
exists. If $f$ is semismooth, then for any $d \in \R^n$, the \emph{directional derivative}
\begin{align*}
    f'(x,d) = \lim_{t \searrow 0} \frac{f(x + t d) - f(x)}{t}
\end{align*}
exists and equals the limit \eqref{eq:def_semismooth}. A large class of semismooth functions are the \emph{piecewise $p$-times differentiable} functions \cite{S2012}, which are continuous functions $f : \R^n \rightarrow \R$ for which there are $p$-times continuously differentiable functions $f_1, \dots, f_m : \R^n \rightarrow \R$, called \emph{selection functions}, such that $f(x) \in \{ f_1(x), \dots, f_m(x) \}$ for all $x \in \R^n$. For such a function, the set $A(x) := \{ i \in \{1,\dots,m\} : f(x) = f_i(x) \}$ is called the \emph{active set}, and the Clarke subdifferential satisfies $\partial f(x) \subseteq \conv(\{ \nabla f_i(x) : i \in A(x) \})$.

\begin{definition} \label{def:order_minimum}
        A point $x^* \in \R^n$ is called a \emph{minimum of order} $p \in \N$ \emph{with constant} $\beta > 0$, if there is some open set $U \subseteq\R^n$ with $x^* \in U$ such that
        \begin{align*}
            f(x) \geq f(x^*) + \beta \| x - x^* \|^p \quad \forall x \in U.
        \end{align*}
    \end{definition}

\begin{align} \label{eq:p_order_min_semismooth}
        \liminf_{\xi \in \partial f(x^* + t d'), t \searrow 0, d' \rightarrow d} \frac{\langle \xi,  d' \rangle}{t^{p-1}} \geq \beta \| d \|^p \quad \forall d \in \R^n \setminus \{ 0 \}.
    \end{align}

\begin{proof}
        Assume that (i) or (ii) do not hold. Then in both cases there is a subsequence $(j_l)_l \in \N$ with $x^{j_l} \neq x^*$ for all $l \in \N$,
        \begin{align} \label{eq:proof_thm_xj_speed_higher_order_1}
            \lim_{l \rightarrow \infty} \frac{\eps_{j_l}}{\| x^{j_l} - x^* \|^{p}} = 0
            \quad \text{and} \quad
             \lim_{l \rightarrow \infty} \frac{\delta_{j_l}}{\| x^{j_l} - x^* \|^{p-1}} < \beta.
        \end{align}
        (In case (ii) does not hold, the second limit actually vanishes.) \\

\textbf{Step 1:} For $l \in \N$ let $g^l \in \partial_{\eps_{j_l}} f(x^{j_l})$ with $\| g^l \| \leq \delta_{j_l}$. By Carathéodory's theorem, for $i \in \{1,\dots,n+1\}$, there are $y_i^l \in \Bcl_{\eps_{j_l}}(x^{j_l})$, $\xi_i^l \in \partial f(y_i^l) \subseteq \partial_{\eps_{j_l}} f(x^{j_l})$ and $\alpha_i^l \geq 0$ with $\sum_{i = 1}^{n+1} \alpha_i^l = 1$ and
\begin{align*}
    g^l = \sum_{i = 1}^{n+1} \alpha_i^l \xi_i^l.
\end{align*}
Since $\| y_i^l - x^{j_l} \| \leq \eps_{j_l}$ it holds $\lim_{l \rightarrow \infty} y_i^l = x^*$ for all $i \in \{1,\dots,n+1\}$. By compactness of the $\eps$-subdifferential at $x^*$ (cf. \cite{G1977}, Proposition 2.3), we can assume w.l.o.g. that $\lim_{l \rightarrow \infty} \xi_i^l = \Bar{\xi}_i \in \R^n$ for all $i \in \{1,\dots,n+1\}$. By \cite{C1990}, Proposition 2.1.5, it follows that $\Bar{\xi}_i \in \partial f(x^*)$. Furthermore, by compactness of the set of convex coefficients, we can assume w.l.o.g. that $\lim_{l \rightarrow \infty} \alpha_i^l = \Bar{\alpha}_i$ for all $i \in \{1,\dots,n+1\}$, such that
\begin{align*}
    \Bar{g} := \sum_{i = 1}^{n+1} \Bar{\alpha}_i \Bar{\xi}_i \in \partial f(x^*)
\end{align*}
is the limit of $(g^l)_l$. (In case (ii) we have $\Bar{g} = 0$.) \\

\textbf{Step 2:} Consider the sequences $(d^l)_l$ and $(d_i^l)_l$ given by
\begin{align*}
    d^l := \frac{x^{j_l} - x^*}{\| x^{j_l} - x^* \|} \quad \text{and} \quad d_i^l := \frac{y_i^l - x^*}{\| x^{j_l} - x^* \|}, \ i \in \{1,\dots,n+1\}.
\end{align*}
By compactness, $(d^l)_l$ must have an accumulation point $\Bar{d} \in \R^n$ with $\| \Bar{d} \| = 1$. Assume w.l.o.g. that $\Bar{d}$ is the limit of $(d^l)_l$. 
For all $i \in \{1,\dots,n+1\}$, it holds
\begin{align*}
    \| d_i^l - d^l \| 
    = \frac{\| y_i^l - x^* - (x^{j_l} - x^*) \|}{\| x^{j_l} - x^* \|}
    = \frac{\| y_i^l - x^{j_l} \|}{\| x^{j_l} - x^* \|}
    \leq \frac{\eps_{j_l}}{\| x^{j_l} - x^* \|},
\end{align*}
and combined with \eqref{eq:proof_thm_xj_speed_higher_order_1}, we obtain
\begin{align} \label{eq:proof_thm_xj_speed_higher_order_2}
    \frac{\| d_i^l - d^l \|}{\| x^{j_l} - x^* \|^{p-1}} \leq \frac{\eps_{j_l}}{\| x^{j_l} - x^* \|^{p}} \xrightarrow[]{l \rightarrow \infty} 0.
\end{align}
In particular, $\lim_{l \rightarrow \infty} d_i^l = \bar{d}$ for all $i \in \{1,\dots,n+1\}$.\\

\textbf{Step 3:} By construction we have 
\begin{align*}
    \xi_i^l \in \partial f(y_i^l) 
    = \partial f \left( x^* + \| x^{j_l} - x^* \| \frac{y_i^l - x^*}{\| x^{j_l} - x^* \|} \right) 
    = \partial f(x^* + \| x^{j_l} - x^* \| d_i^l).
\end{align*}
Assume w.l.o.g. that $x^{j_l} \in U$ with $U$ as in Definition \ref{def:order_minimum}. Combination of \eqref{eq:p_order_min_semismooth} and \eqref{eq:proof_thm_xj_speed_higher_order_2} (and boundedness of $(\xi_i^l)_l$) yields
\begin{equation}
    \begin{aligned} \label{eq:proof_thm_xj_speed_higher_order_3}
        \liminf_{l \rightarrow \infty} \frac{\langle \xi_i^l, d^l \rangle}{\| x^{j_l} - x^* \|^{p-1}}
        &= \liminf_{l \rightarrow \infty} \left( \frac{\langle \xi_i^l, d_i^l \rangle}{\| x^{j_l} - x^* \|^{p-1}} + \frac{\langle \xi_i^l, d^l - d_i^l \rangle}{\| x^{j_l} - x^* \|^{p-1}} \right)\\
        &\stackrel{\eqref{eq:proof_thm_xj_speed_higher_order_2}}{=} \liminf_{l \rightarrow \infty} \frac{\langle \xi_i^l, d_i^l \rangle}{\| x^{j_l} - x^* \|^{p-1}} 
        \stackrel{\eqref{eq:p_order_min_semismooth}}{\geq} \beta \| \Bar{d} \|^p = \beta
    \end{aligned}
\end{equation}

for all $i \in \{1,\dots,n+1\}$. Furthermore note that
\begin{equation} \label{eq:proof_thm_xj_speed_higher_order_5}
    \begin{aligned}
        \delta_{j_l}
        &\geq \| g^l \| 
        = \left\| \sum_{i = 1}^{n+1} \alpha_i^l \xi_i^l \right\|
        = \left\| \sum_{i = 1}^{n+1} \alpha_i^l \xi_i^l \right\| \| d^l \| \\
        &\geq \langle \sum_{i = 1}^{n+1} \alpha_i^l \xi_i^l, d^l \rangle
        = \sum_{i = 1}^{n+1} \alpha_i^l \langle \xi_i^l, d^l \rangle \quad \forall l \in \N.
    \end{aligned}
\end{equation}

    Division of \eqref{eq:proof_thm_xj_speed_higher_order_5} by $\| x^{j_l} - x^* \|^{p-1}$ and combination with \eqref{eq:proof_thm_xj_speed_higher_order_1} and \eqref{eq:proof_thm_xj_speed_higher_order_3} yields
    \begin{equation*}
        \begin{aligned}
            \beta 
            &\stackrel{\eqref{eq:proof_thm_xj_speed_higher_order_1}}{>} \liminf_{l \rightarrow \infty} \frac{\delta_{j_l}}{\| x^{j_l} - x^* \|^{p-1}}
            \stackrel{\eqref{eq:proof_thm_xj_speed_higher_order_5}}{\geq} \liminf_{l \rightarrow \infty} \frac{ \sum_{i = 1}^{n+1} \alpha_i^l \langle \xi_i^l, d^l \rangle}{\| x^{j_l} - x^* \|^{p-1}} \\
            &= \liminf_{l \rightarrow \infty} \sum_{i = 1}^{n+1} \alpha_i^l \frac{\langle \xi_i^l, d^l \rangle}{\| x^{j_l} - x^* \|^{p-1}}
            \geq \sum_{i = 1}^{n+1} \liminf_{l \rightarrow \infty} \alpha_i^l \frac{\langle \xi_i^l, d^l \rangle}{\| x^{j_l} - x^* \|^{p-1}} \\
            &\stackrel{\eqref{eq:proof_thm_xj_speed_higher_order_3}}{\geq} \sum_{i = 1}^{n+1} \Bar{\alpha}_i \beta = \beta,
        \end{aligned}
    \end{equation*}
    which is a contradiction.
\end{proof}

