    \hspace{.2em} Section~\ref{sec:jacobian_online_learning}}}
    %
  \end{algorithm}

\begin{align}
    \|{\hat{\vz}_k}-\vz_k+{\eta_k}(\vF(\vz_k)+\mB_k({\hat{\vz}_k}-\vz_k))\| &\leq {\alpha_1} \sqrt{1+\eta_k \mu} \|\hat{\vz}_k-\vz_k\|, \label{eq:inexact_linear_solver} \\
    \|\hat{\vz}_k - \vz_k + \eta_k \vF(\hat{\vz}_k)\| &\leq {(\alpha_1+\alpha_2) \sqrt{1+\eta_k \mu} \|{\hat{\vz}_k}-\vz_k\|} \label{eq:inexact_proximal_point}, 
%
\end{align}

\begin{equation}\label{eq:extragradient_mixing}
%
  \vz_{k+1} = \theta_k(\vz_k - \eta_k \vF(\hat{\vz}_k))+(1-\theta_k)\hat{\vz}_k,
\end{equation}

\begin{algorithmic}[1]
      \STATE \textbf{Input:} iterate $\vz \in \mathbb{R}^d$,  operator $\vg\in \reals^d$,  Jacobian approximation $\mB$, initial trial step size $\sigma>0$
      \STATE \textbf{Parameters:} line search parameters $\beta\in (0,1)$, $\alpha_1\geq 0$ and $\alpha_2>0$ such that $\alpha_1+\alpha_2<1$
      %
      \STATE Set ${\eta}_{+} \leftarrow \sigma$, {$\vs_{+} \leftarrow \mathsf{LinearSolver}(\mI+\eta_{+}\mB, -\eta_{+}\vg; {\alpha_1}\sqrt{1+\eta_+ \mu})$ and $\hat{\vz}_{+} \leftarrow \vz+\vs_{+}$}
      \WHILE{$\|\hat{\vz}_+ - \vz + \eta_+ \vF(\hat{\vz}_+)\| \geq (\alpha_1+\alpha_2)\sqrt{1+\eta_+ \mu} \|{\hat{\vz}_{+}}-\vz\|$\label{line:check_condition}}
        \STATE Set $\tilde{\vz} \leftarrow \hat{\vz}_{+}$ %
          and $\eta_{+} \leftarrow \beta\eta_+ $ \label{line:decreasing_stepsize}
      \STATE Compute $\vs_{+} \leftarrow \mathsf{LinearSolver}(\mI+\eta_{+}\mB, -\eta_{+}\vg; \alpha_1\sqrt{1+\eta_+ \mu})$ and $\hat{\vz}_{+} \leftarrow \vz+\vs_{+}$
      \ENDWHILE
      \IF{$\eta_+ = \sigma$}
      \STATE \textbf{Return} $\eta_{+}$ and  $\hat{\vz}_{+}$ \label{line:return_1}
      \ELSE 
      \STATE \textbf{Return} $\eta_{+}$, $\hat{\vz}_{+}$ and $\tilde{\vz}$ \label{line:return_2}
      \ENDIF
  \end{algorithmic}

\begin{equation}\label{eq:linear_solver_update}
  \vs_{+} = \mathsf{LinearSolver}(\mI+\eta_{+}\mB, -\eta_{+}\vg; {\alpha_1}\sqrt{1+\eta_+ \mu}) \quad \text{and} \quad \hat{\vz}_{+} = \vz+\vs_{+},
  %
\end{equation}

\begin{equation}\label{eq:loss_of_jacobian}
  \ell_k(\mB) \triangleq 
  \begin{cases}
    0, & \text{if } k\notin \mathcal{B}, \\
    \frac{\|\vu_k-\mB\vs_k\|^2}{\|\vs_k\|^2}, & \text{otherwise}.
  \end{cases}
  %
\end{equation}

\begin{equation}\label{eq:feasible_set_min}
    \calZ = \{\mB \in \sS^d: \; \mu \mI \preceq \mB \preceq L_1 \mI,\; \mB \in \calL\},
  \end{equation}

\begin{equation}\label{eq:feasible_set}
    \mathcal{Z} = \left\{ \mB \in \reals^{d\times d}:\mu \mI \preceq \frac{1}{2}(\mB + \mB^\top )\preceq L_1\mI , \;\|\mB\|_{\op} \leq L_1, \mB \in \mathcal{L} \right\},
    %
  \end{equation}

To set the stage for our Jacobian approximation update algorithm, we take a detour and consider a general online learning problem over a compact feasible set $\calC \subset \reals^D$. For $T$ consecutive rounds $t=0,\dots,T-1$, a learner chooses an action $\vx_t \in \reals^D$ and then observes a convex loss function $\ell_t:\reals^D \rightarrow \reals$. 
\blue{The goal is to minimize either the \emph{static regret} defined by $\mathrm{Reg}_T(\vu; \calC) \triangleq \sum_{t=0}^{T-1} \ell_t(\vx_t) - \sum_{t=0}^{T-1} \ell_t(\vu)$ with a fixed competitor $\vx \in \calC$, or the \emph{dynamic regret} defined by $\dreg_T(\vu_0,\dots,\vu_{T-1}; \calC) \triangleq \sum_{t=0}^{T-1} \ell_t(\vx_t) - \sum_{t=0}^{T-1} \ell_t(\vu_t)$ with a sequence of competitors $\vu_t \in \calC$ for any $t \geq 0$.}
We assume $0\in \mathcal{C}$ without loss of generality. Moreover, we assume that the set $\calC$ is contained in the Euclidean ball $B_R(0):= \{\vw\in \reals^D: \|\vw\|\leq R\}$ for some radius $R>0$.

\begin{definition}\label{def:gauge}
  Let $\calC$ be a compact convex set in $\reals^D$ containing the origin. 
  The oracle $\mathsf{SEP}_{\mathcal{C}}(\vw; \delta)$ takes $\vw\!\in\! \vspan(\calC)$ and $\delta>0$ and returns $\gamma>0$ and a vector $\vs\in \vspan(\calC)$ with one of these outcomes:
   %
   %
    \begin{itemize}
      \item Case I: $\gamma \leq 1$, which implies that $\vw \in (1+\delta)\mathcal{C}$;
       %
      \item Case II: $\gamma>1$, which implies that $\vw/\gamma \in (1+\delta)\mathcal{C} \ $ and $\ \langle \vs, \vw-\vx \rangle \geq {\gamma-1},$  $ \forall\vx\in \mathcal{C}$. 
    \end{itemize}
    %
    %
    %
    %
    %
    \end{definition}

\begin{equation}\label{eq:w_update}
  \vw_{t+1}  = \mathrm{\Pi}_{\mathcal{B}_R(0)}\bigl(\vw_t-\rho \nabla \tilde{\ell}_t(\vw_t)\bigr) = \frac{R}{\max\{\|\vw_t-\rho \tilde{\vg}_t\|_2,R\}} (\vw_t-\rho \tilde{\vg}_t).
\end{equation}

\begin{definition}\label{def:MaxSvec}
  The oracle $\mathsf{MaxSvec}(\mW;\delta,q)$ takes $\mW \in \mathbb{R}^{d\times d}$, $\delta>0$, and $q\in (0,1)$ as input and returns a scalar $\gamma>0$ and a matrix $\mS\in \mathbb{R}^{d\times d}$. With probability at least $1-q$, the returned $\gamma$ and $\mS$ satisfy one of the following properties::
  %
  \begin{itemize}
    \item Case I: $\gamma \leq 1$, which implies that $ \|\mW\|_{\op} \leq 3(1+\delta) $;
    %
    \item Case II: $\gamma>1$, which implies that $ \|\mW/\gamma \|_{\op} \leq 3(1+\delta)$, $\|\mS\|_F \leq 1$ and $\langle \mS,\mW-\hat{\mB}\rangle \geq \gamma -1$ for any $\hat{\mB} \in \reals^{d\times d}$ such that $ \|\hat{\mB}\|_{\op}  \leq 3 $.
  \end{itemize}
\end{definition}

\begin{algorithmic}[1]
      \STATE \textbf{Input:} $\mW \in \reals^{d\times d}$, $\delta>0$, $q\in (0,1)$
      \STATE \textbf{Initialize:} sample $\vv_1\in \reals^d$ uniformly from the unit sphere, $\beta_1 \leftarrow 0$, $\vv_0\leftarrow 0$
      \STATE Set $\bar{\mW} \leftarrow \frac{1}{2}(\mW + \mW^\top)$ and set the number of iterations 
      $N \leftarrow \Bigl\lceil\frac{1}{4}\sqrt{2(1+\frac{1}{\delta})}\log(\frac{11d}{q^2})+\frac{1}{2} \rceil$
      %
      %
      %
      %
      \FOR{$k=1,\dots,N$ \tikzmark{top}}
      \STATE Set $\vw_k \leftarrow \bar{\mW} \vv_k-\beta_k \vv_{k-1}$ 
      \STATE Set $\alpha_k \leftarrow \langle \vw_k,\vv_k \rangle $ and $\vw_k \leftarrow \vw_k-\alpha_k\vv_k$
      \STATE Set $\beta_{k+1} \leftarrow \|\vw_k\|$ and $\vv_{k+1}\leftarrow \vw_k/\beta_{k+1}$
      \ENDFOR
    \STATE Form a tridiagonal matrix $\mT \leftarrow \mathsf{tridiag}(\beta_{2:N},\alpha_{1:N},\beta_{2:N})$
    \STATE \hspace{-1em}\COMMENT{Use the tridiagonal structure to compute eigenvectors of $\mT$}
    \STATE Compute $(\hat{\lambda}_1,\vz^{(1)}) \leftarrow \mathsf{MaxEvec}(\mT)$ and $(\hat{\lambda}_d, \vz^{(d)}) \leftarrow \mathsf{MinEvec}(\mT)$ \tikzmark{right}
    \STATE Set $\vu^{(1)} \leftarrow \sum_{k=1}^N z^{(1)}_k\vv_k$ and $\vu^{(d)} \leftarrow \sum_{k=1}^N z^{(d)}_k\vv_k$ \tikzmark{bottom}
    \STATE Set $\gamma \leftarrow \max\{\hat{\lambda}_1,-\hat{\lambda}_d\}$ 
    \IF{$\gamma \leq 1$}
    \STATE Return $\gamma$ and $\mS = 0$ \COMMENT{Case I: $\gamma\leq 1$, which implies $\|\mW\|_{\op} \leq 1+\delta$}
    \ELSIF{$\hat{\lambda}_1 \geq -\hat{\lambda}_d$}
      \STATE Return $\gamma$ and $\mS = \vu^{(1)}(\vu^{(1)})^\top$ \hspace{.75em}\COMMENT{Case II: $\gamma> 1$ and $\mS$ defines a separating hyperplane}
    \ELSE
      \STATE Return $\gamma$ and $\mS = -\vu^{(d)}(\vu^{(d)})^\top$ \COMMENT{Case II: $\gamma> 1$ and $\mS$ defines a separating hyperplane}
    \ENDIF
  \end{algorithmic}

\begin{lemma}\label{lem:averaging}
  Suppose Assumption~\ref{assum:monotone} holds. 
    Let $\theta_0, \dots, \theta_{T-1} \geq 0$ with $\sum_{t=0}^{T-1} \theta_t = 1$ and let $\vz_0,\dots,\vz_{T-1}\in \reals^d$. Define the averaged iterates as $\bar{\vz}_T = \sum_{t=0}^{T-1} \theta_t \vz_t$. Then: 
    \begin{enumerate}[(i)]
      \item For Problem~\eqref{eq:monotone}, $\gap_{\mathrm{w}}(\vz; \mathcal{D}) \leq \max_{\vz \in \calD}\sum_{t=0}^{T-1} \theta_t \langle \vF(\vz_t), \vz_t-\vz\rangle$. 
      \item For Problem~\eqref{eq:minimization}, $\gap_{f}(\vz; \vz^*) \leq \sum_{t=0}^{T-1} \theta_t \langle \vF(\vz_t), \vz_t-\vz^*\rangle$. 
      \item For Problem~\eqref{eq:minimax}, $\gap_{\mathrm{pd}}(\vz;\calX\times \calY) \leq \max_{\vz \in \calX \times \calY}\sum_{t=0}^{T-1} \theta_t \langle \vF(\vz_t), \vz_t-\vz\rangle$. 
    \end{enumerate} 
   %
\end{lemma}

\begin{lemma}\label{lem:one_step}
  Suppose that the operator $\vF$ in \eqref{eq:monotone} is $\mu$-strongly monotone with $\mu \geq 0$.  
  Let $\{\vz_k\}_{k\geq 0}$ and $\{\hat{\vz}_k\}_{k\geq 0}$ be the iterates generated by Algorithm~\ref{alg:Full_Equasi-Newton}, where $\alpha_1\in [0,1)$, $\alpha_2 \in (0,1)$ and $\alpha_1+\alpha_2 <1$. Then for any $\vz \in \reals^d$ and $k \geq 0$, it holds that
  \begin{equation}\label{eq:one_step}
    \begin{aligned}
      \eta_k \langle \vF(\hat{\vz}_k),\hat{\vz}_k - \vz \rangle &\leq \frac{\|\vz_k\!-\! \vz\|^2}{2} - \frac{1+2\eta_k\mu}{2}\|\vz_{k+1} - \vz\|^2 + \eta_k\mu \|\hat{\vz}_k - \vz\|^2 \\
      & \phantom{{}\leq{}} 
      - \frac{1-\alpha_1-\alpha_2}{2}(\|\hat{\vz}_k - \vz_k\|^2 + \|\hat{\vz}_k-\vz_{k+1}\|^2).
    \end{aligned}
  \end{equation} 

\end{lemma}

\begin{proof}
  To simplify the notation, let $\alpha \triangleq \alpha_1+\alpha_2\in (0,1)$. For any $\vz\in \reals^d$, we have 
\begin{equation}\label{eq:inexact_pp_decomp}
  \eta_k \langle \vF(\hat{\vz}_k), \hat{\vz}_k-\vz \rangle =  \langle \hat{\vz}_k-\vz_k+\eta_k \vF(\hat{\vz}_k), \hat{\vz}_k-\vz \rangle
  +\langle \vz_k-\hat{\vz}_k, \hat{\vz}_k-\vz\rangle. %
   %
   %
\end{equation}
For the first term in \eqref{eq:inexact_pp_decomp}, we can bound it by
\begin{align}
  \langle \hat{\vz}_k-\vz_k+\eta_k \vF(\hat{\vz}_k), \hat{\vz}_k-\vz \rangle &\leq \|\hat{\vz}_k-\vz_k+\eta_k\vF(\hat{\vz}_k)\|\|\hat{\vz}_k-\vz\| \nonumber\\
  &\leq \alpha\sqrt{1+\eta_k\mu}\|\hat{\vz}_k-\vz_k\|\|\hat{\vz}_k-\vz\| \nonumber\\
  &\leq {\frac{\alpha}{2}\|\hat{\vz}_k-\vz_k\|^2+\frac{\alpha(1+\eta_k \mu)}{2}\|\hat{\vz}_k-\vz\|^2}.\label{eq:triangle_ipp}
\end{align}
Here, the first inequality is due to the Cauchy-Schwarz inequality, the second inequality comes from \eqref{eq:inexact_proximal_point}, and the last inequality is a result of Young's inequality. 
Additionally, to handle the second term in \eqref{eq:inexact_pp_decomp}, we apply the three-point equality, yielding:
\begin{equation}\label{eq:three_point}
  \langle \vz_k-\hat{\vz}_k, \hat{\vz}_k-\vz\rangle = \frac{1}{2}\|\vz_k-\vz\|^2-\frac{1}{2}\|\hat{\vz}_k - \vz_k\|^2-\frac{1}{2}\|\hat{\vz}_k-\vz\|^2.
\end{equation}
%
By combining \eqref{eq:inexact_pp_decomp}, \eqref{eq:triangle_ipp} and \eqref{eq:three_point}, we obtain that    
\begin{equation}\label{eq:intermediate_1}
  \eta_k \langle \vF(\hat{\vz}_k), \hat{\vz}_k-\vz \rangle \leq \frac{\|\vz_k-\vz\|^2 }{2}-\frac{1-\alpha}{2}(\|\hat{\vz}_k - \vz_k\|^2 + \|\hat{\vz}_k-\vz\|^2) + \frac{\alpha\eta_k \mu}{2}\|\hat{\vz}_k-\vz\|^2.
\end{equation}
Furthermore, it follows from the update rule in \eqref{eq:extragradient_mixing} that $\eta_k\vF(\hat{\vz}_k) = \vz_k-\vz_{k+1}+2\eta_k\mu (\hat{\vz}_k-\vz_{k+1})$. Thus, for any $\vz\in \reals^d$, it also holds that
%
\begin{equation}
  \begin{aligned}\label{eq:intermediate_2}
    \phantom{{}={}}\eta_k \langle \vF(\hat{\vz}_k), \vz_{k+1}-\vz \rangle &= \langle \vz_k-\vz_{k+1}, \vz_{k+1}-\vz \rangle+2\eta_k\mu \langle \hat{\vz}_k-\vz_{k+1}, \vz_{k+1}-\vz\rangle %
    \\
    & = \frac{\|\vz_{k}-\vz\|^2}{2}-\frac{\|\vz_k-\vz_{k+1}\|^2}{2}-\frac{1+2\eta_k\mu}{2}\|\vz_{k+1}-\vz\|^2\\
    & \phantom{{}={}}+ {\eta_k\mu}\|\hat{\vz}_{k}-\vz\|^2-{\eta_k\mu}\|\hat{\vz}_k-\vz_{k+1}\|^2, 
  \end{aligned}
\end{equation}
where we applied the three-point equality twice in the last equality. Hence, by adding the inequality in \eqref{eq:intermediate_1} with $\vz = \vz_{k+1}$ to the inequality in \eqref{eq:intermediate_2}, we obtain 
\begin{equation}\label{eq:linearized_loss}
  \begin{aligned}
    \eta_k \langle \vF(\hat{\vz}_k),\hat{\vz}_k - \vz \rangle 
    &= \eta_k \langle \vF(\hat{\vz}_k),{\vz}_{k+1} - \vz \rangle 
    +\eta_k \langle \vF(\hat{\vz}_k), \hat{\vz}_{k} - \vz_{k+1} \rangle \\
    &\leq \frac{\|\vz_{k}-\vz\|^2}{2}-\bcancel{\frac{\|\vz_k-\vz_{k+1}\|^2}{2}}-\frac{1+2\eta_k\mu}{2}\|\vz_{k+1}-\vz\|^2 \\
    &\phantom{{}={}} + {\eta_k\mu}\|\hat{\vz}_{k}-\vz\|^2-{{\eta_k\mu}\|\hat{\vz}_k-\vz_{k+1}\|^2} + \bcancel{\frac{\|\vz_k-\vz_{k+1}\|^2}{2}}\\
    &\phantom{{}={}} -\frac{1\!-\!\alpha}{2}(\|\hat{\vz}_k \!-\! \vz_k\|^2 \!+\! \|\hat{\vz}_k\!-\!\vz_{k+1}\|^2 )+{\frac{\alpha \eta_k\mu}{2}\|\hat{\vz}_k\!-\!\vz_{k+1}\|^2} \!. %
    %
  \end{aligned}
\end{equation} 
Moreover, since $\alpha <1$, we further have $-{{\eta_k\mu}\|\hat{\vz}_k-\vz_{k+1}\|^2} + \frac{\alpha \eta_k \mu}{2}\|\hat{\vz}_k-\vz_{k+1}\|^2 \leq -\frac{\eta_k\mu}{2}\|\hat{\vz}_k-\vz_{k+1}\|^2 \leq 0$.  Combining this with \eqref{eq:linearized_loss}  and rearranging the terms, we arrive at the desired result in~\eqref{eq:one_step}. 
\end{proof}

\begin{proof}
Let $\alpha = \alpha_1 + \alpha_2$. First, we prove Part (a). Since $\mF(\vz^*) = 0$ and $\vF$ is $\mu$-strongly monotone by Assumption~\ref{assum:strong_monotone}, it holds that  
\begin{equation}\label{eq:strong_monotone}
\langle \vF(\hat{\vz}_k),\hat{\vz}_k - \vz^* \rangle = \langle \vF(\hat{\vz}_k)-\vF({\vz^*}),\hat{\vz}_k - \vz^* \rangle \geq \mu\|\hat{\vz}_k - \vz^*\|^2.
\end{equation}
By setting $\vz = \vz^*$ in \eqref{eq:one_step} and applying \eqref{eq:strong_monotone}, it yields 
\begin{equation}\label{eq:one_step_strongly}
    0 \leq \frac{1}{2}\|\vz_k- \vz^*\|^2 - \frac{1+2\eta_k\mu}{2}\|\vz_{k+1} - \vz^*\|^2  - \frac{1-\alpha}{2}(\|\hat{\vz}_k - \vz_k\|^2 + \|\hat{\vz}_k-\vz_{k+1}\|^2).
\end{equation} 
Since $\alpha = \alpha_1 + \alpha_2 <1$, we can drop the non-positive last term in \eqref{eq:one_step_strongly} and obtain $0 \leq \frac{1}{2}\|\vz_k- \vz^*\|^2 - \frac{1+2\eta_k\mu}{2}\|\vz_{k+1} - \vz^*\|^2$, which is equivalent to $\|\vz_{k+1} - \vz^*\|^2 \leq \|\vz_k- \vz^*\|^2 (1+2\eta_k\mu)^{-1}$. This completes the proof of Part (a). 

Next, we prove Part (b). Since $\vF$ is monotone by Assumption~\ref{assum:monotone}, we have
  \begin{equation}\label{eq:monotone_star}
    \langle \vF(\hat{\vz}_k),\hat{\vz}_k - \vz^* \rangle = \langle \vF(\hat{\vz}_k)-\vF({\vz^*}),\hat{\vz}_k - \vz^* \rangle \geq 0.
    \end{equation}
    By setting $\vz = \vz^*$ in \eqref{eq:one_step} with $\mu = 0$ and applying \eqref{eq:monotone_star}, it yields 
    \begin{equation}\label{eq:one_step_monotone}
      0 \leq \frac{1}{2}\|\vz_k- \vz^*\|^2 - \frac{1}{2}\|\vz_{k+1} - \vz^*\|^2  - \frac{1-\alpha}{2}(\|\hat{\vz}_k - \vz_k\|^2 + \|\hat{\vz}_k-\vz_{k+1}\|^2).
    \end{equation}
    Again, since the last term in \eqref{eq:one_step_monotone} is non-positive, this immediately implies $\frac{1}{2}\|\vz_{k+1} - \vz^*\|^2 \leq \frac{1}{2}\|\vz_{k} - \vz^*\|^2$, which is equivalent to $\|\vz_{k+1} - \vz^*\| \leq \|\vz_{k} - \vz^*\|$. Additionally, by dropping the non-positive last term in \eqref{eq:one_step} and noting that $\mu = 0$, we also have 
    %
    $\eta_k \langle \vF(\hat{\vz}_k),\hat{\vz}_k - \vz \rangle \leq \frac{1}{2}\|\vz_k- \vz\|^2 - \frac{1}{2}\|\vz_{k+1} - \vz\|^2$.
    %
    By summing this inequality from $k=0$ to $k=N-1$, we further get 
    %
    $\sum_{k=0}^{N-1} \eta_k \langle \vF(\hat{\vz}_k),\hat{\vz}_k - \vz \rangle \leq \frac{1}{2}\|\vz_0- \vz\|^2 - \frac{1}{2}\|\vz_{N} - \vz\|^2 \leq \frac{1}{2}\|\vz_0- \vz\|^2$. 
    %
    Hence, it follows from Lemma~\ref{lem:averaging} that $\gap(\bar{\vz}_N; \calD) \leq \frac{\max_{\vz \in \calD}\,\|\vz_0-\vz\|^2}{2 \sum_{k=0}^{N-1} \eta_k}$, where $\bar{\vz}_N$ is the averaged iterate given by $\bar{\vz}_N = \frac{\sum_{k=0}^{N-1} \eta_k \hat{\vz}_k}{\sum_{k=0}^{N-1} \eta_k}$.  
\end{proof}

\begin{lemma}\label{lem:stepsize_bnd}
Let $\{\eta_k\}_{k=0}^{N-1}$ be the step sizes in Algorithm~\ref{alg:Full_Equasi-Newton} obtained by the line search in Subroutine~\ref{alg:ls}.~Then,
%
\begin{equation}\label{eq:goal}
     \sum_{k=0}^{N-1}\frac{1}{\eta_k} \leq \frac{1}{(1-\beta)\sigma_0}+ \frac{1}{(1-\beta)\alpha_2\beta} 
    %
     \sqrt{N \sum_{k\in \mathcal{B}} \frac{\|\vu_k-\mB_k\vs_k\|^2}{\|\vs_k\|^2}}, 
     %
      %
