This paper addresses the design and convergence analysis of first-order optimization algorithms with momentum for solving unconstrained optimization problems of the type
\begin{align}\label{main problem}
{\rm minimize}\quad f(x)\quad \text{ subject to }x\in\R^n,
\end{align}
where $f:\R^n\rightarrow\overline{\R}$ is a continuously differentiable function on some open and convex subset $X$ of $\R^n$ having a Lipschitz continuous gradient with constant $L>0$ on $X$, i.e.,
\begin{align*}
\norm{\nabla f(x)-\nabla f(y)}\le L\norm{x-y}\;\text{ for all }\;x,y\in X.
\end{align*}


As always, $\N:=\{1,2,\ldots\}$ signifies the collections of natural numbers. Given $r>0$, the open ball centered at $\bar x$ with radius $r$ is denoted by $\mathbb{B}(\bar x,\rho)$ and its closure is $\overline{\mathbb{B}}(\bar x,\rho)$.
The symbol $x^k\st{J}{\to}\ox$ means that $x^k\to\ox$ as $k\to\infty$ with $k\in J\subset\N$. Recall that $\bar x$ is a \textit{stationary point} and that $f(\bar x)$ is a \textit{critical value} of a $\mathcal{C}^1$-smooth function $f\colon\R^n\rightarrow\R$ if $\nabla f(\bar x)=0$. A $\C^1-$smooth function $f:\Omega\rightarrow {\R}$ is said to have a Lipschitz continuous gradient with the uniform constant $L>0$ on some subset $\Omega$ of $\R^n$ if 
\begin{align}\label{Lips def}
\norm{\nabla f(x)-\nabla f(y)}\le L\norm{x-y}\;\text{ for all }\;x,y\in\Omega.
\end{align}
A function $f\colon\R^n\rightarrow\R$ is {\em locally Lipschitz continuous} around $\bar x$  if there is a neighborhood $\Omega$ of $\bar x$ such that \eqref{Lips def} holds; $f$ {\em globally Lipschitz continuous} if \eqref{Lips def} holds for $\Omega=\R^n$. In what follows, we denote by $\mathcal{C}^{1,1}$ the class of smooth functions that have a {\em locally Lipschitz continuous gradient} around $\bar x$, and by $\mathcal{C}^{1,1}_L$ the class of smooth functions that have a {\em globally Lipschitz continuous gradient with constant} $L>0$.

Next we recall the subdifferential constructions for proper extended-real-valued functions $h:\R^n\rightarrow\Bar\R:=(-\infty,\infty]$ with $\dom h:=\{x\in\R^n\;|\;h(x)<\infty\}\ne\emp$ taken from \cite{Mordukhovich2006,Mordukhovich2018,RockafellarWets} and used below. The (Fr\'echet) \textit{regular subdifferential} of $ h $ at $\ox \in\dom  h $ is 
\begin{align}\label{frechet}
\widehat{\partial} h (\bar x):=\Big\{v\in \R^n\;\Big|\;\liminf_{x\rightarrow\bar x}\dfrac{ h (x)- h (\bar x)-\dotproduct{v,x-\bar x}}{\norm{x-\bar x}}\ge 0\Big\},
\end{align}
and the (Mordukhovich) \textit{limiting subdifferential} of $ h $ at $\bar x\in\dom  h $ is defined by 
\begin{align}\label{limiting subdiff}
\partial  h (\bar x):=\set{v\in\R^n\;\big|\;\exists\,x^k\rightarrow \ox,\  h (x^k)\rightarrow h (\bar x),\ \widehat{\partial}h(x^k)\ni v^k\rightarrow v}.
\end{align}
When $ h $ is $\mathcal{C}^1$-smooth around $\bar x$, both subdifferentials in \eqref{frechet} and \eqref{limiting subdiff} reduce to the gradient $\nabla  h (\bar x)$, while for convex functions they agree with the classical subdifferential of convex analysis. A necessary condition for $\bar x\in\R^n$ to be a local minimizer of $ h $ is 
$0\in \partial h (\bar x)$. Any point $\bar x$ satisfying the latter condition is known in the literature as an {\em M$($ordukhovich$)$-stationary} (or {\em limiting-stationary}) point of $h$. Since this paper does not deal with other stationary concepts for nonsmooth functions, we simply use the {\em stationary} point term in what follows.


\begin{Definition}\rm \label{KL ine}\rm We say that a lower semicontinuous (l.s.c.) function $f:\R^n\rightarrow\overline{\R}$ satisfies the $($basic$)$ \textit{Polyak-\L ojasiewicz-Kurdyka} $(PLK)$ condition at $\bar x\in\dom \partial f$ if there exist $\eta\in (0,\infty]$, a neighborhood $U$ of $\bar x$, and a desingularizing concave function $\varphi:[0,\eta)\rightarrow[0,\infty)$ such that:

{\bf(i)} $\varphi(0)=0$.

{\bf(ii)} $\varphi$ is $\mathcal{C}^1$-smooth on $(0,\eta)$.

{\bf(iii)} $\varphi'>0$ on $(0,\eta)$.

{\bf(iv)} For all $x\in U$ with $f(\bar{x})<f(x)<f(\bar{x})+\eta$, we have 
\begin{align}\label{KL 2}
\varphi'\big(f(x)-f(\bar{x})\big)d(0,\partial f(x))\ge 1.
\end{align}
\end{Definition}

\begin{Remark}\rm\label{algebraic}If $f$ satisfies the PLK property at $\bar x$ with a neighborhood $U$, it is clear that the same property holds for any $\tilde x\in U\cap {\rm dom\; }\partial f$ satisfying $f(\tilde x)=f(\bar x).$
It has been realized that the PLK condition is satisfied in rather  broad settings. In particular, it holds at every 
nonstationary point of $f$, for semianalytic and more general functions known as definable in o-minimal structures; see, e.g., \cite{AbsilMahonyAndrews2005,AttouchBolteRedontSoubeyran2010,AttouchBolteSvaiter2013} and the references therein. As demonstrated in \cite[Section~2]{KhanhMordukhovichTran2023}, the PLK condition formulated in \cite{AttouchBolteRedontSoubeyran2010} is stronger than the one in Definition~\ref{KL ine}.
\end{Remark}

Note that condition (ii) ensures that, for any fixed $x\in(0,\eta)$ and $a\in(0,x]$, the function $\varphi'$ is integrable on $[a,x]$ and thus $\varphi(x)=\varphi(a)+\int_a^{x}\varphi'(t)dt$. Taking the limit as $a\rightarrow0^+$ and using  
$\varphi(0)=0$ give us $\varphi(x)=\int_0^{x}\varphi'(t)dt$. The following result plays an important role in our local convergence analysis.


\begin{Remark}\rm\label{rmk general rate} It is easy to see  that condition \eqref{two conditions} in Proposition~\ref{general rate} yields the fulfillment of (H2) and of (H1) with $\sigma=\frac{\alpha}{\beta}$  in Proposition~\ref{general convergence under KL}. Proposition~\ref{general rate} obviously holds true even for extended-real-valued functions $f$ provided that $\{x^k\}$ is convergent and $f$ is ${\cal C}^1$-smooth on an open set containing $\{x^k\}$.
\end{Remark}

