						\D_{\kernel^*}\bigl(\nabla\kernel(x^k)+\delta_{k+1}\bigl[H_k(x^k)-H_k(x^{k-1})\bigr],\nabla\kernel(x^k)\bigr)
					}{
						\delta_{k+1}^2
						\DD_{\kernel}(x^k,x^{k-1})
					}
				\\
				\nonumber
				={} &
					\frac{
						\innprod{
							\nabla^2\kernel^*(\xi_k)
							\bigl[H_k(x^k)-H_k(x^{k-1})\bigr]
						}{
							H_k(x^k)-H_k(x^{k-1})
						}
					}{
						\innprod{
							\nabla^2\kernel^*(\eta_k)
							u^k
						}{
							u^k
						}
					}
				\\
				\nonumber
				={} &
					\frac{
						\innprod{
							\nabla^2\kernel^*(\xi_k)
							u^k
						}{
							u^k
						}
					}{
						\innprod{
							\nabla^2\kernel^*(\eta_k)
							u^k
						}{
							u^k
						}
					}
					-
					2\gamma_k
					\frac{
						\innprod{
							\nabla^2\kernel^*(\xi_k)
							u^k
						}{
							v^k
						}
					}{
						\innprod{
							\nabla^2\kernel^*(\eta_k)
							u^k
						}{
							u^k
						}
					}
					+
